-- Generated by scripts/gen-seed.mjs from stories/. Do not edit by hand.
insert into public.stories (visibility, content, published_at)
select 'marketplace', $story${"format":"grimoire-story/1","meta":{"id":"la-dame-de-trois-heures-dix","title":"La Dame de trois heures dix","lang":"fr","summary":"Novembre 1924. Maître Lécuyer, notaire à Cherbourg, vous charge d'inventorier le manoir du Clos-Aubert avant sa vente. Sa propriétaire est morte il y a trois mois, et depuis, toutes les horloges de la maison se sont arrêtées à la même heure.","players":{"min":1,"max":2},"duration":"2 hours","era":"Novembre 1924","setting":"Le manoir du Clos-Aubert, au-dessus d'une crique de la Hague, et le bourg de Saint-Martin-des-Grèves (Cotentin)","system":"d100","author":"Grimoire","license":"CC-BY-4.0","version":"1.1","tags":["solo","côtier","fantôme","enquête"],"contentWarnings":["noyade (évoquée)","deuil"]},"overview":{"secret":"En 1889, **Adélaïde d'Aubernay**, jalouse, a intercepté les lettres d'amour qu'**Étienne Fauvel**, terre-neuvas de Granville, envoyait à sa sœur jumelle **Clémence**. Se croyant abandonnée, Clémence est descendue dans la crique au pied du manoir une nuit d'octobre et s'est avancée dans la mer, à 3 h 10. Étienne est revenu au printemps : on lui a dit qu'elle était morte, il n'est jamais revenu. Rongée de remords, Adélaïde a caché les lettres derrière un ex-voto de la chapelle et, pendant trente-cinq ans, a remonté chaque nuit toutes les horloges : tant qu'elles tournaient, Clémence restait en paix. Depuis la mort d'Adélaïde, les horloges se sont arrêtées et le fantôme erre, cherchant ses lettres. La nuit de l'anniversaire, s'il ne les retrouve pas, il entraîne la personne la plus proche vers la mer, à sa place.","steps":["[[arrivee-manoir]] : arrivée sous la pluie, Marthe la gouvernante, les horloges arrêtées à 3 h 10.","[[premiere-nuit]] : une note de piano, des pas mouillés de la crique à une chambre fermée.","[[chambre-close]] : la chambre de Clémence, son journal, le portrait des jumelles.","[[le-bourg]] : l'abbé Hébert et le registre, le vieux facteur Jules Leprévost et les lettres.","[[la-chapelle]] : les lettres cachées et la confession d'Adélaïde.","[[la-crique]] : 3 h 10, Clémence au bord de l'eau."],"mustNotMiss":["L'existence des **lettres d'Étienne** : par le facteur ([[le-bourg]]) ou par le journal de Clémence ([[chambre-close]]).","Leur **cachette dans la chapelle** : par la confession d'Adélaïde évoquée par Marthe, ou par les traces de Clémence qui mènent à l'ex-voto ([[la-chapelle]]).","Les lettres doivent être **rendues à Clémence** à la crique ([[la-crique]])."],"ifStuck":["Marthe se souvient que Madame passait chaque dimanche une heure seule à la chapelle.","La nuit, des gouttes d'eau de mer mènent jusqu'à l'ex-voto du navire."],"branches":["Rendre ou lire les lettres à voix haute à Clémence : elle s'apaise et disparaît, les horloges repartent.","Brûler les lettres : Clémence devient furieuse, la fin se joue sur la volonté (POU) et la chance.","Remonter les horloges de la maison retarde la venue du fantôme d'une nuit, mais ne règle rien."],"keeperTips":["En solo, laissez du temps à l'atmosphère : bruits, silences, objets.","Clémence n'est jamais monstrueuse : elle est trempée, triste, et elle a froid.","Pas de combat : la menace, c'est la mer et le chagrin."]},"acts":[{"id":"arrivee","title":"L'arrivée","scenes":[{"id":"arrivee-manoir","title":"Le manoir sous la pluie","lead":"Arrivée au Clos-Aubert, la gouvernante, les horloges arrêtées.","screen":{"place":"manor","preset":"rain","time":"dusk"},"readAloud":["La carriole vous dépose au bout d'une allée de hêtres tordus par le vent. Le manoir du Clos-Aubert se dresse au bord de la lande, gris comme le ciel, et derrière lui on entend la mer cogner au pied de la falaise.","Une femme âgée vous attend sur le perron, une lampe à la main. « Vous êtes l'envoyée de Maître Lécuyer. Entrez, la pluie ne s'arrêtera pas pour vous. »"],"flow":[{"title":"Accueil par Marthe","text":"{{npc:marthe}} remet les clés, montre la cuisine, le salon, la bibliothèque, la chambre d'amis préparée pour l'investigatrice. Elle donne l'inventaire commencé par le notaire → {{handout:lettre-notaire}}.","extra":"Marthe dort dans une petite maison au bout du jardin. L'investigatrice sera seule dans le manoir la nuit."},{"title":"Les horloges","text":"Salon, vestibule, bibliothèque : chaque horloge est arrêtée à **3 h 10**.","roll":{"type":"skill","options":["spot-hidden","mechanical-repair"]},"success":"Aucune n'est cassée : elles ne sont simplement plus remontées. Sur chaque cadran, de minuscules traces de doigts, comme si on les avait remontées chaque jour pendant des années.","failure":"Des horloges arrêtées, la poussière d'une maison en deuil."},{"title":"Interroger Marthe","text":"Sur les horloges, Madame, la maison.","roll":{"type":"skill","options":["charm","psychology","persuade"]},"success":"« Madame les remontait elle-même, chaque soir, toutes. Elle disait que la maison devait garder l'heure. Depuis l'enterrement, je n'ose pas y toucher. »","failure":"« Madame avait ses habitudes. Ce n'est pas à moi d'en parler. »","pushed":"Marthe se ferme tout à fait et ne parlera plus de la famille avant le lendemain."},{"title":"La chambre fermée","text":"Au premier étage, une porte est fermée à clé. Marthe dit qu'elle n'a pas la clé, ce qui est faux.","roll":{"type":"skill","options":["psychology"]},"success":"Elle ment, et elle a peur. Pas de l'investigatrice : de la chambre.","failure":"Elle semble sincère."},{"title":"Le portrait du salon","text":"Au-dessus de la cheminée, le portrait d'Adélaïde jeune, seule sur un banc. À côté d'elle, le peintre a laissé une place vide, comme si quelqu'un avait été effacé.","roll":{"type":"skill","options":["appraise","art-craft"]},"success":"Une moitié de la toile a été repeinte, bien après le reste. Il y avait une seconde personne.","goto":["premiere-nuit"]}],"notes":[{"title":"La maison","items":["Rez-de-chaussée : vestibule, salon, bibliothèque, cuisine, salle à manger.","Premier étage : chambre d'Adélaïde, chambre d'amis, **chambre close** ([[chambre-close]]).","Jardin : potager, maison de Marthe, petite **chapelle** ([[la-chapelle]]), sentier vers la **crique** ([[la-crique]])."]}],"npcs":["marthe"],"handouts":["lettre-notaire"],"ambience":["rain","wind","clock"],"sfx":["door-creak","footsteps"],"next":["premiere-nuit"]},{"id":"premiere-nuit","title":"La première nuit","lead":"Une note de piano, des pas mouillés, une silhouette.","screen":{"place":"manor","preset":"night","time":"night"},"readAloud":["La pluie s'est calmée. Dans le silence, vous entendez la mer, et rien d'autre. Pas une horloge ne bat dans cette maison.","Puis, quelque part en bas, une seule note de piano. Longue. Elle s'éteint lentement."],"flow":[{"title":"Le réveil","text":"Vers 3 h du matin. Si elle descend : le piano du salon est fermé, le couvercle couvert de poussière.","roll":{"type":"skill","options":["listen"]},"success":"Après la note, un bruit d'eau qui goutte, sur le parquet du vestibule.","failure":"Plus rien. Seulement le vent."},{"title":"Les traces","text":"Du vestibule à l'escalier : des empreintes de pieds nus, mouillées. L'eau a le goût du sel et sent le varech. Elles montent jusqu'à la porte de la **chambre close** et s'arrêtent là.","roll":{"type":"skill","options":["track","spot-hidden"]},"success":"Les traces viennent de la porte du jardin, côté mer. Du sable fin est mêlé à l'eau.","failure":"Des traces mouillées, qui sèchent vite."},{"title":"La silhouette","text":"En haut de l'escalier, au bout du couloir, une jeune femme en robe claire, trempée, face à la porte close. Elle pose la main sur la poignée, puis tourne la tête vers l'investigatrice. Et disparaît.","roll":{"type":"san","label":"La femme du couloir","san":"0/1D3"},"extra":"Elle ne fait rien. Elle a seulement l'air de chercher quelque chose."},{"title":"Le matin","text":"Les traces ont séché, mais le sel reste, en petites auréoles blanches sur le parquet. Marthe les voit, pâlit et les essuie sans un mot.","roll":{"type":"skill","options":["psychology","persuade"]},"success":"Marthe finit par donner la clé de la chambre : « Elle revient. Comme avant que Madame ne... Ouvrez, si vous voulez. Moi, je n'y entre pas. »","failure":"Marthe nie tout. La chambre peut être ouverte avec Serrurerie, ou la clé trouvée dans le secrétaire d'Adélaïde (Trouver Objet Caché).","goto":["chambre-close","le-bourg"]}],"rolls":[{"type":"skill","label":"Forcer la porte close","options":["locksmith"]}],"npcs":["clemence"],"ambience":["night-crickets","wind"],"sfx":["footsteps","door-creak"],"next":["chambre-close","le-bourg"]}]},{"id":"secrets","title":"Les secrets","scenes":[{"id":"chambre-close","title":"La chambre close","lead":"La chambre de Clémence, intacte depuis 1889.","screen":{"place":"manor","preset":"candle","time":"night"},"readAloud":["L'air est froid et immobile, comme dans une église. Tout est en place : le lit fait, une robe posée sur une chaise, un bouquet de fleurs devenu poussière dans un vase.","Sur la table de nuit, une petite pendule dorée. Elle aussi est arrêtée à 3 h 10. Sur le parquet, devant la fenêtre qui donne sur la mer, il y a du sable."],"flow":[{"title":"Le portrait des jumelles","text":"Une photographie encadrée : deux jeunes filles identiques, en robe blanche, sur le banc du salon. Au dos : *Adélaïde et Clémence, été 1887*.","extra":"C'est le portrait original du salon, avant qu'Adélaïde ne fasse effacer sa sœur."},{"title":"Fouiller la chambre","roll":{"type":"skill","options":["spot-hidden"]},"success":"Sous le matelas, le **journal de Clémence** → {{handout:journal-clemence}}. Et, glissée dans la reliure, une **lettre déchirée** → {{handout:lettre-dechiree}}.","failure":"Elle ne trouve que le journal, sur l'étagère. La lettre glissée dans la reliure tombe au sol plus tard, quand le vent ouvre la fenêtre.","pushed":"Elle trouve tout, mais la fenêtre s'ouvre d'un coup, le vent glacé souffle la lampe et la porte claque derrière elle (SAN 0/1)."},{"title":"Lire le journal","roll":{"type":"skill","options":["library-use","psychology"]},"success":"Elle comprend : Clémence attendait des lettres de Terre-Neuve, et c'est toujours Adélaïde qui allait chercher le courrier au bourg.","failure":"Une histoire d'amour triste, des noms : Étienne, Granville, le facteur Jules."},{"title":"Le froid","text":"Si l'investigatrice reste longtemps, la pendule dorée fait un seul tic, puis s'arrête à nouveau.","roll":{"type":"san","label":"Le tic de la pendule","san":"0/1"},"goto":["le-bourg","la-chapelle"]}],"notes":[{"title":"Ce que contient la chambre","items":["Une robe de bal bleu pâle, jamais portée.","Une boîte à couture, un mouchoir brodé « C. A. ».","Un coquillage de Terre-Neuve sur la cheminée, cadeau d'Étienne.","La pendule dorée arrêtée à 3 h 10."]}],"npcs":["marthe"],"handouts":["journal-clemence","lettre-dechiree"],"ambience":["wind","rain-window"],"sfx":["door-slam"],"next":["le-bourg","la-chapelle"]},{"id":"le-bourg","title":"Saint-Martin-des-Grèves","lead":"Le registre du curé et la confession du vieux facteur.","screen":{"place":"street","preset":"fog","time":"day"},"readAloud":["Le bourg tient en une rue : l'église de granit, un café-épicerie, des maisons basses aux volets bleus. Des femmes en coiffe vous regardent passer sans répondre à votre bonjour.","À l'épicerie, on parle de « la dame du Clos » à voix basse. Quelqu'un dit que, depuis l'enterrement, on voit de la lumière dans la crique, la nuit."],"flow":[{"title":"Le presbytère","text":"{{npc:abbe-hebert}} reçoit volontiers. Il a enterré Adélaïde et trouve qu'elle « portait quelque chose de trop lourd ».","roll":{"type":"skill","options":["library-use","charm"]},"success":"Le registre de 1889 : *Clémence d'Aubernay, vingt ans, retrouvée noyée dans l'anse du Clos le 9 novembre. Inhumée sans messe, sur décision de la famille.* La date : c'est dans deux jours.","failure":"L'abbé se souvient seulement d'une sœur morte jeune, « un accident ». Il retrouvera le registre pour le lendemain.","pushed":"Il retrouve la page, mais une cloche sonne : un enterrement, il doit partir. Il faudra revenir."},{"title":"Trouver le facteur","text":"À l'épicerie, on indique la maison de {{npc:jules-leprevost}}, ancien facteur, au bout de la rue. « Il en sait des choses, le Jules. Mais il ne parle qu'après le deuxième calva. »"},{"title":"Faire parler Jules","text":"Il reconnaît le nom de Clémence et se met à trembler.","roll":{"type":"skill","options":["persuade","psychology","charm"]},"success":"Il avoue : de mai à octobre 1889, les lettres de Saint-Pierre arrivaient pour Mademoiselle Clémence. Madame Adélaïde l'attendait chaque matin sur la route et les prenait. « Elle me donnait une pièce. J'ai cru que c'était pour les lui porter. » Il en a remis une dizaine.","failure":"« Des lettres, j'en ai porté des milliers, ma petite dame. » Il se ferme, mais ses mains tremblent.","pushed":"Il craque, en larmes, et avoue tout, mais il sort ensuite au café et raconte à tout le bourg que la dame de Paris « réveille la noyée ». Marthe l'apprend le soir même."},{"title":"Le retour d'Étienne","text":"Jules ou l'abbé se souviennent : au printemps 1890, un jeune marin de Granville est venu frapper au Clos. On lui a dit que Clémence était morte. Il est reparti sans un mot et on ne l'a plus revu.","extra":"Si personne ne parle de la date, c'est ici que l'investigatrice apprend que la nuit du 8 au 9 novembre approche.","goto":["la-chapelle"]}],"notes":[{"title":"Ce que sait le bourg","items":["La dame du Clos venait à la messe seule, toujours au dernier rang.","On dit que la crique « garde » ceux qui y descendent la nuit.","Personne n'est entré dans la chapelle du Clos depuis des années, sauf Madame."]}],"npcs":["abbe-hebert","jules-leprevost"],"ambience":["village-day","wind"],"sfx":["knocking","door-open"],"next":["la-chapelle"]},{"id":"la-chapelle","title":"La chapelle du manoir","lead":"Les lettres cachées et la confession d'Adélaïde.","screen":{"place":"church","preset":"candle","time":"dusk"},"readAloud":["La chapelle est une petite bâtisse de granit au fond du jardin, à moitié mangée par le lierre. La porte résiste, puis cède dans un grincement.","À l'intérieur, un prie-Dieu usé jusqu'au bois, une Vierge aux mains jointes et, suspendue au mur, la maquette d'un trois-mâts, offerte comme ex-voto. Sous elle, une bougie. La mèche est encore fraîche."],"flow":[{"title":"Aide de Marthe","text":"Si l'investigatrice a gagné sa confiance, {{npc:marthe}} l'accompagne jusqu'à la porte : « Chaque dimanche, une heure. Elle en ressortait les yeux rouges. » Elle n'entre pas."},{"title":"Fouiller la chapelle","roll":{"type":"skill","options":["spot-hidden"]},"success":"Derrière l'ex-voto, une pierre descellée. Dans la cavité, un coffret en bois de rose.","failure":"Rien. Mais, au sol, des gouttes d'eau de mer mènent jusqu'au mur sous l'ex-voto : Clémence cherche ici, elle aussi. Une nouvelle fouille trouve la pierre."},{"title":"Le coffret","text":"Onze lettres d'Étienne, nouées d'un ruban bleu → {{handout:lettres-etienne}}. Et une feuille pliée, de l'écriture d'Adélaïde → {{handout:confession-adelaide}}.","roll":{"type":"san","label":"La confession","san":"0/1D3"}},{"title":"Le pressentiment","text":"Pendant la lecture, la bougie s'allume seule. Une odeur de varech envahit la chapelle. Dehors, on entend la mer monter. Occultisme ou Psychologie, sinon INT (jets rapides de la scène).","roll":{"type":"skill","options":["occult","psychology"]},"success":"Elle comprend ce que veut Clémence : pas une vengeance, seulement ses lettres. Il faut les lui rendre, là où elle les attendait : à la crique.","failure":"Elle comprend que les lettres sont au cœur de tout, sans savoir quoi en faire."},{"title":"Remonter les horloges ?","text":"La confession donne le rituel. Si l'investigatrice remonte toutes les horloges, Clémence ne vient pas cette nuit-là. Mais cela ne fait que repousser le problème : la nuit de l'anniversaire, elle vient quand même.","goto":["la-crique"]}],"rolls":[{"type":"characteristic","options":["INT"],"label":"Le pressentiment (INT)"}],"npcs":["marthe"],"handouts":["lettres-etienne","confession-adelaide"],"ambience":["wind","rain"],"sfx":["door-creak","latch"],"next":["la-crique"]}]},{"id":"maree","title":"La marée","scenes":[{"id":"la-crique","title":"La crique à 3 h 10","lead":"La nuit de l'anniversaire, Clémence vient chercher quelqu'un.","screen":{"place":"harbour","preset":"storm","time":"night"},"readAloud":["Cette nuit, aucun bruit dans la maison. Puis, d'un coup, toutes les horloges se mettent à sonner ensemble, alors que personne ne les a remontées. Trois coups. Et elles se taisent.","Par la fenêtre, au bas de la falaise, une silhouette claire se tient au bord de l'eau. Elle vous regarde. Elle lève la main, comme pour vous appeler."],"flow":[{"title":"L'appel","text":"Si l'investigatrice reste dans le manoir, Clémence monte la chercher : des pas mouillés dans l'escalier, une main froide sur la sienne.","roll":{"type":"characteristic","options":["POW"]},"success":"Elle garde la tête claire et descend vers la crique de son plein gré, les lettres à la main.","failure":"Elle se retrouve sur le sentier de la falaise, pieds nus, sans savoir comment elle y est arrivée. Elle a les lettres si elle les tenait."},{"title":"La descente","text":"Le sentier est raide et mouillé, le vent tire sur les vêtements.","roll":{"type":"characteristic","options":["DEX"]},"success":"Elle arrive sur les galets sans encombre.","failure":"Une glissade, des écorchures.","pushed":"Elle chute sur les derniers mètres (1D3) et perd la lanterne."},{"title":"Clémence","text":"Elle est là, dans l'eau jusqu'aux chevilles, trempée, avec le visage du portrait. Elle murmure : « Où sont-elles ? »","roll":{"type":"san","label":"Clémence face à face","san":"0/1D4"}},{"title":"Rendre ou lire les lettres","branch":"Si elle a les lettres","text":"Lui tendre les lettres, ou les lire à voix haute face à la mer. Pas de jet nécessaire si l'investigatrice les a.","success":"Clémence prend les lettres. Son visage change : elle sourit, pour la première fois. Elle se retourne et marche vers le large, et l'eau ne fait plus de bruit autour d'elle. Elle a disparu. Dans le manoir, toutes les horloges se remettent à battre."},{"title":"Si elle n'a pas les lettres","text":"Clémence lui prend la main et l'entraîne doucement vers l'eau, sans violence, avec une tristesse infinie. Pour se dégager : POU contre les 70 de POU de Clémence, donc un jet Difficile.","roll":{"type":"characteristic","options":["POW"],"difficulty":"hard","label":"Se dégager (POU)"},"success":"Elle se dégage et parle à Clémence d'Étienne et des lettres cachées. Le fantôme s'arrête, attend. Elle a jusqu'à l'aube pour aller chercher les lettres à la chapelle et revenir.","failure":"L'eau glacée monte à la taille (1D3, froid). {{npc:marthe}} surgit avec une lanterne et la tire en arrière en criant le nom de Clémence. Elle s'en sort, mais Clémence reviendra l'année prochaine."},{"title":"Si elle brûle les lettres","text":"La mer se lève d'un coup, le vent hurle. Clémence crie pour la première fois.","roll":{"type":"luck"},"success":"Une vague la renverse, mais elle parvient à remonter le sentier. Le Clos-Aubert ne sera plus jamais vendu : personne n'y reste plus d'une nuit.","failure":"La vague l'emporte dans l'eau glacée. Marthe la repêche, blessée et grelottante (1D4, perte de 1D6 SAN)."}],"notes":[{"title":"Épilogue","items":["Lettres rendues : l'investigatrice regagne **1D6 SAN**. Le lendemain, Marthe remonte les horloges en pleurant, puis les laisse tourner seules.","Si l'investigatrice cherche Étienne Fauvel à Granville, elle apprend qu'il ne s'est jamais marié et qu'il est mort en mer en 1902.","Lettres brûlées ou perdues : **1/1D4 SAN**. On dit au bourg que la dame du Clos marche toujours sur les galets les nuits de novembre."]}],"rolls":[{"type":"damage","label":"Gain de SAN (fin apaisée)","dice":"1D6"}],"npcs":["clemence","marthe"],"ambience":["storm","wind-howling"],"sfx":["thunder","footsteps"]}]}],"npcs":[{"id":"marthe","name":"Marthe Lemonnier","role":"Gouvernante du Clos-Aubert","description":"Soixante ans, droite et réservée, toujours en noir.","personality":"Loyale à Madame jusque dans la mort. Elle porte un secret depuis trente-cinq ans et a peur de la chambre close.","characteristics":{"STR":45,"CON":55,"SIZ":50,"DEX":45,"INT":60,"POW":55},"hp":10,"dodge":22,"knows":["Madame remontait toutes les horloges chaque soir, elle-même.","Madame avait une sœur jumelle, Clémence, morte noyée en 1889. On n'en parlait jamais.","Cette nuit d'octobre 1889, jeune bonne, elle a vu Clémence descendre vers la crique en chemise de nuit, et n'a rien dit.","Madame passait chaque dimanche une heure seule à la chapelle."]},{"id":"abbe-hebert","name":"Abbé Hébert","role":"Curé de Saint-Martin-des-Grèves","description":"La cinquantaine, lunettes rondes, soutane râpée.","personality":"Bienveillant, curieux, un peu bavard. Il aime ses registres et les histoires du pays.","characteristics":{"INT":70,"POW":60},"hp":11,"dodge":25,"knows":["Clémence d'Aubernay est morte noyée le 9 novembre 1889, inhumée sans messe.","Adélaïde venait prier seule, toujours au dernier rang.","Un jeune marin de Granville est venu au Clos au printemps 1890."]},{"id":"jules-leprevost","name":"Jules Leprévost","role":"Ancien facteur","description":"Quatre-vingts ans, béret, moustache jaunie par le tabac, toujours au coin du feu.","personality":"Bavard sur tout, sauf sur une chose. Rongé de culpabilité.","characteristics":{"CON":40,"POW":40},"hp":8,"dodge":15,"knows":["De mai à octobre 1889, il a remis une dizaine de lettres de Saint-Pierre à Adélaïde au lieu de Clémence.","Adélaïde l'attendait chaque matin sur la route et lui donnait une pièce.","Le marin Étienne Fauvel est revenu au printemps 1890 et est reparti seul."]},{"id":"clemence","kind":"creature","name":"Clémence d'Aubernay","role":"Le fantôme de la jumelle noyée","description":"Une jeune femme de vingt ans en robe claire, trempée, les cheveux pleins de sable. Elle a le visage du portrait d'Adélaïde jeune.","personality":"Triste, perdue, obstinée. Elle cherche ses lettres. Elle ne parle presque pas : un nom, « Étienne », ou « où sont-elles ? ».","characteristics":{"POW":70},"hp":0,"sanLoss":"0/1D4","attacks":[{"name":"Étreinte glacée","skill":50,"damage":"1D3","note":"Pas de violence : la victime est saisie par le froid et entraînée doucement vers l'eau."}],"special":["Immatérielle : les armes et les coups la traversent.","S'apaise si on lui rend ou si on lui lit les lettres d'Étienne.","Ne vient pas les nuits où les horloges de la maison ont été remontées."],"knows":["Elle ne sait pas qu'Adélaïde a caché les lettres. Elle croit qu'Étienne ne lui a jamais écrit."]},{"id":"etienne-fauvel","name":"Étienne Fauvel","role":"Terre-neuvas de Granville (absent)","description":"Le fiancé de Clémence. Il n'apparaît qu'à travers ses lettres."}],"handouts":[{"id":"lettre-notaire","title":"Lettre de Maître Lécuyer","scene":"arrivee-manoir","text":"*Cherbourg, le 3 novembre 1924*\n\nMadame,\n\nComme convenu, je vous confie l'inventaire du mobilier et des objets du Clos-Aubert, dont feu Madame Adélaïde d'Aubernay, sans héritier, était la dernière propriétaire. La vente est prévue au printemps.\n\nMadame Lemonnier, la gouvernante, vous logera. Elle est un peu... attachée à la maison. Soyez patiente avec elle.\n\nVeuillez agréer, Madame, l'expression de mes sentiments distingués.\n\n**Me A. Lécuyer**"},{"id":"journal-clemence","title":"Journal de Clémence (extraits)","scene":"chambre-close","text":"*Mai 1889.* Étienne est parti ce matin de Granville. Il m'écrira de Saint-Pierre, à chaque bateau qui rentre. Adé dit que je suis sotte d'aimer un pêcheur.\n\n*Juillet.* Une lettre ! Une seule, mais elle dit tout. Adé va au bourg chercher le courrier chaque matin, elle est si gentille depuis quelque temps.\n\n*Septembre.* Rien. Les bateaux rentrent et rien. Jules le facteur baisse les yeux quand je le croise.\n\n*Octobre.* Il m'a oubliée. Adé me tient la main le soir. Je n'entends plus que la mer."},{"id":"lettre-dechiree","title":"Lettre d'Étienne (déchirée)","scene":"chambre-close","text":"*Saint-Pierre, juin 1889*\n\nMa Clémence,\n\nLa morue est bonne cette année, et chaque soir sur le pont je regarde vers l'est. Je t'écrirai à chaque courrier, tu entendras parler de moi plus que tu ne voudras. Au printemps je viendrai demander ta main à ta sœur, puisqu'il n'y a qu'elle...\n\n*(la fin est déchirée et manque)*"},{"id":"lettres-etienne","title":"Les lettres d'Étienne (extrait de la dernière)","scene":"la-chapelle","text":"*Saint-Pierre, le 2 octobre 1889*\n\nMa Clémence,\n\nC'est la onzième lettre, et tu ne m'as pas répondu une seule fois. Je me dis que les courriers se perdent, que la mer les mange. Alors j'écris quand même.\n\nNous rentrons en avril. Attends-moi à la crique, comme le dernier soir. Je t'apporterai un coquillage pour chaque lettre que tu n'as pas reçue.\n\nTon Étienne"},{"id":"confession-adelaide","title":"Confession d'Adélaïde","scene":"la-chapelle","text":"*Le Clos-Aubert, 1890*\n\nJ'ai pris ses lettres. Je voulais qu'il m'aime, moi, puisque nous avions le même visage. Elle est descendue à la mer à trois heures dix, et je n'ai rien fait.\n\nDepuis, elle revient. Mais quand les horloges tournent, elle reste en bas, dans l'eau. Alors je les remonterai chaque soir, toutes, jusqu'à ma mort.\n\nQue Dieu me pardonne, puisqu'elle ne le peut pas.\n\n*A. d'A.*"}]}$story$::jsonb, now()
where not exists (select 1 from public.stories where visibility = 'marketplace' and content #>> '{meta,id}' = 'la-dame-de-trois-heures-dix');

insert into public.stories (visibility, content, published_at)
select 'marketplace', $story${"format":"grimoire-story/1","meta":{"id":"la-derniere-seance","title":"La Dernière Séance","lang":"fr","summary":"Mars 1926, Montmartre. Le Mirage, petit cinéma de la rue des Trois-Frères, ferme ses portes. Pour sa dernière séance, il projette une dernière fois L'Invitation, un film muet tourné en 1919 et jamais sorti, dont tout le quartier parle à voix basse : on dit qu'à chaque projection, quelqu'un ne ressort pas.","players":{"min":4,"max":5},"duration":"1 à 2 heures","era":"Samedi 20 mars 1926","setting":"Le Mirage, petit cinéma de quartier de la rue des Trois-Frères, à Montmartre (Paris)","system":"d100","author":"Grimoire","license":"CC-BY-4.0","version":"1.1","tags":["groupe","court","une soirée","cinéma","Paris","huis clos","enquête"],"contentWarnings":["incendie","enfermement (sortie de secours cadenassée, foule piégée)","disparitions","panique de foule"]},"overview":{"secret":"En 1912, des ouvriers qui consolidaient les anciennes carrières de gypse sous la Butte Montmartre ont trouvé un bloc de cristal limpide qui ne reflétait rien. Ils l'ont appelé **la Prunelle**, parce qu'il semblait regarder. Le cinéaste **Octave Lanzac**, qui méprisait les acteurs et voulait « filmer les gens entiers », l'a acheté en 1917 et en a fait tailler un objectif. Ce que la Prunelle filme, quand on s'offre à elle, elle le garde dans l'image : corps et âme. En 1919, Lanzac tourne *L'Invitation*, qui finit sur un bal masqué : au milieu des danseurs, sept costumes vides sur des portemanteaux, sept masques. Son bal doit avoir sept invités, « pas un de moins ». Dans la nuit du vendredi 31 octobre au 1er novembre 1919, Lanzac se filme lui-même parmi les costumes et disparaît : c'est le premier invité. On le dit mort, le film n'est jamais sorti. Le dimanche 18 octobre 1925, **Prosper Courtade**, propriétaire du Mirage, achète aux Puces de Saint-Ouen une caisse de bobines et le carnet de Lanzac. Il projette le film le dernier samedi de chaque mois. À chaque séance, pendant le bal, une torpeur tombe sur la salle ; le masque vide suivant choisit le spectateur qui regarde le plus fixement, qui se lève, entre dans le faisceau et disparaît dans l'écran. Son visage est désormais sous un masque baissé, son nom s'ajoute au générique, et la bobine 5 grandit d'une seconde. Cinq fois : la pianiste Berthe Lacombe (31 octobre), Anatole Brisset (28 novembre), Suzanne Ferrand (26 décembre), Piotr Volkine (30 janvier), Émile Marchal (27 février). Courtade a reconnu Brisset sur l'écran dès décembre et a continué : les recettes montaient, et il lui faut sa retraite. Ce soir, **samedi 20 mars 1926**, dernière séance avant la fermeture, le septième masque prendra son invité et le film sera achevé. Achevé, il n'aura plus besoin du Mirage : il voudra être vu partout. Or **Fernand Delmas**, distributeur, qui a vu le film en février et en rêve chaque nuit, en a acheté l'unique copie : lundi 22 mars, un laboratoire de Joinville en tirera quarante copies, et chacune sera un nouveau bal à remplir, dans chaque salle de province. Ce soir, le bal ne se contente pas d'attendre : il sort de l'écran et envahit la salle pour aller chercher son dernier invité. Trois issues, toutes dans la cabine : **brûler** la bobine (le nitrate flambe, la salle peut brûler, et les cinq disparus sont perdus avec Lanzac) ; la passer **à rebours** (les cinq reviennent, mais Lanzac reste, et un vivant doit prendre de son plein gré la dernière place) ; ou **la laisser finir** et arrêter Delmas ensuite. Si personne n'intervient : l'élu disparaît, quarante copies partent le 1er avril, et dans six mois on disparaîtra dans les cinémas de Lyon, de Lille et de Liège.","steps":["[[devant-le-mirage]] (20 h 30) : la file sous la pluie, Louise et la photo de son frère, la voiture de Delmas, Courtade à la porte.","[[avant-la-seance]] (20 h 40 – 21 h) : le groupe se partage la cabine (Gaston, le registre, la bobine 5), le bureau (le carnet de Lanzac, le contrat, les objets trouvés) et le foyer (Irène Saulnier, Delmas, la sortie cadenassée).","[[la-seance]] (21 h – 22 h 20) : le générique et ses invités, l'entracte, le bal, les visages des disparus, et le septième masque qui choisit.","[[le-bal]] (vers 22 h 20) : la salle devient le bal. Retenir l'élu, atteindre la cabine, et choisir : brûler, passer à rebours, ou laisser finir.","[[epilogue]] : l'incendie, le retour des invités, ou la voiture de Delmas."],"mustNotMiss":["**Le film prend un spectateur à chaque séance** : le registre de Gaston, ouvert sur l'établi (sans jet, [[avant-la-seance]]) ; Louise et la coupure de journal ([[devant-le-mirage]]) ; les objets trouvés du bureau ; les visages sur l'écran ([[la-seance]]).","**Ce soir, c'est le septième et dernier invité, et le film achevé sera copié** : le générique et sa septième ligne vide (sans jet, [[la-seance]]) ; Gaston et ses sept masques ; le carnet de Lanzac ; le contrat de Delmas ([[avant-la-seance]]).","**Tout se joue dans la cabine** : le carnet, la lettre d'Irène et Gaston donnent les trois issues (brûler, à rebours, laisser finir). Pendant le bal, le faisceau du projecteur ramène à la cabine ([[le-bal]])."],"branches":["Brûler la bobine : le film est détruit, les cinq disparus et Lanzac avec. Si les volets de fer des hublots tombent, le feu reste dans la cabine ; sinon la salle brûle, avec deux cents personnes derrière une sortie cadenassée.","La passer à rebours : les cinq disparus reviennent, vivants. Lanzac reste, et quelqu'un doit prendre de son plein gré la dernière place : un investigateur, Irène, Courtade, ou Delmas envoûté qu'on laisse faire.","Laisser finir : l'élu disparaît, le film est achevé. Il faut ensuite reprendre les bobines à Delmas : dans la rue, à son bureau dimanche, ou au laboratoire lundi ([[epilogue]]).","Chaîne retirée de la sortie de secours avant la séance : si le feu passe dans la salle, tout le monde peut sortir.","Louise changée de place ou tenue loin de l'écran : le septième masque choisit un investigateur."],"ifStuck":["À l'entracte, Gaston descend de la cabine, livide, son registre à la main : « La bobine 5 est chaude. Elle n'a jamais été chaude. »","Irène donne la dernière lettre de Lanzac à l'entracte, dès qu'on lui parle des disparus.","Dans le bal, Lanzac désigne le hublot de la cabine et articule deux mots : « À rebours. »","Le faisceau du projecteur traverse le bal comme une colonne de poussière blanche : le remonter mène à la cabine."],"keeperTips":["Rythme : une dizaine de minutes dans la rue, vingt-cinq avant la séance (le groupe se sépare), vingt pour la projection, une demi-heure pour le bal, dix pour l'épilogue.","À quatre ou cinq, séparez le groupe avant la séance et donnez un rôle à chacun dans le bal : retenir l'élu, la cabine, Delmas, la sortie, Lanzac.","Le film passe sans musique depuis la disparition de la pianiste : faites entendre le cliquetis du projecteur, la pluie sur le toit, les toux, les rires nerveux. La valse du piano, au bal, n'en sera que plus forte.","Le surnaturel reste caché jusqu'à la bobine 5 : seuls quelques visages minuscules sur la pellicule, dans la cabine, l'annoncent.","Courtade n'est pas un monstre : un vieux forain fatigué, qui a eu besoin d'argent et a fermé les yeux. Delmas n'est pas un méchant : il est envoûté, et il ne le sait pas.","Irène Saulnier est le cœur triste de l'histoire : elle a aimé Lanzac, et elle est venue voir son dernier film.","Laissez les joueurs compter : sept masques, six visages, une place."]},"acts":[{"id":"avant","title":"Avant la séance","scenes":[{"id":"devant-le-mirage","title":"Rue des Trois-Frères","lead":"20 h 30, la file devant le Mirage : la sœur d'un disparu, le distributeur, le propriétaire.","screen":{"place":"street","preset":"rain","time":"night"},"readAloud":["Une pluie fine fait briller les pavés de la rue des Trois-Frères. Sous une marquise dont la moitié des ampoules sont mortes, une enseigne peinte annonce : LE MIRAGE. La file d'attente déborde déjà sur le trottoir d'en face.","Sur l'affiche, près de la caisse, une bande de papier rouge barre le programme : DERNIÈRE SÉANCE. Dans la file, quelqu'un dit à voix basse que ce soir encore, quelqu'un ne ressortira pas. Personne ne rit."],"flow":[{"title":"L'affiche","text":"Collée près de la caisse vitrée → {{handout:affiche}}.","extra":"Le film n'a jamais été distribué. Tout le monde croit que Lanzac est mort pendant le tournage."},{"title":"Les accroches","text":"Chaque investigateur arrive avec sa raison d'être là (voir *Accroches*). Faites-les se croiser dans la file : c'est là que le groupe se forme."},{"title":"Louise Marchal","text":"{{npc:louise-marchal}} remonte la file, une photographie à la main : un jeune homme en casquette, qui sourit. « Vous l'avez vu ? Émile Marchal. Il est entré ici le 27 février, il n'est jamais rentré. » Elle montre la coupure de journal qu'elle garde dans son sac → {{handout:coupure-echo}}.","extra":"Pas de jet. Elle compte s'asseoir au premier rang, au milieu, pour voir le film « de près »."},{"title":"Les bruits de la file","text":"Faire parler les habitués qui attendent sous la pluie.","roll":{"type":"skill","options":["charm","fast-talk"]},"success":"Une concierge de la rue Ravignan : chaque dernier samedi du mois, quelqu'un manque à la sortie. La pianiste, Mlle Lacombe, en octobre : depuis, plus personne ne veut jouer pour ce film. Le père Brisset, qui s'asseyait toujours au premier rang. Un chauffeur de taxi russe. « Et la police s'en moque. »","failure":"Des plaisanteries, des paris : « Moi, je m'assieds au fond, près de la porte ! » Un nom revient pourtant : Mlle Lacombe, la pianiste, partie un soir sans son châle."},{"title":"La voiture de Delmas","text":"Une Hotchkiss noire se gare, chauffeur en livrée. {{npc:fernand-delmas}}, manteau à col de fourrure, serre la main de Courtade sur le trottoir et parle fort : quarante copies, la province, la Belgique, la Suisse. « Le film dont toute la France va parler ! »","roll":{"type":"skill","options":["psychology"]},"success":"Il a les yeux cernés d'un homme qui ne dort plus, et il parle du film comme d'une femme dont il serait amoureux.","failure":"Un homme d'affaires content de lui, qui a flairé la bonne affaire."},{"title":"Prosper Courtade","text":"{{npc:firmin-courtade}} accueille ses clients à la porte, trop pâle et trop jovial. S'il a engagé un investigateur, il l'attire à l'écart : « Surveillez la salle. Tout le monde. Ce soir, je veux que tout le monde ressorte. » Il a fait cadenasser la sortie de secours, sur l'impasse.","roll":{"type":"skill","options":["psychology"]},"success":"Il sait quelque chose qu'il ne dit pas, et il en a honte.","failure":"Un vieux patron nerveux, un soir de fermeture.","goto":["avant-la-seance"]}],"notes":[{"title":"Accroches","items":["**Engagé par Courtade** : ancien policier, détective privé ou costaud du quartier. Cinquante francs pour « surveiller la salle et voir qui part avant la fin ».","**Un proche d'un disparu** : cousin ou ami d'Émile Marchal (il vient avec Louise), ancien fiancé de Suzanne Ferrand, collègue de taxi de Piotr Volkine, voisin de palier de Berthe Lacombe.","**Journaliste** : envoyé par un grand quotidien après l'article de *L'Écho de la Butte*, pour un papier amusant sur les superstitions de Montmartre.","**Collectionneur ou cinéphile** : Lanzac est une petite légende des ciné-clubs, un film inédit de lui ne se rate pas. Il espère racheter la copie avant Delmas.","**Ami d'Irène Saulnier** : médecin, neveu, ancien partenaire de scène. Elle tient à voir le dernier film qu'elle a tourné, il l'accompagne.","**Policier** : un inspecteur à qui l'on a confié la plainte de Louise « pour la forme », venu voir par acquit de conscience.","**Habitué du quartier** : peintre, étudiant, musicien. Un musicien peut proposer de tenir le piano ce soir : Courtade accepte, soulagé (et le pianiste regarde l'écran de très près…)."]},{"title":"Ce soir au Mirage","items":["Environ deux cents spectateurs, la salle est complète : des curieux attirés par la rumeur, des peintres, des étudiants, des couples, quelques mauvais garçons.","{{npc:firmin-courtade}} à la porte, {{npc:gaston-ribiere}} dans sa cabine, {{npc:fernand-delmas}} et son chauffeur, {{npc:louise-marchal}} au premier rang.","{{npc:irene-saulnier}} arrive en taxi à 20 h 45, seule, sous une voilette noire.","Pas de pianiste : depuis octobre, le film passe sans musique."]},{"title":"Montmartre en 1926","items":["La Butte des cabarets, des escaliers et des moulins. Les peintres sont partis pour Montparnasse, les touristes sont arrivés.","Sous la colline, d'anciennes carrières de gypse, vides et étayées : on en parle comme d'un autre quartier, sous le premier.","Au-dessus des toits, le Sacré-Cœur, consacré il y a sept ans à peine."]}],"npcs":["louise-marchal","fernand-delmas","firmin-courtade"],"handouts":["affiche","coupure-echo"],"ambience":["street","rain"],"sfx":["footsteps","dog-bark","door-open"],"next":["avant-la-seance"]},{"id":"avant-la-seance","title":"Le Mirage, avant la séance","lead":"20 h 40 – 21 h : trois pistes à se partager : la cabine, le bureau, le foyer.","screen":{"place":"street","preset":"bulb","time":"night"},"readAloud":["Le foyer sent la laine mouillée, le tabac et le poêle à charbon. Au-dessus de la buvette, une ampoule nue grésille, s'éteint, se rallume. Par la porte battante, on aperçoit la salle : deux cents fauteuils de velours râpé, un piano sous sa housse, et l'écran, immense et blanc, qui attend.","Au fond du foyer, un escalier de fer monte vers une porte blindée. Derrière, quelque chose cliquette, régulier, comme une horloge qu'on remonte."],"flow":[{"title":"Se partager","text":"Vingt minutes avant l'extinction des lumières. Trois endroits : la **cabine** de projection (en haut de l'escalier de fer), le **bureau** de Courtade (derrière la caisse), le **foyer** et la salle (Irène Saulnier, Delmas, Louise, la sortie de secours).","extra":"Laissez le groupe se séparer : chaque piste donne un morceau. Ce qui n'a pas été trouvé peut l'être à l'entracte ([[la-seance]])."},{"title":"La cabine : Gaston","text":"{{npc:gaston-ribiere}} prépare les cinq bobines. Le règlement interdit la cabine au public, mais il a peur et il le cache mal. Son registre est ouvert sur l'établi, sans jet → {{handout:registre-cabine}}.","roll":{"type":"skill","options":["persuade","psychology","charm"]},"success":"En janvier, il a regardé une seule fois par le hublot pendant le bal : un homme marchait dans le faisceau, droit vers l'écran, et il est entré dedans. Depuis, il tourne la manivelle de la dernière bobine les yeux fermés, en comptant. « Sept masques. Il en reste un. »","failure":"« Je passe les films, je ne les regarde pas. » Mais il ne referme pas le registre.","pushed":"Il les met dehors et verrouille la porte blindée. Il ne rouvrira qu'à l'entracte."},{"title":"La bobine 5","text":"Dérouler la fin de la bobine 5 devant l'ampoule, à la loupe : la scène du bal, des danseurs, et sept silhouettes masquées alignées.","roll":{"type":"skill","options":["spot-hidden"]},"success":"Sur les dernières images, six masques baissés et six visages minuscules, nets comme des photographies : un homme maigre en habit, une femme aux cheveux gris, un vieillard moustachu, une jeune femme, un homme aux pommettes hautes, un jeune homme. Le septième costume porte encore son masque, et entre le masque et le col, il n'y a pas de cou : rien (SAN 0/1).","failure":"Des images minuscules et sombres, des masques. Gaston reprend la pellicule : « Ne traînez pas sous l'ampoule avec ça. Le nitrate, ça part comme de la poudre. »"},{"title":"Le nitrate","text":"Gaston montre ses mains couturées de brûlures : un incendie de cabine à Belleville, en 1921. Le nitrate brûle même sous l'eau, une bobine flambe en quelques secondes, et si la pellicule se bloque devant la lampe, elle prend feu. Les deux hublots ont des **volets de fer** qui tombent quand le cordon fusible fond, et un levier pour les fermer à la main. Ils sont rouillés : il l'a dit cent fois au patron.","extra":"Personne à Paris n'a oublié le Bazar de la Charité (1897) : un projecteur, plus de cent vingt morts."},{"title":"Si on parle de passer le film à l'envers","text":"Gaston hausse les épaules : les forains le faisaient pour amuser le public, les plongeurs qui ressortent de l'eau. On coupe, on remonte la bobine réceptrice en tête, pellicule retournée, et le film repasse à rebours. Deux minutes, pour qui a la main."},{"title":"Le bureau de Courtade","text":"Derrière la caisse, un bureau encombré de vieilles affiches. Courtade est à la porte de la salle, le bureau n'est pas fermé. Sous la table, une caisse marquée OBJETS TROUVÉS : un châle de laine, une canne à pommeau d'os, un sac à main perlé, une casquette de chauffeur de taxi, une écharpe grise.","extra":"Pas de jet. Cinq objets, cinq séances : le registre de Gaston dit où et quand chacun a été trouvé."},{"title":"Fouiller le bureau","roll":{"type":"skill","options":["spot-hidden","library-use"]},"success":"Dans le tiroir, sous des factures, le **carnet d'Octave Lanzac**, trouvé avec les bobines → {{handout:carnet-lanzac}}. Sur le sous-main, le double du **contrat** signé avant-hier → {{handout:contrat-delmas}}.","failure":"Le contrat est sur le sous-main, bien en vue → {{handout:contrat-delmas}}. Le carnet est là aussi, mais Courtade revient avant qu'on le trouve : il faudra le lui demander.","pushed":"Ils trouvent tout, mais Courtade les surprend la main dans le tiroir. Il crie, parle d'appeler les agents, puis s'effondre sur une chaise : passez à l'étape suivante, sans jet."},{"title":"Faire avouer Courtade","text":"Lui montrer les objets trouvés, le registre, la photo d'Émile.","roll":{"type":"skill","options":["psychology","intimidate","persuade"]},"success":"Il avoue : en décembre, il a reconnu le père Brisset sur l'écran, sous un masque baissé. Il a continué : la salle se remplissait, et Delmas lui offre quinze mille francs, sa retraite. Il donne le carnet de Lanzac. « Ce soir, j'ai fait mettre une chaîne à la sortie. Je veux voir de mes yeux qui s'en va. »","failure":"« Des gens partent avant la fin, voilà tout ! » Il s'enferme dans son bureau jusqu'à l'extinction des lumières."},{"title":"Le foyer : Irène Saulnier","text":"Une dame âgée, voilette noire, seule près du poêle : {{npc:irene-saulnier}}. Elle jouait la mère dans *L'Invitation* et n'a jamais vu le film monté. Elle parle volontiers de Lanzac, « un génie qui détestait les acteurs », et du dernier jour de tournage : sept costumes de bal sur des portemanteaux, sept masques. « Il disait que les invités viendraient plus tard. »","roll":{"type":"skill","options":["charm","psychology"]},"success":"Elle sort de son sac la dernière lettre de Lanzac, reçue la veille de sa disparition, qu'elle n'a jamais comprise → {{handout:lettre-irene}}.","failure":"Elle parle de lui avec tendresse, sans plus. Elle donnera la lettre à l'entracte, si on lui parle des disparus."},{"title":"Le foyer : Delmas","text":"{{npc:fernand-delmas}} offre le champagne à la buvette. Il a vu le film le 27 février, le soir où Émile Marchal a disparu. Il montre volontiers son contrat → {{handout:contrat-delmas}} : les bobines partent lundi pour le laboratoire de Joinville.","roll":{"type":"skill","options":["psychology"]},"success":"Il rêve du bal toutes les nuits depuis février. Il ne se souvient pas d'avoir ajouté à la main la clause « y compris la scène du bal », et ça le fait rire.","failure":"Un marchand de films qui a flairé la bonne affaire."},{"title":"La salle et la sortie","text":"La porte de secours, sur l'impasse, est fermée par une chaîne et un cadenas neuf ; la clé est au trousseau de Courtade. Louise est déjà assise au premier rang, au milieu. Convaincre Courtade d'enlever la chaîne :","roll":{"type":"skill","options":["persuade","credit-rating"]},"success":"Il grogne, mais enlève la chaîne.","failure":"« Pas ce soir. Ce soir, personne ne sort avant la fin. »","extra":"Si le feu prend pendant le bal, cette chaîne fait toute la différence."}],"notes":[{"title":"Le Mirage","items":["Un ancien café-concert, devenu cinéma en 1908. **La rue** : marquise, caisse vitrée, affiches.","**Le foyer** : buvette, poêle, banquettes ; au fond, l'escalier de fer et la porte blindée de la cabine.","**Le bureau**, derrière la caisse : affiches, coffre, caisse d'objets trouvés, carnet de Lanzac dans le tiroir.","**La salle** : deux cents fauteuils en pente douce, un piano sous sa housse devant l'écran, une seule porte vers le foyer, et la sortie de secours sur l'impasse, cadenassée ce soir.","**La cabine**, au-dessus du foyer : projecteur à manivelle et lampe à arc, deux hublots à volets de fer (cordon fusible et levier), établi de réembobinage, seau de sable, cinq boîtes de fer."]},{"title":"Les cinq disparus","items":["31 octobre 1925 : **Berthe Lacombe**, 52 ans, pianiste du Mirage. Son châle sur le tabouret.","28 novembre : **Anatole Brisset**, 67 ans, cheminot retraité, toujours au premier rang. Sa canne.","26 décembre : **Suzanne Ferrand**, 22 ans, cousette, venue avec son fiancé. Son sac perlé, au troisième rang.","30 janvier 1926 : **Piotr Volkine**, 41 ans, ancien officier russe devenu chauffeur de taxi. Sa casquette, au deuxième rang.","27 février : **Émile Marchal**, 23 ans, typographe, frère de Louise. Son écharpe grise, au premier rang."]},{"title":"Chronologie de la soirée","items":["20 h 30 : ouverture des portes. 20 h 45 : Irène Saulnier arrive.","21 h : extinction des lumières, bobines 1 à 3.","21 h 45 : entracte, dix minutes.","21 h 55 : bobines 4 et 5. Vers 22 h 15, le bal ; vers 22 h 20, les masques tombent.","22 h 40 : si le film est allé au bout, Delmas emporte les bobines."]}],"npcs":["gaston-ribiere","firmin-courtade","irene-saulnier","fernand-delmas","louise-marchal"],"handouts":["registre-cabine","carnet-lanzac","contrat-delmas","lettre-irene"],"ambience":["crowd-indoor","rain-window","clock"],"sfx":["door-creak","latch","footsteps"],"next":["la-seance"]}]},{"id":"seance","title":"La séance","scenes":[{"id":"la-seance","title":"L'Invitation","lead":"21 h – 22 h 20 : le générique, l'entracte, le bal, les visages, et le septième masque qui choisit.","screen":{"place":"manor","preset":"night","time":"night"},"readAloud":["Les lumières baissent. Dans le noir, deux cents personnes se taisent d'un coup. Derrière vous, le projecteur se met à cliqueter, et un faisceau de poussière blanche passe au-dessus des têtes.","Pas de piano ce soir. Le film commence dans un silence complet, troublé seulement par la pluie sur le toit."],"flow":[{"title":"Le générique","text":"Premier carton : le titre, les acteurs, puis une liste qui n'a rien à faire là → {{handout:generique}}. Pas de jet : tout le monde peut lire les noms. Au premier rang, Louise étouffe un cri.","roll":{"type":"san","label":"Les noms des disparus","san":"0/1"}},{"title":"L'invitation","text":"Lise, l'héroïne, reçoit un carton d'invitation, qui remplit l'écran → {{handout:carton-invitation}}.","extra":"Le carton dit « vous ». Dans la salle, quelques rires nerveux, vite éteints."},{"title":"Les trois premières bobines","text":"Une jeune fille, sa mère (Irène Saulnier, qui pleure sans bruit en se voyant sept ans plus jeune), un inconnu qui l'invite à un bal dans une maison sans nom. Certains plans sont d'une netteté impossible pour 1919 : le grain de la peau, la buée des respirations. Les acteurs semblent regarder la salle.","roll":{"type":"skill","options":["spot-hidden","art-craft:photography"]},"success":"Les plans ordinaires sont flous et rayés, comme tous les films de 1919. Seuls certains plans sont parfaits : ceux tournés à la Prunelle (voir le carnet). Les visages, dans ces plans-là, ne jouent pas : ils regardent.","failure":"Un beau film, étrange, un peu lent."},{"title":"L'entracte","text":"21 h 45, dix minutes de lumière. Dernière chance pour monter à la cabine, fouiller le bureau, parler à Irène (elle donne alors {{handout:lettre-irene}}), faire enlever la chaîne, changer Louise de place. Courtade et Delmas trinquent à la buvette.","extra":"Gaston descend, livide, et cherche les investigateurs : « La bobine 5 est chaude. Elle n'a jamais été chaude. »"},{"title":"Le bal commence","text":"Vers 22 h 15, bobine 5 : la maison sans nom, une salle de bal immense sous des lustres. Au milieu des danseurs, sept invités masqués, immobiles. Une torpeur douce tombe sur la salle : les têtes s'inclinent, le temps semble court. Chaque investigateur qui regarde l'écran fait un jet de POU.","roll":{"type":"characteristic","options":["POW"],"label":"Torpeur (chaque investigateur)"},"success":"L'investigateur garde les yeux ouverts et l'esprit clair.","failure":"Il est captivé : un dé de malus à tous ses jets jusqu'à ce qu'on le secoue. Il ne voit pas qu'on se lève dans la salle.","extra":"Détourner les yeux, fermer les yeux ou regarder vers le projecteur protège de la torpeur, sans jet."},{"title":"Les masques tombent","text":"La caméra glisse devant les sept invités. Un à un, ils baissent leur masque : un homme maigre qui sourit, une femme aux cheveux gris, un vieillard moustachu, une jeune femme, un homme aux pommettes hautes, Émile Marchal. Louise crie son nom. Irène, elle, murmure : « Octave… ». Lanzac n'a jamais joué dans son film.","roll":{"type":"san","label":"Les visages du bal","san":"0/1D4"},"extra":"Avec le registre, les objets trouvés ou le générique, on met un nom sur chaque visage, dans l'ordre."},{"title":"Le septième masque","text":"Le septième invité ne baisse pas son masque. Il tourne la tête, lentement, vers la salle, et regarde quelqu'un : **Louise**, au premier rang, ou, si elle n'y est plus, l'investigateur qui a le plus mal raté son jet de torpeur. L'élu se lève et marche vers l'écran. Si l'élu est un investigateur, il fait un jet de POU difficile.","roll":{"type":"characteristic","options":["POW"],"difficulty":"hard","label":"Résister au septième masque (l'élu)"},"success":"L'élu s'arrête et se débat. Le masque le regarde toujours. (Louise, elle, rate toujours.)","failure":"L'élu marche, souriant, les bras ouverts comme pour une danse.","extra":"Quel que soit le résultat, le faisceau s'élargit et la salle bascule : c'est le dernier invité, et le bal vient le chercher.","goto":["le-bal"]}],"npcs":["louise-marchal","irene-saulnier","septieme-masque"],"handouts":["generique","carton-invitation","lettre-irene"],"ambience":["clock","rain-window"],"sfx":["footsteps","door-creak"],"next":["le-bal"]},{"id":"le-bal","title":"Le bal","lead":"La salle devient le bal. Huit rounds pour retenir l'élu, atteindre la cabine et choisir : brûler, à rebours, ou laisser finir.","screen":{"place":"manor","preset":"nightmare","time":"night"},"readAloud":["Le faisceau s'ouvre comme une porte. Les fauteuils ont disparu : sous vos pieds, un parquet ciré ; au-dessus, des lustres de cristal où brûlent des bougies qui ne fument pas. Tout est gris et argent, comme sur l'écran. Vos mains aussi.","Sous sa housse, le piano joue une valse. Autour de vous, les spectateurs dansent les yeux fermés avec des invités masqués. Très haut, au fond, brille un petit rectangle de lumière blanche : le hublot de la cabine."],"flow":[{"title":"La salle devient le bal","text":"Lancez le compteur *La valse* (0/8). Il avance d'un cran à la fin de chaque round. À 8, le septième masque tombe sur le visage de l'élu : le film est achevé.","roll":{"type":"san","label":"La salle devient le bal","san":"1/1D6"}},{"title":"Qui fait quoi","text":"Le groupe n'a pas le temps de tout faire ensemble. Donnez un rôle à chacun : **retenir l'élu**, **trouver la cabine**, **tenir Delmas**, **la sortie et la foule**, **parler à Lanzac**.","extra":"Les captivés de la séance se réveillent en tombant dans le bal, mais gardent leur dé de malus pour ce premier round."},{"title":"Retenir l'élu","text":"L'élu marche vers l'écran au milieu des danseurs. Le retenir par la voix (Persuasion), ou de force (FOR, jets rapides de la scène).","roll":{"type":"skill","options":["persuade"]},"success":"Ce round, l'élu ne fait pas un pas : *la valse* n'avance pas. Trois fois au plus dans le bal : il finit toujours par gagner du terrain.","failure":"Il se dégage avec une force de somnambule. Un invité masqué invite celui qui le retenait à danser (jet de POU, jets rapides de la scène)."},{"title":"Trouver la cabine","text":"Les portes du fond ouvrent sur d'autres salons, d'autres valses ; l'escalier de fer n'est plus là. Remonter le faisceau du projecteur ramène droit à la cabine : pas de jet si un joueur y pense.","roll":{"type":"skill","options":["navigate","spot-hidden"]},"success":"La porte de fer est là, au bout du faisceau, où était le foyer.","failure":"Ils tournent en rond dans les salons : un round perdu, et un invité masqué les invite à danser ({{npc:les-invites}} : jet de POU, jets rapides de la scène).","pushed":"Ils trouvent la porte, mais l'un d'eux danse jusqu'à la fin du bal, les yeux fermés, et ne peut plus rien faire."},{"title":"Delmas","text":"Envoûté, {{npc:fernand-delmas}} garde la porte de la cabine, sa canne levée : « Laissez-le finir ! C'est le plus beau film du monde ! »","roll":{"type":"skill","options":["fighting-brawl","intimidate","persuade"]},"success":"Il recule, ou il tombe. La voie est libre.","failure":"Il frappe (canne, 1D6+1D4) et tient la porte un round de plus.","extra":"Lui montrer le visage d'Émile sur l'écran, ou lui lire la fin du carnet de Lanzac, donne un dé bonus."},{"title":"La sortie et la foule","text":"Deux cents dormeurs dansent autour d'eux. Si le feu prend, ils seront piégés derrière la sortie cadenassée. {{npc:firmin-courtade}} valse quelque part, les yeux ouverts, heureux, la clé du cadenas dans la poche de son gilet.","roll":{"type":"skill","options":["spot-hidden"]},"success":"Ils trouvent Courtade et prennent la clé : la sortie de secours pourra s'ouvrir d'un coup.","failure":"Courtade est introuvable. Si le feu prend, il faudra forcer la chaîne (FOR, difficile) ou le cadenas (Serrurerie)."},{"title":"Parler à Lanzac","text":"L'homme maigre du premier masque, c'est {{npc:octave-lanzac}}. Il danse seul, ravi. Irène peut l'appeler par son nom ; un investigateur aussi, s'il a lu le carnet ou la lettre.","roll":{"type":"skill","options":["persuade","charm"]},"success":"Lanzac s'arrête et regarde, pour la première fois, ce qu'est devenu son bal. Il désigne le hublot et articule deux mots : « À rebours. » *La valse* n'avance pas ce round (une seule fois).","failure":"Il sourit et tend la main : « Une seule danse ? » ({{npc:les-invites}} : jet de POU, jets rapides de la scène)."},{"title":"La cabine","text":"{{npc:gaston-ribiere}} est là, les yeux fermés, cramponné à la manivelle qui tourne toute seule et lui entraîne le bras. Le libérer :","roll":{"type":"characteristic","options":["STR"]},"success":"Gaston est libre ; la manivelle tourne seule. Il fera ce qu'on lui dit.","failure":"Gaston reste pris un round de plus et la manivelle lui tord le bras (1D3).","extra":"Arrêter le moteur, couper le courant, ôter la bobine : le bal continue sans projecteur. Il ne reste que trois issues."},{"title":"Le choix","text":"Le carnet, la lettre d'Irène et Gaston donnent les trois issues. Les joueurs ont la bobine sous les yeux, et *la valse* tourne."},{"title":"Brûler la bobine","branch":"Si on brûle la bobine","text":"Bloquer la manivelle (la pellicule s'arrête devant la lampe et s'enflamme d'un coup), ou une allumette sur les bobines. Pas de jet. Le bal crie. Sur l'écran, les sept visages fondent et brûlent. Les invités s'effacent, les fauteuils reviennent, la salle se réveille dans une fumée âcre.","roll":{"type":"san","label":"Les visages qui brûlent","san":"1/1D6"},"extra":"Les cinq disparus et Lanzac sont perdus pour toujours. Écran d'ambiance : passez sur « blaze ». Suite : « Le feu : … » ci-dessous."},{"title":"À rebours","branch":"Si on passe la bobine à rebours","text":"Couper la scène du bal, remonter la bobine réceptrice en tête, pellicule retournée, et relancer. Deux rounds, et *la valse* continue d'avancer. Si Gaston est libre et le fait, pas de jet. Si *la valse* atteint 8 avant que le film reparte, il est achevé (« Laisser finir »).","roll":{"type":"skill","options":["mechanical-repair","operate-heavy-machinery"]},"success":"Le projecteur repart. Sur l'écran, le bal tourne à l'envers : les masques remontent, les invités reculent et sortent du faisceau un à un, tombant dans les allées. Berthe Lacombe, Anatole Brisset, Suzanne Ferrand, Piotr Volkine, Émile Marchal : vivants, dans leurs vêtements du soir où ils sont partis, un masque à la main. *La valse* s'arrête là. Suite : « À rebours : la place à tenir ».","failure":"La pellicule se déchire : un round perdu pour la recoller.","pushed":"La pellicule se coince devant la lampe et prend feu : comme « Brûler la bobine »."},{"title":"Laisser finir","branch":"Si personne n'arrête le film","text":"À 8 sur *la valse*, le septième masque tombe : dessous, le visage de l'élu, qui a disparu de la salle. La valse s'arrête. Les lumières reviennent sur un cinéma ordinaire, deux cents personnes qui se frottent les yeux. Sur l'écran, un dernier carton : FIN.","roll":{"type":"san","label":"Le septième visage","san":"1/1D4"},"extra":"Le film est achevé : il ne prendra plus personne au Mirage. Delmas emporte les bobines : [[epilogue]].","goto":["epilogue"]},{"title":"Le feu : les volets de fer","text":"Le nitrate flambe en quelques secondes, une fumée jaune et toxique remplit la cabine. Les volets des hublots doivent tomber.","roll":{"type":"luck"},"success":"Le cordon fusible fond, les volets tombent. Le feu reste dans la cabine.","failure":"Les volets rouillés restent coincés. Un investigateur peut tirer le levier à la main (FOR ou Mécanique, 1D4 de brûlures) ; sinon les flammes passent par les hublots et prennent aux tentures de la salle."},{"title":"Le feu : sortir de la cabine","roll":{"type":"characteristic","options":["DEX"]},"success":"Dehors par la porte de fer, devant la fumée.","failure":"Brûlures et fumée : 1D6 points de vie."},{"title":"Le feu : la salle","text":"Si les flammes passent dans la salle : lancez le compteur *Le feu* (0/5), qui avance à chaque round. Deux cents personnes réveillées en sursaut, une seule sortie par le foyer, et la sortie de secours, si personne n'a la clé ou n'a enlevé la chaîne.","roll":{"type":"skill","options":["persuade","intimidate","fast-talk"]},"success":"La foule sort en ordre par le foyer et par la sortie de secours, si elle est ouverte. Personne ne meurt.","failure":"Panique : on tombe, on piétine. Tant que la sortie de secours reste fermée, à 5 sur *le feu*, il reste des gens dans la salle.","goto":["epilogue"]},{"title":"À rebours : la place à tenir","text":"Le bal se vide, mais Lanzac reste : il n'est pas un invité, il est l'hôte. Le septième masque attend, tendu vers la salle, et le bal tire sur tout le monde. Il faut qu'un vivant le prenne, de son plein gré, avant la fin de la bobine (deux rounds). Qui ?","extra":"Irène s'avance d'elle-même : « Il m'a attendue assez longtemps. » Courtade le propose aussi, s'il a avoué. Delmas, envoûté, y marche tout seul si on ne le retient pas : le laisser faire est un choix. Si personne n'y va, le bal reprend tout ce qu'il a rendu, l'élu avec : le film est achevé (« Laisser finir »).","goto":["epilogue"]}],"rolls":[{"type":"characteristic","label":"Retenir l'élu de force (FOR)","options":["STR"]},{"type":"characteristic","label":"Refuser une danse (POU)","options":["POW"]},{"type":"damage","label":"Canne de Delmas","dice":"1D6+1D4"},{"type":"damage","label":"Brûlures (nitrate)","dice":"1D6"}],"notes":[{"title":"Les règles du bal","items":["Les invités masqués ne peuvent pas être blessés : les coups les traversent comme de la lumière.","Une invitation à danser : jet de POU (jets rapides de la scène). Raté, l'investigateur danse un round, sans rien pouvoir faire.","Rallumer les lumières de la salle, braquer une lampe sur un invité : il pâlit et recule d'un pas, rien de plus.","Les autres spectateurs dorment en dansant. Les réveiller de force ne sert à rien tant que dure le bal."]}],"npcs":["octave-lanzac","les-invites","septieme-masque","gaston-ribiere","fernand-delmas","firmin-courtade","irene-saulnier","louise-marchal"],"ambience":["crowd-indoor","clock","wind-howling"],"sfx":["door-slam","footsteps","latch"],"next":["epilogue"]}]},{"id":"apres","title":"Après","scenes":[{"id":"epilogue","title":"Après la dernière séance","lead":"Minuit sur la Butte : l'incendie, le retour des invités, ou la voiture de Delmas.","screen":{"place":"street","preset":"fog","time":"night"},"readAloud":["La pluie a cessé. Rue des Trois-Frères, les spectateurs se dispersent sans se regarder, comme on sort d'un rêve qu'on ne veut pas raconter.","Au-dessus des toits, la coupole blanche du Sacré-Cœur flotte dans la brume. Derrière vous, la marquise du Mirage. Plus personne n'y entrera pour voir un film."],"flow":[{"title":"Ce qui s'est passé dans la cabine","text":"Choisissez la suite selon le choix fait au [[le-bal|bal]]."},{"title":"L'incendie","branch":"Si le Mirage a brûlé","text":"Les pompiers arrivent en dix minutes. Gaston jure que c'est un accident de cabine, comme il y en a tant. Courtade regarde brûler sa salle sans pleurer. Un commissaire interroge les témoins.","roll":{"type":"skill","options":["fast-talk","persuade"]},"success":"Accident de nitrate, affaire classée.","failure":"Le commissaire a lu la plainte de Louise Marchal. Il convoque les investigateurs lundi : rien ne sera prouvé, mais leurs noms restent dans un dossier.","extra":"Écran d'ambiance : « blaze » tant que la salle brûle. Si les volets sont tombés, seule la cabine a brûlé et la salle est sauve."},{"title":"Le retour des invités","branch":"Si les invités sont revenus","text":"Cinq personnes égarées sur le trottoir, qui croient sortir de la séance de leur soir. Berthe Lacombe cherche son châle, Piotr Volkine son taxi. Pour eux, le bal n'a duré qu'une valse. Émile serre Louise dans ses bras.","roll":{"type":"skill","options":["psychology","persuade"]},"success":"Ils acceptent l'idée de mois perdus, sans comprendre. Ils ne parleront jamais du bal.","failure":"Suzanne Ferrand fait une crise de nerfs ; des agents l'emmènent à l'hôpital, et le quartier en parlera des semaines.","extra":"La bobine à rebours ne montre plus qu'un salon vide, un hôte et un invité masqué : celui qui a pris la place. Gaston la scelle dans sa boîte de fer."},{"title":"La voiture de Delmas","branch":"Si le film est achevé","text":"22 h 40 : Delmas charge les cinq boîtes dans le coffre de l'Hotchkiss. Ce soir et dimanche, elles dorment à son bureau, 42, rue du Faubourg-Saint-Denis ; lundi 22 mars à 8 h, son chauffeur les porte au laboratoire de Joinville. Trois occasions de l'arrêter (étapes suivantes).","extra":"Le convaincre ne marche pas tant qu'il est envoûté (Psychologie le montre). Lui faire lire le générique, avec ses sept noms, donne un dé bonus à toute tentative."},{"title":"Delmas : dans la rue, tout de suite","roll":{"type":"skill","options":["fast-talk","sleight-of-hand","drive-auto"]},"success":"Le chauffeur distrait, le coffre ouvert, un taxi en travers de la rue : les boîtes changent de mains.","failure":"La voiture démarre. Il reste le bureau et le laboratoire."},{"title":"Delmas : au bureau, dimanche","roll":{"type":"skill","options":["locksmith","stealth"]},"success":"Dans l'arrière-boutique déserte, les cinq boîtes attendent sur une étagère.","failure":"Le concierge les surprend : fuite par les toits, ou nuit au poste. Il reste le laboratoire."},{"title":"Delmas : au laboratoire, lundi","roll":{"type":"skill","options":["persuade","credit-rating","fast-talk"]},"success":"Le chef de laboratoire rend les boîtes, ou accepte de « perdre » la commande.","failure":"Le contretype est tiré. Quarante copies partiront le 1er avril."},{"title":"Ce qu'on fait des bobines","text":"Les brûler, loin de tout (le nitrate flambe comme une torche), ou les repasser à rebours au Mirage avant sa démolition, avec Gaston : les six invités reviennent, l'élu compris, au même prix (quelqu'un doit rester)."}],"notes":[{"title":"Épilogue","items":["**Film brûlé, salle sauve** (volets tombés, ou tout le monde sorti) : chaque investigateur regagne **1D6 SAN**. Les cinq disparus sont perdus : Louise ne pardonne pas, mais elle sait.","**Film brûlé, des morts dans l'incendie** : en plus, **1/1D6 SAN**. Les journaux reparlent du Bazar de la Charité ; Courtade est ruiné.","**À rebours** : chaque investigateur regagne **1D8 SAN**. Si un investigateur a pris la place, il quitte le jeu : on dit qu'il danse. Les autres perdent **0/1D4 SAN**. Brûler la bobine, plus tard, ce serait l'éteindre.","**Achevé, mais Delmas arrêté et les bobines détruites** : **1D4 SAN** regagnés, mais **1/1D4 SAN** pour l'élu perdu (davantage si c'était un ami).","**Achevé, et les copies parties** : perte de **1D6 SAN**. À l'automne, des journaux de Lyon, de Lille et de Liège parlent de spectateurs qui ne ressortent pas de leur cinéma."]}],"rolls":[{"type":"damage","label":"Gain de SAN (film détruit)","dice":"1D6"},{"type":"damage","label":"Gain de SAN (invités rendus)","dice":"1D8"},{"type":"damage","label":"Gain de SAN (Delmas arrêté)","dice":"1D4"}],"npcs":["fernand-delmas","louise-marchal","firmin-courtade","gaston-ribiere"],"ambience":["street","wind"],"sfx":["footsteps","dog-bark"]}]}],"npcs":[{"id":"firmin-courtade","name":"Prosper Courtade","role":"Propriétaire du Mirage","description":"Soixante-trois ans, gros, moustache blanche, gilet à chaîne de montre. Ancien forain qui promenait un cinématographe de foire en foire avant 1908.","personality":"Jovial en façade, rongé par la honte. Il veut sa retraite et ne veut pas savoir. Ce soir, il a peur, et il le noie dans le bavardage.","characteristics":{"STR":45,"CON":50,"SIZ":65,"DEX":40,"APP":45,"INT":65,"POW":45,"EDU":50},"hp":11,"dodge":20,"skills":{"credit-rating":35,"fast-talk":60,"persuade":50},"knows":["Il a acheté les cinq bobines et le carnet de Lanzac aux Puces de Saint-Ouen, le dimanche 18 octobre 1925, pour trente francs.","En décembre, il a reconnu le père Brisset, un habitué, sous un masque baissé du bal. Il a continué : les recettes montaient.","Il a vendu la copie à Delmas pour quinze mille francs (contrat signé le jeudi 18 mars). Le Mirage ferme à la fin du mois : l'immeuble est vendu pour en faire un garage.","Ce soir, il a fait cadenasser la sortie de secours pour voir de ses yeux qui s'en va. La clé est dans la poche de son gilet."]},{"id":"gaston-ribiere","name":"Gaston Ribière","role":"Projectionniste du Mirage","description":"Trente-quatre ans, maigre, mains couturées de brûlures, une cigarette éteinte au coin des lèvres (jamais allumée en cabine).","personality":"Ancien de Verdun, calme, précis, méthodique. Il a peur du film, mais plus encore de laisser sa cabine à quelqu'un d'autre.","characteristics":{"STR":60,"CON":55,"SIZ":55,"DEX":65,"INT":70,"POW":65,"EDU":55},"hp":11,"dodge":32,"skills":{"mechanical-repair":70,"electrical-repair":50,"art-craft:photography":50,"first-aid":40,"spot-hidden":55},"attacks":[{"name":"Coup de poing","skill":50,"damage":"1D3"}],"knows":["Il tient le registre de cabine : dates, entrées, incidents, longueur de la bobine 5, qui grandit de trente centimètres (une seconde) à chaque séance.","Le 30 janvier, il a vu par le hublot un homme entrer dans l'écran pendant le bal. Depuis, il tourne la dernière bobine les yeux fermés.","Le nitrate brûle même sous l'eau ; une pellicule bloquée devant la lampe prend feu. Les volets de fer des hublots sont rouillés.","Il sait repasser un film à l'envers : un vieux tour de forain."]},{"id":"fernand-delmas","name":"Fernand Delmas","role":"Distributeur de films (Delmas & Cie)","description":"Quarante-six ans, large, manteau à col de fourrure, canne à pommeau d'argent, chauffeur et Hotchkiss noire.","personality":"Marchand affable et sûr de lui. Depuis le 27 février, il rêve du bal chaque nuit et ne vit plus que pour ce film. Envoûté, il le défendra avec violence.","characteristics":{"STR":60,"CON":60,"SIZ":70,"DEX":50,"APP":55,"INT":65,"POW":40,"EDU":60},"hp":13,"dodge":25,"damageBonus":"+1D4","skills":{"persuade":60,"credit-rating":60,"psychology":40},"attacks":[{"name":"Canne","skill":50,"damage":"1D6+1D4"},{"name":"Coup de poing","skill":55,"damage":"1D3+1D4"}],"knows":["Il a vu le film le 27 février, attiré par les recettes du Mirage. Il ne se souvient pas d'avoir vu quelqu'un se lever.","Contrat signé le 18 mars : la copie lui est remise ce soir, après la séance. Lundi 22 mars, contretype et quarante copies au laboratoire Cinéchrome de Joinville-le-Pont.","Les bobines passeront la nuit et le dimanche à son bureau, 42, rue du Faubourg-Saint-Denis."]},{"id":"louise-marchal","name":"Louise Marchal","role":"Blanchisseuse, sœur d'Émile","description":"Dix-neuf ans, petite, les mains rougies par la lessive, un manteau trop grand qui était à son frère.","personality":"Têtue, courageuse, à bout. Personne ne l'a crue : ce soir, elle veut voir. Elle fera n'importe quoi pour Émile.","characteristics":{"STR":55,"CON":60,"SIZ":45,"DEX":60,"APP":55,"INT":55,"POW":60,"EDU":40},"hp":10,"dodge":30,"knows":["Émile Marchal, 23 ans, typographe, est allé voir le film le samedi 27 février et n'est jamais rentré. Il était assis au premier rang.","Elle a porté plainte au commissariat du quartier : on lui a ri au nez.","Elle a la coupure de *L'Écho de la Butte* du 13 mars et une photo d'Émile."]},{"id":"irene-saulnier","name":"Irène Saulnier","role":"Ancienne actrice, la mère dans L'Invitation","description":"Cinquante-huit ans, très droite, voilette noire, gants usés. Une voix de théâtre qu'elle baisse par habitude.","personality":"Digne, ironique, tendre. Elle a aimé Lanzac et ne s'est jamais consolée de sa disparition. Elle est venue voir son dernier film comme on va sur une tombe.","characteristics":{"STR":35,"CON":45,"SIZ":50,"DEX":45,"APP":60,"INT":70,"POW":70,"EDU":65},"hp":9,"dodge":22,"knows":["Lanzac détestait les acteurs, « qui mentent tous ». Il voulait filmer les gens entiers.","Il tournait certains plans avec un objectif à part, taillé dans un cristal des carrières de la Butte, qu'il appelait la Prunelle.","Le dernier jour de tournage, en octobre 1919 : sept costumes de bal vides sur des portemanteaux, sept masques. « Les invités viendront plus tard. »","Elle a la dernière lettre de Lanzac, datée du jeudi 30 octobre 1919, la veille de sa disparition."]},{"id":"octave-lanzac","kind":"creature","name":"Octave Lanzac","role":"Le cinéaste, premier invité et hôte du bal","description":"Un homme maigre d'une quarantaine d'années, en habit, le masque baissé, gris et argent comme l'image. Il a le visage de 1919.","personality":"Ravi, absent, comme un homme qui a enfin le film qu'il voulait. Au fond, il sait ce que son bal a coûté.","characteristics":{"POW":85},"sanLoss":"0/1D3","special":["Ne peut pas être blessé.","Appelé par son nom (par Irène, ou par quelqu'un qui a lu son carnet ou sa lettre), il hésite : une seule fois, *la valse* n'avance pas ce round, et il souffle « à rebours ».","Il n'est pas un invité mais l'hôte : il ne sort pas quand on passe le film à rebours."],"knows":["Tout : la Prunelle, les sept places, ce que deviendra le film achevé, et qu'à rebours le bal rend ses invités contre une place tenue."]},{"id":"les-invites","kind":"creature","name":"Les invités du bal","role":"Les masqués du film, sortis de l'écran","description":"Des danseurs gris et argent, en costumes de 1919, masques de velours. Parmi eux, les cinq disparus, masques baissés, qui dansent sans voir personne.","personality":"Courtois, insistants, muets. Ils invitent à danser et ne lâchent pas la main.","characteristics":{"POW":60},"sanLoss":"1/1D6","attacks":[{"name":"Invitation à danser","skill":60,"damage":"0","note":"Jet de POU de la victime : en cas d'échec, elle danse un round sans rien pouvoir faire."}],"special":["Ne peuvent pas être blessés : les coups les traversent comme de la lumière.","Une lampe braquée sur l'un d'eux le fait pâlir et reculer d'un pas.","Disparaissent quand la bobine brûle, ou rentrent dans l'écran quand elle passe à rebours (les cinq disparus, eux, en sortent)."]},{"id":"septieme-masque","kind":"creature","name":"Le septième masque","role":"La place vide du bal","description":"Un costume de bal gris, debout, coiffé d'un masque de porcelaine blanche sans bouche. Entre le masque et le col, il n'y a rien.","personality":"Patient. Il regarde l'élu, et seulement lui.","characteristics":{"POW":80},"sanLoss":"0/1D4","special":["Choisit le spectateur qui regarde l'écran le plus fixement (Louise, ce soir, si rien ne change).","À 8 sur *la valse*, il baisse son masque : dessous, le visage de l'élu, qui a disparu. Le film est achevé.","Quand on passe le film à rebours, il reste, tendu vers la salle : quelqu'un doit prendre la place de son plein gré."]}],"handouts":[{"id":"affiche","title":"L'affiche du Mirage","scene":"devant-le-mirage","text":"**LE MIRAGE**\n14, rue des Trois-Frères\n\nSamedi 20 mars 1926, 21 heures\n**DERNIÈRE SÉANCE** avant fermeture définitive\n\n**L'INVITATION**\nDrame inédit en cinq parties\nd'Octave Lanzac (1919)\n\n*Le film dont tout Montmartre parle*\n\nPlaces : 2 F 50 et 4 F"},{"id":"coupure-echo","title":"L'Écho de la Butte, 13 mars 1926","scene":"devant-le-mirage","text":"**LE CINÉMA QUI MANGE SON MONDE**\n\nOn connaissait les salles obscures où l'on s'endort ; voici, rue des Trois-Frères, celle où l'on disparaît. À en croire le quartier, chaque dernier samedi du mois, *L'Invitation*, film inédit du regretté Octave Lanzac, avale un spectateur : la pianiste de la maison en octobre, un retraité des chemins de fer en novembre, et ainsi de suite.\n\nUne jeune blanchisseuse de la rue Lepic, Mlle Louise M., jure que son frère Émile, vingt-trois ans, typographe, est entré au Mirage le 27 février et n'en est jamais ressorti. Le commissariat, consulté, sourit : à Montmartre, on ne compte plus les jeunes gens qui découchent.\n\nM. Courtade, propriétaire, n'en a cure : le Mirage fermant ses portes à la fin du mois, il annonce une dernière projection pour le samedi 20 mars. On y fera la queue.\n\n*R. V.*"},{"id":"registre-cabine","title":"Registre de cabine de Gaston Ribière","scene":"avant-la-seance","text":"*Le Mirage. Registre de cabine. G. Ribière.*\n\n*Lundi 19 oct. 1925.* Reçu du patron 5 bobines, *L'Invitation*. Nitrate, bon état. Bob. 5 mesurée : 296,0 m.\n\n*Sam. 31 oct.* Séance spéciale 21 h. Entrées : 74. Mlle Lacombe (piano) partie avant la fin ? Son châle sur le tabouret. Bob. 5 au réembobinage : 296,3 m.\n\n*Sam. 28 nov.* Entrées : 102. Pas de piano. Objet trouvé rang 1 : canne à pommeau d'os (le père Brisset ?). Bob. 5 : 296,6 m.\n\n*Sam. 26 déc.* Entrées : 131. Un jeune homme cherche sa fiancée (Mlle Ferrand) après la séance. Sac perlé rang 3. Bob. 5 : 296,9 m.\n\n*Sam. 30 janv. 1926.* Entrées : 158. Vu par le hublot, pendant le bal, un homme marcher dans le faisceau jusqu'à l'écran. Casquette de taxi rang 2. Bob. 5 : 297,2 m. Je ne regarderai plus la bobine 5.\n\n*Sam. 27 fév.* Entrées : 176. Écharpe grise rang 1. Lundi, une jeune fille est venue demander son frère (M. Marchal). Bob. 5 : 297,5 m.\n\nUne seconde de plus à chaque fois. Sept masques. Il en reste un."},{"id":"carnet-lanzac","title":"Carnet d'Octave Lanzac (extraits)","scene":"avant-la-seance","text":"*12 mars 1918.* Tixier a fini de tailler la Prunelle. Il me l'a rendue sans la regarder : en la polissant, dit-il, il a vu sa femme morte au fond du verre. Je n'y vois que de la lumière. Mais quelle lumière.\n\n*Juin 1919.* Les acteurs jouent. Ils mentent tous. Je ne veux pas des gens qui font semblant : je veux les gens entiers, et que l'image les garde.\n\n*Septembre 1919.* La Prunelle ne prend pas les acteurs, elle les traverse. Elle ne garde que ceux qui se donnent, ou qui regardent assez fort. Mon bal aura sept invités, pas un de moins. J'ai fait coudre sept costumes. Les places attendent.\n\n*29 octobre.* Un film achevé doit être vu. Quand les sept masques seront tombés, le bal n'aura plus besoin de moi ni de personne : il voudra des salles, partout, et dans chaque salle de nouveaux invités.\n\n*30 octobre.* Ce que la Prunelle prend, elle le rend à l'envers : Tixier l'a dit, et il avait peur. Le feu le tuerait, et tous mes invités avec.\n\n*31 octobre.* Il faut un premier invité. Demain, c'est la Toussaint. Ce sera moi."},{"id":"lettre-irene","title":"Dernière lettre de Lanzac à Irène","scene":"avant-la-seance","text":"*Paris, jeudi 30 octobre 1919*\n\nMa chère Irène,\n\nTu m'as demandé pourquoi sept costumes vides au milieu de mon bal. Je te réponds enfin : parce que les vrais invités ne sont pas encore venus. Ils viendront, un à un, et ils ne joueront pas : ils seront là.\n\nSi un jour il fallait défaire mon bal, dis-leur ceci, toi qui te souviens de tout : *à rebours*. Passé à l'envers, le bal rend tout ce qu'il a pris. Mais un bal ne se défait pas sans que quelqu'un reste pour éteindre les lustres. Il faut qu'on y entre de son plein gré, sinon le bal vide se referme sur toute la salle.\n\nNe me cherche pas demain. Je serai occupé.\n\nTon Octave"},{"id":"contrat-delmas","title":"Contrat de cession","scene":"avant-la-seance","text":"**CONTRAT DE CESSION**\n\nEntre M. Prosper Courtade, exploitant du cinéma Le Mirage, 14, rue des Trois-Frères, Paris (18e), et la maison Delmas & Cie, location de films, 42, rue du Faubourg-Saint-Denis, Paris (10e), représentée par M. Fernand Delmas, il est convenu ce qui suit :\n\n1. M. Courtade cède à Delmas & Cie l'unique copie connue du film *L'Invitation* (O. Lanzac, 1919), en cinq bobines, et tous droits d'exploitation, pour la somme de quinze mille francs.\n\n2. La copie sera remise à M. Delmas à l'issue de la séance du samedi 20 mars 1926.\n\n3. Un contretype et quarante (40) copies positives seront tirés au laboratoire Cinéchrome de Joinville-le-Pont dès le lundi 22 mars, pour exploitation en province, en Belgique et en Suisse à compter du 1er avril 1926.\n\n4. *(ajouté à la main, d'une autre encre)* Le film sera projeté dans son intégralité, sans coupure, y compris la scène du bal.\n\nFait à Paris, en double exemplaire, le jeudi 18 mars 1926.\n\n*F. Courtade* · *F. Delmas*"},{"id":"generique","title":"Le générique de L'Invitation","scene":"la-seance","text":"**L'INVITATION**\nDrame en cinq parties\nMise en scène d'Octave Lanzac\n\nLise . . . . . Mlle Jeanne Darnal\nLa mère . . . . . Mme Irène Saulnier\nL'inconnu . . . . . M. Paul Vigan\nL'hôte . . . . . M. Henri Bastide\n\n**LES INVITÉS DU BAL**\nOctave Lanzac\nBerthe Lacombe\nAnatole Brisset\nSuzanne Ferrand\nPiotr Volkine\nÉmile Marchal\n. . . . . . . . . . . . . . ."},{"id":"carton-invitation","title":"Le carton d'invitation (intertitre)","scene":"la-seance","text":"*Madame, Mademoiselle, Monsieur,*\n\n*L'Hôte de la Maison sans nom a l'honneur de vous prier à son bal masqué.*\n\n*Sept invités sont attendus.*\n*Le dernier masque tombera à la fin de la valse.*\n\n*Une place vous est réservée.*"}],"knowledge":[{"need":"Relier les disparitions au film","best":"Le registre de Gaston (sans jet)","backup":"Louise et la coupure, les objets trouvés, Baratin ou Charme dans la file"},{"need":"Mettre un nom sur les visages du bal","best":"Le générique (sans jet)","backup":"Trouver Objet Caché sur la bobine 5, le registre, la photo d'Émile"},{"need":"Comprendre la Prunelle et les sept places","best":"Le carnet de Lanzac","backup":"Irène Saulnier (Charme, Psychologie), Gaston"},{"need":"Savoir comment arrêter le film","best":"Le carnet et la lettre d'Irène","backup":"Gaston (le nitrate, l'envers), Lanzac dans le bal"},{"need":"Atteindre la cabine pendant le bal","best":"Remonter le faisceau (sans jet)","backup":"Orientation, Trouver Objet Caché"},{"need":"Passer la bobine à rebours","best":"Gaston, s'il est libre","backup":"Mécanique, Machines lourdes"},{"need":"Ouvrir la sortie de secours","best":"La clé de Courtade","backup":"Serrurerie, FOR (difficile)"},{"need":"Calmer la foule","best":"Persuasion","backup":"Intimidation, Baratin"}],"trackers":[{"id":"valse","label":"La valse","max":8,"unit":"rounds","help":"Avance d'un cran à la fin de chaque round du bal, sauf si l'élu a été retenu ou si Lanzac a hésité. À 8, le septième masque tombe sur le visage de l'élu : le film est achevé.","scenes":["le-bal"]},{"id":"feu","label":"Le feu","max":5,"unit":"rounds","help":"Seulement si les flammes passent dans la salle. Avance d'un cran par round. À 5, la salle est perdue : quiconque y est encore prend 1D6 par round, et si la sortie de secours est restée fermée, des spectateurs y meurent.","scenes":["le-bal"]}]}$story$::jsonb, now()
where not exists (select 1 from public.stories where visibility = 'marketplace' and content #>> '{meta,id}' = 'la-derniere-seance');

insert into public.stories (visibility, content, published_at)
select 'marketplace', $story${"format":"grimoire-story/1","meta":{"id":"le-choeur-du-givre","title":"Le Chœur du givre","lang":"fr","summary":"Janvier 1927. Votre plus vieil ami soigne sa tuberculose au sanatorium des Gentianes, sur le plateau d'Assy. Ses lettres ont dit le désespoir, puis la guérison, puis des chants, la nuit, dans les galeries de cure. La dernière tient en un mot : viens.","players":{"min":1,"max":1},"duration":"2 séances de 3 heures","era":"Janvier 1927","setting":"Le sanatorium des Gentianes, sur le plateau d'Assy au-dessus de Passy, et le hameau des Combes (Haute-Savoie)","system":"d100","author":"Grimoire","license":"CC-BY-4.0","version":"1.1","tags":["solo","montagne","sanatorium","huis clos","enquête","dilemme moral"],"contentWarnings":["tuberculose (toux, crachements de sang, agonie évoquée)","horreur corporelle (un lichen qui remplace les poumons, des corps givrés)","éthique médicale : des patients sacrifiés à leur insu","mort de patients","perte de soi (somnambulisme, volonté qui s'efface)"]},"overview":{"secret":"**1867-1868.** Sous le pré où s'élève aujourd'hui le sanatorium, la petite mine de plomb de la Chaux creuse la galerie Saint-Bernard. Au fond, sur la roche, pousse un lichen blanc comme le givre. Les mineurs aux poumons rongés par la poussière guérissent à son contact ; puis, au cœur de l'hiver, ils chantent la nuit. Le 7 février 1868, on en retrouve trois assis au fond, contre la roche, couverts de givre. Les hommes des Combes font trois jours de feu à l'entrée et murent la galerie le 20 mars ; ceux qui avaient respiré la « fleur blanche » crachent le sang tout le printemps, et plusieurs en meurent. Le feu n'est pas allé assez loin : au fond, la colonie survit.\n\n**Octobre 1924.** Le docteur **Henri Castagnier**, directeur du sanatorium des Gentianes (ouvert en 1923), fait creuser les fondations de l'aile Est. Le 6 octobre, les terrassiers crèvent le vieux mur : la galerie, le lichen, les trois Gelés intacts. Castagnier comprend que l'air glacé de la galerie porte des spores qui s'enracinent dans les poumons malades et comblent les cavernes. Il essaie d'abord sur sa femme, **Madeleine**, tuberculeuse : elle dort à l'entrée de la galerie dès novembre et guérit au printemps 1925. À l'été 1925, son mécanicien **Baptiste Ducrey** construit une gaine qui aspire l'air de la galerie et le souffle sous les chaises longues de la galerie de cure de nuit, dans l'aile Est. Les guérisons deviennent spectaculaires : 92 % en 1926, une liste d'attente.\n\n**Mais le lichen ne répare pas : il remplace.** Un poumon guéri est un poumon de lichen, et ce lichen fait partie de la colonie. Sept à dix mois après la guérison, les guéris entendent le chœur (une note tenue, dans les os) ; puis ils le chantent la nuit, en dormant ; douze à quinze mois après leur première nuit sur la galerie, ils se lèvent une nuit de grand froid, descendent dans la galerie et s'asseyent contre la paroi. Le givre les couvre en quelques heures et le lichen pousse à travers eux. Ils respirent encore, une fois toutes les quatre minutes ; les ramener à la chaleur les tue en une heure. Madeleine est descendue dans la nuit du 13 au 14 janvier 1926. Depuis septembre 1926, dix patients ont suivi ; Castagnier les inscrit « transférés à la clinique du Chamossaire, à Leysin ».\n\nDeux lois, que Castagnier a apprises à ses dépens. **La chaleur apaise** : près d'un feu, un guéri redevient lucide ; les guéris partis à Nice ou à Alger n'entendent presque rien, ceux qui retournent au froid finissent par revenir (Anatole Rey est remonté à pied de la gare en décembre). **La colonie et les poumons qu'elle a faits ne sont qu'un** : la nuit du 18 au 19 mars 1926, une fuite de vapeur a réchauffé la galerie ; sept guéris ont craché le sang, Pellissier en est mort. Détruire la colonie, c'est faire rechuter tous les guéris.\n\nCastagnier sait tout. Il descend s'asseoir devant Madeleine, qu'il croit vivante. Il fait son compte : sur cent poumons sauvés, dix finiront dans la paroi. Il sait que le mensonge des transferts ne tiendra pas jusqu'à l'été et que l'hiver prochain, ceux de 1926 seront une vingtaine à descendre.\n\n**Julien Mercadier**, le vieil ami de l'investigateur, gazé en 1918 puis tuberculeux, est arrivé en octobre 1925 et dort sur la galerie de nuit depuis novembre. Guéri en mars 1926, il est resté comme secrétaire du directeur et a tapé lui-même les lettres de transfert. Il chante depuis l'automne. Le samedi 8 janvier 1927, contre le poêle, lucide, il a écrit à l'investigateur. **Irène Lacombe**, sur la galerie depuis octobre 1925, descendra la deuxième nuit ; Julien, la troisième.\n\n**Si personne n'intervient** : lundi 17 janvier au soir, la tempête coupe la route des lacets et le téléphone jusqu'au jeudi midi. Dans la nuit du mardi au mercredi, Irène descend ; au matin, Castagnier la dit « transférée », alors que la route est coupée. Dans la nuit du mercredi au jeudi, Julien descend et s'assoit près d'elle. Le jeudi, Castagnier présente à l'investigateur ses regrets : Julien serait parti pour la Suisse. Au printemps, le mensonge craque, et l'hiver suivant une vingtaine de patients descendent.\n\nLes poumons sains n'accrochent pas les spores : l'investigateur ne risque rien de ce côté. Au fond, le danger, c'est le froid et le chant.","steps":["[[les-gentianes]] (lundi 17 janvier) : la montée dans la neige avec Baptiste, l'accueil de Castagnier, Julien trop gai.","[[premiere-nuit]] : la tempête coupe la route ; la galerie de nuit chante ; Julien dort fenêtre ouverte dans la neige.","[[le-matin-blanc]] (mardi 18) : isolés ; les bouches d'air froid ; Hortense Vial ; Irène au piano ; Julien près du poêle et son carnet.","[[la-chapelle]], [[l-infirmerie]], [[les-combes]], [[le-bureau-du-directeur]] : l'enquête, dans l'ordre que choisit l'investigateur.","[[deuxieme-nuit]] : le givre dans la chambre chauffée de Julien ; Irène descend ; au matin, elle est « transférée ».","[[la-chaufferie]] (mercredi 19) : Baptiste, la gaine, la porte de fer, ce que peuvent la vapeur et la dynamite.","[[la-galerie]] : le lichen, les Gelés, Madeleine, et le marché du docteur Castagnier.","[[la-nuit-du-choeur]] : tous les guéris chantent, Julien descend ; détruire, sauver Julien seul, ou laisser faire.","[[epilogue]] (jeudi 20) : la route rouvre, et chaque choix a son prix."],"mustNotMiss":["**Les guéris chantent la nuit, et la chaleur rend Julien à lui-même** : la galerie de nuit et la fenêtre ouverte ([[premiere-nuit]], sans jet), Julien près du poêle ([[les-gentianes]], [[le-matin-blanc]]), le cahier d'Odile ([[l-infirmerie]]), l'abbé ([[la-chapelle]]).","**Les transferts en Suisse sont faux** : Hortense ([[le-matin-blanc]], sans jet), le carnet de Julien, les valises ([[l-infirmerie]]), la patronne des Combes ([[les-combes]]), le registre et la lettre de Leysin ([[le-bureau-du-directeur]]), Irène « transférée » alors que la route est coupée ([[deuxieme-nuit]], sans jet).","**Ce qui guérit vient de la vieille mine sous l'aile Est** : les bouches d'air froid montrées par Castagnier ([[le-matin-blanc]]), les radiographies ([[l-infirmerie]]), le registre de 1868 ([[la-chapelle]]), Joséphine ([[les-combes]]), le journal de Castagnier ([[le-bureau-du-directeur]]), Baptiste ([[la-chaufferie]]).","**Où est la galerie** : la porte de fer derrière la chaudière (carnet de Julien, Baptiste, Irène suivie dans [[deuxieme-nuit]], plan de Joséphine, clé du tiroir du bureau).","**Détruire la colonie fera rechuter les guéris, Julien compris** : la semaine de mars 1926 (lettre de Julien, Odile, journal de Castagnier, Baptiste) et le printemps 1868 (Joséphine) ; Castagnier le dit lui-même ([[la-galerie]])."],"branches":["Retenir Irène la deuxième nuit ([[deuxieme-nuit]]) : elle vit un jour de plus et se lèvera avec Julien la troisième nuit ; il faudra garder deux personnes.","Convaincre Castagnier ([[la-galerie]]) : il donne sa clé, ordonne à Baptiste d'aider, et demande à rester au fond près de Madeleine.","Accepter le marché de Castagnier : Julien part pour Menton dès jeudi, à ses frais, en échange du silence. La colonie vit.","Détruire la colonie par la vapeur, le feu ou la dynamite ([[la-nuit-du-choeur]]) : tous les guéris rechutent, Julien aussi ; il y aura des morts.","Sauver Julien seul : le garder contre la chaudière jusqu'à l'aube puis l'emmener au soleil, ou le descendre cette nuit même par le câble de ravitaillement.","Laisser faire : Julien descend. L'investigateur peut au moins obtenir de Castagnier que les patients soient prévenus et choisissent."],"ifStuck":["Hortense Vial dit tout haut au réfectoire ce que personne n'ose dire : « Transférés par où ? »","Près d'un poêle, Julien retrouve sa lucidité d'un coup et parle vite : son carnet, les lettres de transfert, la porte de fer.","Odile frappe à la porte de l'investigateur au milieu de la nuit, son cahier de ronde à la main.","Baptiste, malade d'inquiétude pour sa sœur Mélanie, vient de lui-même raconter la nuit de mars 1926.","Le givre qui pousse dans les chambres chauffées dessine toujours ses fougères dans la même direction : vers l'aile Est."],"keeperTips":["C'est une histoire d'amitié. Dès la première scène, donnez à Julien et à l'investigateur des souvenirs communs (le front, le lycée, une ville, un été). Les lettres évitent le genre de l'investigateur : adaptez les répliques.","Personne n'est méchant. Castagnier sauve réellement des vies et le sait ; il a perdu sa femme et refuse de le dire. Jouez-le doux, épuisé, logique, jamais menaçant.","Le surnaturel reste discret jusqu'à la galerie : une note, du givre, des gens trop heureux. Pas de monstre. Les Gelés ne bougent qu'une fois, à la fin.","Aucun combat n'est nécessaire. Si Castagnier sort son pistolet, c'est pour lui-même.","Rattrapez les mauvais jets par les alliés (Odile, l'abbé, Baptiste, Hortense) et par le temps : chaque fait important a plusieurs sources ; un échec coûte une heure, une nuit ou la confiance de quelqu'un, jamais la vérité.","Rythme : première séance jusqu'au mardi soir ([[le-bureau-du-directeur]] ou le début de [[deuxieme-nuit]]), seconde séance de la deuxième nuit à l'aube du jeudi.","En 1927, la tuberculose tue, surtout les pauvres et les anciens soldats. Ne la rendez pas pittoresque : le dilemme doit peser."]},"acts":[{"id":"la-montee","title":"La montée","scenes":[{"id":"les-gentianes","title":"Les Gentianes","lead":"Lundi 17 janvier : la montée dans la neige, l'accueil, et Julien qui va trop bien.","screen":{"place":"asylum","preset":"snow","time":"dusk"},"readAloud":["À la gare du Fayet, un autocar bleu marqué SANATORIUM DES GENTIANES attend sous la neige, moteur tournant. Le chauffeur hisse votre valise sur le toit, entre des sacs de courrier et une caisse d'oranges. « Montez vite. Ça va tomber fort cette nuit. »","La route grimpe en lacets entre les sapins. À chaque virage, la vallée s'enfonce un peu plus dans le gris. Puis la forêt s'ouvre : sur le plateau, un long bâtiment blanc aligne ses galeries vitrées face aux montagnes qu'on ne voit plus. Sur les terrasses, des silhouettes couchées sous des couvertures ne bougent pas.","Dans le hall surchauffé flotte une odeur d'encaustique et de phénol. Un homme en blouse blanche vient à vous, les mains tendues. « Vous venez pour Julien ! Il ne parle que de vous depuis une semaine. Bienvenue aux Gentianes. »"],"flow":[{"title":"Avant de partir","text":"L'investigateur a avec lui les lettres de Julien → {{handout:lettres-de-julien}} et la dernière → {{handout:derniere-lettre}}. Les lui donner à lire dans le train.","extra":"La lettre du 28 mars 1926 parle déjà de la semaine où les guéris ont rechuté ensemble : un indice pour la fin."},{"title":"L'autocar","text":"{{npc:baptiste-ducrey}}, mécanicien et chauffeur du sanatorium, conduit. Il parle volontiers : les « miraculés » du docteur, la liste d'attente, la neige qui arrive. Il s'arrête au hameau des Combes pour déposer le courrier au café.","extra":"Il dit sans y penser que la Renault du docteur « n'a pas fait cent kilomètres depuis l'été ». Les « transferts » à Leysin, à cent cinquante kilomètres, sont censés se faire dans cette voiture."},{"title":"Les Gelés de Saint-Bernard","text":"Lancer Baptiste sur le pays, les Combes, les vieilles histoires.","roll":{"type":"skill","options":["charm","persuade","history"]},"success":"Il raconte la légende de son grand-père : une vieille mine de plomb sous le plateau, fermée en 1868 après que trois mineurs sont « restés en bas, gelés, assis contre la roche, à chanter ». « Des histoires de vieux. » Il se tait d'un coup quand l'autocar longe l'aile Est.","failure":"Il ne parle plus que de la route et du prix du charbon. (La légende reste à trouver aux Combes, [[les-combes]], ou chez l'abbé, [[la-chapelle]].)"},{"title":"Le docteur Castagnier","text":"{{npc:henri-castagnier}} accueille avec chaleur et fait visiter : réfectoire, salon de musique, galeries de cure plein sud, et la galerie de l'aile Est où dorment la nuit les patients de « cure de nuit ». Il remet la brochure → {{handout:brochure-gentianes}}. Dans son bureau : un graphique des guérisons au mur, le portrait d'une femme blonde. « Madeleine, ma femme. Elle se soigne en Suisse. »","roll":{"type":"skill","options":["psychology"]},"success":"Il est sincèrement heureux de cette visite, et épuisé jusqu'à l'os. Il regarde le portrait quand il croit qu'on ne le voit pas.","failure":"Un médecin aimable et fier de son œuvre."},{"title":"L'infirmière","text":"{{npc:odile-perrollaz}}, infirmière-major, conduit l'investigateur à sa chambre d'hôte, au premier étage, deux portes après celle de Julien. Polie, pressée, elle demande à voix basse : « Vous restez combien de temps ? », puis se reprend.","roll":{"type":"skill","options":["psychology"]},"success":"Elle espérait que quelqu'un vienne. Elle ne sait pas encore si elle peut parler. Elle parlera plus tard ([[l-infirmerie]]) si on la ménage.","failure":"Une infirmière débordée, rien de plus."},{"title":"Julien","text":"{{npc:julien-mercadier}} arrive en courant, rose, rieur, sans une toux. Il serre l'investigateur dans ses bras et parle de tout. De la dernière lettre, il rit : « Un coup de cafard, j'ai eu honte après. Je guéris, tu vois bien ! » Pendant qu'il parle, il fredonne sans s'en rendre compte une note tenue, toujours la même.","extra":"Il a les mains glacées. Près du poêle du salon, il se tait un instant, se frotte les yeux et regarde l'investigateur comme s'il venait seulement d'arriver. Puis il s'éloigne du poêle, et le sourire revient."},{"title":"Observer Julien","roll":{"type":"skill","options":["medicine","spot-hidden"]},"success":"Médecine : pas un râle, un souffle profond et lent comme celui d'un dormeur, une température de 35,8°. Trouver Objet Caché : de minuscules cristaux de givre au coin de ses lèvres, qui fondent quand il passe près du poêle.","failure":"Il a l'air en parfaite santé. Peut-être un peu pâle des mains."},{"title":"Le dîner","text":"Au réfectoire, les guéris rient aux longues tables ; {{npc:irene-lacombe}} parle musique avec Julien. À une petite table près du poêle, les malades qui ne guérissent pas toussent dans leur serviette ; {{npc:hortense-vial}} lève son face-à-main vers l'investigateur avec intérêt. Baptiste annonce que l'autocar ne redescendra pas ce soir : la neige tombe trop fort.","goto":["premiere-nuit"]}],"notes":[{"title":"Calendrier","items":["**Lundi 17 janvier 1927** : arrivée vers 15 h 30. Vers 23 h, une coulée de neige coupe la route au lacet des Ravines ; le téléphone est mort, le câble de ravitaillement arrêté par le givre.","**Mardi 18** : isolés. Nuit du mardi au mercredi : Irène descend.","**Mercredi 19** : Irène est dite « transférée ». Nuit du mercredi au jeudi : Julien descend.","**Jeudi 20** : le chasse-neige des Ponts et Chaussées rouvre la route vers midi.","Le jour se lève vers 7 h, la nuit tombe vers 16 h 30."]},{"title":"Le sanatorium","items":["**Bâtiment principal** (trois niveaux) : au rez-de-chaussée le hall, le réfectoire, le salon de musique et le **bureau du directeur** ([[le-bureau-du-directeur]]) ; au premier, les chambres du personnel et des hôtes (Julien, l'investigateur) ; au deuxième, des chambres de malades, la **lingerie** et l'**infirmerie** avec la salle de radiologie ([[l-infirmerie]]).","**Aile Est** (1925) : la galerie de cure de nuit, une trentaine de chaises longues ; au sous-sol, la **chaufferie**, et derrière elle la **porte de fer** ([[la-chaufferie]]).","**Chapelle** accolée à l'aile ouest ([[la-chapelle]]). Garage (la Renault du docteur), station du câble de ravitaillement au bord du plateau.","**Les Combes** : le hameau, vingt minutes plus bas en raquettes ([[les-combes]])."]}],"npcs":["baptiste-ducrey","henri-castagnier","odile-perrollaz","julien-mercadier","irene-lacombe","hortense-vial"],"handouts":["lettres-de-julien","derniere-lettre","brochure-gentianes"],"ambience":["wind","fireplace"],"sfx":["door-open","footsteps"],"next":["premiere-nuit"]},{"id":"premiere-nuit","title":"La première nuit","lead":"La tempête coupe la route ; vers deux heures, la galerie de nuit chante.","screen":{"place":"asylum","preset":"snow","time":"night"},"readAloud":["Le vent cogne aux volets toute la soirée. Vers minuit, la lumière vacille, s'éteint une seconde, revient plus jaune. Le radiateur de votre chambre claque doucement.","Puis, sous le vent, autre chose. Une note. Longue, tenue, faite de beaucoup de voix ensemble, si basse qu'elle passe dans le bois du lit avant d'arriver aux oreilles."],"flow":[{"title":"La tempête","text":"Vers 23 h, la route a été coupée au lacet des Ravines et le téléphone est tombé. Personne ne le sait encore : on l'apprendra au matin ([[le-matin-blanc]])."},{"title":"Le chant","text":"Vers 2 h. Il suffit de sortir dans le couloir pour l'entendre mieux.","roll":{"type":"skill","options":["listen"]},"success":"Il vient de l'est, de la galerie de nuit, mais aussi d'en dessous : par la grille d'aération du couloir, la même note monte du sous-sol.","failure":"Le chant semble venir de partout à la fois, comme le vent."},{"title":"La galerie de nuit","text":"Par le couloir vitré de l'aile Est, l'investigateur arrive au bout de la galerie. Une trentaine de chaises longues alignées, les patients emmaillotés sous les couvertures, la neige qui entre par rafales. Tous dorment. Tous chantent, bouche fermée, la même note. Du givre sur les cils. Sous chaque chaise, une grille de fonte souffle un air glacé.","roll":{"type":"san","label":"Le chœur endormi","san":"0/1D3"}},{"title":"Irène","text":"Au bout de la rangée, {{npc:irene-lacombe}} ne dort pas. Assise, les yeux ouverts, elle chante plus fort que les autres et sourit à l'investigateur sans s'arrêter.","extra":"Si on lui parle, elle répond entre deux souffles : « Écoutez. On nous attend. » Puis elle reprend la note."},{"title":"Odile","text":"{{npc:odile-perrollaz}} fait sa ronde avec une lampe et une seringue de bromure. Elle sursaute. « Retournez vous coucher, je vous en prie. Ce n'est rien. Ils rêvent. »","roll":{"type":"skill","options":["psychology","charm"]},"success":"Elle chuchote : « Ça dure depuis l'automne. Le docteur dit de ne rien noter. Moi, je note. » Elle n'en dira pas plus cette nuit.","failure":"Elle raccompagne l'investigateur jusqu'au couloir, sans un mot de plus.","pushed":"Elle appelle le docteur, qui arrive en robe de chambre, très calme, et donne un somnifère « pour le dépaysement ». L'investigateur dort jusqu'à 9 h, et Castagnier se méfie désormais : un dé de malus pour obtenir quoi que ce soit de lui."},{"title":"La chambre de Julien","text":"En revenant par le couloir du premier : la porte de Julien est entrouverte, la chambre glacée, la fenêtre grande ouverte sur la tempête. Julien dort dans la neige qui couvre le parquet, souriant, et chante. Le radiateur est brûlant. Pas de jet pour fermer la fenêtre et le recoucher.","extra":"Réveillé, il ne se souvient de rien et grelotte. Collé au radiateur, il se met à trembler et murmure : « Ne me laisse pas dormir dehors. » Au matin, il n'en saura plus rien."},{"title":"Le reste de la nuit","text":"Vers 4 h, le chant s'éteint d'un coup, partout à la fois, comme une lampe qu'on souffle.","goto":["le-matin-blanc"]}],"npcs":["odile-perrollaz","irene-lacombe","julien-mercadier"],"ambience":["wind-howling","clock"],"sfx":["footsteps","door-creak","latch"],"next":["le-matin-blanc"]}]},{"id":"les-miracules","title":"Les miraculés","scenes":[{"id":"le-matin-blanc","title":"Le matin blanc","lead":"Mardi 18 : le plateau coupé du monde, les guéris trop gais, le carnet de Julien.","screen":{"place":"mountain","preset":"snow","time":"day"},"readAloud":["Au matin, le monde a disparu. La neige monte jusqu'aux rebords des fenêtres du rez-de-chaussée, le ciel est blanc, la vallée n'existe plus. Dans le réfectoire, on rit.","Aux longues tables du fond, les guéris mangent de bon appétit, le teint clair, la voix forte. À une petite table près du poêle, quelques malades toussent dans leur serviette et ne regardent personne."],"flow":[{"title":"L'annonce","text":"{{npc:henri-castagnier}} se lève : la route est coupée au lacet des Ravines, le téléphone aussi, le câble de ravitaillement arrêté par le givre. « Deux ou trois jours. Nous avons des vivres pour un mois. » Il invite l'investigateur à rester autant qu'il le faudra.","extra":"Personne ne peut descendre à Passy avant jeudi. Les Combes, plus bas sur le plateau, restent accessibles en raquettes."},{"title":"La visite de la galerie Est","text":"Castagnier montre fièrement son « procédé » : sous chaque chaise longue de la galerie de nuit, une bouche de fonte souffle l'air du sous-sol, « plus froid, plus pur, sans une poussière : un procédé à moi ». Il en parle sans se faire prier.","roll":{"type":"skill","options":["spot-hidden"]},"success":"Sur les grilles, un dépôt blanc, fin comme de la farine, qui ne fond pas sous le doigt et sent la pierre mouillée.","failure":"Des grilles de fonte propres et froides."},{"title":"Madame Vial","text":"{{npc:hortense-vial}}, à la table des toussants, fait signe à l'investigateur de s'asseoir. Elle refuse la galerie : « Je n'ai pas fait soixante-sept ans pour geler sur une chaise longue. » Pas de jet : elle adore parler. Ce qu'elle dit sans qu'on demande : les guéris chantent la nuit, « tous, et jamais nous autres » ; on ne voit jamais partir les « transférés », jamais de voiture, toujours la nuit ; le petit Excoffier, le 9, a laissé ses pantoufles au pied de son lit ; elle a vu le docteur revenir de l'aile Est à l'aube, du givre sur les épaules de son manteau."},{"title":"Irène au piano","text":"Au salon de musique, {{npc:irene-lacombe}} joue, très lentement, une mélodie sans début ni fin.","roll":{"type":"skill","options":["listen"]},"success":"C'est la note de la nuit, déployée en mélodie. Irène sourit : « Je vais partir bientôt. Le docteur dit la Suisse. Moi, je sais que c'est plus près. » Elle n'a pas peur.","failure":"Une jolie mélodie triste. Si on l'interroge, Irène dit quand même qu'elle va « partir bientôt »."},{"title":"Julien près du poêle","text":"Au grand jour, Julien est gai et nie tout : le chant, la fenêtre, la lettre. Pour qu'il parle, il faut l'amener près d'une vraie chaleur (le poêle du salon, un bain chaud, la chaufferie) et l'y garder un moment.","roll":{"type":"skill","options":["psychology","persuade"]},"success":"Contre le poêle, il redevient lui-même d'un coup, livide, et parle vite : il a tapé lui-même les lettres de transfert ; personne n'est jamais parti ; Irène descendra la première, lui ensuite. Il donne son carnet, caché sous le tiroir de sa table → {{handout:carnet-julien}}.","failure":"Il rit, puis s'assoupit près du poêle. À son réveil, il dit seulement : « Mon carnet. Sous le tiroir. » et ne s'en souvient plus l'instant d'après. Le carnet est bien là → {{handout:carnet-julien}}."},{"title":"Où aller ?","text":"La journée est à l'investigateur : l'abbé à la chapelle ([[la-chapelle]]), Odile à l'infirmerie ([[l-infirmerie]]), les Combes en raquettes ([[les-combes]]), et le bureau du directeur, de préférence quand il n'y est pas ([[le-bureau-du-directeur]]).","extra":"Le soir venu, passer à [[deuxieme-nuit]].","goto":["la-chapelle","l-infirmerie","les-combes","le-bureau-du-directeur"]}],"npcs":["henri-castagnier","hortense-vial","irene-lacombe","julien-mercadier"],"handouts":["carnet-julien"],"ambience":["crowd-indoor","fireplace","clock"],"sfx":["door-open"],"next":["la-chapelle","l-infirmerie","les-combes","le-bureau-du-directeur"]},{"id":"la-chapelle","title":"La chapelle","lead":"L'abbé Mugnier, le registre de 1868, et ce que les guéris disent en confession.","screen":{"place":"church","preset":"snow","time":"day"},"readAloud":["La chapelle est accolée à l'aile ouest : un toit pentu sous la neige, un petit clocher de bois. À l'intérieur, il fait presque aussi froid que dehors ; un poêle de fonte ronfle près de la sacristie.","Un vieux prêtre en pèlerine balaie la neige que le vent a poussée sous la porte. Il s'arrête en vous voyant, appuyé sur son balai. « Vous êtes la visite de Julien. Venez près du poêle, on y parle mieux. »"],"flow":[{"title":"L'abbé","text":"{{npc:abbe-mugnier}} est aumônier des Gentianes et curé des Combes. Il aime Julien, qui lui sert la messe le dimanche."},{"title":"Les guéris","text":"Sur les guéris, sur Julien.","roll":{"type":"skill","options":["psychology","persuade"]},"success":"« Je ne peux rien vous dire de ce qu'on me confie. Mais je peux vous dire ce qu'on ne me confiait pas avant : des hommes guéris qui pleurent de joie et qui me disent qu'on les attend, en bas, et que c'est doux. Ce n'est pas la voix de Dieu, ça. » Plus bas : « Julien s'est confessé samedi. Ne le laissez pas seul la nuit. »","failure":"Il parle du secret de la confession et n'en démord pas. Mais en raccompagnant l'investigateur, il lui serre le bras : « Ne laissez pas Julien seul la nuit. »"},{"title":"Octobre 1924","text":"Interrogé sur l'aile Est (pas de jet) : il a béni le chantier en octobre 1924. Le contremaître lui a dit, blanc comme un linge, qu'on avait crevé « le mur des Gelés », la vieille galerie Saint-Bernard. Le docteur a payé les terrassiers et les a renvoyés le lendemain. Baptiste Ducrey était du chantier ([[la-chaufferie]])."},{"title":"Le registre des Combes","text":"Les vieux registres des Combes sont à la sacristie depuis l'automne : le toit du presbytère fuit.","roll":{"type":"skill","options":["library-use","history"]},"success":"L'année 1868 → {{handout:registre-1868}}.","failure":"La reliure est en morceaux, les années mélangées. L'abbé passe l'après-midi à chercher et apporte la page le soir, au dîner → {{handout:registre-1868}}. L'investigateur a perdu le temps d'une visite."},{"title":"Madame Castagnier","text":"L'abbé se souvient (pas de jet) : Madeleine Castagnier était malade, la première soignée par son mari. En décembre 1925, il l'a entendue chanter seule dans la chapelle, la nuit, cette même note. En janvier, elle était « partie en Suisse ». « Il ne va jamais la voir là-bas. Il descend à l'aile Est le dimanche et revient les yeux rouges. »"},{"title":"Un allié","text":"L'abbé aidera si on lui dit la vérité : veiller Julien, calmer les somnambules, porter, prier. Il refuse de mettre le feu « à des chrétiens », sauf si on lui montre que les Gelés ne reviendront pas.","roll":{"type":"skill","options":["persuade"]},"success":"Il sera là la troisième nuit, dès le premier chant, et donne un dé bonus pour garder Julien.","failure":"Il hésite. Il viendra quand même la troisième nuit, s'il entend Julien passer devant la chapelle."}],"notes":[{"title":"Ce que dit l'abbé si on le lance sur le pays","items":["La mine de la Chaux a fermé en 1868 ; la Compagnie est partie au printemps, sans payer les veuves.","On dit aux Combes que la galerie « garde » ses hommes, et qu'il ne faut pas siffler sur le pré des Gentianes la nuit.","La vieille Joséphine Bochatay « y était » : son père a muré la galerie ([[les-combes]])."]}],"npcs":["abbe-mugnier"],"handouts":["registre-1868"],"ambience":["wind"],"sfx":["door-creak","footsteps"],"next":["l-infirmerie","les-combes","le-bureau-du-directeur"]},{"id":"l-infirmerie","title":"L'infirmerie","lead":"Odile, les radiographies, le givre dans une chambre chauffée, les valises des transférés.","screen":{"place":"asylum","preset":"bulb","time":"day"},"readAloud":["Au deuxième étage, l'infirmerie sent l'éther et le linge bouilli. Une ampoule nue pend au-dessus de la table de radiologie ; elle grésille et baisse par moments, quand la chaudière force.","Sur le négatoscope, des radiographies de poitrines sont alignées. Sur certaines, entre les côtes, s'étend une trame pâle et ramifiée, fine comme des fougères de givre sur une vitre."],"flow":[{"title":"Odile","text":"Elle travaille sans s'arrêter. Pour qu'elle parle, il faut la ménager, ou lui montrer qu'on sait déjà quelque chose (le chant, le carnet de Julien, ce que dit Hortense).","roll":{"type":"skill","options":["psychology","charm"]},"success":"Elle ferme la porte et sort son cahier de ronde → {{handout:cahier-de-ronde}}. Elle raconte la semaine de mars 1926 : une nuit, la chaudière a fui dans la gaine de l'aile Est, et le lendemain tous les guéris ont craché le sang en même temps ; M. Pellissier en est mort. « Le docteur a crié sur Ducrey comme je ne l'avais jamais entendu crier. »","failure":"Elle se tait. Si l'investigateur l'aide une heure (porter les bassins, veiller un malade, Premiers soins), elle montre le cahier en fin de journée et raconte mars 1926.","pushed":"Elle parle, mais Castagnier entre à ce moment-là. Il ne dit rien et la retire du service de nuit : la troisième nuit, elle ne sera plus là pour aider."},{"title":"Les radiographies","text":"Odile laisse regarder. Les films de Julien sont classés par mois depuis octobre 1925.","roll":{"type":"skill","options":["medicine","natural-world"]},"success":"Ni calcification ni cicatrice : c'est trop régulier, presque cristallin. Mois après mois, la trame comble les cavernes de Julien en mars 1926, puis continue et gagne le tissu sain. En janvier 1927, ses poumons en sont presque entièrement faits. Ce qui l'a guéri ne répare pas : ça remplace (SAN 0/1).","failure":"Des cicatrices étranges. Odile répète ce que dit le docteur : « C'est la guérison qui se voit. » (Le journal de Castagnier le dit clairement : [[le-bureau-du-directeur]].)"},{"title":"La chambre 21","text":"Odile montre (pas de jet) la chambre de M. Excoffier, vide depuis le 9 janvier. Le radiateur est brûlant ; pourtant un givre épais couvre l'intérieur des vitres, le pied du lit, l'oreiller, en fougères ramifiées qui partent toutes du traversin et pointent toutes vers l'est.","roll":{"type":"san","label":"Le givre dans la chambre chaude","san":"0/1"}},{"title":"Les valises","text":"La lingerie, au fond du couloir, est fermée à clé. Avec Odile, pas de jet : elle a la clé. Seul :","roll":{"type":"skill","options":["locksmith"]},"success":"Derrière les piles de draps, dix valises pleines, étiquetées au nom des « transférés », et une onzième, plus belle, aux initiales M. C. : celle de Madame Castagnier. Ils sont tous partis en pyjama.","failure":"La serrure tient. Il faut la clé d'Odile ou le passe de Baptiste ([[la-chaufferie]]).","pushed":"La serrure cède avec un bruit sec ; une infirmière accourt. Castagnier l'apprendra ce soir et gardera désormais sur lui la clé de la porte de fer."},{"title":"Ce qu'Odile sait encore","text":"Une fois en confiance : le docteur ne prend jamais la voiture « pour aller voir Madame en Suisse » ; Julien est venu frapper chez elle en larmes, la nuit du 15 au 16, pour qu'elle l'enferme.","extra":"Son grand-oncle Claude Perrollaz est mort à la mine en 1868 ; elle ne fait le lien que si on lui montre le registre des Combes. Elle aidera la troisième nuit : soins, morphine, surveiller les malades."}],"notes":[{"title":"Les valises","items":["Dix valises des transférés (Morel, Saillet, Burnier, Thévenet, Ravanel, Gaillard, Charvet, Rey, Mollard, Excoffier), plus celle de Madeleine Castagnier : **onze en tout**. Si Irène est déjà descendue, la sienne y est aussi."]}],"npcs":["odile-perrollaz"],"handouts":["cahier-de-ronde"],"ambience":["clock","wind"],"sfx":["latch","footsteps"],"next":["la-chapelle","les-combes","le-bureau-du-directeur"]},{"id":"les-combes","title":"Les Combes","lead":"Le hameau sous la neige, la mère d'une « transférée », la vieille Joséphine et le plan de la mine.","optional":true,"screen":{"place":"mountain","preset":"snow","time":"day"},"readAloud":["Vingt minutes de raquettes dans une neige jusqu'aux genoux, et le hameau sort du blanc : une dizaine de fermes aux toits écrasés, une fontaine gelée, une petite chapelle, la fumée droite des cheminées.","Au café-épicerie, trois hommes jouent aux cartes près du poêle. Ils se taisent quand vous entrez. La patronne s'essuie les mains à son tablier et vient à vous. « Vous descendez de là-haut ? Vous avez des nouvelles de notre Suzanne ? »"],"flow":[{"title":"La descente","text":"Baptiste prête des raquettes ; le sentier est balisé de perches. Pas de jet s'il accompagne l'investigateur.","roll":{"type":"skill","options":["survival","natural-world"]},"success":"Une heure aller-retour, sans encombre.","failure":"Une chute dans une combe : l'investigateur arrive trempé et transi (1 point de vie) et perd une heure à se sécher au poêle du café."},{"title":"La patronne","text":"Rosalie Mollard (pas de jet) : sa fille Suzanne, guérie aux Gentianes, a été « transférée en Suisse » le 2 janvier. Pas une lettre depuis ; le docteur a écrit qu'elle « se reposait ». Suzanne avait laissé son chapelet sur sa table de nuit. « Elle ne s'en séparait jamais. Jamais. »"},{"title":"Les joueurs de cartes","text":"Une tournée payée suffit (pas de jet) : la vieille mine sous le pré des Gentianes, les trois « Gelés » de 1868, « ceux de là-haut ont creusé dedans en 24, ça ne pouvait rien donner de bon ». Ils envoient chez la mère Bochatay, « la seule qui y était »."},{"title":"Joséphine Bochatay","text":"{{npc:josephine-bochatay}}, au coin de son feu, raconte sans qu'on la presse : elle attendait que quelqu'un descende de là-haut pour lui demander. Pas de jet pour son récit (voir notes).","roll":{"type":"san","label":"Le récit de Joséphine","san":"0/1"}},{"title":"Le plan de la mine","text":"Elle a gardé le plan de son père.","roll":{"type":"skill","options":["persuade","charm","psychology"]},"success":"Elle le donne → {{handout:plan-saint-bernard}}. « Il n'y a que le feu. Mais il faut le porter au fond. Nous, on n'a pas osé : les Gelés étaient nos hommes. »","failure":"Elle le garde : « Revenez quand vous saurez ce que vous ferez. » Elle le donnera si l'investigateur revient le lendemain avec une décision. Baptiste connaît le même chemin ([[la-chaufferie]])."},{"title":"Le retour","text":"Il faut remonter avant la nuit : vers 16 h, la lumière baisse déjà et le vent reprend.","goto":["le-bureau-du-directeur","deuxieme-nuit"]}],"notes":[{"title":"Ce que raconte Joséphine","items":["Elle avait vingt-deux ans en 1868. Son père, Jean-Pierre Bochatay, était boiseur à la mine de la Chaux.","Il toussait depuis dix ans, « la maladie de la mine ». À l'automne 1867, on a trouvé la fleur blanche au fond de Saint-Bernard : en deux mois, il ne toussait plus. Les autres non plus.","À Noël, ils se sont mis à chanter la nuit, en dormant, tous les mêmes. Puis trois sont redescendus une nuit de février et on les a trouvés assis contre la roche, givrés, « encore tièdes ».","Les hommes ont fait trois jours de feu à l'entrée et muré la galerie le 20 mars. Son père a posé les pierres lui-même. Ceux qui avaient respiré la fleur ont craché le sang tout le printemps ; son père est mort à la Saint-Jean. « Il savait que ça le tuerait. Il l'a fait quand même. »","« Le feu n'est pas allé assez loin. La fleur est encore en bas. On l'entend, les nuits de grand froid, si on pose l'oreille sur la pierre de la fontaine. »"]}],"npcs":["josephine-bochatay"],"handouts":["plan-saint-bernard"],"ambience":["village-day","wind","fireplace"],"sfx":["dog-bark","knocking","door-open"],"next":["le-bureau-du-directeur","deuxieme-nuit"]},{"id":"le-bureau-du-directeur","title":"Le bureau du directeur","lead":"Le registre des sorties, la lettre de Leysin, le journal de Castagnier.","screen":{"place":"library","preset":"candle","time":"night"},"readAloud":["Le bureau sent le tabac froid et le papier. Une lampe verte, un fauteuil de cuir, des revues médicales jusqu'au plafond. Au mur, le graphique des guérisons monte en flèche à partir de l'été 1925.","Au-dessus de la cheminée éteinte, le portrait d'une femme blonde en robe claire, assise, les mains ouvertes sur les genoux. Elle a un léger sourire, comme quelqu'un qui écoute."],"flow":[{"title":"Entrer","text":"Le jour, Castagnier y reçoit ; il en sort pour ses visites de 10 h et de 17 h, et la nuit il descend souvent à l'aile Est. Julien, son secrétaire, a une clé : lucide, il la donne ; sinon elle est dans la poche de sa veste. Sans clé, la serrure est simple.","roll":{"type":"skill","options":["stealth","locksmith"]},"success":"Personne ne voit l'investigateur entrer.","failure":"Une infirmière de nuit l'aperçoit dans le couloir. Castagnier le saura au matin : froid, poli, attentif, il gardera sur lui la clé de la porte de fer.","pushed":"Castagnier entre pendant la fouille. Il préfère parler que crier : jouer la conversation de [[la-galerie]] (étapes « Castagnier » et « Le marché »), ici, à la lumière de la lampe verte."},{"title":"Le registre des sorties","text":"Sur une étagère, à portée de main, pas de jet → {{handout:registre-des-sorties}}.","extra":"Si Irène est déjà descendue, une onzième ligne à l'encre fraîche : « 19 janv. 1927 — LACOMBE Irène, 26 ans, Lyon — id. »"},{"title":"Les comptes","text":"Le grand livre est sur le bureau.","roll":{"type":"skill","options":["accounting"]},"success":"Aucune dépense de transport, d'essence, de douane ni de pension à Leysin depuis septembre. Les transférés restent inscrits comme payants jusqu'à la fin de leur mois : leurs familles paient encore.","failure":"Des comptes bien tenus, rien qui saute aux yeux."},{"title":"Le tiroir fermé","text":"Le tiroir de gauche est fermé. La clé est collée derrière le portrait de Madeleine (Julien le sait).","roll":{"type":"skill","options":["spot-hidden","locksmith"]},"success":"Dedans : la lettre de Leysin → {{handout:lettre-leysin}}, le journal d'observations → {{handout:journal-castagnier}}, un pistolet Browning chargé et une clé de fer longue comme la main : celle de la porte du sous-sol.","failure":"Le tiroir résiste. Forcé au coupe-papier, il cède en éclatant : tout est là, mais Castagnier le verra au matin.","pushed":"Le bois éclate avec un bruit de coup de feu dans le bâtiment endormi. Castagnier arrive en robe de chambre (voir « Entrer », coup de force)."},{"title":"Lire le journal","roll":{"type":"san","label":"Le journal de Castagnier","san":"0/1D3"}},{"title":"Le portrait","text":"Après le journal, regarder à nouveau le portrait : Madeleine est assise comme les Gelés, les mains ouvertes sur les genoux. Le peintre l'a faite ainsi en 1923, bien avant.","goto":["deuxieme-nuit","la-chaufferie"]}],"npcs":["henri-castagnier","julien-mercadier"],"handouts":["registre-des-sorties","lettre-leysin","journal-castagnier"],"ambience":["clock","wind-howling"],"sfx":["latch","footsteps","door-creak"],"next":["deuxieme-nuit","la-chaufferie"]},{"id":"deuxieme-nuit","title":"La deuxième nuit","lead":"Du mardi au mercredi : le givre chez Julien, Irène descend, et au matin elle est « transférée ».","screen":{"place":"asylum","preset":"bulb","time":"night"},"readAloud":["Le vent est tombé. Dans le silence, le bâtiment craque de froid. Sur la vitre, côté intérieur, des fougères de givre poussent lentement, alors que le radiateur brûle sous la main.","À une heure, le chant commence. Cette fois, il ne vient pas seulement de la galerie : il est dans les murs, dans les tuyaux, dans le verre d'eau de la table de nuit, dont la surface tremble."],"flow":[{"title":"Julien","text":"S'il a parlé près du poêle, Julien a supplié l'investigateur de veiller sur lui. Sa chambre se couvre de givre malgré le radiateur. Il dort, chante, s'agite.","extra":"Ce n'est pas encore son tour. L'investigateur ne le sait pas."},{"title":"Des pas nus","text":"Vers 1 h 30, des pas nus passent dans le couloir : {{npc:irene-lacombe}}, en chemise de nuit, les yeux ouverts, qui marche vers l'aile Est en chantant. Rester avec Julien, la suivre, ou l'arrêter ?"},{"title":"Rester avec Julien","branch":"Si l'investigateur reste avec Julien","text":"Vers 3 h, Julien se lève, va à la fenêtre et l'ouvre. Cette nuit, le retenir est facile (pas de jet) : il se laisse recoucher, pleure, puis dort. Au matin, il a du givre dans les cheveux."},{"title":"Suivre Irène","branch":"Si l'investigateur suit Irène","text":"Couloir de l'aile Est, escalier de service, sous-sol : la chaudière ronfle, Irène passe derrière sans hésiter. Une porte de fer est ouverte ; une lampe attend dans l'antichambre : Castagnier.","roll":{"type":"skill","options":["stealth"]},"success":"L'investigateur voit sans être vu : Castagnier prend la main d'Irène et l'emmène au-delà de la porte. Il revient seul une heure plus tard, du givre sur les joues, et referme à clé.","failure":"Castagnier l'aperçoit. Il ne s'emporte pas : « Retournez vous coucher. Vous ne pouvez rien pour elle cette nuit. Demain, si vous voulez, je vous montrerai. » Il referme la porte de fer derrière Irène. (Il tiendra parole : [[la-galerie]].)"},{"title":"Arrêter Irène","branch":"Si l'investigateur retient Irène","text":"Elle ne se débat pas vraiment : elle tire vers l'aile Est avec une force douce et obstinée. La convaincre, ou la porter (FOR, jets rapides de la scène).","roll":{"type":"skill","options":["persuade","psychology"]},"success":"Ramenée au chaud (radiateur, bain chaud), Irène se réveille, lucide et terrifiée, et tousse du sang dans ses mains : « Je ne veux pas descendre. Mais j'ai si froid quand je ne descends pas. » Elle passe la nuit. La troisième, elle se lèvera avec Julien ([[la-nuit-du-choeur]]).","failure":"Elle glisse entre les mains de l'investigateur et court, pieds nus, plus vite qu'on ne le croirait. La porte de fer se referme sur elle avant qu'il n'arrive.","pushed":"L'investigateur la rattrape dans l'escalier, mais tombe avec elle sur les marches (1D3 points de vie chacun). Elle est sauvée pour cette nuit, comme sur une réussite."},{"title":"Le matin","text":"Mercredi 19, au petit déjeuner, Castagnier annonce d'une voix égale : « Mademoiselle Lacombe nous a quittés cette nuit. Transférée à Leysin. » La route est coupée depuis lundi. {{npc:hortense-vial}}, très fort : « Transférée par où, docteur ? Par le câble ? » Pas de jet.","extra":"Si Irène a été retenue, Castagnier ne dit rien et regarde longuement l'investigateur. Il viendra lui parler dans la journée ([[la-galerie]])."},{"title":"La chaise vide","text":"Sur la galerie de nuit, la chaise longue d'Irène est vide, la couverture raide de givre ; dessous, la bouche de fonte souffle toujours.","roll":{"type":"san","label":"La chaise vide","san":"0/1"},"goto":["la-chaufferie","la-galerie"]}],"rolls":[{"type":"characteristic","label":"Porter Irène jusqu'au chaud","options":["STR"]}],"npcs":["julien-mercadier","irene-lacombe","henri-castagnier","hortense-vial"],"ambience":["wind","clock"],"sfx":["footsteps","door-slam","latch"],"next":["la-chaufferie","la-galerie"]}]},{"id":"sous-l-aile-est","title":"Sous l'aile Est","scenes":[{"id":"la-chaufferie","title":"La chaufferie","lead":"Baptiste Ducrey, la gaine, la porte de fer, et ce qu'on pourrait faire avec une chaudière.","screen":{"place":"crypt","preset":"bulb","time":"day"},"readAloud":["L'escalier de service descend dans une chaleur de four. Sous une rangée d'ampoules nues, la grande chaudière ronfle, la gueule rouge ouverte ; un homme en maillot de corps y jette le charbon à grandes pelletées.","Au fond de la salle, la chaleur s'arrête net, comme devant un mur. Une gaine de tôle large comme un homme part du plafond et s'enfonce dans le béton. À côté, une porte de fer peinte en gris. Sur ses gonds, du givre."],"flow":[{"title":"Baptiste","text":"{{npc:baptiste-ducrey}} se méfie : il tient à sa place, et sa sœur Mélanie, lingère, est une guérie de l'automne dernier. Un dé bonus si l'investigateur lui montre une preuve (registre, lettre de Leysin, valises, Irène « transférée » malgré la route).","roll":{"type":"skill","options":["persuade","psychology"]},"success":"Il pose sa pelle, s'essuie le front et parle (voir notes).","failure":"Il nie tout et retourne à son charbon. Le soir, il vient frapper à la porte de l'investigateur : il a eu peur pour Mélanie toute la journée. Il parle alors."},{"title":"La gaine","text":"Avec Baptiste, pas de jet : il l'a construite à l'été 1925, sur ordre du docteur. Un ventilateur aspire l'air de l'antichambre, derrière la porte de fer, et le souffle jusqu'aux grilles de la galerie de nuit. Ordre formel : jamais de chaleur de ce côté-ci. Seul :","roll":{"type":"skill","options":["mechanical-repair","spot-hidden"]},"success":"L'investigateur suit le circuit : la gaine prend l'air derrière la porte de fer et le pousse jusqu'aux bouches de la galerie de nuit.","failure":"Une gaine d'aération, et un froid qui en tombe."},{"title":"Mars 1926","text":"Baptiste raconte (pas de jet) : la nuit du 18 au 19 mars 1926, une vanne a fui et la vapeur est passée dans la gaine. Au matin, les guéris crachaient le sang. Pellissier est mort le 23. Mélanie n'était pas encore guérie : elle n'a rien eu. « Le docteur m'a dit : c'est comme si tu leur avais brûlé les poumons toi-même. »"},{"title":"Ce que peut la chaudière","text":"Baptiste le sait (pas de jet) : en arrêtant le ventilateur et en ouvrant la conduite de vapeur de l'aile Est, jamais raccordée, on pousserait la vapeur dans l'antichambre et jusqu'au fond de la galerie. Trois heures de chaudière forcée pour réchauffer le fond. Et dans l'ancienne poudrière de la mine, à mi-galerie, il a rangé en 1924 trois caisses de dynamite du chantier. « Elle suinte. Je n'y touche plus. »"},{"title":"La porte de fer","text":"Baptiste a une clé, comme le docteur (et celle du tiroir du bureau, [[le-bureau-du-directeur]]). Sans clé :","roll":{"type":"skill","options":["locksmith"],"difficulty":"hard"},"success":"La serrure tourne. Derrière, le froid.","failure":"Une serrure de coffre, gelée par-dessus le marché. Il faut une clé : Baptiste, Castagnier ou le tiroir du bureau.","goto":["la-galerie"]},{"title":"Le dilemme de Baptiste","text":"Il veut que Mélanie vive. Si on lui explique que détruire la colonie la fera rechuter, il blêmit et propose plutôt de l'envoyer dans le Midi. Il aidera à ce que l'investigateur décidera s'il en est convaincu, et il viendra la troisième nuit s'il entend Julien descendre.","extra":"Le câble de ravitaillement : Baptiste peut remettre le treuil en marche malgré le givre. La benne à charbon descend à Chedde en vingt minutes. Personne n'y monte jamais."}],"notes":[{"title":"Ce que sait Baptiste","items":["Son grand-père était mineur à la Chaux ; il a aidé à murer Saint-Bernard en 1868.","Le 6 octobre 1924, il était du chantier quand la pioche a crevé le vieux mur. Il a vu les trois Gelés. Le docteur l'a gardé, les autres ont été payés et renvoyés.","Il a construit la gaine à l'été 1925. Il entretient la chaudière et le ventilateur, et n'est jamais allé plus loin que l'antichambre depuis 1924.","La Renault du docteur n'a pas fait cent kilomètres depuis l'été : c'est lui qui l'entretient.","En décembre, un ancien patient, Anatole Rey, est remonté à pied de la gare du Fayet, la nuit, en souliers de ville. On l'a trouvé au matin dans le hall, à moitié gelé, qui disait qu'il était « rentré »."]}],"npcs":["baptiste-ducrey"],"ambience":["fireplace"],"sfx":["latch","door-slam"],"next":["la-galerie"]},{"id":"la-galerie","title":"La galerie Saint-Bernard","lead":"Le lichen, les Gelés, Madeleine et Irène, et le choix du docteur Castagnier.","screen":{"place":"cavern","preset":"ritual","time":"night"},"readAloud":["Derrière la porte de fer, une antichambre de béton, puis la roche. Le froid prend aux dents. La galerie descend doucement entre de vieux étais noircis, et votre lampe allume sur les parois un givre épais, blanc, qui ne fond pas sous la flamme.","Plus loin, la lampe devient inutile. Le givre luit de lui-même, très faiblement, comme la neige sous la lune. L'air est plein d'une poussière fine qui scintille. Quelque part devant vous, très bas, on chante.","La galerie s'ouvre sur une salle basse. Le long des parois, des gens sont assis."],"flow":[{"title":"Le froid du fond","text":"Environ −8° dans la salle. Sans pelisse de cure (il y en a à la réserve de la galerie de nuit), 1 point de vie par demi-heure passée au fond.","extra":"Les poumons sains de l'investigateur n'accrochent pas les spores."},{"title":"Le lichen","roll":{"type":"skill","options":["natural-world","medicine"]},"success":"Un lichen, mais aucun connu : il pousse sur la roche nue sans lumière, en fines fougères cristallines, et il est tiède sous le doigt. La poussière qui scintille, ce sont ses spores. C'est la trame des radiographies.","failure":"Du givre qui n'en est pas, tiède sous le doigt."},{"title":"La salle des Gelés","text":"Quinze personnes assises contre la roche, givrées (quatorze si Irène a été retenue) : trois mineurs en vieux habits, lampes à huile éteintes sur les genoux ; une femme blonde en chemise de nuit et châle, une chaise de cuisine posée devant elle ; dix patients en pyjama ; et, au bout, Irène, le visage encore visible sous un givre mince.","roll":{"type":"san","label":"Les Gelés","san":"1/1D6"}},{"title":"De près","roll":{"type":"skill","options":["medicine","first-aid"]},"success":"Ils respirent : une fois toutes les quatre minutes, un souffle qui fait chanter le givre. Le lichen sort de leurs narines et de leur bouche en fines fougères et rentre dans la roche. Les détacher, les remonter à la chaleur : ils mourraient en une heure (le journal de Castagnier le dit aussi).","failure":"Des corps gelés. Puis l'un d'eux respire, et le givre tinte (SAN 0/1)."},{"title":"Irène","text":"Si elle est ici, Irène a les yeux ouverts et elle sourit. On ne peut plus rien pour elle : la détacher de la paroi la tuerait."},{"title":"Castagnier","text":"{{npc:henri-castagnier}} est là, assis sur la chaise devant Madeleine, ou il descend derrière l'investigateur. Il ne crie pas. Il explique (voir notes). Si l'investigateur parle de feu, il pose la main sur la poche où est son pistolet."},{"title":"Le marché","text":"Castagnier propose : il signe la sortie de Julien et l'envoie à Menton dès que la route rouvre, à ses frais. Au soleil, Julien vivra, s'il ne revient jamais dans le froid. En échange : le silence, et qu'on le laisse continuer."},{"title":"Le faire changer d'avis","text":"Un dé bonus si l'investigateur lui oppose ce qu'il ne peut pas balayer : la lettre de Leysin, Rey remonté à pied de la gare, l'hiver prochain (une vingtaine, il l'a écrit), Irène « transférée » alors que la route est coupée.","roll":{"type":"skill","options":["persuade","psychology"]},"success":"Il se tait longtemps, la main sur le genou de Madeleine. « Faites ce que vous devez. Mais je reste avec elle. » Il donne sa clé, dira à Baptiste d'obéir, et demande une seule chose : qu'on le laisse descendre s'asseoir près d'elle avant. S'il refuse la destruction mais accepte la vérité, il écrira à chaque patient ce qu'il risque.","failure":"Il remonte, referme la porte de fer et garde sa clé. Il ne dénoncera pas l'investigateur, il n'en a pas les moyens, mais ne le quitte plus des yeux. Son marché tient toujours.","pushed":"Il sort le pistolet. Psychologie : le canon n'est pas pour l'investigateur, il est pour lui. Le désarmer demande une FOR opposée (jets rapides de la scène) ; le laisser parler une minute de plus le fait renoncer et poser l'arme sur la chaise."}],"notes":[{"title":"La galerie","items":["Porte de fer → antichambre de béton (1924), où débouchent la gaine et la conduite de vapeur jamais raccordée.","Galerie ancienne : descend vers le nord sur environ cent cinquante mètres. Rails rouillés, étais noircis par le feu de 1868 sur les trente premiers mètres : là, pas de lichen.","À soixante-dix mètres, à gauche : l'ancienne **poudrière**, trois caisses de dynamite de 1924, suintantes.","Au bout : la **salle des Gelés**, ancienne salle de la veine, basse, entièrement couverte de lichen, sol compris."]},{"title":"Ce que dit Castagnier","items":["« Quatre-vingt-douze pour cent. Avant moi, sur ce plateau, on en enterrait un sur deux. »","« Ils ne sont pas morts. Ils respirent. Ils chantent. Madeleine m'entend, j'en suis sûr. »","« Sur cent que je sauve, dix descendent. Quel médecin oserait refuser ce marché à cent malades ? »","« Je sais que le mensonge ne tiendra pas. Je cherche une autre solution avant l'été. Je n'en ai pas. »","« Si vous la brûlez, ils rechutent tous. Tous ceux que j'ai guéris. Votre ami aussi. »"]}],"npcs":["henri-castagnier","madeleine-castagnier","le-choeur","irene-lacombe"],"ambience":["wind"],"sfx":["footsteps","latch","door-slam"],"next":["la-nuit-du-choeur"],"rolls":[{"type":"characteristic","label":"Désarmer Castagnier (FOR opposée)","options":["STR"]}]}]},{"id":"le-chant","title":"Le chœur","scenes":[{"id":"la-nuit-du-choeur","title":"La nuit du chœur","lead":"Du mercredi au jeudi : tous les guéris chantent, Julien descend. Détruire, sauver Julien seul, ou laisser faire.","screen":{"place":"asylum","preset":"nightmare","time":"night"},"readAloud":["Toute la soirée, le froid gagne le bâtiment. Les radiateurs tiédissent, puis refroidissent, alors que la chaudière hurle en bas. Le givre monte aux vitres du réfectoire, aux miroirs, au verre des lampes.","À minuit et demi, le chant commence partout à la fois. Les guéris chantent dans leurs lits, dans les couloirs, sur la galerie. Le bâtiment entier vibre sur une seule note, et l'eau des carafes frémit."],"flow":[{"title":"Le chœur","roll":{"type":"san","label":"Le bâtiment qui chante","san":"0/1D3"}},{"title":"Julien se lève","text":"Vers 2 h, Julien se lève, et Irène avec lui si elle a été retenue la veille. Tracker « Julien vers la galerie » : +1 à chaque étape franchie. Contre une vraie chaleur, il redevient lucide par moments et supplie qu'on le retienne.","extra":"Les alliés convaincus sont là : Baptiste à la chaudière, Odile auprès des malades, l'abbé auprès de Julien, peut-être Castagnier. L'aube vient vers 7 h : alors le chant faiblit et Julien s'endort."},{"title":"Que faire ?","text":"L'investigateur a jusqu'à l'aube. Les choix ci-dessous peuvent se combiner (sauver Julien pendant que Baptiste force la chaudière), mais détruire la colonie fera rechuter Julien quoi qu'il arrive."},{"title":"La vapeur","branch":"Détruire par la vapeur","text":"Baptiste (ou l'investigateur, Mécanique) arrête le ventilateur et ouvre la conduite de l'aile Est. Trois heures de chaudière forcée : tracker « Agonie de la colonie », +1 par demi-heure réussie. Le givre gagne les vannes.","roll":{"type":"skill","options":["mechanical-repair","operate-heavy-machinery"]},"success":"La vapeur passe : +1.","failure":"Une vanne gèle ; il faut la dégeler à la lampe à souder. La demi-heure est perdue.","pushed":"La vanne cède d'un coup : jet de vapeur brûlante, 1D6 points de vie, mais le palier est gagné."},{"title":"Le feu","branch":"Détruire par le feu","text":"Deux bidons de pétrole (la Renault, la réserve des lampes) portés jusqu'à la salle des Gelés. Le lichen brûle comme de la cire : +2 par round de feu au fond, trois rounds suffisent avec les deux bidons. Les Gelés brûlent avec lui. Sortir avant la fumée : DEX.","roll":{"type":"san","label":"Les Gelés brûlent","san":"1/1D6"}},{"title":"La dynamite","branch":"Faire sauter la salle des Gelés","text":"La dynamite de la poudrière, portée jusqu'au fond, la mèche posée par Baptiste (ou Mécanique). La voûte écrase la salle : +6 d'un coup ; écrasée et coupée de l'air, la colonie meurt en quelques jours.","roll":{"type":"luck"},"success":"La dynamite suintante tient jusqu'au fond. Deux minutes de mèche pour remonter : largement assez.","failure":"Un bâton glisse et explose à mi-chemin : DEX pour se jeter à terre (1D3 points de vie, sinon 2D6). La galerie s'effondre entre la poudrière et la salle : la colonie est murée, pas tuée, comme en 1868 (voir [[epilogue]])."},{"title":"Sauver Julien","branch":"Sauver Julien seul","text":"Le garder contre la chaudière jusqu'à l'aube, puis l'emmener dès que la route rouvre. Ou cette nuit même par le câble : Baptiste au treuil, la benne à charbon jusqu'à Chedde, vingt minutes dans le vent (Escalade ou Chance pour tenir dans la benne qui tangue). Chaque heure avant l'aube, il faut le garder. L'abbé ou Odile donnent un dé bonus.","roll":{"type":"skill","options":["psychology","persuade"]},"success":"Julien reste. Il pleure, chante, se calme contre la chaleur.","failure":"Tracker +1 : il s'arrache et franchit une étape. Le rattraper : FOR contre 45 (jets rapides de la scène)."},{"title":"Laisser faire","branch":"Laisser faire","text":"Julien descend. L'investigateur peut l'accompagner, lui tenir la main jusqu'à la salle, le voir s'asseoir près d'Irène. Lucide une dernière fois, il dit : « Ce n'est pas froid, tu sais. »","roll":{"type":"san","label":"Julien prend sa place","san":"1/1D6"}},{"title":"Au fond, le chant","text":"Pour qui descend dans la salle des Gelés cette nuit (feu, dynamite, ou pour accompagner Julien) : le chœur appelle aussi les vivants.","roll":{"type":"characteristic","options":["POW"]},"success":"L'investigateur garde la tête claire.","failure":"Il s'arrête, s'assoit presque contre la paroi ; le givre prend ses cils. Un allié présent le tire en arrière. Seul : jet de Chance pour se reprendre ; échec, 1D3 points de vie de froid avant de se relever."},{"title":"Les Gelés ouvrent les yeux","text":"Dès que la colonie souffre (tracker à 3, ou au premier round de feu), les Gelés ouvrent les yeux tous ensemble, et le chant devient un cri sans bouche, dans la roche et dans les os.","roll":{"type":"san","label":"Les yeux des Gelés","san":"1/1D4"}},{"title":"Les guéris crachent le sang","text":"Tracker à 3 : dans tout le sanatorium, les guéris toussent et crachent le sang. Julien s'effondre, s'il n'est pas déjà au fond.","roll":{"type":"skill","options":["first-aid","medicine"]},"success":"L'investigateur le garde en vie jusqu'à l'aube, la tête sur le côté, au chaud.","failure":"Odile arrive avec la morphine (ou l'abbé, s'il est là) : Julien passe la nuit de justesse. Son sort se joue dans l'épilogue."},{"title":"Castagnier","text":"Convaincu, il descend s'asseoir devant Madeleine avant la vapeur, le feu ou la dynamite, et n'en remonte pas. Sinon, il tente de fermer la conduite ou d'arracher la mèche : le convaincre (Persuasion), ou l'en empêcher (FOR, jets rapides de la scène). Il ne tire pas sur l'investigateur.","goto":["epilogue"],"roll":{"type":"skill","options":["persuade"]},"success":"Il lâche la vanne ou la mèche et s'assoit par terre, la tête dans les mains.","failure":"Il faut l'écarter de force (FOR) ou perdre un palier du tracker le temps de réparer ce qu'il a défait."}],"notes":[{"title":"Le déroulé de la nuit","items":["22 h : les radiateurs refroidissent, le givre monte dans les chambres.","0 h 30 : le chant, partout.","2 h : Julien se lève (et Irène, si elle a été retenue). Une étape du tracker par quart d'heure s'il n'est pas retenu : chambre, couloir, escalier de l'aile Est, sous-sol, porte de fer.","Si la colonie souffre : les guéris somnambules descendent vers la chaufferie et se tiennent devant les vannes, sans violence. Les écarter : Persuasion, ou l'aide de l'abbé et d'Odile.","7 h : l'aube. Le chant faiblit. Ceux qui ne sont pas au fond s'endorment où ils sont."]}],"npcs":["julien-mercadier","baptiste-ducrey","odile-perrollaz","abbe-mugnier","henri-castagnier","le-choeur"],"ambience":["wind-howling","clock"],"sfx":["footsteps","door-slam","latch"],"next":["epilogue"],"rolls":[{"type":"characteristic","label":"Retenir Julien (FOR contre 45)","options":["STR"]},{"type":"characteristic","label":"Se jeter à terre / sortir avant la fumée","options":["DEX"]},{"type":"luck","label":"Tenir dans la benne du câble"}]},{"id":"epilogue","title":"Le jeudi blanc","lead":"Jeudi 20 janvier : la route rouvre. Ce que chaque choix a coûté.","screen":{"place":"mountain","preset":"fog","time":"dusk"},"readAloud":["Au matin, le ciel est d'un bleu dur. Les montagnes sont revenues, immenses, et la vallée fume de brume. Vers midi, on entend monter dans les lacets le moteur du chasse-neige.","Sur la galerie de nuit, les chaises longues sont alignées sous la neige fraîche. On n'entend plus rien."],"flow":[{"title":"La route","text":"Vers midi, le chasse-neige des Ponts et Chaussées atteint le plateau. Baptiste peut redescendre l'investigateur, Julien et qui voudra partir. Le téléphone revient dans l'après-midi.","extra":"Si l'investigateur prévient les autorités (gendarmerie de Saint-Gervais, préfecture d'Annecy) : enquête, scandale, l'aile Est murée par ordre du préfet. Voir « Colonie murée »."},{"title":"Récompenses et pertes","text":"Appliquer les notes ci-dessous selon ce qui s'est passé."}],"notes":[{"title":"Épilogue","items":["**Colonie détruite** (vapeur, feu, ou dynamite au fond) : l'investigateur gagne **1D6 SAN**. Dans les jours qui suivent, tous les guéris rechutent. Aux Gentianes, sept meurent avant Pâques ; parmi les anciens patients dispersés en France, une douzaine de plus avant l'été (**1/1D4 SAN** en l'apprenant par Odile). Les Gelés dégèlent et s'affaissent : on peut enfin les enterrer aux Combes, avec une vraie messe. Joséphine y vient.","**Julien, si la colonie est détruite** : jet de Chance de l'investigateur. Réussite : Julien survit, très affaibli ; il part pour Vence et vivra encore quelques années, en toussant, en écrivant chaque dimanche. Échec : il meurt en mars à Passy, lucide jusqu'au bout, et remercie l'investigateur de lui avoir rendu sa tête (perte de **1D4 SAN**).","**Colonie murée seulement** (dynamite tombée à mi-chemin, ou l'aile Est murée par les autorités) : les guéris rechutent comme au printemps 1868, moins gravement (trois morts aux Gentianes ; Julien survit, affaibli). La colonie vit derrière la roche. L'hiver suivant, d'anciens patients reviennent gratter la neige sur le pré des Gentianes, la nuit. Pas de gain de SAN.","**Julien sauvé seul** (gardé jusqu'à l'aube puis emmené, descendu par le câble, ou parti grâce au marché) : **1D4 SAN**. Julien vit à Menton ; il chante un peu les nuits de mistral et ne doit jamais revoir la neige. L'hiver suivant, une vingtaine de patients de 1926 descendent : **1/1D3 SAN** quand Odile l'écrit à l'investigateur.","**Laisser faire** : perte de **1D6 SAN**. Si Castagnier a promis d'avertir les patients, la perte n'est que de **1D3** : il écrit à chacun ce qu'il risque, et certains choisissent la galerie en le sachant.","**Castagnier** : convaincu et la colonie détruite, on le retrouve au fond, assis devant Madeleine, mort de froid ou de feu. Sinon, le sanatorium ferme en 1928 et il disparaît. Si la colonie vit, la plainte des Saillet amène une enquête au printemps ; il se tue dans la galerie et l'aile Est est murée : voir « Colonie murée ».","**Les autres** : Mélanie Ducrey rechute si la colonie meurt, mais elle est jeune et guérie depuis peu : elle survit. Si Julien part dans le Midi, Baptiste y envoie sa sœur aussi. Hortense Vial, si la colonie vit, demande à dormir sur la galerie de nuit : « À mon âge, quinze mois, c'est une éternité. »"]}],"rolls":[{"type":"damage","label":"Gain de SAN (colonie détruite)","dice":"1D6"},{"type":"damage","label":"Gain de SAN (Julien sauvé)","dice":"1D4"},{"type":"luck","label":"Julien survit-il à la rechute ?"}],"npcs":["julien-mercadier","baptiste-ducrey","odile-perrollaz","henri-castagnier"],"ambience":["wind","village-day"],"sfx":["door-open"]}]}],"npcs":[{"id":"julien-mercadier","name":"Julien Mercadier","kind":"person","role":"Le vieil ami, guéri, secrétaire du directeur","description":"Trente-trois ans, grand, maigre, le teint redevenu rose, une cicatrice d'éclat d'obus au menton. Ancien instituteur à Lyon, gazé en 1918, tuberculeux depuis 1923.","personality":"Gai, doux, absent, et il fredonne. Près d'une vraie chaleur, il redevient lui-même : lucide, terrifié, pressé de tout dire avant que ça ne reparte.","knows":["Il a tapé lui-même les dix lettres de transfert pour Leysin ; aucune voiture n'est partie.","Les valises des transférés sont à la lingerie du deuxième étage.","Le chant monte par les grilles de la galerie de nuit ; au sous-sol, derrière la chaudière, il y a une porte de fer (Ducrey et le docteur en ont la clé).","La clé du tiroir du bureau est collée derrière le portrait de Madeleine.","Irène descendra d'abord, puis lui. Il ne sait pas comment il le sait.","Il a rêvé de Madame Castagnier, assise dans la pierre, qui lui faisait de la place."],"characteristics":{"STR":45,"CON":50,"SIZ":60,"DEX":55,"APP":55,"INT":70,"POW":45,"EDU":70},"hp":11,"dodge":27},{"id":"henri-castagnier","name":"Dr Henri Castagnier","kind":"person","role":"Directeur médical des Gentianes","description":"Cinquante-quatre ans, barbe grise taillée court, lunettes cerclées d'or, blouse impeccable. Il a les yeux de quelqu'un qui ne dort plus.","personality":"Courtois, brillant, sincère. Il a sauvé des centaines de malades et sacrifié onze personnes, dont sa femme, et il a fait le compte. Mis devant la vérité, il ne ment plus : il argumente.","knows":["Tout : la galerie, le lichen (*Pruina canens*, dans son journal), la gaine, Madeleine, les transferts inventés.","La chaleur rend les guéris lucides ; les guéris partis dans le Midi ne reviennent pas.","Détruire ou réchauffer la colonie fait rechuter tous les guéris (mars 1926).","Irène puis Julien descendront ; l'hiver prochain, une vingtaine.","Le mensonge des transferts ne tiendra pas jusqu'à l'été."],"characteristics":{"STR":50,"CON":55,"SIZ":65,"DEX":50,"APP":60,"INT":80,"POW":65,"EDU":85},"hp":12,"dodge":25,"skills":{"medicine":75,"persuade":60,"psychology":55},"attacks":[{"name":"Pistolet Browning 6,35","skill":30,"damage":"1D6","note":"Il ne tire pas sur l'investigateur. L'arme est pour lui-même."},{"name":"Coup de poing","skill":35,"damage":"1D3"}]},{"id":"odile-perrollaz","name":"Odile Perrollaz","kind":"person","role":"Infirmière-major","description":"Quarante et un ans, Savoyarde de Passy, coiffe blanche, mains rougies par le désinfectant.","personality":"Dévouée aux malades, sèche avec les visiteurs, terrifiée de perdre sa place et plus encore de ce qu'elle voit la nuit. Elle a besoin qu'on la croie.","knows":["Les guéris chantent la nuit depuis l'automne ; ils disparaissent toujours la nuit, en pyjama, et le docteur dit « transféré ».","Le docteur lui a ordonné de ne rien noter ; elle tient un cahier de ronde.","La semaine de mars 1926 : une fuite de la chaudière dans la gaine, et le lendemain tous les guéris ont craché le sang ; Pellissier est mort.","Les valises des transférés sont à la lingerie, dont celle de Madame Castagnier.","Julien est venu la supplier de l'enfermer la nuit du 15 au 16 janvier."],"characteristics":{"STR":50,"CON":60,"SIZ":55,"DEX":60,"INT":65,"POW":60},"hp":11,"dodge":30,"skills":{"first-aid":70,"medicine":45,"psychology":45}},{"id":"abbe-mugnier","name":"Abbé Anselme Mugnier","kind":"person","role":"Aumônier des Gentianes et curé des Combes","description":"Soixante-deux ans, pèlerine noire, gros souliers cloutés, un nez cassé de montagnard.","personality":"Simple, têtu, bon. Lié par le secret de la confession, il cherche à avertir sans le trahir.","knows":["Des guéris lui confient qu'on les attend « en bas » et que c'est doux.","Julien s'est confessé samedi : il ne faut pas le laisser seul la nuit.","En octobre 1924, les terrassiers ont crevé « le mur des Gelés » ; le docteur les a payés et renvoyés.","Le registre des Combes de 1868 (à la sacristie).","Madeleine Castagnier chantait seule dans la chapelle en décembre 1925 ; le docteur ne va jamais la voir « en Suisse »."],"characteristics":{"STR":40,"CON":45,"SIZ":55,"DEX":40,"INT":70,"POW":75},"hp":10,"dodge":20,"skills":{"history":50,"psychology":60}},{"id":"baptiste-ducrey","name":"Baptiste Ducrey","kind":"person","role":"Mécanicien, chauffeur et chauffagiste des Gentianes","description":"Trente-huit ans, des épaules de bûcheron, de la suie dans les rides, enfant des Combes.","personality":"Taiseux, loyal au docteur qui l'a embauché, rongé par la nuit de mars 1926 et par la peur pour sa sœur Mélanie, lingère, guérie l'automne dernier.","knows":["La légende des Gelés de Saint-Bernard ; son grand-père a aidé à murer la galerie.","Il était du chantier le 6 octobre 1924 et a vu les trois Gelés.","Il a construit la gaine en 1925 ; jamais de chaleur côté porte de fer.","La nuit du 18 au 19 mars 1926, sa vanne a fui dans la gaine : les guéris ont craché le sang.","Comment pousser la vapeur au fond de la galerie ; où sont les trois caisses de dynamite ; comment faire marcher le câble.","La Renault du docteur n'a pas fait cent kilomètres depuis l'été ; Anatole Rey est remonté à pied de la gare en décembre."],"characteristics":{"STR":70,"CON":70,"SIZ":70,"DEX":55,"INT":55,"POW":50},"hp":14,"dodge":27,"damageBonus":"1D4","skills":{"mechanical-repair":75,"operate-heavy-machinery":60,"drive-auto":60,"climb":50,"survival":50},"attacks":[{"name":"Clé à molette","skill":50,"damage":"1D6+1D4"},{"name":"Coup de poing","skill":55,"damage":"1D3+1D4"}]},{"id":"irene-lacombe","name":"Irène Lacombe","kind":"person","role":"Patiente guérie, pianiste","description":"Vingt-six ans, professeur de piano à Lyon, cheveux noirs coupés court, d'une pâleur lumineuse.","personality":"Sereine, presque heureuse. Elle sait qu'elle va descendre et n'en a pas peur. Ramenée de force à la chaleur, elle redevient une jeune femme terrifiée qui tousse du sang.","knows":["Elle va « partir bientôt », « plus près que la Suisse ».","La mélodie qu'elle joue est la note de la nuit.","Elle dort sur la galerie de nuit depuis octobre 1925, un mois avant Julien."],"characteristics":{"STR":35,"CON":45,"SIZ":45,"DEX":60,"APP":65,"INT":60,"POW":50},"hp":9,"dodge":30},{"id":"hortense-vial","name":"Hortense Vial","kind":"person","role":"Patiente qui ne guérit pas","description":"Soixante-sept ans, veuve d'un notaire de Grenoble, châle violet, face-à-main, une toux de crécelle.","personality":"Mauvaise langue, lucide, courageuse. Elle refuse la galerie par coquetterie et par instinct, et dit tout haut ce que les autres taisent.","knows":["Les guéris chantent la nuit, jamais les malades.","On ne voit jamais partir les transférés ni la voiture ; toujours la nuit.","Le petit Excoffier a laissé ses pantoufles au pied de son lit, le 9 janvier.","Elle a vu le docteur revenir de l'aile Est à l'aube, du givre sur son manteau."],"characteristics":{"CON":30,"INT":70,"POW":60},"hp":7},{"id":"josephine-bochatay","name":"Joséphine Bochatay","kind":"person","role":"Doyenne des Combes","description":"Quatre-vingt-deux ans, toute petite, coiffe noire, des yeux très clairs.","personality":"Patiente et grave. Elle attend depuis soixante ans que quelqu'un vienne lui demander.","knows":["La fleur blanche a guéri les poumons de son père et des mineurs en 1867 ; puis ils ont chanté ; trois sont restés au fond en février 1868.","Trois jours de feu à l'entrée, la galerie murée le 20 mars ; ceux qui avaient respiré la fleur ont craché le sang, son père en est mort à la Saint-Jean.","« Il n'y a que le feu, et il faut le porter au fond. »","Le plan de la mine levé par son père."],"characteristics":{"CON":40,"INT":65,"POW":70},"hp":8},{"id":"madeleine-castagnier","name":"Madeleine Castagnier","kind":"person","role":"La femme du directeur, la première descendue","description":"Assise contre la roche dans la salle des Gelés, en chemise de nuit et châle, les mains ouvertes sur les genoux, le visage du portrait sous un an de givre. Une chaise de cuisine est posée devant elle.","personality":"Elle ne parle pas. Elle respire une fois toutes les quatre minutes, et le givre tinte.","sanLoss":"0/1D3","knows":["Descendue dans la nuit du 13 au 14 janvier 1926. Officiellement, elle « se soigne en Suisse »."]},{"id":"le-choeur","name":"Le Chœur","kind":"creature","role":"La colonie de lichen blanc de la galerie Saint-Bernard, et les Gelés qu'elle garde","description":"Un lichen pâle, en fougères cristallines, qui couvre la salle des Gelés du sol à la voûte, tiède au toucher, luisant faiblement. Ses spores scintillent dans l'air froid. Quinze personnes assises dans la paroi, givrées, respirent avec lui.","personality":"Pas une volonté qu'on puisse raisonner : une faim lente et douce, qui guérit pour prendre.","sanLoss":"1/1D6","special":["Ses spores ne s'accrochent qu'aux poumons malades ; elles comblent les cavernes, puis remplacent le tissu sain.","Les guéris font partie de lui : s'il souffre (chaleur, feu), ils crachent le sang ; s'il meurt, ils rechutent tous.","Il appelle les guéris par le froid, douze à quinze mois après leur première nuit sur la galerie. La chaleur les rend lucides ; le Midi les fait presque taire.","Pour les vivants dans la salle : un jet de POU quand le chant enfle (échec : s'asseoir contre la paroi, 1D3 points de vie de froid).","Insensible aux coups. La vapeur (trois heures), le feu porté au fond ou l'effondrement de la salle le tuent. Le feu à l'entrée seulement ne fait que le blesser (1868).","Les Gelés ne bougent pas, sauf une fois : quand il souffre, ils ouvrent les yeux (SAN 1/1D4). Les détacher de la paroi les tue en une heure."]}],"handouts":[{"id":"lettres-de-julien","title":"Les lettres de Julien","scene":"les-gentianes","text":"*Les Gentianes, dimanche 22 novembre 1925*\n\n… On nous couche dehors sur la galerie, douze heures par jour, face au Mont-Blanc qu'on ne voit jamais, sous trois couvertures. Depuis cette semaine, je dors même dehors la nuit : le docteur m'a mis à la « cure de nuit ». Le froid entre partout. Je crache rouge le matin. Je compte les chaises vides. Ne viens pas : je ne veux pas que tu me voies comme ça.\n\n*Dimanche 28 mars 1926*\n\nJe guéris. Je l'écris et je n'y crois pas. Plus de fièvre, plus de sang. Le docteur m'a montré ma radiographie : les cavernes sont comblées, « comme du givre sur une vitre », dit-il. Pourtant, quelle semaine : plusieurs guéris ont rechuté d'un coup, tous ensemble, et le pauvre Pellissier en est mort. Moi, j'ai toussé deux jours, puis plus rien. Le docteur me garde comme secrétaire. Je reste : je respire si bien, ici.\n\n*Dimanche 7 novembre 1926*\n\nJe guéris tout à fait. Je ne tousse plus du tout, même dans le froid. Surtout dans le froid. La nuit, on chante dans les galeries. Pas des chansons : une seule note, longue, que tout le monde connaît sans l'avoir apprise. Je crois que je la chante aussi. C'est très doux. Je n'ai jamais si bien dormi.\n\nTon Julien"},{"id":"derniere-lettre","title":"La dernière lettre de Julien","scene":"les-gentianes","text":"*Les Gentianes, samedi 8 janvier 1927*\n\nViens. Viens tout de suite, je t'en prie.\n\nJe ne peux pas l'écrire ici, ça ne veut pas venir sur le papier ; j'écris contre le poêle et déjà ma main ralentit. Dis au docteur que tu viens me rendre visite, rien de plus. Ne lui montre pas cette lettre. Ne m'écris pas : viens.\n\nJulien\n\n*Au dos, de la même main, mais plus lente, plus droite :*\n\nTout va bien. Ne viens pas. Je guéris."},{"id":"brochure-gentianes","title":"Brochure du sanatorium des Gentianes","scene":"les-gentianes","text":"**SANATORIUM DES GENTIANES**\nPlateau d'Assy (Haute-Savoie), altitude 1 000 mètres\nGare du Fayet (ligne P.-L.-M.), service d'autocar quotidien\n\nDirection médicale : **Dr Henri Castagnier**, ancien interne des Hôpitaux de Lyon\n\n120 lits. Galeries de cure exposées plein sud, face à la chaîne du Mont-Blanc. Chauffage central, eau chaude, radiologie. Chapelle.\n\n**Résultats 1926 : 92 % de guérisons cliniques** (ni bacilles ni fièvre à la sortie).\n\n*Règlement de la cure*\n— Cure de galerie de 9 h à 12 h et de 14 h à 18 h. Silence absolu de 14 h à 16 h.\n— Les malades désignés par le Directeur suivent la **cure de nuit** sur la galerie de l'aile Est, alimentée en air froid filtré selon le procédé du Dr Castagnier.\n— Extinction des feux à 21 h. Les visiteurs sont logés au premier étage."},{"id":"carnet-julien","title":"Le carnet de Julien","scene":"le-matin-blanc","text":"*Pages écrites au crayon, d'une écriture pressée*\n\nJe n'écris ici que contre le poêle. Loin du feu, je ne veux plus rien écrire. Je ne veux plus rien du tout.\n\nLes transferts. J'ai tapé moi-même dix lettres pour Leysin. Aucune voiture n'est partie : Ducrey dit que la Renault n'a pas bougé du garage. Leurs valises sont à la lingerie du deuxième. Ils sont partis en pyjama.\n\nLe chant monte par les grilles de la galerie de nuit. Il vient d'en dessous. Au sous-sol, derrière la chaudière, il y a une porte de fer. Ducrey a une clé, et le docteur.\n\nIrène d'abord, puis moi. Je ne sais pas comment je le sais. C'est l'ordre du chant : ceux qui sont arrivés les premiers sur la galerie.\n\nLe portrait du bureau, c'est Madame Castagnier. Je l'ai vue cette nuit, en rêve, blanche, assise dans la pierre, les mains ouvertes. Elle m'a fait de la place.\n\nSi tu lis ceci : garde-moi au chaud. Ne me laisse pas dormir dehors. Et si je te dis que tout va bien, ne me crois pas."},{"id":"registre-1868","title":"Registre des sépultures des Combes, 1868","scene":"la-chapelle","text":"*Registre des sépultures de la chapelle des Combes, année 1868*\n\nLe sept février mil huit cent soixante-huit ont été retrouvés au fond de la galerie Saint-Bernard, de la mine de la Chaux, les nommés Pierre Anthonioz, quarante et un ans, Claude Perrollaz, trente-six ans, et Joseph-Marie Bouvard, vingt-neuf ans, mineurs, morts de froid, assis contre la roche. Les familles s'étant opposées à ce qu'on les en détache, l'absoute a été donnée à l'entrée de la galerie.\n\n*En marge, de la même main :* Les mineurs disent qu'ils « chantent encore » et refusent de redescendre. Superstition à combattre. La galerie a été murée le vingt mars, après trois jours de feu à l'entrée.\n\n*J. Tissot, curé*"},{"id":"cahier-de-ronde","title":"Le cahier de ronde d'Odile","scene":"l-infirmerie","text":"*Cahier de ronde de nuit, O. Perrollaz (extraits)*\n\n**Nuit du 12 au 13 septembre 1926.** 2 h, galerie de nuit : les guéris chantent en dormant, tous, bouche fermée. 4 h : M. Morel n'est plus sur sa chaise. Le docteur dit : « transféré ». Je n'ai vu aucune voiture.\n\n**Nuit du 1er au 2 janvier 1927.** Mlle Mollard debout à 1 h, les yeux ouverts. Le bromure ne fait rien. Partie à 4 h. Ses pantoufles sous la chaise.\n\n**Nuit du 8 au 9 janvier.** Du givre DANS la chambre 21 (M. Excoffier), le radiateur brûlant. 3 h : chambre vide. Le docteur m'a dit de ne plus rien noter. Je note.\n\n**Nuit du 15 au 16 janvier.** Mlle Lacombe chante seule, debout à sa fenêtre ouverte. 4 h : M. Mercadier frappe chez moi, en larmes, et me demande de l'enfermer à clé dans sa chambre. Le docteur a dit non : « Laissez-le dormir. »"},{"id":"plan-saint-bernard","title":"Le plan de la galerie Saint-Bernard","scene":"les-combes","text":"*Mine de la Chaux, galerie Saint-Bernard. Levé par J.-P. Bochatay, boiseur, 1866.*\n\nL'entrée est au bas du pré des Gentianes, côté levant. La galerie descend vers le nord sur deux cents pas jusqu'à la salle de la veine. À quatre-vingt-dix pas, à main gauche, la niche à poudre.\n\n*Au crayon, d'une main qui tremble, 1868 :*\n\nLa fleur blanche pousse sur toute la salle de la veine, et à la voûte. Ceux qui l'ont respirée guérissent de la poitrine et ne toussent plus. Puis ils chantent. On a fait le feu trois jours et muré le 20 mars. Le feu n'a pas été assez loin. Il n'y a que le feu, et il faut le porter au fond. Que Dieu garde les nôtres là-dessous."},{"id":"registre-des-sorties","title":"Registre des sorties, 1926-1927","scene":"le-bureau-du-directeur","text":"*Sanatorium des Gentianes, registre des sorties (extrait, dactylographié)*\n\n12 sept. 1926 — MOREL Lucien, 31 ans, Grenoble — guéri — transféré clinique du Chamossaire, Leysin (Vaud), voiture du Directeur.\n2 oct. — SAILLET Marguerite, 24 ans, Annecy — id.\n17 oct. — BURNIER Joseph, 45 ans, Chambéry — id.\n29 oct. — THÉVENET Germaine, 38 ans, Lyon — id.\n8 nov. — RAVANEL Paul, 27 ans, Sallanches — id.\n21 nov. — GAILLARD Henriette, 33 ans, Bonneville — id.\n4 déc. — CHARVET Émile, 52 ans, Saint-Étienne — id.\n19 déc. — REY Anatole, 29 ans, Lyon (sorti guéri le 14 juin, revenu le 18 déc.) — id.\n2 janv. 1927 — MOLLARD Suzanne, 22 ans, Les Combes — id.\n9 janv. — EXCOFFIER Raymond, 35 ans, Thonon — id.\n\n*Paraphé à chaque ligne :* H. C."},{"id":"lettre-leysin","title":"Lettre de la clinique du Chamossaire","scene":"le-bureau-du-directeur","text":"*Clinique du Chamossaire, Leysin (Vaud), le 30 novembre 1926*\n\nMonsieur et cher Confrère,\n\nLa famille de Mademoiselle Marguerite Saillet, d'Annecy, s'inquiète auprès de nous de n'avoir aucune nouvelle de sa fille, que vous nous auriez adressée le 2 octobre dernier.\n\nNous n'avons reçu ni cette malade, ni aucun malade de votre établissement, ni aucune demande d'admission de votre part. Vous comprendrez que nous ne puissions laisser cette famille dans l'incertitude.\n\nVeuillez agréer, Monsieur et cher Confrère, l'assurance de nos sentiments distingués.\n\n**Dr E. Aebischer**, médecin-directeur\n\n*Au crayon, en travers, de la main de Castagnier :* Répondu le 6 déc. : erreur d'aiguillage, dirigée sur Montana. Gagner du temps."},{"id":"journal-castagnier","title":"Le journal d'observations du Dr Castagnier","scene":"le-bureau-du-directeur","text":"*Journal d'observations, Dr H. Castagnier (extraits)*\n\n**6 octobre 1924.** Le mur a cédé sous la pioche des terrassiers. Derrière, une galerie ancienne, l'air à −6°. Trois hommes assis contre la roche, givrés, intacts. Sur toute la paroi, un lichen blanc que je ne connais pas. Faute de mieux : *Pruina canens*.\n\n**2 novembre 1924.** Madeleine dort à l'entrée de la galerie, sous les fourrures. Je n'en ai pas le droit. Je n'ai plus d'autre remède.\n\n**24 mars 1925.** Plus un bacille dans ses crachats. À la radiographie, les cavernes sont comblées par une trame claire, ramifiée, comme du givre sur une vitre.\n\n**14 janvier 1926.** Madeleine est descendue cette nuit. Je l'ai trouvée au fond, assise près des trois autres, les mains ouvertes. Elle respire, une fois toutes les quatre minutes. Je l'ai portée dans l'antichambre : à la chaleur, son souffle s'est arrêté. Redescendue, il est revenu. Elle n'est pas morte. Elle demeure.\n\n**19 mars 1926.** Fuite de vapeur dans la gaine cette nuit : +9° au fond. Ce matin, sept guéris crachent le sang. (*Plus bas :* 23 mars. Pellissier est mort.) La colonie a souffert, et ils ont souffert avec elle. Ils sont elle. Elle ne doit jamais avoir chaud.\n\n**13 septembre 1926.** Morel. Le premier des patients. Il faut un mot pour les registres. J'écris : transféré.\n\n**20 décembre 1926.** Rey, sorti guéri en juin, est remonté à pied depuis la gare, en souliers de ville, par la neige. Les guéris partis à Nice ou à Alger ne reviennent pas. C'est le froid qui les appelle.\n\n**9 janvier 1927.** Excoffier, le dixième. Lacombe ensuite, puis Mercadier : je le sais à leur souffle. Mercadier tape mes lettres ; il sait. Le mensonge ne tiendra pas jusqu'à l'été, et l'hiver prochain ils seront vingt. Mais sur cent que je sauve, quatre-vingt-dix vivent. Qui d'autre peut en dire autant ?"}],"knowledge":[{"need":"Faire parler Julien","best":"La chaleur (poêle, bain, chaufferie) et Psychologie","backup":"Persuasion ; son carnet dit tout s'il échoue"},{"need":"Gagner la confiance d'Odile","best":"Psychologie","backup":"Charme ; l'aider une heure dans son service"},{"need":"Lire les radiographies","best":"Médecine","backup":"Naturalisme ; le journal de Castagnier"},{"need":"Fouiller le bureau du directeur","best":"La clé de Julien","backup":"Discrétion, Serrurerie, Trouver Objet Caché"},{"need":"Comprendre la gaine et la chaudière","best":"Baptiste","backup":"Mécanique, Trouver Objet Caché"},{"need":"Ouvrir la porte de fer","best":"La clé de Baptiste, de Castagnier ou du tiroir","backup":"Serrurerie (difficile)"},{"need":"Forcer la vapeur dans la galerie","best":"Baptiste","backup":"Mécanique, Conduite d'engins lourds"},{"need":"Porter la dynamite au fond","best":"Baptiste pour la mèche","backup":"Chance, DEX"},{"need":"Garder Julien jusqu'à l'aube","best":"Psychologie, Persuasion","backup":"La chaleur ; l'abbé ou Odile (dé bonus) ; FOR pour le retenir"},{"need":"Résister au chant dans la salle des Gelés","best":"POU","backup":"Un allié qui tire en arrière ; Chance"}],"trackers":[{"id":"nuits","label":"Nuits aux Gentianes","max":3,"unit":"nuits","help":"Nuit 1 : la tempête et le chant. Nuit 2 : Irène descend. Nuit 3 : Julien descend.","scenes":["premiere-nuit","le-matin-blanc","deuxieme-nuit","la-nuit-du-choeur"]},{"id":"descente-julien","label":"Julien vers la galerie","max":5,"unit":"étapes","help":"Chambre, couloir, escalier de l'aile Est, sous-sol, porte de fer. +1 par quart d'heure s'il n'est pas retenu, ou à chaque échec pour le garder. À 5, il passe la porte de fer et descend s'asseoir dans la salle des Gelés.","scenes":["la-nuit-du-choeur"]},{"id":"agonie-colonie","label":"Agonie de la colonie","max":6,"unit":"paliers","help":"Vapeur : +1 par demi-heure réussie. Feu porté au fond : +2 par round. Dynamite au fond : 6 d'un coup. À 3, les Gelés ouvrent les yeux et les guéris crachent le sang. À 6, la colonie meurt.","scenes":["la-nuit-du-choeur"]}]}$story$::jsonb, now()
where not exists (select 1 from public.stories where visibility = 'marketplace' and content #>> '{meta,id}' = 'le-choeur-du-givre');

insert into public.stories (visibility, content, published_at)
select 'marketplace', $story${"format":"grimoire-story/1","meta":{"id":"le-livre-de-l-envers","title":"Le Livre de l'Envers","lang":"fr","summary":"Lyon, fin novembre 1924. Sur les pentes de la Croix-Rousse, un relieur est retrouvé mort dans son atelier fermé de l'intérieur, tous ses miroirs tournés vers le mur. Il reliait un livre ancien pour une cliente que personne ne connaît. Dans une semaine, la ville posera des lumignons à toutes ses fenêtres.","players":{"min":4,"max":5},"duration":"2 séances de 3 à 4 heures","era":"Décembre 1924","setting":"Lyon : les pentes de la Croix-Rousse et leurs traboules, le Vieux-Lyon, la Presqu'île, Fourvière","system":"d100","author":"Grimoire","license":"CC-BY-4.0","version":"1.1","tags":["groupe","enquête urbaine","Lyon","années 1920","miroirs","société secrète"],"contentWarnings":["meurtre","miroirs et doubles","sacrifice humain","deuil (guerre de 1914-1918)","enfant menacé (évoqué)"]},"overview":{"secret":"**Le Livre de l'Envers** est un in-quarto imprimé à rebours sur soie, à Lyon, en 1852, d'après un très vieux texte de banquiers lucquois de la rue Juiverie. Lu dans un miroir à la lumière d'une flamme, il ouvre sur l'**Envers**, un Lyon retourné où se tient le **Teneur**, une présence toujours vue de dos qui tient les comptes : on peut y faire passer une ruine, une dette, un malheur sur quelqu'un d'autre, et prendre sa fortune. Le mercredi 8 décembre 1852, la nuit où Lyon posa pour la première fois des lumignons à ses fenêtres, le fabricant de soieries **Claude Mazaud**, au bord de la faillite, l'ouvrit dans son atelier des pentes ; son frère Étienne fut pris en arrhes. Avec les Bellevrand, les Vial et les Dumoulin, il fonda le **Cercle de la Navette** et signa la **garde**, une page de soie signée au fil d'argent : tous les vingt-quatre ans, le soir où la ville s'allume, le compte se solde d'un vivant du sang du **premier nom** brodé, celui des Mazaud. Joséphine en 1876, Louis en 1900. Le lundi 8 décembre 1924, c'est le tour de **Lucie Perret-Mazaud**, 31 ans ; après elle, en 1948, viendra son fils Jean, 9 ans. Lucie veut sortir : vers le 20 novembre, elle a pris le livre dans la Salle des Glaces (les Mazaud en ont les clés) et, sous le nom de « Mme Morel », l'a confié le lundi 24 au relieur **Joannès Ravier** pour qu'il en ôte la garde sans l'abîmer. Elle voulait découdre le nom des Mazaud, en sachant que le nom suivant, Bellevrand, paierait à sa place. Ravier, curieux, a lu le livre au miroir le mardi 25 au soir, et a écrit à son ami le libraire Montcharmont. Le jeudi 27, l'homme de main du maître, **Gaudin**, qui faisait le tour des relieurs, est venu demander le livre ; Ravier a nié. Le soir, vers 22 h, Ravier relisait le livre quand son apprenti Firmin a vu, dans la vitre noire, un grand homme de dos debout entre eux, dans une pièce où il n'y avait personne. Ravier a confié la garde à Firmin, l'a renvoyé, s'est barricadé et a tout couvert, sauf l'encrier ouvert devant lui. Le Teneur l'a pris par ce petit miroir noir et a laissé son reflet à sa place : un cadavre à l'envers, le cœur à droite. Le vendredi 28, la police a trouvé le corps et saisi le livre ; le samedi 29, le maître du Cercle, le charmant **Hector Bellevrand**, l'a fait rendre par le commissaire central et a envoyé Gaudin chercher la garde chez la mère de Firmin. Sans garde, c'est le lecteur qui paie : Bellevrand ne lira pas sans elle. Si personne n'intervient, le lundi 8 décembre à 21 h, dans la Salle des Glaces au-dessus d'une traboule des pentes, Bellevrand lit, et Lucie entre dans la glace. Le livre et sa garde ne brûlent que cette nuit-là, quand le passage est ouvert : brûlé, le livre défait tout ce qui a été échangé, et les quatre familles perdent tout, Lucie comprise.","steps":["**Acte I** · [[l-atelier]] (lundi 1ᵉʳ décembre) : la chambre close, les glaces retournées, l'encrier, le livre de commandes (« Mme Morel »), la lettre de la rue Juiverie.","[[firmin]] : l'apprenti a vu le reflet dans la vitre ; il cache la garde de soie. L'enterrement (mardi 2) montre l'écusson de la Navette et la dame voilée.","**Acte II, dans l'ordre que choisissent les joueurs** : [[commissariat]] (le corps inversé ; Bellevrand a repris le livre ; le dossier de 1900), [[rue-juiverie]] (l'avertissement : le livre ne brûle pas), [[palais-saint-jean]] (un Mazaud disparu tous les vingt-quatre ans, le soir du 8 décembre), [[traboule]] (l'écusson, la porte de fer, la mère Brossard), [[hotel-bellevrand]] (le maître charmant et sa récompense), [[fourviere]] (Lucie avoue tout et donne ses clés).","**Acte III** · [[le-reflet]] (vendredi 5 au soir) : le reflet de Ravier écrit « le premier nom paie » ; Gaudin attaque Firmin. [[les-caves]] (facultatif) : le Grand-Livre du Cercle et l'escalier secret.","**Acte IV** · [[salle-des-glaces]] (lundi 8, 21 h) : le Cercle solde son compte ; brûler le livre, faire payer Bellevrand, ou laisser faire. [[apres-les-lumieres]] : ce que cela coûte.","Séance 1 : actes I et II, jusqu'à la rencontre avec Lucie ou l'attaque de Gaudin. Séance 2 : actes III et IV."],"mustNotMiss":["**Bellevrand et la Navette** : le dossier de police (sans jet, [[commissariat]]), la gerbe de l'enterrement ([[firmin]]), l'écusson ([[traboule]]), la carte et la chevalière ([[hotel-bellevrand]]), les échos mondains ([[palais-saint-jean]]).","**Le 8 décembre et les Mazaud** : les journaux ([[palais-saint-jean]]), le dossier de 1900 ([[commissariat]]), la mère Brossard ([[traboule]]), la clause de la garde ([[firmin]]), Lucie et sa convocation ([[fourviere]]), le Grand-Livre ([[les-caves]]).","**Le premier nom paie, on peut le découdre** : la garde ([[firmin]]), la lettre de Louis ([[fourviere]]), le message du reflet ([[le-reflet]]).","**Le livre ne brûle que la nuit du passage** : Montcharmont ([[rue-juiverie]]), Lucie et la lettre de Louis ([[fourviere]]), le Grand-Livre ([[les-caves]]).","**Où et quand** : la Salle des Glaces au-dessus de la traboule, lundi 8 à 21 h : la convocation ([[fourviere]]), la mère Brossard ([[traboule]]), Gaudin ([[le-reflet]]), le dossier de 1900 ([[commissariat]])."],"branches":["Brûler le livre pendant que le passage est ouvert : personne n'est pris (ceux qui ont été pris cette nuit reviennent), les reflets prisonniers sont libérés, et les quatre familles, Lucie comprise, sont ruinées dans l'année.","Découdre le nom des Mazaud, avant la nuit ou pendant : la glace prend Bellevrand, dernier de son sang. Le pousser dans la glace ouverte a le même effet, au prix de 1D6 SAN pour celui qui pousse.","Rapporter la garde à Bellevrand (5 000 francs) : intacte, elle condamne Lucie ; décousue en secret, elle condamne le maître, s'il ne voit pas les trous d'aiguille.","Garder la garde loin de la cérémonie ne sauve pas Lucie : Bellevrand la fait lire à sa place, et sans garde c'est le lecteur qui paie.","Convaincre Clotilde Vial de passer à la place de Lucie : Lucie vit, mais en 1948 ce sera le tour de son fils Jean.","Garder le livre : le pouvoir d'échanger, contre de la SAN et un reflet qui retarde.","Voler le livre avant le 8 : il ne brûle pas encore ; la nuit venue, le passage s'ouvre là où il est, et le Cercle vient le reprendre."],"ifStuck":["Rabatel fait signe : le secrétaire de Bellevrand est revenu demander « la page de soie brodée ».","Bellevrand invite les investigateurs ({{handout:carte-bellevrand}}) : il veut qu'ils trouvent la garde pour lui.","Firmin vient les trouver, terrifié, après la visite de Gaudin chez sa mère.","Lucie envoie son mot : Fourvière, dimanche, quatre heures.","Le reflet de Ravier dans une vitrine ([[le-reflet]]) : à jouer dès qu'une piste s'épuise.","Montcharmont envoie chercher les investigateurs : Gaudin est passé chez lui demander une « page de soie »."],"keeperTips":["À quatre ou cinq, laissez le groupe se séparer en journée : chaque accroche ouvre une piste (l'ami de l'inspecteur au commissariat, le journaliste à la bibliothèque, le libraire rue Juiverie, l'ancien apprenti chez Firmin, le client à l'atelier). Réunissez-les le soir, autour d'un mâchon, pour mettre les pièces en commun.","Tenez le compteur **Jours** : une piste prend une demi-journée, une piste ratée une journée. Les événements du calendrier ([[l-atelier]]) arrivent même si personne n'y va.","Bellevrand n'est pas un monstre de théâtre : il est drôle, généreux, il pleure son fils, il aime ses canuts. Il pense sincèrement qu'une famille qui paie vaut mieux qu'une ville qui a faim. Faites-le aimer un peu.","Le Teneur n'a pas de visage : on le voit toujours de dos, de quelque côté qu'on se place. Il ne parle pas. Montrez-le rarement : la vitre du jeudi (racontée), la vitrine du café, puis les quarante glaces.","Petit détail à semer : le reflet de quiconque a tenu la garde a une demi-seconde de retard dans les vitrines.","Lyon en 1924 : les traboules, le claquement des métiers derrière les hautes fenêtres, la ficelle qui monte à la Croix-Rousse et à Fourvière, le brouillard de la Saône, les mâchons du matin. Le 8 décembre, des lumignons dans leurs verres de couleur sur chaque rebord de fenêtre."]},"acts":[{"id":"le-relieur","title":"Le relieur de la montée Saint-Sébastien","scenes":[{"id":"l-atelier","title":"L'atelier de la montée Saint-Sébastien","lead":"Lundi 1ᵉʳ décembre : la chambre close du relieur, ses glaces retournées, son livre de commandes.","screen":{"place":"library","preset":"dust","time":"day"},"readAloud":["La montée Saint-Sébastien grimpe raide entre des immeubles hauts et gris, percés de grandes fenêtres. Derrière les vitres, partout, le claquement des métiers à tisser. Au numéro 12, une voûte mène à une cour humide où sèche du linge.","La porte de l'atelier a été forcée : le bois est fendu autour des deux verrous. À l'intérieur, une odeur de colle de peau et de cuir. Sur les murs, huit miroirs de toutes tailles sont tournés face au plâtre. Les carreaux des fenêtres sont couverts, du haut en bas, de papier marbré bleu et rouge.","La concierge reste sur le seuil, les bras croisés sur son tablier. « Moi, je n'entre pas. Il était pas superstitieux, M. Ravier. Pas avant jeudi. »"],"flow":[{"title":"La pièce","text":"Établi sous les fenêtres, presse à percussion, cousoir, fers à dorer rangés au-dessus du poêle. Une armoire, tirée devant la porte, a été repoussée par la police. Sur l'établi : une bougie entièrement consumée, un encrier ouvert, des fils de soie ivoire coupés, des ais de bois nus. Le cuivre de la presse est enveloppé d'un chiffon.","extra":"Pas de jet : tout cela se voit. Le livre n'est plus là (voir [[commissariat]])."},{"title":"Les miroirs","text":"Si on en retourne un : un simple miroir. Sur le plus grand, à hauteur de visage, la trace d'une main posée à plat. Elle ne part pas au chiffon : elle est de l'autre côté du verre. On peut croire à un défaut du tain.","roll":{"type":"san","san":"0/1","label":"La main dans la glace"}},{"title":"L'encrier","roll":{"type":"skill","options":["spot-hidden"]},"success":"Tout ce qui pouvait refléter a été couvert : glaces, vitres, cuivre. Tout, sauf l'encrier, ouvert juste devant la place où Ravier était assis, à côté du livre. À la flamme d'une bougie, l'encre noire fait un miroir parfait.","failure":"Un encrier ouvert, de l'encre qui sèche.","extra":"Si quelqu'un se penche sur l'encre à la bougie : une silhouette passe dans le reflet, de dos. Peut-être celle d'un des investigateurs."},{"title":"Le livre de commandes","text":"Sur l'étagère près de la porte, ouvert à la dernière page → {{handout:registre-commandes}}. Pas de jet.","extra":"« Mme Morel » est Lucie Perret-Mazaud ([[fourviere]]). La note en marge est de la main de Ravier."},{"title":"La lettre de la rue Juiverie","roll":{"type":"skill","options":["spot-hidden"]},"success":"Dans la poche du tablier pendu derrière la porte, une lettre froissée → {{handout:lettre-montcharmont}}.","failure":"Rien. Mais la concierge se souvient : « Jeudi matin, il a reçu une lettre de la rue Juiverie. Il l'a lue dans la cour et il est devenu tout blanc. » La lettre finit par être retrouvée dans le tiroir de l'établi, sous les fers, une heure plus tard."},{"title":"Interroger la concierge","text":"{{npc:benoite-gros}} parle volontiers, surtout de ce qu'elle n'a pas compris.","roll":{"type":"skill","options":["charm","persuade","fast-talk"]},"success":"Elle raconte tout : la dame voilée du lundi 24, en demi-deuil gris, gantée, qui sentait l'iris et regardait sans cesse derrière elle ; le grand costaud en casquette, l'oreille gauche fendue d'une vieille cicatrice, venu jeudi vers trois heures demander « un livre en soie » ; jeudi soir vers dix heures et demie, un bruit de meubles traînés ; l'adresse de Firmin, l'apprenti.","failure":"Elle parle surtout de la dame voilée (« une dame de la haute ») et donne l'adresse de Firmin. Le costaud, elle ne s'en souviendra qu'en le revoyant.","pushed":"Elle se vexe et raconte dans tout le quartier qu'on fouine chez le mort : Gaudin l'apprend le soir même."},{"title":"La sœur de Ravier","text":"La concierge prévient : Mme Jacquet, la sœur du relieur, fait vider l'atelier samedi 6. Ce qui n'aura pas été vu d'ici là partira à la brocante.","goto":["firmin","commissariat","rue-juiverie"]}],"notes":[{"title":"Accroches (une par investigateur)","items":["**L'ami de l'inspecteur** : {{npc:germain-rabatel}} n'aime pas qu'on lui ait fait classer l'affaire en vingt-quatre heures. Il demande à un vieil ami de regarder, sans bruit. Ouvre le [[commissariat]] sans jet.","**L'ancien apprenti** : formé chez Ravier il y a quinze ans, aujourd'hui relieur à son compte. Il connaît l'atelier par cœur (dé bonus aux fouilles), et Firmin lui fait confiance ([[firmin]]).","**Le client** : collectionneur, il avait confié à Ravier un livre d'heures lyonnais de 1548 (commande n° 1190). Il veut le récupérer avant la vente de samedi, et comprendre.","**Le journaliste du *Progrès*** : son rédacteur en chef veut « la chambre close de la Croix-Rousse » en trois colonnes. Il a accès aux archives du journal (une seconde source pour [[palais-saint-jean]]).","**Le libraire ancien** : confrère d'{{npc:isidore-montcharmont}}, qui l'appelle à l'aide : « Joannès devait venir dimanche. Il est mort jeudi. Et je crois savoir pourquoi. »","**Le médecin** : camarade de faculté du {{npc:lucien-fayolle}}, qui lui écrit : « Viens voir un cadavre qui n'aurait pas dû exister. »"]},{"title":"Calendrier","items":["Vers le 20 novembre : Lucie prend le livre dans la Salle des Glaces.","Lun. 24 nov. : « Mme Morel » (Lucie) apporte le livre à Ravier.","Mar. 25 au soir : Ravier lit le livre dans un miroir pour la première fois. Il écrit à Montcharmont.","Mer. 26 : Bellevrand découvre le vol. Gaudin fait le tour des relieurs.","Jeu. 27 : la lettre de Montcharmont le matin ; Gaudin à l'atelier vers 15 h ; à 22 h, Firmin voit le reflet. Ravier lui confie la garde et s'enferme.","Ven. 28, 8 h 20 : la police force la porte. Le livre est mis sous scellés. Le soir, un entrefilet du *Progrès* parle d'un « livre ancien imprimé sur soie ».","Sam. 29 : autopsie ; plainte de Bellevrand à 11 h, livre rendu à 16 h. Gaudin chez la mère de Firmin vers 17 h.","**Lun. 1ᵉʳ déc. : début de la partie.** Lucie reçoit sa convocation.","Mar. 2, 10 h : enterrement de Ravier à Saint-Polycarpe, puis au cimetière de Loyasse.","Ven. 5 au soir : Gaudin s'en prend à Firmin ([[le-reflet]]). Sam. 6 : l'atelier est vidé ; Lucie envoie son mot si personne n'est venu à elle. Dim. 7, 16 h : Fourvière.","**Lun. 8 déc.** : lumignons à la nuit tombée ; le Cercle monte à 21 h ([[salle-des-glaces]])."]}],"npcs":["benoite-gros"],"handouts":["registre-commandes","lettre-montcharmont"],"ambience":["street","clock"],"sfx":["door-creak","latch"],"next":["firmin","commissariat","rue-juiverie","palais-saint-jean"]},{"id":"firmin","title":"Firmin, l'apprenti","lead":"Le témoin du reflet, la garde de soie qu'il cache, et l'enterrement du mardi.","screen":{"place":"street","preset":"fog","time":"dusk"},"readAloud":["En haut de la colline, sur le plateau, les immeubles de canuts alignent leurs fenêtres immenses. Au cinquième, sans ascenseur, une porte s'entrouvre sur une pièce de quatre mètres sous plafond, où une femme dévide de la soie sur un rouet.","Le garçon qui se lève de la table a quinze ans, des mains tachées de colle et des yeux qui n'ont pas dormi. Avant de vous répondre, il regarde la fenêtre. Puis il tire le rideau."],"flow":[{"title":"Trouver Firmin","text":"Rue d'Austerlitz, chez sa mère, Mme Chabert, dévideuse. L'adresse vient de la concierge. La mère est méfiante : un homme est déjà venu samedi."},{"title":"Le récit du jeudi soir","text":"Sans jet, si on l'écoute : vers dix heures, {{npc:firmin-chabert}} balayait. Le patron lisait un livre de soie dans un miroir à main, à la bougie, en parlant tout seul. Firmin a regardé la fenêtre noire. Dedans, il y avait l'atelier, le patron, lui-même, et entre eux deux un grand homme en redingote, de dos. Il s'est retourné : personne. Le patron l'avait vu aussi.","extra":"C'est le reflet vu dans la vitre alors qu'il n'y avait personne dans la pièce. Psychologie : Firmin est terrifié, et sincère."},{"title":"Les derniers mots du patron","text":"« Il m'a donné un paquet. Il m'a dit : *Prends ça, ne l'ouvre jamais devant une glace, ne le donne à personne, même pas à la dame.* Il a dit qu'il essaierait de le brûler, et puis il a ri : *ça ne brûle pas, ces choses-là.* Il m'a mis dehors. Je l'ai entendu pousser les verrous, et traîner l'armoire. »"},{"title":"Gagner sa confiance","text":"L'ancien apprenti de Ravier obtient le paquet sans jet.","roll":{"type":"skill","options":["persuade","charm","psychology"]},"success":"Il sort de sous son matelas un papier kraft ficelé. Dedans, une feuille de soie brodée → {{handout:garde-de-soie}}.","failure":"Il jure qu'il n'a rien. Il la donnera s'ils le protègent de Gaudin ([[le-reflet]]), ou s'il vient les trouver, terrifié, après une nouvelle visite du costaud.","pushed":"Firmin s'enfuit dans l'escalier avec le paquet. Il revient le soir, mais Gaudin l'a vu courir : il reviendra plus tôt."},{"title":"Lire la garde","text":"Toute la broderie est à l'envers. Il faut un miroir, ou regarder l'étoffe par derrière, à contre-jour : sur l'envers de la soie, le texte se lit à l'endroit.","roll":{"type":"skill","options":["spot-hidden","art-craft"]},"success":"Quelqu'un remarque qu'à contre-jour, par l'envers, les lettres se lisent : pas besoin de miroir.","failure":"Il faudra un miroir. C'est sans danger : la garde n'est pas le livre. Mais Firmin supplie qu'on ne le fasse pas chez lui.","extra":"Désormais, le reflet de quiconque a tenu la garde a un très léger retard dans les vitres. Ne le dites que si quelqu'un regarde."},{"title":"L'homme de samedi","text":"Mme Chabert : samedi vers cinq heures, un grand costaud poli, l'oreille fendue, a demandé « le paquet du patron, de la part du propriétaire ». Elle n'a rien dit. Il a laissé une pièce de cinq francs et promis de revenir.","extra":"C'est {{npc:ferreol-gaudin}}. Si personne ne protège Firmin, il revient le vendredi 5 au soir ([[le-reflet]])."},{"title":"L'enterrement (mardi 2, 10 h)","text":"Église Saint-Polycarpe, sur les pentes, puis le cimetière de Loyasse. Firmin y va. Au fond de l'église, une dame voilée de gris, seule ; près du portail, Gaudin. Parmi les couronnes, une gerbe de lys avec un ruban de soie tissé : *Le Cercle de la Navette à M. J. Ravier*, et un écusson : une navette posée sur un miroir ovale, une clef au-dessus.","roll":{"type":"skill","options":["stealth","track"]},"success":"Ils suivent la dame voilée à pied jusqu'à la rue Puits-Gaillot : la maison Mazaud, soieries. Ils remarquent que Gaudin la suit aussi.","failure":"Elle monte dans un fiacre. Le cocher, retrouvé à la station, se souvient de la course : rue Puits-Gaillot, maison Mazaud.","goto":["fourviere","hotel-bellevrand"]}],"npcs":["firmin-chabert","ferreol-gaudin","lucie-mazaud"],"handouts":["garde-de-soie"],"ambience":["street","wind"],"sfx":["footsteps","knocking"],"next":["commissariat","rue-juiverie","palais-saint-jean","traboule","hotel-bellevrand","fourviere"]}]},{"id":"les-fils","title":"Les fils de la soie","scenes":[{"id":"commissariat","title":"Le commissariat du 1ᵉʳ arrondissement","lead":"Le dossier classé en vingt-quatre heures, le cadavre à l'envers, et un nom : Bellevrand.","screen":{"place":"police","preset":"rain","time":"day"},"readAloud":["Une salle de garde qui sent le poêle à charbon et le drap mouillé. Des agents en pèlerine secouent la pluie de leur képi. Derrière un guichet, un planton tape à la machine avec deux doigts.","L'inspecteur Rabatel vous emmène dans un bureau minuscule et referme la porte. Il pose sur la table une chemise cartonnée, très mince, et garde la main dessus. « Avant que vous lisiez : officiellement, c'est un cœur qui a lâché. »"],"flow":[{"title":"Rabatel","text":"{{npc:germain-rabatel}} montre le dossier sans jet à l'ami de l'accroche. Les autres doivent le convaincre.","roll":{"type":"skill","options":["persuade","law","credit-rating"]},"success":"Il fait passer le dossier → {{handout:rapport-police}}.","failure":"Il refuse. Le soir, il glisse le dossier sous la porte de l'un d'eux avec un mot : *À me rendre demain.*"},{"title":"Le cadavre à l'envers","text":"Le rapport du {{npc:lucien-fayolle}} : cœur à droite, alliance à la main droite, la vieille cicatrice de la paume gauche passée à droite. Le docteur, à l'Hôtel-Dieu, en parle volontiers.","roll":{"type":"skill","options":["medicine","first-aid"]},"success":"Ce n'est pas une rareté de naissance : tout est inversé, jusqu'aux grains de beauté et à la raie des cheveux, que Firmin décrit de l'autre côté. Fayolle, à voix basse : « Comme si on avait enterré son reflet. »","failure":"Une anomalie de naissance très rare, dit Fayolle, mais qu'un conseil de révision n'aurait jamais pu manquer. Il n'en dort plus.","extra":"Le Teneur a pris Ravier de l'autre côté et laissé ici son reflet, qui ne vit pas de ce côté-ci."},{"title":"La plainte et la restitution","text":"Sans jet, dans le dossier : samedi 29, 11 h, plainte de M. Hector Bellevrand, négociant en soieries, pour le vol du livre ; 16 h, scellé n° 4 rendu à son secrétaire, sur ordre du commissaire central. Rabatel : « Et le secrétaire a demandé trois fois s'il n'y avait pas aussi une page de soie brodée. »","goto":["hotel-bellevrand"]},{"title":"L'affaire de 1900","text":"Si on parle de la Navette, des Mazaud ou du 8 décembre, Rabatel fouille les archives de l'hôtel de police (une demi-journée).","roll":{"type":"skill","options":["library-use"]},"success":"Le dossier de disparition de Louis Mazaud, 31 ans, fabricant de soieries : vu pour la dernière fois le samedi 8 décembre 1900 vers 20 h, en habit, entrant dans une traboule de la rue des Tables-Claudiennes. Une note : *son cercle, la Navette, y a un local. M. Jules Bellevrand, président, affirme qu'il n'y est jamais arrivé.* Classé : présumé noyé.","failure":"Le dossier est introuvable ce jour-là. Rabatel le retrouve le lendemain matin (un jour de perdu).","goto":["traboule"]},{"title":"La mise en garde","text":"« Le commissaire central m'a dit de laisser tomber. Les soyeux ont le bras long, ici. Si vous trouvez quelque chose, apportez-le-moi. Pas à lui. »","extra":"Rabatel peut venir le 8 au soir si on le prévient : un revolver de plus, mais il aura du mal à croire ce qu'il verra."}],"npcs":["germain-rabatel","lucien-fayolle"],"handouts":["rapport-police"],"ambience":["crowd-indoor","rain"],"sfx":["door-open","footsteps"],"next":["hotel-bellevrand","traboule","palais-saint-jean","rue-juiverie"]},{"id":"rue-juiverie","title":"La librairie de la rue Juiverie","lead":"Le vieil ami de Ravier sait ce qu'est le livre, d'où il vient, et qu'il ne brûle pas.","screen":{"place":"library","preset":"candle","time":"dusk"},"readAloud":["Rue Juiverie, dans le Vieux-Lyon, les façades de la Renaissance se penchent les unes vers les autres. Une enseigne de fer : *I. Montcharmont, livres anciens*. Le grelot de la porte sonne longtemps.","La boutique est un couloir de livres jusqu'au plafond. Contre les rayonnages, des formes drapées de blanc, hautes comme des hommes. Un vieil homme en calotte de velours sort de l'ombre, une loupe à la main. « Vous venez pour Joannès. Fermez la porte. »"],"flow":[{"title":"Les draps","text":"{{npc:isidore-montcharmont}} a couvert tous les miroirs anciens de sa boutique depuis dimanche soir, quand il a appris la mort de Ravier. Il ne s'en cache pas : « Une précaution de vieux fou. »"},{"title":"Ce qu'il sait du livre","text":"Sans jet, l'essentiel : un in-quarto imprimé à rebours sur soie, à Lyon, en 1852, pour un fabricant nommé Mazaud. Le texte est bien plus ancien. On l'appelle le Livre de l'Envers.","roll":{"type":"skill","options":["occult","history"]},"success":"L'histoire entière : au XVIᵉ siècle, ici même, rue Juiverie, un banquier de Lucques aurait écrit un *Miroir des débiteurs*, qu'on lisait au miroir pendant les paiements des foires pour voir « l'envers des comptes » : qui paie, au bout du compte, la fortune des autres. Le manuscrit s'est perdu ; Mazaud en a trouvé une copie et l'a fait imprimer sur soie, « parce que la soie est une étoffe vivante ». Il a fondé ensuite un cercle de soyeux : la Navette.","failure":"Il ne connaît que le nom, et une rumeur : « un cercle de soyeux, la Navette, s'en sert depuis soixante-dix ans »."},{"title":"La visite de 1899","text":"Sans jet : « En octobre 1899, Louis Mazaud est venu ici, blanc comme un linge, avec le livre. Il voulait que je l'achète et que je l'emporte loin, en Amérique s'il le fallait. Il l'avait jeté au feu : le feu s'était couché dessus sans le prendre. J'ai refusé. J'avais peur. Il a disparu le soir des illuminations de l'année suivante. »","extra":"Deux faits clés : le livre ne brûle pas (Montcharmont ignore qu'il brûle la nuit où le passage est ouvert), et les Mazaud disparaissent le 8 décembre."},{"title":"Le conseil","text":"« Couvrez les glaces. Ne lisez jamais ce livre dans un miroir, surtout le soir, à la flamme. Et méfiez-vous de la Navette : ils sont charmants. Ils ont toujours été charmants. »","roll":{"type":"skill","options":["occult"]},"success":"Il ajoute ce que disent les vieux catalogues des livres de miroir : *qui tient la garde tient le compte*. La page de garde compte plus que tout le reste.","failure":"Il n'en sait pas plus."},{"title":"Le visiteur","text":"Le mercredi 3 (ou le lendemain de leur visite), Gaudin passe demander si Ravier ne lui aurait pas confié « une page de soie ». Montcharmont le dit s'ils reviennent, ou les envoie chercher.","goto":["traboule","hotel-bellevrand"]}],"npcs":["isidore-montcharmont"],"ambience":["clock","rain-window"],"sfx":["door-creak"],"next":["palais-saint-jean","traboule","hotel-bellevrand","fourviere"]},{"id":"palais-saint-jean","title":"La bibliothèque du palais Saint-Jean","lead":"Les journaux reliés : un Mazaud disparaît tous les vingt-quatre ans, le soir du 8 décembre.","screen":{"place":"library","preset":"dust","time":"day"},"readAloud":["La Bibliothèque de la Ville occupe l'ancien palais des archevêques, collé à la cathédrale Saint-Jean. On monte un escalier de pierre usé en cuvette. Dans la salle de lecture, sous les hautes fenêtres, des lecteurs en pardessus prennent des notes dans le froid.","Les cloches de la cathédrale sonnent l'heure à travers les murs. Une bibliothécaire aux manches de lustrine vous regarde par-dessus ses lunettes. « Joannès Ravier ? Il nous restaurait nos registres. Nous l'aimions bien. »"],"flow":[{"title":"Mlle Sauzet","text":"{{npc:adrienne-sauzet}} aide volontiers ceux qui viennent pour Ravier. Elle connaît les collections de journaux reliés : *Courrier de Lyon*, *Salut public*, *Progrès*. Le nom de Mazaud, de la Navette, de Bellevrand ou la date du 8 décembre suffisent à lancer la recherche."},{"title":"Les journaux reliés","roll":{"type":"skill","options":["library-use"]},"success":"En deux heures, quatre entrefilets → {{handout:coupures}}.","failure":"Une journée entière de recherche (un jour de perdu sur le compteur), mais le résultat est le même.","pushed":"Ils trouvent, mais Mlle Sauzet, inquiète, en parle au secrétaire du Cercle, M. Collonges, qui vient chaque mois : Bellevrand sait qu'on fouille, et Gaudin les suit."},{"title":"Compter les années","text":"1852, 1876, 1900 : chaque fois un Mazaud, chaque fois le soir des illuminations.","roll":{"type":"characteristic","options":["INT"]},"success":"Vingt-quatre ans d'écart. Le prochain soir tombe cette année : lundi 8 décembre 1924.","failure":"Mlle Sauzet fait le calcul à leur place, un doigt sur le calendrier : « Mais... c'est lundi prochain. »"},{"title":"Le dernier Mazaud","text":"Sans jet, dans l'Annuaire du commerce : le dernier Mazaud vivant est une femme, Mme veuve Perret, née Mazaud, qui dirige la maison de soieries de la rue Puits-Gaillot. Son mari est mort à Verdun en 1916 ; elle a un fils.","goto":["fourviere"]},{"title":"Les archives du Progrès","text":"Le journaliste peut faire la même recherche au journal, rue de la République, sans jet : la documentation du *Progrès* garde un dossier « Mazaud », ouvert en 1900, où quelqu'un a noté au crayon : *et 1876 ? et 1852 ?*","goto":["traboule"]}],"npcs":["adrienne-sauzet"],"handouts":["coupures"],"ambience":["clock"],"sfx":["footsteps"],"next":["fourviere","traboule","rue-juiverie","hotel-bellevrand"]},{"id":"traboule","title":"La traboule de la Navette","lead":"Un écusson de pierre dans une cour des pentes, une vieille dévideuse, une porte de fer.","screen":{"place":"street","preset":"fog","time":"night"},"readAloud":["On entre par une porte quelconque de la rue des Tables-Claudiennes. Derrière, un couloir voûté qui sent la pierre mouillée, une cour, un escalier à vis à jour, une seconde voûte. La traboule descend par paliers vers la montée des Carmélites, de cour en cour.","Dans la deuxième cour, au-dessus d'une porte de fer, un écusson sculpté, noirci par la suie : une navette de tisserand posée sur un miroir ovale, une clef au-dessus. Dessous court une devise dont toutes les lettres sont gravées à l'envers.","Au rez-de-chaussée, derrière une vitre, une très vieille femme fait tourner un rouet. Elle vous regarde lever la tête vers l'écusson, et son rouet s'arrête."],"flow":[{"title":"Trouver la traboule","text":"Par le dossier de 1900 ([[commissariat]]), par Lucie, par Montcharmont, ou en suivant Gaudin ou Bellevrand un soir. Sans indication, les pentes comptent des dizaines de traboules.","roll":{"type":"skill","options":["spot-hidden","navigate"]},"success":"Ils la trouvent dans la soirée.","failure":"Une soirée perdue dans les traboules ; ils la trouvent le lendemain."},{"title":"L'écusson","text":"La devise, lue dans un miroir ou de mémoire : *CE QUI EST DESSOUS TIENT CE QUI EST DESSUS*.","roll":{"type":"skill","options":["history","appraise"]},"success":"La pierre date des années 1850. C'est le même écusson que sur la garde, sur la gerbe de l'enterrement, sur la chevalière de Bellevrand. La porte de fer et sa serrure, elles, sont neuves.","failure":"Un vieil emblème de soyeux, comme il y en a cent sur les pentes."},{"title":"La mère Brossard","text":"Un café, une brioche aux pralines et un peu de patience aident.","roll":{"type":"skill","options":["charm","persuade"]},"success":"{{npc:mere-brossard}} : « Ils montent chaque année, le maître surtout, le soir des lumignons. Et tous les vingt-quatre ans, ils montent tous, en habit, avec quelqu'un qu'ils tiennent par le bras. En 76, une jeune fille en robe de bal. En 1900, un monsieur qui m'a dit bonsoir. Ils ne sont jamais redescendus. Lundi, c'est encore le tour. » Elle montre du menton les grandes fenêtres du cinquième : l'ancien atelier.","failure":"Elle se signe et ferme son volet. Mais à travers : « Lundi soir, n'y soyez pas. »"},{"title":"La porte de fer","text":"Avec les clés de Lucie : pas de jet. Sinon, la serrure, ou forcer la porte (FOR, jets rapides de la scène).","roll":{"type":"skill","options":["locksmith"],"difficulty":"hard"},"success":"Elle s'ouvre sans bruit : un escalier descend vers les caves ([[les-caves]]), un autre monte, fermé par une grille.","failure":"Trop de bruit : la mère Brossard frappe à sa vitre pour les prévenir que quelqu'un vient. Ils ont juste le temps de se cacher.","goto":["les-caves"]},{"title":"Le guetteur","text":"Le soir, {{npc:ferreol-gaudin}} vient vérifier la porte, ou y conduit Bellevrand, qui monte seul avec une lanterne préparer la salle.","roll":{"type":"group","options":["stealth"]},"success":"Ils voient sans être vus : Bellevrand monte, Gaudin garde la porte en fumant. Gaudin a l'oreille gauche fendue.","failure":"Gaudin les voit. Il ne se bat pas ici : il les salue de la casquette. Bellevrand sait le soir même qu'on s'intéresse à la Navette, et les invite ({{handout:carte-bellevrand}})."}],"rolls":[{"type":"characteristic","options":["STR"],"label":"Forcer la porte de fer (bruyant)"}],"npcs":["mere-brossard","ferreol-gaudin","hector-bellevrand"],"ambience":["wind","village-night"],"sfx":["footsteps","latch","dog-bark"],"next":["les-caves","hotel-bellevrand","fourviere","le-reflet"]},{"id":"hotel-bellevrand","title":"L'hôtel Bellevrand","lead":"Le maître de la Navette reçoit : charmant, généreux, et il veut la garde.","screen":{"place":"manor","preset":"rain","time":"dusk"},"readAloud":["Rue Sala, près de Bellecour, une façade claire aux balcons de fer forgé. Un valet prend vos manteaux mouillés. Dans le vestibule, le grand miroir est voilé de crêpe noir, comme ceux de l'escalier, comme celui du salon.","Hector Bellevrand se lève de son fauteuil près du feu. Cheveux blancs, moustache soignée, une chevalière à la main gauche. Il vous serre la main un par un et retient vos noms du premier coup. « Pardonnez le deuil de cette maison. Mon fils est tombé au Chemin des Dames, et je n'ai jamais eu le cœur d'ôter les voiles. »"],"flow":[{"title":"L'invitation","text":"S'ils ont fait parler d'eux (concierge, bibliothèque, Gaudin), Bellevrand les invite lui-même → {{handout:carte-bellevrand}}. Sinon, ils peuvent se présenter : il reçoit tout le monde, à l'heure du thé."},{"title":"La conversation","text":"{{npc:hector-bellevrand}} parle du Cercle (une vieille société de bienfaisance qui entretient l'hospice des vieux canuts), de Ravier (« un artisan admirable, quelle tristesse »), du livre (« une curiosité de 1852 : notre fondateur voulait prouver qu'on peut tout imprimer sur soie, même à rebours »).","roll":{"type":"skill","options":["psychology"]},"success":"Il est sincère sur l'hospice et sur son fils. Il ment sur le livre, et très bien. Au nom de Mazaud, il a un instant de tristesse vraie.","failure":"Un homme de bien, affable, cultivé. Difficile de ne pas l'apprécier."},{"title":"L'offre","text":"« Il manque au livre sa page de garde : une soie brodée des signatures de nos fondateurs. Une relique. Je donnerai cinq mille francs à qui me la rapportera, et je ne demanderai rien à personne. » Il soupçonne « une femme » d'avoir pris le livre, et refuse de dire laquelle : « Je ne porterai pas plainte contre elle. »","extra":"Cinq mille francs : plus d'un an de traitement d'un inspecteur de police."},{"title":"S'ils lui rapportent la garde","branch":"S'ils lui rapportent la garde","text":"Il paie comptant, remercie avec chaleur, puis regarde la soie à la lampe. Si le nom des Mazaud a été décousu, jet de Chance du plus malchanceux du groupe.","roll":{"type":"luck"},"success":"Il ne voit rien. Il range la garde dans son coffre, avec le livre.","failure":"Il voit les trous d'aiguille. Il sourit, très calme, et sonne Gaudin. Clotilde Vial recoudra le nom avant lundi, à moins qu'on ne reprenne la garde.","extra":"Il peut proposer à l'un d'eux d'entrer au Cercle : coudre son nom au bas de la garde. Ce qu'il promet est vrai : la fortune. Ce qu'il tait aussi : le sang d'un nom paie un jour."},{"title":"S'ils refusent","branch":"S'ils refusent ou n'ont rien","text":"Il sourit, ne s'en offense pas, renouvelle l'offre « si vous la trouviez ». Gaudin les raccompagne en automobile et retient leurs adresses."},{"title":"Clotilde Vial","text":"Si la visite dure, {{npc:clotilde-vial}}, vieille amie de la maison, entre sans se faire annoncer et parle trop : « Ce sont les gens pour la garde, Hector ? Pauvre petite Lucie... » Bellevrand la raccompagne doucement.","roll":{"type":"skill","options":["charm","psychology"]},"success":"Seule un instant avec eux, elle murmure : « J'ai vu partir Joséphine Mazaud en 1876. Elle avait dix-neuf ans. Je ne veux pas voir partir sa petite-nièce. Mais je suis trop vieille pour être courageuse. »","failure":"Elle se tait dès que Bellevrand revient."},{"title":"Regarder autour de soi","roll":{"type":"skill","options":["spot-hidden"]},"success":"La chevalière porte l'écusson de la traboule. Dans la bibliothèque, derrière un miroir voilé, un coffre-fort : le livre y reste jusqu'au 8.","failure":"Des livres reliés de soie, des portraits de famille, le portrait d'un jeune lieutenant au crêpe noir.","extra":"Voler le livre : Serrurerie difficile, de nuit, Gaudin et un valet dans la maison. Il ne brûle pas avant le 8 (voir [[salle-des-glaces]])."}],"npcs":["hector-bellevrand","clotilde-vial","ferreol-gaudin"],"handouts":["carte-bellevrand"],"ambience":["rain-window","fireplace","clock"],"sfx":["door-open","knocking"],"next":["fourviere","traboule","le-reflet"]},{"id":"fourviere","title":"Lucie, à Fourvière","lead":"Celle qui veut sortir : la Mazaud qui doit payer lundi, ses lettres de soie, ses clés.","screen":{"place":"church","preset":"candle","time":"dusk"},"readAloud":["La ficelle vous hisse au flanc de la colline, puis il faut monter à pied, dans le vent. En haut, la basilique toute neuve écrase de sa masse blanche la vieille chapelle. En bas, Lyon fume sous un ciel bas, entre ses deux fleuves.","Dans la chapelle, il fait presque noir. Des centaines de cierges brûlent devant la Vierge. Les murs sont couverts jusqu'à la voûte d'ex-voto : des plaques de marbre, des cœurs d'argent, des béquilles. Pas une glace.","Une femme en demi-deuil gris se lève d'un prie-Dieu et relève sa voilette. « Ici, ils ne nous voient pas. Asseyez-vous près de moi. »"],"flow":[{"title":"Le rendez-vous","text":"Si on va chez elle, rue Puits-Gaillot, {{npc:lucie-mazaud}} nie tout devant ses employés (Gaudin la fait surveiller) et glisse un mot : *Demain, Fourvière, quatre heures, chapelle de la Vierge. Venez sans miroir.* Si personne ne vient à elle, elle envoie ce mot elle-même samedi 6, pour dimanche 7."},{"title":"La confiance","text":"S'ils ont la garde et la lui montrent : pas de jet, elle pleure en la voyant.","roll":{"type":"skill","options":["persuade","psychology","charm"]},"success":"Elle raconte tout et montre ce qu'elle a apporté → {{handout:convocation-soie}} et {{handout:lettre-louis}}.","failure":"Elle avoue seulement être « Mme Morel » et avoir confié le livre à Ravier. Elle laisse la convocation sur le banc en partant ; la lettre de son père, elle la donnera lundi.","pushed":"Elle se lève et s'en va. Gaudin, qui l'a suivie, attend sur le parvis et voit leurs visages."},{"title":"Ce qu'elle veut","text":"« Le premier nom brodé sur la garde est le nôtre. Le Teneur prend le sang du premier nom : Étienne, ma grand-tante Joséphine, mon père. Lundi, moi. Et dans vingt-quatre ans, mon fils Jean. Je voulais découdre notre nom. Le suivant, c'est Bellevrand. Je le sais. Il le sait depuis toujours. »","extra":"Elle ne cache rien de ce que coûte chaque issue (voir [[salle-des-glaces]])."},{"title":"Brûler le livre ?","text":"« Il ne brûle pas. Mon père a essayé. Mon arrière-grand-mère aussi, en 1877, après Joséphine. Peut-être cette nuit-là seulement, quand la glace est ouverte : mon père l'a écrit. Et si on le brûle, tout ce que le Cercle a reçu repart. Ma maison, mes trois cents métiers, mes ouvriers. Je l'accepterais. Mais il faut que vous le sachiez. »"},{"title":"L'ex-voto","roll":{"type":"skill","options":["spot-hidden"]},"success":"Au mur, une petite plaque de marbre : *À Notre-Dame, pour Joséphine, de l'autre côté des glaces. 1877. A. M.* La mère de Joséphine.","failure":"Lucie la leur montre en partant, sans un mot."},{"title":"Les clés","text":"Les Mazaud sont les gardiens de la salle : Lucie a les clés de la porte de fer de la traboule et de la grille de l'escalier. Elle les donne s'ils promettent d'être là lundi soir. Elle-même montera avec le Cercle : « Si je n'y vais pas, ils iront chercher Jean. »","goto":["traboule","les-caves","salle-des-glaces"]}],"npcs":["lucie-mazaud"],"handouts":["convocation-soie","lettre-louis"],"ambience":["wind","crowd-indoor"],"sfx":["footsteps","door-creak"],"next":["traboule","les-caves","le-reflet","salle-des-glaces"]}]},{"id":"les-reflets","title":"Les reflets","scenes":[{"id":"le-reflet","title":"La nuit des pentes","lead":"Le reflet de Ravier écrit sur une vitrine ; Gaudin vient chercher la garde.","screen":{"place":"street","preset":"fog","time":"night"},"readAloud":["Il est tard. Le brouillard monte de la Saône et noie les becs de gaz des pentes. La montée est déserte, sauf un café dont la vitrine éclaire encore le pavé mouillé.","Dans la vitrine, vous vous voyez passer, tous. Puis vous voyez qu'il y a quelqu'un de plus parmi vous, dans le reflet : un homme en tablier de cuir, les manches retroussées. Sur le trottoir, à cet endroit, il n'y a personne."],"flow":[{"title":"Quand jouer cette scène","text":"Vendredi 5 au soir par défaut, ou la première nuit où ils passent sur les pentes après avoir rencontré Firmin. Elle peut aussi relancer une table qui piétine."},{"title":"Le reflet de Ravier","text":"Ceux qui l'ont connu reconnaissent {{npc:joannes-ravier}}. Il les regarde, pose un doigt sur ses lèvres, puis souffle sur la vitre, de l'intérieur.","roll":{"type":"san","san":"0/1D4","label":"Ravier dans la vitrine"}},{"title":"Le message","text":"Dans la buée, il écrit avec le doigt, à l'envers pour eux, à l'endroit pour lui → {{handout:message-reflet}}.","extra":"S'ils n'ont pas encore la garde, il écrit d'abord FIRMIN, et montre du doigt la direction du plateau."},{"title":"Celui qui se tient derrière","text":"Derrière Ravier, dans le reflet, un grand homme en redingote, de dos, lui pose la main sur l'épaule. La buée gèle d'un coup ; la vitre se couvre de givre. Quand elle s'éclaircit, il n'y a plus que leurs propres reflets.","roll":{"type":"san","san":"1/1D6","label":"Le Teneur"},"extra":"Le patron du café n'a rien vu. Il a seulement froid."},{"title":"Un cri","text":"Plus haut dans la montée (ou chez eux, si ce sont eux qui ont la garde) : {{npc:ferreol-gaudin}} et un {{npc:homme-de-main}} ont coincé Firmin dans l'escalier d'une traboule. Gaudin veut la garde, pas tuer : il fuit sous la moitié de ses points de vie, ou si un revolver sort."},{"title":"L'homme de main","text":"Payé dix francs pour la soirée, il n'a pas envie de mourir.","roll":{"type":"skill","options":["intimidate"]},"success":"Il détale dans le brouillard ; Gaudin reste seul.","failure":"Il se bat aux côtés de Gaudin jusqu'à ce que celui-ci fuie."},{"title":"Faire parler Gaudin","text":"S'il est pris ou à terre.","roll":{"type":"skill","options":["intimidate","persuade"]},"success":"« M. Bellevrand veut la page avant lundi. Lundi soir, à neuf heures, ils montent tous dans la salle aux glaces de la traboule. Moi, je garde la porte d'en bas. La dame Mazaud monte avec eux. Il paraît que c'est son tour. Je pose pas de questions. »","failure":"Il se tait et attend que son patron le fasse sortir. Rabatel, s'il l'arrête, doit le relâcher le lendemain sur ordre."},{"title":"Après","text":"Si Firmin est sauf et a encore la garde, il la leur donne sans condition. Si Gaudin l'a emportée, elle sera posée sur le livre lundi soir ([[salle-des-glaces]]).","goto":["les-caves","salle-des-glaces"]}],"npcs":["joannes-ravier","le-teneur","ferreol-gaudin","homme-de-main","firmin-chabert"],"handouts":["message-reflet"],"ambience":["village-night","wind"],"sfx":["footsteps","door-slam"],"next":["les-caves","fourviere","salle-des-glaces"]},{"id":"les-caves","title":"Les caves de la Navette","lead":"Sous la traboule : le Grand-Livre du Cercle, les portraits de dos, et le chemin secret vers la salle.","optional":true,"screen":{"place":"crypt","preset":"candle","time":"night"},"readAloud":["L'escalier descend plus bas que des caves ordinaires. La pierre change : de grands blocs taillés, très anciens, puis une voûte de briques plates. L'air est sec et sent le papier.","La lanterne éclaire des rayonnages de registres, des liasses de cartons perforés de métiers Jacquard, des pièces de soie roulées. Au fond, trois tableaux dans des cadres dorés. Les trois personnages sont peints de dos."],"flow":[{"title":"Entrer","text":"Par la porte de fer de la [[traboule]] : clés de Lucie, ou Serrurerie. Ou par la cave de la mère Brossard, qui communique par un soupirail à moitié muré (FOR, jets rapides de la scène) : elle les y conduit si elle leur fait confiance."},{"title":"Le Grand-Livre","text":"Ouvert sur un pupitre, à la dernière page écrite → {{handout:grand-livre}}. Pas de jet pour la lire.","roll":{"type":"skill","options":["accounting","library-use"]},"success":"En feuilletant : soixante-douze ans d'échanges. Chaque fortune du Cercle a son revers, une ruine chez quelqu'un d'autre, à Lyon. Les noms de ces autres sont soigneusement tenus.","failure":"Ils s'en tiennent à la dernière page, qui suffit."},{"title":"Les portraits de dos","text":"Étiquettes : *Étienne, 1852. Joséphine, 1876. Louis, 1900.* Un quatrième cadre, vide, attend contre le mur.","roll":{"type":"san","san":"0/1D3","label":"Les portraits de dos"}},{"title":"La glace voilée","text":"Dans une niche, un miroir couvert d'un drap noir. Si on le découvre, à la lanterne : la cave s'y reflète à l'envers, et quatre silhouettes s'y tiennent, de dos : les trois des portraits et Ravier. L'une d'elles, en habit (Louis), trace sur la glace, à l'envers : LUCIE. Puis : PAS ELLE.","roll":{"type":"san","san":"1/1D4","label":"Les soldés dans la glace"},"extra":"Recouvrir la glace suffit. Qui reste plus d'une minute devant fait un jet de POU : en cas d'échec, une main sort du verre (voir {{npc:le-teneur}})."},{"title":"Les galeries","text":"De vieilles galeries maçonnées, peut-être romaines, filent sous la colline. L'une remonte par un escalier de service jusque derrière le mur de glaces de la salle du cinquième.","roll":{"type":"skill","options":["navigate","spot-hidden"]},"success":"Ils trouvent l'escalier : lundi soir, ils pourront arriver derrière les glaces sans passer devant Gaudin (dé bonus pour entrer, [[salle-des-glaces]]).","failure":"Une heure perdue dans les galeries ; ils ressortent par une cave de la montée des Carmélites."},{"title":"La Salle des Glaces, avant lundi","text":"Par la grille (clé de Lucie) ou l'escalier de service : un ancien atelier de canut, plafond de quatre mètres, trois hautes fenêtres sur la Saône et Fourvière. Le mur d'en face n'est que miroirs anciens, une quarantaine, cadre contre cadre. Au centre, un vieux métier Jacquard sert de pupitre. Des centaines de lumignons attendent, déjà posés sur le plancher. Le livre n'est pas là : Bellevrand l'apportera lundi.","extra":"Briser des glaces ou les couvrir avant lundi ne fait que retarder : le passage s'ouvrira aussi dans les vitres. Comptez un round de plus avant de lancer le compteur **Le passage s'ouvre**.","goto":["salle-des-glaces"]}],"rolls":[{"type":"characteristic","options":["STR"],"label":"Dégager le soupirail de la cave Brossard"}],"npcs":["les-soldes","joannes-ravier","le-teneur","mere-brossard"],"handouts":["grand-livre"],"ambience":["wind-howling"],"sfx":["latch","door-creak","footsteps"],"next":["salle-des-glaces"]}]},{"id":"la-nuit-des-lumieres","title":"La nuit des lumières","scenes":[{"id":"salle-des-glaces","title":"La nuit des lumières","lead":"Lundi 8 décembre, neuf heures du soir : le Cercle solde son compte devant quarante miroirs.","screen":{"place":"manor","preset":"ritual","time":"night"},"readAloud":["À la nuit tombée, Lyon s'allume fenêtre par fenêtre. Sur chaque rebord, des lumignons dans leurs verres de couleur. Les rues sont noires de monde ; une procession de flambeaux monte vers Fourvière, et là-haut la basilique brille comme une lanterne.","Dans la salle du cinquième étage, trois cents petites flammes tremblent sur le plancher. Par les hautes fenêtres, toute la ville brille jusqu'aux collines. Et sur le mur d'en face, dans quarante miroirs, toute la ville brille une seconde fois, à l'envers.","Devant le métier à tisser, Hector Bellevrand ouvre un livre aux pages de soie et lève les yeux vers la plus grande glace. « Mes amis, dit-il doucement. Il est l'heure. »"],"flow":[{"title":"Arriver","text":"Les rues sont pleines, les tramways bondés : partir avant huit heures. À la porte de fer, {{npc:ferreol-gaudin}}, s'il est libre, avec un gourdin. Le Cercle monte à neuf heures : {{npc:hector-bellevrand}}, {{npc:clotilde-vial}}, le banquier Henri Dumoulin et son fils {{npc:gaston-dumoulin}}, et {{npc:lucie-mazaud}} en gris, qui marche seule."},{"title":"Entrer","text":"Dé bonus s'ils connaissent l'escalier de service ([[les-caves]]). Avec Rabatel en uniforme, personne ne les arrête, mais Bellevrand le fait asseoir comme un invité.","roll":{"type":"group","options":["stealth"]},"success":"Ils arrivent sans être vus (derrière les glaces par l'escalier de service, ou cachés dans l'atelier voisin). Ils voient tout, et choisissent leur moment.","failure":"On les voit. Gaston Dumoulin barre la porte. Bellevrand, sans hausser la voix : « Laissez-les. Qu'ils voient ce que coûte Lyon. » Ils sont tenus contre le mur, sous la garde de Gaston, mais peuvent agir dès que la lecture commence."},{"title":"Où est la garde ?","text":"Si Bellevrand l'a récupérée, elle est posée sur le livre, et le nom des Mazaud est le premier (sauf s'il a été décousu à son insu). Si les investigateurs l'ont, Bellevrand ouvre le livre puis le tend à Lucie : sans garde, c'est le lecteur qui paie. Elle accepte, pour Jean.","extra":"Règles complètes dans les notes ci-dessous."},{"title":"La lecture","text":"Le lecteur lit à voix basse, dans la grande glace. Une à une, les villes reflétées s'éteignent. Dans chaque miroir, la même pièce, sans personne, et la même silhouette en redingote, de dos, au milieu. Lancez le compteur **Le passage s'ouvre**.","roll":{"type":"san","san":"1/1D8","label":"Le Teneur dans quarante glaces"}},{"title":"Chaque round","text":"Les glaces se bombent comme une eau sur le point de déborder. Des mains sortent du verre vers quiconque tient le livre ou s'approche à moins de deux pas (attaque des Mains, voir {{npc:le-teneur}}). À 3, on peut franchir la glace, ou y être poussé. À 6, le solde. À 9, le passage se referme."},{"title":"Le solde","text":"À 6, la glace prend un vivant du premier nom brodé sur la garde, ou le lecteur si la garde manque, sauf si quelqu'un du sang de la Navette a franchi la glace avant. La personne marche vers la glace, prend la main de son propre reflet et entre. La surface se referme comme une eau calme."},{"title":"Ce qu'ils peuvent faire","text":"Tant que le compteur tourne, chacun agit à son tour. Les choix ci-dessous se combinent : l'un brûle le livre pendant qu'un autre retient Lucie, qu'un troisième tient Gaston à distance."},{"title":"Brûler le livre","branch":"S'ils brûlent le livre","text":"Arracher le livre au lecteur, puis le tenir dans les lumignons trois rounds (compteur **Le livre brûle**). Cette nuit, la soie brûle : lentement, avec une odeur de cheveux. Gaston et Gaudin veulent l'empêcher ; les mains des glaces se tendent vers celui qui le tient.","roll":{"type":"opposed","options":["sleight-of-hand","fighting-brawl"],"against":{"npc":"hector-bellevrand","skill":"dodge"}},"success":"Ils ont le livre. Au troisième round dans la flamme, les quarante glaces se fendent ensemble, du haut en bas. Dans les fissures, de dos, Étienne, Joséphine, Louis et Ravier s'éloignent dans une rue à l'envers, puis plus rien. Le passage est clos pour toujours. Si quelqu'un a été pris cette nuit et que le compteur n'avait pas atteint 9, la glace le rejette sur le plancher, vivant.","failure":"Le lecteur garde le livre contre lui et recule vers la glace. Réessayez au round suivant."},{"title":"Découdre le nom des Mazaud","branch":"Si le nom des Mazaud est décousu","text":"Avant la nuit, ou maintenant : prendre la garde sur le livre puis découdre le nom, deux rounds. Sans le savoir-faire, DEX difficile (jets rapides de la scène).","roll":{"type":"skill","options":["art-craft"],"difficulty":"hard"},"success":"À 6, ce n'est pas Lucie que la glace appelle. Dans la grande glace, le reflet de Bellevrand s'avance seul et lui tend la main. Il comprend, regarde Lucie, et murmure : « Bien joué, petite. » Il pose le livre sur le métier et entre.","failure":"Le fil casse, l'aiguille tremble : encore un round.","extra":"Si la garde n'est plus sur le livre à 6, c'est le lecteur qui paie : Bellevrand s'il lit, Lucie si c'est elle. Pour sauver Bellevrand ensuite, il faudrait un autre solde, ou brûler le livre avant 9."},{"title":"Pousser Bellevrand","branch":"S'ils poussent Bellevrand dans la glace","text":"Une fois le compteur à 3, la glace est assez ouverte pour qu'on y tombe. Bellevrand est du sang de la Navette : il solde le compte.","roll":{"type":"opposed","options":["fighting-brawl"],"against":{"npc":"hector-bellevrand","skill":"fighting-brawl"}},"success":"Il bascule dans le verre comme dans une eau froide. Sa main reste un instant tendue hors de la glace, puis la surface se referme. Celui qui a poussé perd 1D6 SAN, sans jet.","failure":"Il se dégage ; Gaston Dumoulin se jette sur l'investigateur."},{"title":"Clotilde Vial","branch":"Si Clotilde Vial prend la place de Lucie","text":"Possible seulement si on lui a parlé avant ([[hotel-bellevrand]]), ou si on lui rappelle Joséphine en 1876.","roll":{"type":"skill","options":["persuade"],"difficulty":"hard"},"success":"La vieille dame se lève, embrasse Lucie et entre dans la glace avant que Bellevrand puisse la retenir. Elle est de la Navette par son mariage : le compte est soldé.","failure":"Elle pleure, mais ne bouge pas."},{"title":"Traverser la glace","branch":"S'ils traversent la glace","text":"À partir de 3, on peut entrer dans la glace (l'Envers, en note). Pour ramener quelqu'un déjà pris, il faut le trouver, le prendre par la main et revenir avant 9. Le Teneur se tient dans l'encadrement, de dos ; sur le verre, à l'envers : UN NOM POUR UN NOM.","roll":{"type":"san","san":"1/1D6","label":"Entrer dans l'Envers"},"extra":"Deux manières de ressortir avec la personne : le livre brûle de ce côté pendant ce temps, ou quelqu'un de la Navette reste à sa place. Sinon, ceux qui sont entrés restent de l'autre côté, de dos, pour toujours."},{"title":"Si personne n'arrête la lecture","branch":"Si personne n'arrête la lecture","text":"Lucie s'avance. Dans la glace, son reflet l'attend et, à côté, de dos, un homme en habit de 1900. Elle ne se retourne pas."},{"title":"Après le solde","text":"À 9, le passage se referme. Bellevrand, s'il est encore là, ferme le livre et souffle les lumignons un par un. S'il reste un livre, quelqu'un peut le prendre.","goto":["apres-les-lumieres"]}],"notes":[{"title":"Les règles de l'Envers (pour le Gardien)","items":["Le livre se lit dans un miroir, à la lumière d'une flamme. Le lecteur voit l'Envers, et l'Envers le voit. Un intrus qui insiste est pris (Ravier).","Le 8 décembre, tous les vingt-quatre ans, quand la ville s'allume, la lecture ouvre le passage : le Teneur prend un vivant du sang du **premier nom** brodé sur la garde.","Si la garde n'est pas sur le livre, c'est le **lecteur** qui paie.","Toute personne de la Navette (de sang ou par mariage) qui franchit la glace ouverte solde le compte à la place du premier nom.","On ajoute un nom en le cousant, on l'ôte en le décousant.","Le livre et sa garde ne brûlent, ne se déchirent ni ne se mouillent, sauf quand le passage est ouvert.","Le livre brûlé, tout ce qui a été passé à l'envers revient à son propriétaire : fortunes, ruines, dettes. Les morts d'autrefois ne reviennent pas ; ceux qui ont été pris cette nuit, si.","Lire le livre, pour un investigateur : SAN 1/1D6, puis un jet de POU par minute ; au premier échec, les mains du Teneur sortent de la glace."]},{"title":"L'Envers","items":["Lyon retourné : la Saône coule à l'est, le Rhône à l'ouest ; Fourvière est en bas, la Croix-Rousse au fond d'un creux. Les enseignes se lisent à rebours.","Les lumignons brûlent d'une flamme noire qui ne chauffe pas. Pas un bruit, sauf, très loin, celui d'une navette qui va et vient.","Tous les passants sont vus de dos, de quelque côté qu'on se place. Étienne, Joséphine, Louis et Ravier se tiennent là, immobiles.","À la place de la basilique, un comptoir immense et un registre ouvert, où une plume écrit seule."]},{"title":"Si le livre a été volé avant le 8","items":["Il ne brûle pas avant la nuit. Le 8, quand la ville s'allume, les glaces et les vitres autour du livre s'assombrissent : le passage s'ouvre là où il est, sans lecteur, et le Teneur prend à 6 le premier nom de la garde, ou celui qui tient le livre si la garde manque.","Bellevrand, Gaston Dumoulin et Gaudin viennent le reprendre avant neuf heures. Jouez cette scène là où se trouvent les investigateurs."]},{"title":"Forces en présence","items":["Bellevrand (canne-épée), Gaston Dumoulin, Gaudin s'il est libre. Henri Dumoulin et Clotilde ne se battent pas.","Lucie aide les investigateurs dès qu'ils agissent ; sinon, elle marche vers la glace."]}],"rolls":[{"type":"characteristic","options":["DEX"],"label":"Découdre sans savoir-faire (difficile)"},{"type":"characteristic","options":["POW"],"label":"Se dégager des mains des glaces"},{"type":"damage","dice":"1D6","label":"SAN perdue par celui qui pousse"}],"npcs":["hector-bellevrand","lucie-mazaud","clotilde-vial","gaston-dumoulin","ferreol-gaudin","le-teneur","les-soldes"],"ambience":["street","wind-howling","clock"],"sfx":["footsteps","door-slam","knocking"],"next":["apres-les-lumieres"]},{"id":"apres-les-lumieres","title":"Le matin du 9 décembre","lead":"Ce que la nuit a coûté, issue par issue.","screen":{"place":"street","preset":"rain","time":"dusk"},"readAloud":["Au petit jour, une pluie fine lave les pentes. Sur les rebords des fenêtres, les lumignons éteints gardent un fond de cire noire. D'un immeuble à l'autre, les métiers reprennent leur claquement, comme chaque matin."],"flow":[{"title":"Le 9 au matin","text":"Choisissez l'issue qui correspond à la nuit. Plusieurs peuvent se combiner."},{"title":"Le livre a brûlé","branch":"Si le livre a brûlé","text":"Chaque investigateur présent regagne 1D8 SAN. Dans l'année, la Navette se défait : la banque Dumoulin suspend ses paiements au printemps, l'hospice des vieux canuts ferme, la maison Mazaud fait faillite à l'automne 1925. Lucie vend tout, garde Jean, et remercie les investigateurs sans amertume. Bellevrand ne sort plus de chez lui ; on le trouve un matin de 1926 assis devant un miroir dévoilé, l'air paisible.","roll":{"type":"damage","dice":"1D8","label":"SAN regagnée (livre brûlé)"}},{"title":"Bellevrand a soldé le compte","branch":"Si Bellevrand a soldé le compte","text":"Chacun regagne 1D6 SAN pour Lucie sauvée ; celui qui a poussé a déjà payé. Le Cercle se tait. Lucie devient la gardienne du livre. Le nom des Bellevrand meurt avec le maître : en 1948, le premier nom vivant de la garde sera celui des Vial. Lucie promet de brûler le livre ce soir-là. Tiendra-t-elle parole, quand la ville s'allumera ?","roll":{"type":"damage","dice":"1D6","label":"SAN regagnée (Lucie sauvée)"}},{"title":"Clotilde s'est offerte","branch":"Si Clotilde Vial s'est offerte","text":"Chacun regagne 1D4 SAN. Lucie est sauve, mais le nom des Mazaud reste le premier : en 1948, ce sera le tour de Jean, à moins qu'on ne découse le nom d'ici là.","roll":{"type":"damage","dice":"1D4","label":"SAN regagnée (Clotilde)"}},{"title":"Lucie est passée","branch":"Si Lucie est passée","text":"Le Cercle prospère. Jean est confié à Clotilde Vial. Quelques semaines plus tard, l'un des investigateurs aperçoit, dans une vitrine de la rue de la République, une femme en gris qui lui tourne le dos et ne bouge pas avec la foule.","roll":{"type":"san","san":"1/1D6","label":"Lucie perdue"}},{"title":"Ils ont gardé le livre","branch":"S'ils ont gardé le livre","text":"Le livre marche pour eux : une dette passée à un inconnu, une chance prise à un rival. Chaque échange coûte 1D4 SAN et allonge d'un instant le retard du reflet de celui qui lit. Le compte court toujours : le 8 décembre 1948 tombe un mercredi.","roll":{"type":"san","san":"0/1D4","label":"Premier échange"}},{"title":"Ravier","text":"Quelle que soit l'issue, l'affaire reste classée. Mme Jacquet vend les outils du relieur ; Firmin en rachète un à un avec ses gages. Si le livre a brûlé, aucune vitre ne montre plus Ravier. Sinon, certains soirs, dans la vitrine du café de la montée, un homme en tablier de cuir regarde passer les gens."}],"notes":[{"title":"Ce que deviennent les autres","items":["**Rabatel** demande sa mutation à Marseille, ou reste, et devient un allié fidèle pour d'autres affaires.","**Montcharmont** ôte les draps de ses miroirs si le livre a brûlé. Sinon, il ferme boutique au printemps.","**Gaudin** disparaît de Lyon si son patron n'est plus là ; sinon, il reste son chauffeur, et se souvient des visages.","**Le journaliste** : *Le Progrès* refuse l'article entier. Trois lignes paraissent en page six : « Mort naturelle d'un relieur des pentes »."]}],"npcs":["lucie-mazaud","firmin-chabert","germain-rabatel"],"ambience":["rain","street"],"sfx":["door-open"]}]}],"npcs":[{"id":"joannes-ravier","name":"Joannès Ravier","role":"Relieur-doreur, la victime (son reflet)","description":"Cinquante-huit ans, veuf, tablier de cuir, mains brûlées par les fers à dorer, une vieille cicatrice de couteau à parer dans la paume gauche.","personality":"Artisan scrupuleux et curieux, qui lisait toujours ce qu'il reliait. Son reflet, prisonnier de l'Envers, veut prévenir les vivants.","knows":["Le texte est imprimé à rebours et se lit au miroir.","Il a confié la garde à Firmin le jeudi 27 au soir.","Dans l'Envers, il a compris la règle : le premier nom paie, et on peut le découdre."]},{"id":"firmin-chabert","name":"Firmin Chabert","role":"Apprenti de Ravier","description":"Quinze ans, maigre, des mains tachées de colle, une casquette trop grande.","personality":"Loyal à son patron jusqu'au bout, terrifié, fier. Il ne fait confiance qu'à ceux qui le protègent ou qui ont connu Ravier.","characteristics":{"STR":50,"CON":55,"SIZ":45,"DEX":65,"INT":60,"POW":45},"hp":10,"dodge":32,"knows":["Jeudi 27 vers 22 h, il a vu dans la vitre noire un grand homme de dos entre lui et son patron, dans une pièce vide.","Ravier lui a confié un paquet (la garde) : ne jamais l'ouvrir devant une glace, ne le donner à personne.","Un costaud à l'oreille fendue est venu chez sa mère le samedi 29.","Ravier avait la cicatrice dans la paume gauche, la raie des cheveux à gauche."]},{"id":"benoite-gros","name":"Benoîte Gros","role":"Concierge du 12, montée Saint-Sébastien","description":"La soixantaine, tablier bleu, chat sur l'épaule, voix qui porte dans toute la cour.","personality":"Bavarde, curieuse, susceptible. Elle aimait bien Ravier, « un homme tranquille ».","knows":["Lundi 24 : une dame voilée en demi-deuil gris, qui sentait l'iris, a apporté un paquet.","Jeudi 27 vers 15 h : un grand costaud en casquette, oreille gauche fendue, a demandé « un livre en soie ».","Jeudi matin, Ravier a reçu une lettre de la rue Juiverie et il est devenu tout blanc.","Jeudi vers 22 h 30 : des meubles traînés dans l'atelier.","L'adresse de Firmin ; la sœur de Ravier fait vider l'atelier samedi 6."]},{"id":"germain-rabatel","name":"Germain Rabatel","role":"Inspecteur de police","description":"Quarante-six ans, moustache tombante, pardessus usé, un mégot éteint toujours aux lèvres.","personality":"Honnête, têtu, amer qu'on lui ait fait classer l'affaire. Il croit aux preuves, pas aux fantômes.","characteristics":{"STR":60,"CON":60,"SIZ":65,"DEX":55,"INT":65,"POW":55},"hp":12,"dodge":27,"attacks":[{"name":"Revolver d'ordonnance","skill":55,"damage":"1D10"},{"name":"Poings","skill":55,"damage":"1D3"}],"knows":["Le constat, l'autopsie et ses anomalies.","Le livre a été rendu à Bellevrand sur ordre du commissaire central, le jour même de l'autopsie.","Le secrétaire de Bellevrand cherchait une « page de soie brodée ».","Il peut retrouver le dossier de la disparition de Louis Mazaud (1900)."]},{"id":"lucien-fayolle","name":"Dr Lucien Fayolle","role":"Médecin légiste","description":"Cinquante ans, lorgnon, blouse tachée, fume trop.","personality":"Rigoureux, ébranlé : ce cadavre contredit tout ce qu'il sait.","knows":["Le corps de Ravier est inversé : cœur à droite, foie à gauche, alliance à droite, cicatrice et grains de beauté du mauvais côté.","Le conseil de révision de 1886 n'a rien relevé : impossible pour un cœur à droite."]},{"id":"isidore-montcharmont","name":"Isidore Montcharmont","role":"Libraire ancien, rue Juiverie","description":"Soixante et onze ans, calotte de velours, loupe au cou, voix douce.","personality":"Érudit, peureux, honteux d'avoir refusé d'aider Louis Mazaud en 1899. Il veut se racheter, de loin.","knows":["Le Livre de l'Envers : un texte lucquois du XVIᵉ siècle, imprimé sur soie et à rebours en 1852 pour Claude Mazaud.","En octobre 1899, Louis Mazaud a voulu lui vendre le livre ; il l'avait jeté au feu sans qu'il brûle.","Louis a disparu le soir des illuminations de 1900.","« Qui tient la garde tient le compte. »","La Navette a un local dans une traboule des pentes, rue des Tables-Claudiennes."]},{"id":"adrienne-sauzet","name":"Adrienne Sauzet","role":"Bibliothécaire au palais Saint-Jean","description":"Trente-huit ans, manches de lustrine, chignon serré, lunettes sur le bout du nez.","personality":"Précise, vive, aime les énigmes. Elle avait de l'affection pour Ravier.","knows":["Ravier restaurait les registres de la bibliothèque.","Les collections de journaux reliés depuis 1830.","Le secrétaire du Cercle de la Navette, M. Collonges, vient consulter les échos chaque mois."]},{"id":"mere-brossard","name":"La mère Brossard","role":"Vieille dévideuse de la traboule","description":"Soixante-dix-huit ans, châle noir, doigts déformés par cinquante ans de soie. Elle vit au rez-de-chaussée de la deuxième cour depuis 1869.","personality":"Pieuse, gourmande, maligne. Elle a tout vu et n'a jamais rien dit à personne.","knows":["Le maître monte chaque année le soir des lumignons.","En 1876, une jeune fille en robe de bal est montée avec eux ; en 1900, un monsieur en habit. Ils ne sont jamais redescendus.","Lundi 8, « c'est encore le tour ».","Sa cave communique avec celles de la Navette par un soupirail à moitié muré."]},{"id":"lucie-mazaud","name":"Lucie Perret-Mazaud","role":"Fabricante de soieries, le premier nom","description":"Trente et un ans, demi-deuil gris, parfum d'iris, le bout des doigts durci par la soie : elle travaille dans ses ateliers avec ses ouvrières.","personality":"Lucide, droite, épuisée. Elle veut sortir du Cercle et sauver son fils Jean, neuf ans. Elle n'a pas peur pour elle ; elle a honte de vouloir qu'un autre paie à sa place.","characteristics":{"STR":45,"CON":50,"SIZ":50,"DEX":60,"APP":65,"INT":75,"POW":70,"EDU":70},"hp":10,"dodge":30,"skills":{"art-craft":70,"accounting":60,"persuade":50},"knows":["Elle est « Mme Morel » : elle a confié le livre à Ravier pour faire ôter la garde et découdre le nom des Mazaud.","Le premier nom paie ; sans garde, c'est le lecteur qui paie.","Étienne en 1852, sa grand-tante Joséphine en 1876, son père Louis en 1900, pour l'épargner, elle.","Le livre ne brûle pas, sauf peut-être la nuit où le passage est ouvert.","Elle a les clés de la porte de fer et de la grille : les Mazaud sont les gardiens de la salle.","Brûler le livre ruinerait les quatre familles, la sienne et ses trois cents ouvriers compris."]},{"id":"hector-bellevrand","name":"Hector Bellevrand","role":"Négociant en soieries, maître du Cercle de la Navette","description":"Soixante et un ans, cheveux blancs, moustache soignée, chevalière à l'écusson de la navette. Veuf depuis 1920 ; son fils unique, le lieutenant Marc Bellevrand, est tombé le 16 avril 1917.","personality":"Courtois, drôle, cultivé, généreux avec les pauvres, sincèrement attaché à Lyon et à ses canuts. Il croit qu'il vaut mieux qu'une famille paie qu'une ville entière. Il ne menace jamais lui-même : il laisse Gaudin s'en charger. Sa peur : être le premier nom.","characteristics":{"STR":45,"CON":50,"SIZ":65,"DEX":45,"APP":70,"INT":80,"POW":75,"EDU":85},"hp":11,"dodge":22,"attacks":[{"name":"Canne-épée","skill":45,"damage":"1D6"},{"name":"Poings","skill":30,"damage":"1D3"}],"skills":{"dodge":22,"fighting-brawl":30,"persuade":80,"charm":75,"psychology":65,"occult":55,"spot-hidden":50},"knows":["Toutes les règles du livre ; il a vu les soldes de 1876 et 1900.","Lucie a pris le livre et l'a confié à Ravier ; il le lui a pardonné en souriant.","Sans la garde, le lecteur paie : il ne lira pas sans elle, et fera lire Lucie s'il le faut.","En 1917, il a demandé à l'Envers de lui rendre son fils : refusé.","Si le nom des Mazaud disparaît de la garde, c'est lui qui paie : il est le dernier des Bellevrand."]},{"id":"ferreol-gaudin","name":"Ferréol Gaudin","role":"Chauffeur et homme de main de Bellevrand","description":"Quarante et un ans, ancien marinier du Rhône, épaules de débardeur, casquette, l'oreille gauche fendue par un vieux coup de gaffe.","personality":"Poli, patient, sans curiosité. Fidèle à qui le paie. Il ne veut pas savoir ce qui se passe là-haut.","characteristics":{"STR":80,"CON":70,"SIZ":80,"DEX":50,"INT":45,"POW":40},"hp":15,"dodge":25,"build":1,"damageBonus":"+1D4","attacks":[{"name":"Poings","skill":65,"damage":"1D3+1D4"},{"name":"Gourdin","skill":60,"damage":"1D8+1D4"},{"name":"Couteau","skill":45,"damage":"1D4+1D4"}],"skills":{"intimidate":55,"stealth":40,"drive-auto":60},"knows":["Il a fait le tour des relieurs de Lyon le mercredi 26 et le jeudi 27 ; Ravier a nié avoir le livre.","Il est allé chez la mère de Firmin le samedi 29.","Lundi 8 à 21 h, le Cercle monte dans la salle aux glaces de la traboule ; il garde la porte d'en bas.","« La dame Mazaud monte avec eux. Il paraît que c'est son tour. »"]},{"id":"homme-de-main","name":"Un débardeur du port Rambaud","role":"Homme de main payé à la soirée","description":"Trente ans, bras énormes, bonnet de laine, sent le vin rouge.","personality":"Payé dix francs, il n'a pas l'intention de mourir pour ça.","characteristics":{"STR":70,"CON":65,"SIZ":70,"DEX":50,"INT":40,"POW":40},"hp":13,"dodge":25,"damageBonus":"+1D4","attacks":[{"name":"Poings","skill":55,"damage":"1D3+1D4"},{"name":"Barre de fer","skill":45,"damage":"1D8+1D4"}],"knows":["Rien, sinon que « le costaud » paie bien."]},{"id":"clotilde-vial","name":"Clotilde Vial","role":"Doyenne du Cercle de la Navette","description":"Soixante-quatorze ans, canne à pommeau d'argent, robe noire de l'ancien temps. Entrée chez les Vial par son mariage en 1875.","personality":"Fière, fidèle au Cercle, hantée par ce qu'elle a vu. Elle parle trop quand elle a peur.","characteristics":{"STR":30,"CON":40,"SIZ":45,"DEX":35,"INT":70,"POW":60},"hp":8,"dodge":17,"knows":["Elle a vu Joséphine Mazaud entrer dans la glace en 1876, et Louis en 1900.","Les règles, à peu près : le premier nom paie.","Elle sait broder ; c'est elle qui recoudrait un nom sur la garde."]},{"id":"gaston-dumoulin","name":"Gaston Dumoulin","role":"Fils du banquier Henri Dumoulin, membre du Cercle","description":"Vingt-huit ans, nez cassé, habit trop étroit aux épaules. Ancien boxeur amateur.","personality":"Brutal par loyauté envers son père, pas par goût. Il a peur des glaces.","characteristics":{"STR":70,"CON":65,"SIZ":70,"DEX":60,"INT":50,"POW":45},"hp":13,"dodge":30,"damageBonus":"+1D4","attacks":[{"name":"Poings","skill":65,"damage":"1D3+1D4"}],"skills":{"fighting-brawl":65,"dodge":30},"knows":["Le Cercle monte le 8 à 21 h ; c'est sa première fois.","Son père lui a dit : « Tu ne regardes pas les glaces, tu tiens la porte. »"]},{"id":"le-teneur","kind":"creature","name":"Le Teneur","role":"Celui qui tient les comptes de l'Envers","description":"Un homme très grand en redingote noire de coupe ancienne, toujours vu de dos, de quelque côté qu'on le regarde. Il n'existe que dans les reflets.","personality":"Exact, patient, indifférent. Il ne veut que des comptes justes.","characteristics":{"POW":100},"sanLoss":"1/1D8","attacks":[{"name":"Mains des glaces","skill":60,"damage":"1D3","note":"Des mains glacées sortent du verre et tirent vers la glace. La victime fait un jet de POU pour se dégager ; deux échecs de suite et elle passe de l'autre côté. Un compagnon qui la retient lui donne un dé bonus."}],"special":["N'existe que dans les reflets : glaces, vitres la nuit, eau ou encre sous une flamme. Couvrir ou briser le reflet le chasse de là.","Ne parle jamais. Écrit parfois, à l'envers, dans la buée ou le givre.","Ne sort du verre que ses mains et ses bras, sauf la nuit où le passage est ouvert.","Rien ne le blesse. Le livre brûlé, il disparaît avec le passage."],"knows":["Le compte de chaque échange depuis 1852."]},{"id":"les-soldes","kind":"creature","name":"Les soldés","role":"Les reflets de ceux qui ont payé","description":"Étienne Mazaud (1852), en redingote de jeune homme ; Joséphine Mazaud (1876), en robe de bal ; Louis Mazaud (1900), en habit. Ravier les a rejoints. Dans l'Envers, toujours de dos.","personality":"Muets, tristes, sans haine. Louis veut sauver sa fille.","sanLoss":"0/1D4","special":["Ne parlent pas ; écrivent à l'envers sur les glaces.","Ne peuvent rien contre le Teneur.","Libérés si le livre brûle : ils s'éloignent et disparaissent."],"knows":["Louis : « PAS ELLE ». Il sait que le nom peut être décousu."]}],"handouts":[{"id":"registre-commandes","title":"Le livre de commandes de Ravier","scene":"l-atelier","text":"**Atelier J. Ravier, relieur-doreur — 12, montée Saint-Sébastien**\n*Livre des commandes, novembre 1924*\n\nN° 1186 — 14 nov. — M. l'abbé Coste, Saint-Polycarpe : missel, recouvrir en chagrin noir. 12 fr. *Livré.*\n\nN° 1187 — 18 nov. — Bibliothèque de la Ville (palais Saint-Jean), Mlle Sauzet : six registres paroissiaux, restaurer les dos. 90 fr. *Livré le 22.*\n\nN° 1188 — 21 nov. — M. Faure, avocat : trois volumes de jurisprudence, demi-basane. 30 fr.\n\nN° 1189 — 24 nov. — **Mme Morel** (pas d'adresse, repassera) : ouvrage ancien imprimé sur soie, in-quarto, sans titre. Dérelier sans rien abîmer. Ôter la garde brodée, la rendre à part, en main propre. Relier le reste à l'identique. *Payé d'avance : 200 fr.*\n*(en marge, d'une autre encre, d'une écriture qui tremble)* Texte imprimé à rebours. Lu au miroir le 25 au soir. NE PAS RECOMMENCER. Écrit à Montcharmont.\n\nN° 1190 — 25 nov. — Un collectionneur : livre d'heures, Lyon, 1548. Consolider la couture, ne pas toucher à la reliure d'origine."},{"id":"lettre-montcharmont","title":"Lettre de la rue Juiverie","scene":"l-atelier","text":"*Lyon, le mercredi 26 novembre 1924*\n\nMon cher Joannès,\n\nTa lettre m'a glacé. Un in-quarto sur soie, imprimé à rebours, une navette et une clef sur la garde : je crois savoir ce que tu as sur ton établi, et je te supplie de le rendre à ta cliente sans le lire davantage.\n\nNe le lis plus dans une glace. Surtout pas le soir, à la chandelle. Et retourne tes miroirs en attendant. Je sais que tu vas rire.\n\nIl y a vingt-cinq ans, un homme est venu me proposer ce livre, ou son jumeau. Il me suppliait de l'acheter pour l'emporter loin de Lyon. J'ai refusé, Dieu me pardonne. L'année suivante, le soir des illuminations, il a disparu.\n\nViens me voir dimanche après la messe, rue Juiverie. Je te dirai le reste de vive voix : il y a des choses qu'on n'écrit pas.\n\nTon vieil ami,\n**Isidore M.**"},{"id":"rapport-police","title":"Dossier de police (extraits)","scene":"commissariat","text":"**Police de Lyon — Commissariat du 1ᵉʳ arrondissement**\n*Procès-verbal de constat, vendredi 28 novembre 1924, 8 h 20*\n\nAffaire : RAVIER Joannès, 58 ans, relieur-doreur, veuf, 12 montée Saint-Sébastien.\n\nPorte de l'atelier fermée de l'intérieur par deux verrous, une armoire poussée contre. Fenêtres closes, carreaux entièrement couverts de papier marbré collé. Huit miroirs retournés face au mur ; la presse de cuivre enveloppée d'un chiffon. Le corps est assis à l'établi, sans trace de lutte. Sur l'établi : une bougie consumée, un encrier ouvert, un ouvrage ancien imprimé sur soie, dérelié, texte illisible (**scellé n° 4**).\n\n*Rapport d'autopsie du Dr L. Fayolle, samedi 29 novembre :* décès par arrêt du cœur dans la nuit du 27 au 28. **Observations** : inversion complète des viscères (cœur à droite, foie à gauche). Alliance portée à l'annulaire droit. La cicatrice ancienne que le témoin (l'apprenti Chabert) situe dans la paume gauche se trouve dans la paume droite. Le soussigné s'étonne qu'une telle anomalie n'ait pas été relevée au conseil de révision de 1886.\n\nConclusion : mort naturelle. Affaire classée.\n\n*Samedi 29 novembre, 11 h :* plainte de M. Hector BELLEVRAND, négociant en soieries, 4 rue Sala, pour le vol, courant novembre, dans sa bibliothèque, d'un ouvrage de famille imprimé sur soie.\n*Samedi 29 novembre, 16 h :* scellé n° 4 restitué à M. Désiré Collonges, secrétaire du plaignant, sur ordre de M. le Commissaire central.\n\n*(au crayon, dans la marge, de la main de Rabatel)* Rendu le jour même de l'autopsie ! Le secrétaire a demandé trois fois : « et la page de soie brodée ? » Pas de page dans le scellé."},{"id":"coupures","title":"Quatre entrefilets","scene":"palais-saint-jean","text":"*Le Courrier de Lyon, vendredi 10 décembre 1852*\nAu milieu de l'allégresse qui a illuminé notre ville le soir du 8, une famille est dans l'angoisse : M. Étienne MAZAUD, vingt-quatre ans, frère d'un fabricant estimé des pentes de la Croix-Rousse, n'a pas reparu depuis cette soirée.\n\n*Le Salut public, dimanche 10 décembre 1876*\nOn est toujours sans nouvelles de Mlle Joséphine MAZAUD, dix-neuf ans, fille de M. Claude Mazaud, fabricant de soieries, sortie vendredi soir pour voir les illuminations. On craint qu'elle ne soit tombée dans la Saône.\n\n*Le Progrès, lundi 10 décembre 1900*\nDISPARITION. M. Louis MAZAUD, trente et un ans, fabricant de soieries rue Puits-Gaillot, a quitté son domicile samedi vers huit heures du soir, en habit, en disant se rendre à son cercle. Il n'y est jamais arrivé. Il laisse une fillette de sept ans.\n\n*Le Salut public, échos, décembre 1902*\nLe Cercle de la Navette, fondé le 8 décembre 1852 par MM. Claude Mazaud, Antoine-Marie Bellevrand, Pierre Vial et Jean-Baptiste Dumoulin, a donné son banquet annuel au profit de l'hospice des vieux canuts, sous la présidence de M. Jules Bellevrand."},{"id":"garde-de-soie","title":"La garde de soie","scene":"firmin","text":"*Une feuille de soie ivoire, brodée de fil d'argent terni. Tout est brodé à l'envers : on la lit dans un miroir, ou par l'envers de l'étoffe, à contre-jour.*\n\nEn tête : une navette posée sur un miroir ovale, une clef au-dessus.\n\nCE QUI EST DESSOUS TIENT CE QUI EST DESSUS\n\nNous, soussignés, ouvrons compte au Teneur de l'Envers, ce huitième jour de décembre 1852, nuit où la ville s'allume.\nTout ce qui sera passé à l'envers sera tenu.\nLe solde de chaque exercice de vingt-quatre années se paiera au soir où la ville s'allume, d'un vivant du sang du premier nom brodé ci-dessous.\nSi la garde manque au livre, le lecteur solde.\n\n**Claude Mazaud**\nAntoine-Marie Bellevrand\nPierre Vial\nJean-Baptiste Dumoulin\n\n*Plus bas, en soies plus récentes, d'autres mains :* Jules Bellevrand, maître, 1881. Hector Bellevrand, maître, 1908."},{"id":"convocation-soie","title":"La convocation sur soie","scene":"fourviere","text":"*Un ruban de soie gris perle, tissé au métier Jacquard, roulé dans une enveloppe sans nom. Arrivé le lundi 1ᵉʳ décembre.*\n\nCERCLE DE LA NAVETTE\nExercice 1900-1924\nLundi 8 décembre, neuf heures du soir\nSalle des Glaces\nSOLDE\nLe premier nom est attendu."},{"id":"lettre-louis","title":"La lettre de Louis Mazaud","scene":"fourviere","text":"*Une lettre sur soie fine, pliée en huit, l'encre un peu passée. Lucie la porte toujours sur elle.*\n\n*Le 8 décembre 1900, sept heures du soir.*\n\nMa Lucie,\n\nTu liras ceci quand tu seras grande. Ce soir, je vais là où ta grand-tante Joséphine est allée avant moi, et Étienne avant elle. C'est le prix que notre nom paie pour la Navette, parce que le nôtre est le premier brodé sur la garde. Le Teneur prend un vivant du premier nom. Si ce n'est pas moi, ce sera toi un jour.\n\nJ'ai voulu brûler ce livre l'an dernier : le feu n'en a pas voulu. Il ne brûle peut-être que la nuit où la glace s'ouvre. Je n'ai pas eu ce courage-là.\n\nSi un jour tu peux découdre notre nom, fais-le. Mais sache que le nom suivant paiera à notre place. Moi, je n'ai pas pu me résoudre à faire peser cela sur un autre.\n\nNe crois jamais les Bellevrand quand ils sont aimables. Ils le sont toujours.\n\nTon papa qui t'aime,\n**Louis**"},{"id":"message-reflet","title":"Le message dans la buée","scene":"le-reflet","text":"*Dans la buée de la vitrine, tracé du doigt depuis l'intérieur. Pour qui regarde de la rue, les lettres sont à l'envers.*\n\nLA GARDE\nLE 1ᵉʳ NOM PAIE\nDÉCOUDRE\nNE LISEZ PAS"},{"id":"grand-livre","title":"Le Grand-Livre du Cercle (dernière page)","scene":"les-caves","text":"*Grand-Livre du Cercle de la Navette. Compte ouvert au Teneur. Écrit à l'endroit, d'écritures différentes.*\n\n1853. Passé à l'envers : la faillite de la maison Mazaud, sur la maison Rivoire-Besson. Tenu.\n1867. L'incendie de l'entrepôt Bellevrand, sur l'entrepôt Morillon, quai de la Pêcherie. Tenu.\n8 décembre 1876. Solde : Joséphine Mazaud, 19 ans. Payé.\n1877. Mme Mazaud a jeté le livre au feu. Il n'a pas brûlé.\n1889. Les dettes de jeu de M. Henri Dumoulin, sur son créancier. Tenu.\n8 décembre 1900. Solde : Louis Mazaud, 31 ans. Payé.\n1912. La faillite de la banque Dumoulin, sur la banque Giraudier. Tenu.\n1917. Demandé à l'envers : la vie du lieutenant Marc Bellevrand. Refusé. Ce qui est payé en vie ne se rend pas.\n1921. Le marché des soies de l'armée, pris à la maison Pélissier, qui ferme. Tenu.\n8 décembre 1924. Solde : *(au crayon, déjà écrit)* L. Perret, née Mazaud."},{"id":"carte-bellevrand","title":"L'invitation de M. Bellevrand","scene":"hotel-bellevrand","text":"*Un carton épais, doublé d'une soie tissée où l'on reconnaît une navette posée sur un miroir ovale, une clef au-dessus.*\n\nM. Hector Bellevrand, président du Cercle de la Navette, a appris avec intérêt que vous vous souciez de la mort de M. Joannès Ravier, qui fut aussi un ami de notre maison.\n\nIl serait honoré de vous recevoir demain, à cinq heures, en son hôtel, 4 rue Sala, pour le thé.\n\n*Une ligne à la plume, d'une belle écriture :* Il est question d'une récompense."}],"knowledge":[{"need":"Comprendre ce qu'a vu Ravier","best":"Le récit de Firmin (pas de jet)","backup":"Psychologie, Trouver Objet Caché dans l'atelier"},{"need":"Obtenir le dossier de police","best":"L'ami de Rabatel (pas de jet)","backup":"Persuasion, Droit, Crédit"},{"need":"Retrouver les disparus du 8 décembre","best":"Bibliothèque","backup":"Archives du Progrès (le journaliste), la mère Brossard, Lucie"},{"need":"Lire la garde","best":"La regarder par l'envers, à contre-jour","backup":"Un miroir, Trouver Objet Caché, Art (broderie)"},{"need":"Reconnaître l'écusson de la Navette","best":"La gerbe de l'enterrement, la chevalière de Bellevrand","backup":"Histoire, Évaluation"},{"need":"Ouvrir la porte de fer de la traboule","best":"Les clés de Lucie","backup":"Serrurerie (difficile), FOR"},{"need":"Faire parler Gaudin","best":"Intimidation","backup":"Persuasion"},{"need":"Découdre le nom des Mazaud","best":"Art/Artisanat (couture, broderie), ou Lucie","backup":"DEX (difficile), deux rounds"},{"need":"Brûler le livre","best":"Une flamme, trois rounds, seulement quand le passage est ouvert","backup":"Les lumignons de la salle, une lampe à pétrole"}],"trackers":[{"id":"jours","label":"Jours avant la nuit des lumières","max":7,"unit":"jours","help":"Lundi 1ᵉʳ décembre au matin : 0. Avancez d'un cran chaque soir. À 7, c'est le lundi 8 au soir : [[salle-des-glaces]].","scenes":["l-atelier","firmin","commissariat","rue-juiverie","palais-saint-jean","traboule","hotel-bellevrand","fourviere","le-reflet","les-caves"],"fullMessage":"Lundi 8 décembre : la ville s'allume."},{"id":"passage","label":"Le passage s'ouvre","max":9,"unit":"rounds","help":"Démarre quand le livre est lu. À 3, on peut franchir la glace, ou y être poussé. À 6, le Teneur prend son dû. À 9, le passage se referme.","scenes":["salle-des-glaces"],"fullMessage":"Le passage se referme."},{"id":"livre-brule","label":"Le livre brûle","max":3,"unit":"rounds","help":"Seulement quand le passage est ouvert. Tenir le livre dans la flamme trois rounds de suite ; s'il est lâché, recommencer.","scenes":["salle-des-glaces"],"fullMessage":"Les quarante glaces se fendent : le passage est clos pour toujours."}]}$story$::jsonb, now()
where not exists (select 1 from public.stories where visibility = 'marketplace' and content #>> '{meta,id}' = 'le-livre-de-l-envers');

insert into public.stories (visibility, content, published_at)
select 'marketplace', $story${"format":"grimoire-story/1","meta":{"id":"le-miel-de-saint-fiacre","title":"Le Miel de Saint-Fiacre","lang":"fr","summary":"Fin août 1929, dans les Baronnies. Ventebrune, village perché au-dessus des champs de lavande, s'apprête à fêter la Saint-Fiacre, et son miel gagne tous les concours depuis cinq ans. Deux étrangers venus pour la fête de l'an dernier n'en sont jamais repartis : ils vendent ce miel sur la place, avec le même sourire que tout le village.","players":{"min":4,"max":5},"duration":"1 à 2 heures","era":"Jeudi 29 et vendredi 30 août 1929","setting":"Ventebrune, village perché des Baronnies (Drôme provençale), entre Nyons et Buis-les-Baronnies, et la chapelle de l'ermitage Saint-Fiacre sur son rocher","system":"d100","author":"Grimoire","license":"CC-BY-4.0","version":"1.1","tags":["groupe","court","horreur rurale","Provence","fête de village","enquête"],"contentWarnings":["insectes","perte du libre arbitre","deuil","morts de vieillards (épilogue)"]},"overview":{"secret":"**Mai 1923.** {{npc:baptistin-arnaud}}, 72 ans, maître apiculteur de Ventebrune, a perdu son fils Paul à Verdun en 1916 et sa femme Rose en 1922. En cherchant des essaims sauvages, il en trouve un dans le mur de la chapelle en ruine de l'ermitage Saint-Fiacre, sur le rocher au-dessus du village : l'ermitage que la paroisse avait incendié en 1721, après qu'on y eut trouvé l'ermite mort, souriant, couvert d'abeilles muettes. Ces abeilles-là sont pâles et ne font aucun bruit. Leur reine n'est pas une abeille : une chose molle et cireuse de la taille d'un poing, qui pense lentement. Baptistin goûte leur miel, et son chagrin s'en va. Au lieu de recueillir l'essaim, il le mure dans la niche derrière l'autel en ne laissant qu'un trou de vol, refait le toit et ferme la porte d'une chaîne.\n\n**Le miel** fait de ceux qui en mangent une part de l'essaim : plus de chagrin, plus de peur, plus de volonté propre, une seule pensée lente partagée par tous. En mars 1924, Baptistin fonde avec le maire {{npc:marius-blanc}} la Coopérative apicole ; à la Saint-Fiacre 1924, le gâteau de miel est partagé à tout le village. Depuis 1925, le miel gagne tous les concours. Depuis l'hiver 1926-1927, Baptistin ne redescend plus : il est assis dans le chœur de la chapelle sous un manteau vivant d'abeilles, il est le cœur et la voix de l'essaim. Chaque dimanche soir, des hommes conduits par sa belle-fille {{npc:fernande-arnaud}} montent chercher environ 180 kg de miel, été comme hiver. Les 146 ruches de la colline sont à moitié vides : un décor.\n\n**La portée.** Le miel n'asservit qu'à portée de l'essaim, environ trois kilomètres autour de l'ermitage. Plus loin, il apaise seulement, et l'on y revient : vendu à Lyon et à Paris, il attire des acheteurs qui finissent par venir s'installer. Ventebrune est passé de 164 habitants en 1921 à 212 aujourd'hui, quand tous les villages des Baronnies se vident. À la Saint-Fiacre de 1928, {{npc:helene-vasseur}}, peintre parisienne, et {{npc:lucien-merle}}, représentant d'une épicerie lyonnaise, ont mangé le gâteau ; ils ne sont jamais repartis. Seule {{npc:odile-fabre}}, l'institutrice, diabétique, n'a jamais goûté au miel ; elle a tout noté, et elle a peur.\n\n**Ce jeudi 29 août 1929**, veille de la Saint-Fiacre, une soixantaine d'invités des villages voisins, le conseiller général et les investigateurs sont attendus à la veillée. À minuit, la coopérative offre à chaque invité une part du gâteau de Saint-Fiacre. **Si personne n'intervient**, tous ceux qui en mangent deviennent l'essaim ; ceux qui vivent loin reviennent s'installer dans l'année ; l'essaim grossit, et sa portée avec lui : l'an prochain, les hameaux voisins.\n\n**Ce qui l'arrête.** La fumée engourdit l'essaim et desserre son emprise sur le village pour une heure. Le feu le détruit. Brûler la colonie ou tuer la Reine libère tout le monde d'un coup : six ans de deuils et de peurs reviennent en une nuit, et les plus vieux, dont le cœur ne tient pas, en meurent, Baptistin le premier.","steps":["[[la-place]] (jeudi 29 août, 10 h) : l'arrivée, le miel offert, les deux étrangers au sourire identique, les abeilles muettes ; à midi, toutes les têtes se tournent vers la chapelle.","[[les-pistes]] (l'après-midi) : quatre pistes à se partager : la coopérative et ses registres, les ruchers vides et les abeilles mortes, Odile Fabre et son carnet, la chambre d'Hélène.","[[la-veillee]] (20 h - minuit) : la farandole d'un seul pas, le silence de 23 h, et le gâteau de minuit à empêcher.","[[l-ermitage]] : la chapelle verrouillée, le Père sous son manteau d'abeilles, la Reine dans le mur : enfumer, brûler, négocier ou partir.","[[epilogue]] (vendredi 30 août, jour de la Saint-Fiacre) : ce que chaque choix a coûté."],"mustNotMiss":["**Le miel change les gens** : la faucille sur la place, les phrases finies par un autre ([[la-place]]), les lettres d'Hélène (sans jet), le carnet d'Odile, et le miel lui-même pour qui en a mangé.","**Le miel vient de l'ermitage, pas des ruches** : les registres (l'« apport de l'Ermitage » chaque dimanche, même en janvier, visible sans jet), les ruches vides, la piste des abeilles mortes, le carnet d'Odile ([[les-pistes]]).","**Le Père est là-haut** : Fernande, Marius, la toile retournée d'Hélène, le carnet d'Odile ([[les-pistes]]) ; les têtes tournées vers la chapelle à midi et à 23 h.","**Le gâteau de minuit** : l'affiche de la fête (sans jet), la dernière lettre d'Hélène, le carnet d'Odile, le discours du maire ([[la-veillee]]).","**Fumée et feu** : la grange Achard et la note de 1721 dans le carnet d'Odile, les enfumoirs jamais servis de la miellerie, l'inscription du linteau ([[l-ermitage]]). Tout apiculteur sait que la fumée calme les abeilles.","**La clé de la chapelle** : sur le trousseau de Fernande à la miellerie, ou chez le garde champêtre ; sinon la chaîne se force."],"branches":["**Brûler la colonie ou tuer la Reine** : l'essaim meurt, tout le village se réveille en pleurs ; Hélène et Lucien sont libres ; trois des plus vieux, dont Baptistin, meurent dans la nuit ([[epilogue]]).","**Enfumer seulement** : gagne 1D6+2 rounds et réveille Baptistin une minute, mais ne règle rien si l'on s'arrête là.","**Saboter le gâteau** (ipéca du médecin ou de la pharmacie de l'école) : les invités vomissent le miel et sont sauvés cette année ; l'essaim vit.","**Négocier** : l'essaim ne ment pas. Il relâche Hélène, Lucien et les investigateurs s'ils partent cette nuit et se taisent ; les invités mangent le gâteau ; le village grandit.","**Emmener Hélène ou Lucien loin du village** (à plus de trois kilomètres) : libère cette personne, au prix de son chagrin revenu d'un coup.","**Partir, ou emporter un pot** : rien n'est réglé, et le pot attend son heure.","Un investigateur qui a trop mangé (Emprise 3) se range du côté du village jusqu'à ce que l'essaim meure ou qu'on l'emmène loin."],"ifStuck":["Odile vient d'elle-même à l'auberge à 17 h, si personne n'est allé la voir : elle a vu des étrangers refuser le miel.","Un chien du village gronde à chaque villageois et suit les investigateurs ; le soir, il les mène au pied du sentier de l'ermitage et refuse d'aller plus loin.","À 23 h, à la veillée, tout le village se tourne vers la chapelle : une lueur dorée passe derrière les fentes de sa porte.","Lucien, interrogé sur ses affaires, dit tranquillement : « Le gros du miel, nous le descendons de l'ermitage le dimanche. Le Père le fait. »","Pour le feu : la distillerie de lavande, au bas du village, garde des bonbonnes d'essence de lavande, qui brûle comme de l'alcool."],"keeperTips":["Horreur en plein jour : soleil, cigales, sourires, tables dressées. Ne montrez rien de monstrueux avant la chapelle. Le malaise vient des détails : le silence des abeilles, les phrases finies par un autre, la faucille.","Les villageois ne sont jamais méchants. Ils sont doux, généreux, patients. Ils veulent seulement que vous goûtiez. C'est ce qui fait peur.","À 4 ou 5 joueurs, encouragez la séparation l'après-midi ([[les-pistes]]) : chacun sa piste, puis on met en commun à l'auberge avant la veillée. Chaque accroche pousse vers une piste différente.","Notez discrètement qui a mangé du miel et son Emprise (règle dans [[la-place]]). Ne dites pas aux joueurs que l'Emprise existe : dites-leur ce que leur investigateur ne ressent plus.","Aucun enfant n'est en danger : l'école est en vacances, les enfants du village passent l'été chez des parents dans la vallée, la coopérative ne donne jamais de miel aux enfants, et les invités montent à la veillée sans les leurs.","Baptistin n'est pas un méchant : c'est un vieil homme qui ne voulait plus avoir mal. Laissez-le revenir une seconde, sous la fumée ou dans le feu, pour dire un nom."]},"acts":[{"id":"le-village","title":"Le village au miel","scenes":[{"id":"la-place","title":"La place de Ventebrune","lead":"Jeudi 29 août, 10 h : l'arrivée, le miel offert, les sourires, les abeilles muettes.","screen":{"place":"street","preset":"dust","time":"day"},"notesFirst":true,"readAloud":["L'autocar de Nyons vous laisse au pied du village à dix heures, dans une odeur de poussière chaude et de lavande coupée. Ventebrune s'accroche à la colline : des maisons de pierre dorée, des volets bleus, un clocher à campanile et, tout en haut, au-dessus des derniers oliviers, une petite chapelle seule sur son rocher.","Sur la place, sous les platanes, on dresse déjà les tables de la fête. Les cigales crient à vous rendre sourds. Une femme blonde en blouse de peintre vient vers vous avec un plateau : du pain, un pot de miel presque blanc, et un sourire. « Bienvenue à Ventebrune. Goûtez. Tout le monde goûte. »"],"flow":[{"title":"Le miel de bienvenue","text":"{{npc:helene-vasseur}} tend les tartines. Le miel sent la lavande et la cire tiède. **Notez qui mange.** Chaque investigateur qui goûte fait aussitôt un jet de POU (voir « La règle du miel »).","roll":{"type":"characteristic","options":["POW"]},"success":"Un goût de lavande, de cire et d'autre chose, très doux. Rien de plus, pour l'instant.","failure":"**Emprise 1.** Une paix lourde, comme au sortir d'un bain chaud. Le prochain jet de SAN de cet investigateur est ignoré. Ne lui dites que ce qu'il ne ressent plus.","extra":"Refuser poliment ne fâche personne. Mais toute la journée, à chaque porte, on reproposera du miel, gentiment."},{"title":"Les retrouvailles","text":"Le parent d'Hélène la reconnaît ; l'acheteur de Lyon reconnaît, d'après sa photographie, {{npc:lucien-merle}} derrière l'étal de miel, sous un platane. Ni l'un ni l'autre n'est surpris. Hélène : « Tu es là pour la fête. Je suis contente. » Elle ne demande aucune nouvelle de la famille.","roll":{"type":"skill","options":["psychology"]},"success":"Ni comédie ni folie : elle est sincèrement heureuse, et derrière ses yeux il manque quelque chose, comme une pièce vidée de ses meubles. Quand on parle de sa mère, morte l'an dernier, rien ne bouge sur son visage. Lucien, lui, parle de sa fiancée morte en 1918 sur le ton d'un bulletin météo.","failure":"Ils ont l'air en pleine santé, reposés, heureux. Ils ont bonne mine, tout simplement."},{"title":"Le maire et la secrétaire","text":"{{npc:marius-blanc}}, maire et président de la coopérative, et {{npc:fernande-arnaud}}, sa secrétaire, viennent saluer. L'un commence une phrase, l'autre la finit, sans se regarder. « Vous êtes nos invités pour la veillée de ce soir... » « ...et pour le gâteau, à minuit. » Marius donne le programme → {{handout:affiche-fete}} et propose de visiter la coopérative à 14 h. Il ajoute, fier : « Deux cent douze habitants ! Le seul village du canton qui grandit. »","roll":{"type":"san","label":"Les phrases qui se finissent ailleurs","san":"0/1"},"extra":"Si on les interroge séparément, ils racontent la même chose avec les mêmes mots."},{"title":"Les abeilles muettes","text":"Des abeilles se posent sur les pots de l'étal, boivent à la fontaine. Il suffit d'y prêter attention : on ne les entend pas.","roll":{"type":"skill","options":["natural-world","science:biology"]},"success":"Une abeille bourdonne toujours : c'est le battement de ses ailes. Celles-ci volent sans un bruit. Et elles sont trop pâles, presque blondes, sans le duvet roux des abeilles du pays.","failure":"Des abeilles attirées par le miel. Avec les cigales, on n'entend rien d'autre, de toute façon.","extra":"Les chiens du village s'écartent des pots et grondent au passage des villageois, jamais à celui des investigateurs."},{"title":"La faucille","text":"Au bord de la place, un jeune coupeur de lavande affûte sa faucille et s'entaille la paume jusqu'à l'os. Il regarde sa main, sourit, l'essuie sur son pantalon et reprend son travail. Ceux qui ont vu : SAN 0/1.","roll":{"type":"skill","options":["medicine","first-aid"]},"success":"Coupure profonde, tendon touché. Pouls lent et régulier, pupilles calmes : aucun signe de douleur, ni de choc. Le sang a une odeur sucrée.","failure":"Une vilaine coupure, vite bandée. Le garçon remercie poliment et retourne à ses bottes de lavande."},{"title":"Midi","text":"L'angélus sonne au clocher. Pendant le temps d'un souffle, toute la place s'immobilise.","roll":{"type":"skill","options":["spot-hidden"]},"success":"Tous, sans exception, même Hélène et Lucien, ont tourné la tête vers la chapelle du rocher au même instant, puis repris leur geste. Deux seulement ne l'ont pas fait : un chien jaune, et une femme brune derrière la fenêtre de l'école, qui baisse aussitôt le rideau.","failure":"Midi sonne, la place se vide pour le déjeuner. On sert aux investigateurs, à l'auberge, du pain et du miel.","extra":"La femme de l'école est {{npc:odile-fabre}}. Si personne ne la remarque, elle viendra à eux à 17 h ([[les-pistes]]).","goto":["les-pistes"]}],"notes":[{"title":"Accroches (une par investigateur)","items":["**L'ingénieur agronome** de la Préfecture de la Drôme : enquête sur des rendements impossibles avant que le préfet ne décore la coopérative → {{handout:ordre-de-mission}}. Piste naturelle : la coopérative et ses registres.","**Un parent d'Hélène Vasseur** (sœur, frère, cousin) : plus de lettres depuis novembre dernier, neuf lettres restées sans réponse → {{handout:lettres-helene}}. Piste naturelle : Hélène et sa chambre.","**L'acheteur de la Maison Gerbier**, épicerie fine de Lyon : remplacer Lucien Merle, négocier l'exclusivité pour 1930, et le ramener s'il le peut → {{handout:lettre-gerbier}}. Pistes naturelles : Lucien, les ventes, la miellerie.","**Le médecin en vacances** à Nyons pour le climat : un confrère lui a conseillé la fête de Ventebrune. Il a sa trousse, et du sirop d'ipéca. Piste naturelle : les corps des villageois, les abeilles mortes, la purge.","**Le photographe d'un journal de Valence**, envoyé pour un article sur « le village qui ne se vide pas » : il connaît les recensements (164 habitants en 1921, 212 aujourd'hui). Pistes naturelles : la mairie, l'école, ses photos développées à l'auberge.","Ils ont pris le même tramway de Pierrelatte à Nyons, puis le même autocar : de quoi faire connaissance. Ils logent tous à l'auberge de la place."]},{"title":"La règle du miel (Emprise)","items":["Chaque fois qu'un investigateur mange du miel (tartine, gâteau, rayon) : jet de POU, **Difficile** pour le gâteau de minuit ou un rayon de la chapelle. Échec : **Emprise +1**.","Qui a au moins Emprise 1 refait un jet de POU à la fin de l'après-midi ([[les-pistes]]) et à l'ouverture de la veillée ([[la-veillee]]) : échec, +1. Le miel continue d'agir.","**Emprise 1** : calme, peurs émoussées. Le prochain jet de SAN est ignoré.","**Emprise 2** : il entend « nous ». Il sait où est l'essaim, finit les phrases des villageois. Un dé de malus à tout jet pour tromper, retenir ou blesser un villageois ou l'essaim.","**Emprise 3** : pris. Le joueur garde son investigateur mais le joue serein : il ne s'oppose plus au village. Une fois par scène, si un compagnon lui parle de ce qu'il a perdu, POU Difficile pour agir librement un round.","**Retour** : une purge (ipéca, eau salée) dans les six heures annule le dernier point gagné ; une heure à plus de trois kilomètres de l'ermitage retire 1 point (SAN 0/1 par point, le chagrin revient) ; la mort de l'essaim remet tout à 0 (SAN 1/1D4)."]},{"title":"Ventebrune en 1929","items":["212 habitants (164 en 1921). La place et ses platanes, la fontaine, l'auberge, l'église paroissiale, la mairie-école.","La coopérative et sa miellerie, à l'entrée du village ; la distillerie de lavande, en contrebas, froide depuis la fin de la coupe.","Les ruchers sur la colline, au milieu du thym, au pied du sentier de l'ermitage (25 minutes de montée).","Le cimetière, sur la route de Buis : aucune fleur sur aucune tombe depuis des années, pas même sur le monument aux morts."]},{"title":"Chronologie","items":["1721 : l'ermite de Saint-Fiacre trouvé mort, souriant, couvert d'abeilles muettes ; la paroisse brûle l'ermitage.","1916 : Paul Arnaud, fils de Baptistin, tué à Verdun. 1922 : mort de Rose, sa femme.","Mai 1923 : Baptistin trouve l'essaim dans le mur de la chapelle et l'y mure.","Mars 1924 : fondation de la coopérative. 30 août 1924 : premier gâteau de Saint-Fiacre.","1925 : premier prix à Nyons. 1927 : médaille d'or à la Foire de Lyon. Hiver 1926-1927 : Baptistin ne redescend plus.","Octobre 1927 : Odile Fabre nommée institutrice. Août 1928 : Hélène et Lucien mangent le gâteau.","Février 1929 : médaille d'or au Concours général agricole de Paris ; la grange Achard brûle. Jeudi 29 août 1929 : la veillée."]}],"npcs":["helene-vasseur","lucien-merle","marius-blanc","fernande-arnaud"],"handouts":["ordre-de-mission","lettres-helene","lettre-gerbier","affiche-fete"],"ambience":["village-day","nature-day"],"sfx":["dog-bark","footsteps"],"next":["les-pistes"]},{"id":"les-pistes","title":"L'après-midi : les quatre pistes","lead":"14 h - 19 h : la coopérative, les ruchers, l'école, la chambre d'Hélène. Les joueurs se partagent les pistes.","screen":{"place":"farm","preset":"dust","time":"day"},"readAloud":["À deux heures, le village dort derrière ses volets. La chaleur écrase la place, l'air tremble au-dessus des tuiles. Sur la colline, les ruches de la coopérative s'alignent entre les touffes de thym, blanches et propres.","Plus haut, la chapelle de l'ermitage porte un toit de tuiles neuves. Sa porte est fermée par une chaîne. Tout autour d'elle, les cigales se taisent."],"flow":[{"title":"A · La miellerie","text":"Marius et Fernande font visiter : l'extracteur, les bidons, les pots, les médailles (Nyons 1925, Lyon 1927, Paris 1929). Fernande tient les registres. L'agronome qui montre son ordre de mission les obtient sans jet.","roll":{"type":"skill","options":["persuade","credit-rating"]},"success":"Fernande sort les registres sans méfiance : elle n'a rien à cacher, elle ne sait plus ce que c'est → {{handout:registre-cooperative}}.","failure":"« Le président doit signer. » Il faudra revenir pendant la veillée : la miellerie est fermée, mais personne ne la garde (Serrurerie, ou la fenêtre de derrière).","extra":"Sur une étagère, six enfumoirs neufs, jamais allumés, couverts de poussière. « Ici, on n'enfume pas. Nos abeilles sont douces. » Au clou derrière la porte, le trousseau de clés de Fernande."},{"title":"A · Lire les registres","text":"Même sans jet, on voit que l'« apport de l'Ermitage » tombe chaque mois, y compris en janvier, quand aucune abeille ne butine.","roll":{"type":"skill","options":["accounting","natural-world"]},"success":"146 ruches donnent au mieux 1 500 à 2 200 kg par an dans les Baronnies. Les ruchers en déclarent 940, ce qui va avec une ruche sur deux habitée. Tout le reste, plus de neuf tonnes et demie, vient d'un seul endroit sans ruche déclarée : l'Ermitage, environ 180 kg chaque dimanche. Signé « B. A. » jusqu'en 1926, puis « pour B. A. : F. A. ».","failure":"Des colonnes bien tenues. Mais l'Ermitage livre chaque dimanche, été comme hiver, et personne ne déclare de ruche là-haut."},{"title":"A · Fernande et le beau-père","text":"B. A., c'est Baptistin Arnaud, le fondateur, son beau-père. « Il garde l'ermitage. » Elle parle de son mari Paul, tué à Verdun, comme d'un voisin parti en voyage.","roll":{"type":"skill","options":["psychology","charm"]},"success":"Une seconde, sa voix se casse : « Père est là-haut. Il nous tient tous. » Puis elle sourit de nouveau, comme si rien n'avait été dit.","failure":"« Il est vieux. Il se repose là-haut, près de ses abeilles. On lui monte ce qu'il faut le dimanche. »","pushed":"Elle se fige au milieu d'un mot, et Marius, à l'autre bout de la miellerie, finit sa phrase. Tous deux vous regardent. Ce soir, le village entier sait ce que vous cherchez : le garde champêtre gardera le pied du sentier pendant la veillée."},{"title":"B · Les ruches vides","text":"Sur la colline, au milieu du thym. Soulever un couvercle.","roll":{"type":"skill","options":["natural-world"]},"success":"Une ruche sur deux est vide : cadres propres, cire neuve, jamais habitée. Les autres abritent de vraies abeilles du pays, rousses, qui bourdonnent fort, et qui n'ont guère de miel. Les ruchers sont un décor.","failure":"Des abeilles rousses furieuses : une piqûre, 1 point de vie. Mais en refermant, on voit que la ruche voisine n'a personne à son entrée : elle est vide, et la suivante aussi."},{"title":"B · Les abeilles mortes","text":"Au bout des ruchers, sur le sentier qui monte, de petits tas d'abeilles pâles, mortes.","roll":{"type":"skill","options":["science:biology","natural-world","medicine"]},"success":"Ce ne sont pas des abeilles. Pas d'aiguillon, pas d'yeux à facettes : une seule tache lisse et luisante. Le ventre est plein d'une pâte blanche, encore tiède, qui sent la cire et la peau. Les pattes finissent par de petits crochets pâles. SAN 0/1D3.","failure":"Des abeilles mortes de chaleur, plus claires que celles du pays. Elles laissent sur les doigts une graisse blanche qui ne part pas à l'eau."},{"title":"B · La piste des mortes","text":"Les petits tas jalonnent le sentier vers la chapelle.","roll":{"type":"skill","options":["track","spot-hidden"]},"success":"Dans la poussière du sentier, des dizaines de traces de pas, montées et descendues, et les ronds laissés par des bidons posés pour souffler. On monte là-haut souvent, et chargé.","failure":"Le sentier grimpe au soleil vers la chapelle. Personne n'y passe de jour.","extra":"S'ils montent à la chapelle maintenant, jouez [[l-ermitage]] en plein jour (voir ses notes).","goto":["l-ermitage"]},{"title":"C · L'école : Odile Fabre","text":"{{npc:odile-fabre}} ouvre la porte de la mairie-école, pâle, et offre un café. Elle regarde qui a mangé du miel. Pas de jet si un investigateur dit qu'il a refusé le miel et qu'on la croit.","roll":{"type":"skill","options":["charm","psychology","persuade"]},"success":"Elle ferme les volets, parle tout bas, et donne son carnet → {{handout:carnet-odile}}.","failure":"« Je ne sais rien, je suis de Valence. » Elle donnera le carnet à la veillée, si elle les voit refuser le miel.","extra":"Si personne n'est venu à l'école, Odile vient à l'auberge à 17 h, son carnet dans un cabas."},{"title":"C · Ce qu'Odile a compris","text":"Elle est diabétique : elle n'a jamais touché au miel, et le village le sait. Elle dit tout ce qu'elle sait (voir ses « knows »). Elle ajoute : « La fumée. Le jour de la grange Achard, pendant une heure, ils étaient redevenus des gens. » Et : « Dans la pharmacie de l'école, j'ai du sirop d'ipéca. »","extra":"Si le groupe le lui demande, elle les accompagne à la veillée et même à l'ermitage. Elle lit le latin."},{"title":"D · La chambre d'Hélène","text":"Hélène loue une chambre au-dessus du four du boulanger. Elle n'en ferme jamais la porte. Des dizaines de toiles : les villageois, un par un, tous avec le même sourire, et tous les regards tournés vers le haut à gauche, vers l'ermitage.","roll":{"type":"skill","options":["spot-hidden"]},"success":"Sous la pile, une dernière toile retournée contre le mur : un vieil homme assis dans une chapelle, vêtu jusqu'au menton d'un manteau d'or qui semble remuer. Au dos : *Le Père. Février 1929.* SAN 0/1.","failure":"Des portraits, des paysages de lavande. Et, dans le tiroir de la commode, les lettres de sa famille, toutes non décachetées."},{"title":"D · Lucien Merle à l'étal","text":"{{npc:lucien-merle}} parle affaires volontiers avec l'acheteur de Gerbier : prix, volumes, exclusivité. Il ne cache rien.","roll":{"type":"skill","options":["fast-talk","persuade","psychology"]},"success":"« Le gros du miel, nous le descendons de l'ermitage le dimanche. Le Père le fait. » Et, sans changer de ton : « En mars, je suis allé à Nyons. À mi-chemin, j'ai pensé à Jeanne. Je suis rentré à pied. On ne part pas, vous savez. On revient toujours. »","failure":"« L'exclusivité ? Nous en parlerons demain, après la fête. Goûtez donc. »"},{"title":"Les photos du photographe","text":"S'il y a un photographe, il peut développer ses plaques du matin dans la cave de l'auberge (une heure).","roll":{"type":"skill","options":["art-craft:photography"]},"success":"Sur la photo de midi, tous les visages de la place sont tournés vers la chapelle, nets, immobiles, comme posés. Sur chaque photo, les abeilles en vol sont nettes elles aussi : elles ne battent pas des ailes.","failure":"Des plaques un peu voilées par la chaleur. Sur celle de midi, on devine pourtant que toutes les têtes regardent du même côté."},{"title":"18 h : le miel agit","text":"Fin d'après-midi. Chaque investigateur qui a au moins Emprise 1 refait un jet de POU. Puis on met en commun à l'auberge avant la veillée.","roll":{"type":"characteristic","options":["POW"]},"success":"Rien ne change.","failure":"Emprise +1.","goto":["la-veillee","l-ermitage"]}],"notes":[{"title":"Qui va où (4 ou 5 joueurs)","items":["A · Coopérative : l'agronome, l'acheteur. B · Ruchers et sentier : le médecin, quiconque connaît les abeilles. C · École : le parent d'Hélène, le photographe. D · Chambre d'Hélène et étal de Lucien : le parent, l'acheteur.","Alternez les pistes toutes les deux ou trois minutes de jeu ; aucune ne doit durer plus d'un quart d'heure. Rendez-vous à l'auberge vers 19 h.","Chaque piste suffit à elle seule à pointer l'ermitage : A par les registres, B par le sentier, C par le carnet, D par la toile et Lucien."]},{"title":"La miellerie","items":["Un extracteur à manivelle, des bidons de 20 kg, des centaines de pots étiquetés « Miel de Saint-Fiacre ».","Les médailles encadrées au mur, et une photographie de mars 1924 : les fondateurs, avec au centre un vieil homme maigre au chapeau de paille, Baptistin Arnaud.","Six enfumoirs neufs, jamais servis. Le trousseau de Fernande au clou : la clé du cadenas de la chapelle est la plus neuve.","Derrière, la camionnette de la coopérative, avec un bidon d'essence."]},{"title":"Le cimetière (sans jet, sur la route de Buis)","items":["Les tombes sont propres, désherbées, sans une fleur. La dernière, celle de la mère Faure, décembre 1927, n'a même pas de photographie.","Sur le monument aux morts, le nom de Paul Arnaud, 1916. Pas un pot de fleurs, pas un ruban, alors que partout en France on fleurit les monuments."]}],"npcs":["marius-blanc","fernande-arnaud","odile-fabre","lucien-merle","helene-vasseur"],"handouts":["registre-cooperative","carnet-odile"],"ambience":["nature-day","village-day"],"sfx":["door-open","latch","dog-bark"],"next":["la-veillee","l-ermitage"]}]},{"id":"la-saint-fiacre","title":"La veillée de la Saint-Fiacre","scenes":[{"id":"la-veillee","title":"La veillée","lead":"20 h - minuit : le village danse d'un seul pas ; à minuit, le gâteau sera partagé entre tous les invités.","screen":{"place":"street","preset":"night","time":"night"},"readAloud":["Des lampions pendent entre les platanes. Sur les longues tables, des fougasses, des melons, des carafes de vin du pays et, au centre, sous un linge blanc, quelque chose de rond et de doré. Une soixantaine d'invités sont montés des villages voisins : on entend des rires, les accents de Buis et de Nyons.","Puis l'accordéon attaque une farandole, et tout Ventebrune se lève. Deux cents personnes, un seul pas. Les semelles frappent la terre ensemble, si exactement qu'on n'entend qu'un seul coup."],"flow":[{"title":"La farandole","text":"Les invités rient et se font entraîner, en retard d'un temps. Les villageois, eux, ne se trompent jamais. Le tracker « Heures avant le gâteau » commence.","roll":{"type":"san","label":"Deux cents personnes, un seul pas","san":"0/1D3"},"extra":"Un investigateur en Emprise 2 se retrouve dans la farandole sans l'avoir décidé : POU pour en sortir."},{"title":"Le miel, encore","text":"À l'ouverture de la veillée, chaque investigateur qui a au moins Emprise 1 refait un jet de POU.","roll":{"type":"characteristic","options":["POW"]},"success":"Rien ne change.","failure":"Emprise +1."},{"title":"Le discours du maire","text":"{{npc:marius-blanc}} lève son verre : « À nos invités... » Deux cents voix achèvent : « ...à ceux qui nous rejoignent. » Le conseiller général applaudit, un peu gêné. Marius rappelle le gâteau de minuit, « offert à chacun de nos invités, et à nos amis d'aujourd'hui », en désignant les investigateurs.","extra":"Hélène fait au fusain le portrait des invités qui le veulent. Lucien sert le vin et le miel. Le garde champêtre {{npc:auguste-pelissier}} ne danse pas : il fume au bas de la place, près du sentier de l'ermitage."},{"title":"Odile","text":"Si le groupe ne l'a pas encore vue, {{npc:odile-fabre}} vient s'asseoir près d'eux, très pâle, et glisse son carnet sous la table → {{handout:carnet-odile}}. « Ils l'ont fait l'an dernier, à minuit. Ne mangez pas. Je vous en supplie, faites quelque chose. »"},{"title":"Onze heures : le silence","text":"Au milieu d'une valse, d'un coup, tous les villageois s'arrêtent et se tournent vers la chapelle du rocher. L'accordéon se tait. Les invités rient, mal à l'aise. Puis tout reprend. Les investigateurs en Emprise 1 ou plus savent, sans savoir comment, que le Père les appelle.","roll":{"type":"skill","options":["listen","spot-hidden"]},"success":"Les cigales et les grillons se sont tus d'un coup, partout autour du village. Là-haut, une lueur dorée passe derrière les fentes de la porte de la chapelle, et s'éteint.","failure":"Un silence gêné, puis la musique repart, plus fort."},{"title":"Que faire avant minuit ?","text":"Le gâteau est sous son linge, au centre de la table d'honneur. Fernande ne le quitte guère des yeux. Les invités ne savent rien. Les choix les plus probables suivent ; on peut en combiner plusieurs si le groupe se sépare."},{"title":"Monter à l'ermitage","branch":"S'ils montent à l'ermitage","text":"Quitter la fête et prendre le sentier (25 minutes). Le garde champêtre garde le pied du sentier ; on peut le distraire, le contourner par les ruchers, ou lui parler.","roll":{"type":"group","options":["stealth"]},"success":"Personne ne les voit partir. Le tracker « Les villageois montent » démarrera à 0.","failure":"Cent têtes se tournent en même temps, puis reviennent à la danse. Le tracker « Les villageois montent » démarrera à 2.","goto":["l-ermitage"]},{"title":"Saboter le gâteau","branch":"S'ils sabotent le gâteau","text":"Verser l'ipéca du médecin (ou de la pharmacie de l'école) dans le gâteau, ou dans le vin de minuit. Il faut détourner l'attention de Fernande : un autre joueur peut l'occuper.","roll":{"type":"skill","options":["sleight-of-hand"]},"success":"À minuit, tout le monde mange. Vingt minutes plus tard, invités et villageois vomissent sous les platanes. Le miel est rendu avant d'agir : les invités sont sauvés cette année. Les villageois, eux, sourient en s'essuyant la bouche. L'essaim est intact.","failure":"Fernande les voit, sans colère. Le gâteau est emporté et remplacé par un autre, gardé à la miellerie. Des villageois entourent doucement les investigateurs et leur tendent une part, chacun, avec patience.","pushed":"Fernande et une dizaine de villageois les tiennent par les bras, sans violence, et portent le gâteau à leurs lèvres : POU Difficile, échec Emprise +2."},{"title":"Emmener Hélène ou Lucien","branch":"S'ils emmènent Hélène ou Lucien loin du village","text":"En voiture (celle du médecin ou de l'agronome, ou la camionnette de la coopérative) sur la route de Nyons. Il faut d'abord les faire monter : ils viennent volontiers « faire un tour ».","roll":{"type":"skill","options":["drive-auto"]},"success":"À trois kilomètres, la personne se met à trembler. Au bout d'une heure, elle pleure comme si son deuil datait d'hier, et demande quel jour on est. Elle est libre, au prix de ce chagrin et d'une année dont elle ne se souvient qu'à moitié.","failure":"Dans un lacet, avec un sourire, la personne tire le frein à main. La voiture finit dans le fossé (1D3 à chacun) ; elle remonte au village à pied, sans se presser."},{"title":"Rester et refuser","branch":"S'ils restent et refusent le gâteau","text":"Refuser ne coûte rien : on les laisse tranquilles. Les invités mangent. Rien n'est réglé, et la nuit ne fait que commencer : ils peuvent encore monter à l'ermitage après minuit."},{"title":"Minuit : le gâteau","text":"Si rien ne l'a empêché, Marius découvre le gâteau et chaque invité reçoit sa part. Un investigateur qui mange : POU Difficile, échec Emprise +1. Les invités rient, puis, peu à peu, se taisent et sourient.","extra":"Le vendredi matin, les invités redescendront chez eux, calmes. Dans l'année, la plupart reviendront s'installer à Ventebrune."}],"notes":[{"title":"Sur la place","items":["Les invités : le conseiller général du canton et sa femme, des gens de Buis, de Mollans et de Nyons, des marchands de lavande. Une soixantaine en tout, venus sans enfants : la veillée finit tard.","Le gâteau de Saint-Fiacre : une grande couronne de pâte briochée fourrée de miel, sous un linge brodé, sur la table d'honneur.","Le garde champêtre fume au pied du sentier de l'ermitage de 21 h à minuit ; il a l'autre clé du cadenas.","La miellerie est fermée mais personne ne la garde : enfumoirs, trousseau de Fernande, bidon d'essence de la camionnette."]},{"title":"Si un investigateur est pris (Emprise 3)","items":["Il se lève pour la farandole, sourit, propose du miel à ses compagnons. Il ne les trahit pas activement, mais il ne les aide plus contre le village.","S'il apprend qu'on veut brûler l'ermitage, il le dit aux villageois, simplement, comme on donne l'heure (le tracker « Les villageois montent » démarre à 3).","Le traîner loin du village en voiture le libère à raison d'1 point par heure."]}],"npcs":["marius-blanc","fernande-arnaud","odile-fabre","helene-vasseur","lucien-merle","auguste-pelissier","villageois"],"handouts":["carnet-odile"],"ambience":["village-night","night-crickets"],"sfx":["footsteps","dog-bark"],"next":["l-ermitage","epilogue"]},{"id":"l-ermitage","title":"L'ermitage Saint-Fiacre","lead":"La chapelle verrouillée, le vieil apiculteur sous son manteau d'abeilles, la Reine dans le mur : le choix.","screen":{"place":"church","preset":"ritual","time":"night"},"readAloud":["Le sentier monte entre les chênes verts et le thym. Plus vous approchez, plus le silence s'épaissit : plus une cigale, plus un grillon, rien que vos pas sur les cailloux.","La chapelle est petite, trapue, coiffée de tuiles neuves. Une chaîne et un cadenas ferment sa porte. Par les fentes du bois filtre une lumière jaune et chaude, et une odeur de cire si forte qu'elle colle au fond de la gorge."],"flow":[{"title":"La porte","text":"La clé du trousseau de Fernande ou celle du garde champêtre ouvre sans bruit. Sinon : crocheter le cadenas (Serrurerie), ou arracher la chaîne de ses pitons (FOR, dans les jets rapides de la scène). Une petite fenêtre haute, côté vallée, laisse passer une personne (Grimper).","roll":{"type":"skill","options":["locksmith"]},"success":"La porte s'ouvre sans bruit.","failure":"Le métal grince, un piton saute avec un claquement sec. Tout le village l'a senti : le tracker « Les villageois montent » démarre, ou avance de 1."},{"title":"Le Père","text":"Les murs disparaissent sous les rayons de cire pâle. Derrière l'autel, une niche murée, fissurée, d'où la cire déborde ; au centre, un trou de vol. Dans le chœur, sur un banc, {{npc:baptistin-arnaud}} : un vieil homme assis, les mains sur les genoux, vêtu jusqu'au menton d'un manteau d'abeilles pâles qui remue lentement. Elles ne font aucun bruit. Ses yeux sont ouverts. Il sourit.","roll":{"type":"san","label":"Le Père sous son manteau d'abeilles","san":"1/1D6"},"extra":"La lumière jaune ne vient d'aucune lampe : la cire elle-même luit faiblement, et respire."},{"title":"L'inscription","text":"Sur le linteau de la niche, des lettres latines taillées dans la pierre, à demi noyées dans la cire → {{handout:inscription-ermitage}}. Odile, si elle est là, la lit sans jet.","roll":{"type":"skill","options":["language-other:latin","history","occult"]},"success":"« Ne touche pas au miel. C'est un doux oubli. Le feu seul délie. 1721. »","failure":"Des mots usés : *MEL*, *IGNIS*. Le miel, le feu. Et une date, 1721."},{"title":"Baptistin parle","text":"Il parle lentement, pour l'essaim, au pluriel. Il tend à chacun un morceau de rayon qui coule. « Vous avez mal. Tous. Nous le sentons d'ici. Ça peut s'arrêter. » Voir « Ce que dit l'essaim ». Le choix des joueurs suit ; manger le rayon : POU Difficile, échec Emprise +1."},{"title":"Enfumer","branch":"S'ils enfument l'essaim","text":"Un enfumoir de la miellerie, ou un fagot de thym vert et de paille de lavande qui fume. À défaut de Sciences naturelles, un jet de Chance.","roll":{"type":"skill","options":["natural-world"]},"success":"Le manteau glisse de Baptistin comme un drap. Les abeilles se massent dans la niche, engourdies, pour 1D6+2 rounds. Baptistin ferme les yeux et dit, pour la première fois depuis six ans : « Rose. » En bas, la musique s'arrête : le village est hébété pour une heure.","failure":"La fumée est trop maigre : l'essaim se soulève d'un seul bloc, sans un bruit, et attaque (voir {{npc:l-essaim}}).","extra":"La fumée ne règle rien seule : elle donne le temps de briser la niche, de parler à Baptistin redevenu lui-même une minute, ou de repartir."},{"title":"Briser la niche et brûler","branch":"S'ils brûlent la colonie","text":"Il faut ouvrir la niche (STR, ou deux rounds avec une barre ou une pioche) puis mettre le feu à la cire : essence de lavande de la distillerie, essence de la camionnette, huile d'une lanterne.","roll":{"type":"characteristic","options":["STR"]},"success":"Le plâtre cède. Derrière, un mur de rayons pâles et, au centre, {{npc:la-reine}} (SAN 1/1D8). Le feu prend dans la cire comme dans de l'huile ; la Reine se recroqueville. Tout l'essaim tombe en une minute, comme une pluie sèche.","failure":"Le mur résiste : il faut verser le combustible par le trou de vol. Cela marche, mais l'essaim sort d'abord tout entier (une attaque de {{npc:l-essaim}} sur chacun) et le feu ne prend qu'un round plus tard.","extra":"Baptistin, dans les flammes ou dehors sur l'herbe, redevient un vieil homme. Il dit « Paul... », pleure, et meurt. En bas, montant du village, un cri de deux cents gorges : SAN 1/1D4. Puis → [[epilogue]].","goto":["epilogue"]},{"title":"Arracher la Reine","branch":"S'ils tuent la Reine de leurs mains","text":"Ouvrir la niche (comme ci-dessus), plonger la main dans la cire tiède, saisir la Reine. La toucher : POU, échec Emprise +1, et l'investigateur la tient contre lui au lieu de l'écraser.","roll":{"type":"characteristic","options":["POW"]},"success":"Elle éclate entre les doigts comme un fruit trop mûr (SAN 1/1D8). L'essaim tombe en une minute. Même fin que le feu, mais la cire et le miel restent, inertes : ce n'est plus que du miel.","failure":"Elle est tiède, elle bat doucement, elle est si légère. L'investigateur la serre contre sa poitrine. Un compagnon doit la lui arracher (STR opposée) ou il faut tout brûler.","goto":["epilogue"]},{"title":"Négocier","branch":"S'ils négocient","text":"L'essaim ne ment pas : une seule pensée n'a pas besoin de mentir. Il veut être mangé, et grandir. Il peut relâcher Hélène, Lucien et les investigateurs, s'ils partent cette nuit et se taisent (et si l'agronome écrit un bon rapport).","roll":{"type":"skill","options":["persuade","psychology"]},"success":"Accordé. Hélène et Lucien seront « laissés froids » s'ils partent avant l'aube ; l'Emprise des investigateurs tombe à 0 dès qu'ils passent la crête. Le gâteau sera partagé à minuit, ou l'a déjà été.","failure":"Il ne comprend pas ce qu'on lui refuse. Il ne sait proposer qu'une chose : le miel, encore.","goto":["epilogue"]},{"title":"Partir, avec ou sans pot","branch":"S'ils repartent sans rien faire","text":"Baptistin tend un pot fermé à celui qui a le plus perdu dans sa vie. « Pour plus tard. Pour le jour où ça fera trop mal. » Le prendre ou non : notez qui le prend. Rien n'est réglé.","goto":["epilogue"]},{"title":"Les villageois arrivent","text":"Quand le tracker atteint 6, ils emplissent la porte, lanternes à la main, sans un mot, Marius et Fernande devant. Ils ne frappent pas : ils tiennent, et portent du miel aux lèvres (voir {{npc:villageois}}). Pour se dégager : Corps à corps opposé, ou FOR (jets rapides de la scène) contre leur FOR.","roll":{"type":"opposed","options":["fighting-brawl"],"against":{"npc":"villageois","skill":"fighting-brawl"}},"success":"L'investigateur se dégage et garde un round d'avance.","failure":"Tenu. Chaque round tenu : POU, échec Emprise +1.","extra":"Si la fumée est dans la chapelle, ils s'arrêtent sur le seuil, hébétés. Si la colonie brûle, ils tombent à genoux et pleurent."}],"notes":[{"title":"Ce que dit l'essaim (par la bouche de Baptistin)","items":["« Nous n'avons plus peur. Nous n'avons plus froid. Nous ne perdons plus personne. »","« Paul est mort à Verdun. Ça ne fait rien. Rien ne fait rien. C'est doux. »","« Les gens d'en bas ont choisi. Ils ont goûté. Ils restent. »","Si on parle du feu : « Ils ont déjà brûlé, il y a longtemps. Nous sommes revenus. Nous revenons toujours. »","Si on parle d'Odile : « Celle qui ne goûte pas. Elle goûtera. Tout le monde finit par avoir mal assez. »","Sous la fumée, une minute, Baptistin lui-même : « Rose... Je voulais juste dormir. Brûlez-la. Brûlez-moi avec. »"]},{"title":"De jour (s'ils montent dans l'après-midi)","items":["Midi passé, plein soleil, 35 degrés à l'ombre des chênes verts. Passez l'écran d'ambiance en jour.","La moitié de l'essaim butine sur la garrigue : un dé de bonus pour enfumer, mais les butineuses reviennent en trois rounds si on attaque la niche.","Les villageois sont au village à préparer la fête : le tracker « Les villageois montent » commence quand l'essaim est attaqué, et ils mettent tout de même six rounds.","Si l'essaim est détruit l'après-midi, la veillée n'a pas lieu : passez directement à l'[[epilogue]], qui se joue le soir même."]},{"title":"Combat dans la chapelle","items":["L'essaim attaque tous ceux qui touchent à la niche ou à Baptistin, un par round, puis tout le monde s'il est blessé par le feu.","Baptistin ne se lève pas et ne se bat pas.","Fumée sur la chapelle : l'essaim engourdi, les villageois hébétés sur le seuil, Baptistin lucide une minute."]}],"npcs":["baptistin-arnaud","l-essaim","la-reine","villageois","odile-fabre"],"handouts":["inscription-ermitage"],"ambience":["night-crickets","wind"],"sfx":["latch","door-creak","footsteps"],"next":["epilogue"],"rolls":[{"type":"characteristic","options":["STR"],"label":"Arracher la chaîne, se dégager"}]},{"id":"epilogue","title":"Le jour de la Saint-Fiacre","lead":"Vendredi 30 août : ce que chaque choix a coûté.","screen":{"place":"graveyard","preset":"dust","time":"day"},"readAloud":["Le vendredi 30 août se lève blanc de chaleur sur la colline. Les cloches de Ventebrune sonnent pour la Saint-Fiacre, patron des jardiniers. Les cigales reprennent, une à une."],"flow":[{"title":"Ce matin-là","text":"Jouez l'issue qui correspond à ce que le groupe a fait. Plusieurs peuvent se combiner (gâteau saboté et colonie brûlée, par exemple)."},{"title":"La colonie a brûlé","branch":"Si l'essaim est mort (feu ou Reine tuée)","text":"Toute la nuit, le village a pleuré. Au matin, trois des plus vieux sont morts dans leur lit : la mère Ginoux, 94 ans, le père Achard, 88 ans, et Baptistin là-haut. Fernande pleure Paul comme au jour du télégramme de 1916. Marius erre sur la place, désemparé. Le cimetière, pour la première fois depuis six ans, est plein de monde et de fleurs. Personne ne remercie les investigateurs ; certains les maudissent. Des années plus tard, quelques-uns leur écriront.","roll":{"type":"damage","label":"Gain de SAN : l'essaim détruit","dice":"1D6"},"extra":"Hélène pleure sa mère et demande à rentrer à Paris. Lucien retourne à Lyon et démissionne de Gerbier. Les invités qui ont mangé le gâteau cette nuit sont libres aussi."},{"title":"Le gâteau saboté","branch":"Si le gâteau a été saboté mais l'essaim vit","text":"Les invités repartent malades, vexés, mais libres. Ventebrune sourit toujours. L'an prochain, il y aura une autre Saint-Fiacre, et un autre gâteau.","roll":{"type":"damage","label":"Gain de SAN : les invités sauvés","dice":"1D3"}},{"title":"Le marché","branch":"S'ils ont négocié","text":"Hélène et Lucien partent à l'aube avec eux, en larmes dès la crête. L'essaim tient parole. Dans l'année, une quarantaine d'invités de la veillée viennent s'installer à Ventebrune ; le village dépasse 250 habitants au printemps. La coopérative reçoit une nouvelle médaille, et l'agronome est invité à la remettre.","roll":{"type":"san","label":"Ce qu'on a laissé derrière soi","san":"0/1D3"}},{"title":"Rien n'est fait","branch":"S'ils sont partis sans rien faire","text":"Les invités redescendent calmes et souriants. Hélène et Lucien restent. Odile Fabre écrit aux investigateurs à l'automne ; à Noël, sa lettre se termine par : « J'ai goûté. Nous allons bien. Venez pour la Saint-Fiacre. »","roll":{"type":"san","label":"La lettre d'Odile","san":"1/1D4"}},{"title":"Le pot de miel","text":"Celui qui a gardé un pot l'emporte chez lui. Loin de l'essaim, ce miel n'asservit pas : il efface le chagrin, un temps, et l'on y revient. Le jour où l'investigateur perd quelqu'un, le gardien lui demande s'il ouvre le pot. S'il l'ouvre : plus de perte de SAN pour ce deuil, et une envie, chaque année vers la fin août, de prendre l'autocar de Nyons.","extra":"Si l'essaim est mort, le pot n'est plus que du miel. L'investigateur ne le sait pas forcément."},{"title":"Un investigateur pris","text":"Un investigateur resté en Emprise 3 alors que l'essaim vit reste à Ventebrune. Il écrit à sa famille une lettre calme, puis plus rien. Il devient un personnage du gardien, que les autres peuvent revenir chercher l'an prochain."}],"notes":[{"title":"Récompenses et pertes","items":["Essaim détruit : **1D6 SAN** pour chacun ; ceux qui avaient de l'Emprise perdent **1/1D4 SAN** quand leur propre chagrin revient.","Gâteau saboté (essaim vivant) : **1D3 SAN**.","Hélène ou Lucien ramené loin du village : **1D3 SAN** pour celui qui l'a emmené.","Marché conclu : **0/1D3 SAN**. Rien fait : **1/1D4 SAN** à la lettre d'Odile.","Investigateur pris et laissé à Ventebrune : **1/1D6 SAN** pour ses compagnons."]},{"title":"Ventebrune après","items":["Si l'essaim est mort : la coopérative est dissoute au printemps 1930 ; les ruchers sont vendus ; la chapelle de l'ermitage s'effondre aux pluies d'automne. Ventebrune redevient un village des Baronnies qui se vide.","L'agronome doit écrire un rapport. Ce qu'il y met est son affaire.","Odile Fabre demande sa mutation, ou reste, selon ce que les investigateurs ont fait pour elle."]}],"npcs":["fernande-arnaud","helene-vasseur","lucien-merle","odile-fabre"],"ambience":["village-day","nature-day"],"sfx":["footsteps"]}]}],"npcs":[{"id":"baptistin-arnaud","name":"Baptistin Arnaud","role":"Maître apiculteur, fondateur de la coopérative : le cœur de l'essaim","description":"78 ans. Assis dans le chœur de la chapelle depuis l'hiver 1926-1927, vêtu jusqu'au menton d'un manteau d'abeilles pâles et muettes. Maigre, propre, les yeux ouverts, un sourire immobile.","personality":"Il n'est plus vraiment lui-même : il parle pour l'essaim, lentement, au pluriel. Sous cette voix reste un vieil homme qui a perdu son fils et sa femme et ne voulait plus avoir mal. La fumée le fait revenir une minute.","characteristics":{"STR":25,"CON":35,"SIZ":50,"DEX":15,"INT":65,"POW":85},"hp":8,"sanLoss":"1/1D6","knows":["Il a trouvé l'essaim dans le mur de la chapelle en mai 1923 et l'y a muré au lieu de le recueillir.","Il savait pour l'incendie de 1721 : tout le monde au village connaissait le dicton « À l'ermitage, on ne monte pas ». Il est monté quand même.","Le feu tuera l'essaim, et lui avec. Sous la fumée, il le dit."],"special":["Ne se lève pas, ne se bat pas.","Tant qu'il vit, l'essaim a une voix et peut négocier.","Meurt quand la colonie brûle ou que la Reine meurt, après avoir dit un nom : Paul, ou Rose."]},{"id":"l-essaim","kind":"creature","name":"L'essaim de l'ermitage","role":"Les abeilles pâles et muettes","description":"Des milliers d'insectes presque blonds, sans aiguillon visible ni yeux à facettes, qui volent sans le moindre bruit. Le ventre plein d'une pâte de cire tiède.","personality":"Une seule pensée, lente et patiente, partagée avec tout le village. Ne hait rien. Veut être mangé, et grandir.","hp":20,"armor":0,"attacksPerRound":1,"attacks":[{"name":"Piqûres","skill":60,"damage":"1D3","note":"Indolores. CON, sinon un dé de malus pendant une heure (engourdissement). Trois piqûres ou plus dans le même round : POU, sinon Emprise +1 (le dard porte le miel)."}],"sanLoss":"0/1D4","special":["Silencieux : aucun bourdonnement, jamais.","Les armes ne servent à rien contre la masse. Le feu lui fait 1D6 points par round ; l'eau ne fait rien.","La fumée l'engourdit 1D6+2 rounds : il se masse dans la niche, et son emprise sur le village se relâche pour une heure.","Meurt tout entier en une minute si la Reine meurt."]},{"id":"la-reine","kind":"creature","name":"La Reine","role":"Ce qui vit au fond du mur","description":"Une masse molle, cireuse, translucide, de la taille d'un poing, au centre des rayons. Trop de pattes, courtes et pâles. Sur le dos, un motif qui ressemble à un visage endormi et n'en est pas un. Elle est tiède, et elle bat lentement.","personality":"Elle pense lentement, avec tout le village. Elle n'a pas de nom ; Odile l'appelle « la Reine », le registre de 1721 « la mère du miel ».","hp":6,"armor":0,"sanLoss":"1/1D8","special":["Ne se défend pas : ses abeilles le font pour elle.","La toucher à mains nues : POU, sinon Emprise +1. Elle veut qu'on la prenne.","Morte, écrasée ou brûlée, tout l'essaim tombe en une minute, comme une pluie sèche, et le village se réveille."]},{"id":"marius-blanc","name":"Marius Blanc","role":"Maire de Ventebrune, président de la coopérative","description":"58 ans, gros, rouge, moustache blanche, gilet ouvert sur une chemise impeccable. Il serre les mains à deux mains.","personality":"Jovial, généreux, intarissable sur sa coopérative et ses médailles. Finit les phrases de Fernande, et elle les siennes. Sa femme Augustine a perdu leur fille en 1919 ; il n'en parle jamais.","characteristics":{"STR":60,"CON":65,"SIZ":70,"DEX":45,"INT":55,"POW":35},"hp":13,"dodge":22,"attacks":[{"name":"Empoigner","skill":50,"damage":"0","note":"Il retient, il ne frappe pas."}],"knows":["La coopérative a été fondée en mars 1924 avec Baptistin Arnaud. Médailles : Nyons 1925, Lyon 1927, Paris 1929.","212 habitants, contre 164 en 1921 : « Le seul village du canton qui grandit. »","La chapelle est fermée « parce que le toit est dangereux » (faux : le toit est neuf).","« Baptistin se repose là-haut. Il garde l'ermitage. »"]},{"id":"fernande-arnaud","name":"Fernande Arnaud","role":"Secrétaire-comptable de la coopérative, belle-fille de Baptistin","description":"49 ans, mince, robe grise, un trousseau de clés à la ceinture. Une écriture d'institutrice.","personality":"Précise, aimable, sans défense : elle répond à tout. Veuve de Paul Arnaud, tué à Verdun en 1916, dont elle parle comme d'un voisin parti en voyage. Une fissure, parfois : « Père est là-haut. Il nous tient tous. »","characteristics":{"STR":45,"CON":55,"SIZ":50,"DEX":55,"INT":65,"POW":35},"hp":10,"dodge":27,"knows":["Elle tient les registres : l'apport de l'Ermitage, environ 180 kg chaque dimanche, qu'elle signe « pour B. A. » depuis 1927.","Chaque dimanche soir, elle mène les porteurs à la chapelle avec la clé du cadenas, sur son trousseau.","Baptistin ne redescend plus depuis l'hiver 1926-1927."]},{"id":"odile-fabre","name":"Odile Fabre","role":"Institutrice de Ventebrune","description":"34 ans, brune, chignon serré, lunettes cerclées d'acier. Nommée de Valence en octobre 1927. Diabétique : elle n'a jamais touché au miel.","personality":"Méthodique, effrayée, têtue. Elle a tout noté pour se prouver qu'elle n'est pas folle. Soulagée jusqu'aux larmes de trouver quelqu'un qui voit la même chose qu'elle.","characteristics":{"STR":40,"CON":45,"SIZ":45,"DEX":55,"INT":75,"POW":70,"EDU":80},"hp":9,"dodge":27,"skills":{"language-other:latin":50,"library-use":60,"first-aid":40},"knows":["Personne au village ne porte le deuil, ne pleure, ne fleurit une tombe.","Hélène et Lucien ont changé le lendemain du gâteau de la Saint-Fiacre 1928.","Chaque dimanche à la nuit, des hommes montent à l'ermitage avec des bidons vides et redescendent chargés, Fernande devant.","En février 1929, la fumée de la grange Achard a couvert la place une heure : les villageois se sont arrêtés, hébétés, et Augustine Blanc a crié le nom de sa fille morte. Puis le vent a tourné.","Lucien est parti pour Nyons en mars et revenu à pied dans la nuit, en pleurs ; le matin, il souriait. « On revient toujours. »","Elle a recopié aux archives de la mairie la note du curé de 1721 sur l'incendie de l'ermitage.","Il y a du sirop d'ipéca dans la pharmacie de l'école."]},{"id":"helene-vasseur","name":"Hélène Vasseur","role":"Peintre parisienne, venue pour la Saint-Fiacre 1928","description":"27 ans, blonde, hâlée, blouse de peintre tachée de couleurs. Elle sent la térébenthine et le miel.","personality":"Douce, heureuse, attentive, et vide derrière les yeux. Sa mère est morte en avril 1928 : elle était descendue dans le Midi pour peindre et oublier. Elle a oublié.","characteristics":{"STR":40,"CON":55,"SIZ":45,"DEX":65,"APP":70,"INT":65,"POW":30},"hp":10,"knows":["« Le Père est là-haut. Je l'ai peint, une fois. Il est beau. »","Elle n'ouvre plus les lettres de sa famille : « Je sais ce qu'elles disent. »","Elle aimerait que son parent goûte le gâteau à minuit, « pour qu'on soit ensemble »."]},{"id":"lucien-merle","name":"Lucien Merle","role":"Ancien représentant de la Maison Gerbier (Lyon), tient l'étal de miel","description":"31 ans, costume de ville trop chaud, manches retroussées, canotier. Bronzé comme un paysan.","personality":"Affable, commerçant jusqu'au bout des ongles, d'une franchise désarmante. Sa fiancée Jeanne est morte de la grippe en octobre 1918 ; il en parle sur le ton d'un bulletin météo.","characteristics":{"STR":55,"CON":60,"SIZ":60,"DEX":55,"INT":60,"POW":30},"hp":12,"dodge":27,"knows":["Les prix, les volumes, les clients de la coopérative à Lyon et à Paris.","Depuis le printemps, il porte les bidons de l'ermitage le dimanche : « Le Père le fait. »","En mars, il a voulu aller à Nyons ; il est rentré à pied. « On ne part pas. On revient toujours. »"]},{"id":"auguste-pelissier","name":"Auguste Pélissier","role":"Garde champêtre","description":"52 ans, grand et lourd, képi, plaque de cuivre, gourdin de châtaignier.","personality":"Lent, placide, souriant. Pendant la veillée, il fume au pied du sentier de l'ermitage. Il ne s'énerve jamais ; il barre le chemin.","characteristics":{"STR":70,"CON":65,"SIZ":75,"DEX":45,"INT":45,"POW":35},"hp":14,"dodge":22,"attacks":[{"name":"Empoigner","skill":55,"damage":"0","note":"Il retient."},{"name":"Gourdin","skill":45,"damage":"1D6","note":"Seulement si quelqu'un s'en prend à l'essaim sous ses yeux."}],"knows":["Il a la seconde clé du cadenas de la chapelle.","« Personne ne monte à l'ermitage la nuit de la fête. Le Père se repose. »"]},{"id":"villageois","name":"Villageois de Ventebrune (type)","role":"Les habitants, d'un seul pas","description":"Coupeurs de lavande, paysannes, artisans : hâlés, propres, souriants. Ils arrivent ensemble et bougent ensemble.","personality":"Doux, patients, sans colère et sans peur. Ils ne blessent pas : ils tiennent, et offrent du miel.","characteristics":{"STR":55,"CON":60,"SIZ":60,"DEX":50,"INT":50,"POW":30},"hp":12,"dodge":25,"attacks":[{"name":"Empoigner","skill":45,"damage":"0","note":"À plusieurs : chaque round où un investigateur est tenu, on lui porte du miel aux lèvres : POU, sinon Emprise +1."}],"special":["Sous la fumée, ils s'arrêtent, hébétés, pour une heure.","Si l'essaim meurt, ils tombent à genoux et pleurent."],"skills":{"fighting-brawl":45}}],"handouts":[{"id":"ordre-de-mission","title":"Ordre de mission de la Préfecture","scene":"la-place","text":"*PRÉFECTURE DE LA DRÔME — Direction des Services agricoles*\n*Valence, le 24 août 1929*\n\nÀ l'ingénieur agronome chargé de mission,\n\nLa Coopérative apicole de Ventebrune (canton de Buis-les-Baronnies), médaille d'or au Concours général agricole de Paris en février dernier, sollicite pour son président la croix du Mérite agricole.\n\nAvant toute suite, M. le Préfet souhaite un avis sur les points suivants :\n\n1. La Coopérative déclare **10 530 kg** de miel vendus en 1928 pour **146 ruches**, soit plus de 70 kg par ruche, quand les meilleurs ruchers du département n'en donnent pas 20.\n2. L'analyse faite pour le jury par la Station agronomique de Valence ne relève **aucun grain de pollen identifiable**, ce qui est sans exemple pour un miel naturel, et une matière azotée que le laboratoire n'a pu déterminer. Les échantillons ne cristallisent pas après six mois.\n\nM. le Maire de Ventebrune invite M. le Préfet à la fête de la Saint-Fiacre, le 30 août. M. le Préfet, retenu, vous y délègue. Vous vous présenterez le jeudi 29 et visiterez ruchers et miellerie.\n\n*Pour le Préfet et par délégation,*\n**Le Directeur des Services agricoles**"},{"id":"lettres-helene","title":"Lettres d'Hélène Vasseur à sa famille","scene":"la-place","text":"*Ventebrune, le 1er septembre 1928*\n\nMes chers tous,\n\nQuelle fête ! Des lampions, une farandole, et à minuit un gâteau au miel qu'on partage entre tous. J'en ai pris deux parts. Depuis Maman, je n'avais pas dormi une nuit entière. Ici, je dors. Je reste quelques jours, il y a tant à peindre.\n\n*Le 12 septembre*\n\nJe ne pense plus à Maman. Je veux dire : j'y pense, mais ça ne fait plus rien. C'est merveilleux, non ? Les gens d'ici sont si calmes. Je loue une chambre au-dessus du four.\n\n*Le 8 octobre*\n\nNous allons bien. Il fait doux. Ne m'écrivez pas tant.\n\n*Le 2 novembre*\n\nNe venez pas me chercher. Venez pour la Saint-Fiacre, le 30 août. Mangez le gâteau. Vous comprendrez. Nous vous attendons.\n\nHélène\n\n*(Depuis, neuf lettres de la famille sont restées sans réponse.)*"},{"id":"lettre-gerbier","title":"Lettre de la Maison Gerbier","scene":"la-place","text":"*MAISON GERBIER — Épicerie fine, primeurs, confiserie — rue Mercière, Lyon*\n*Lyon, le 26 août 1929*\n\nComme convenu, vous vous rendrez à Ventebrune pour la Saint-Fiacre. Notre représentant, M. Lucien Merle, envoyé là-bas pour la fête de l'an dernier, ne nous est jamais revenu. Voici son télégramme du 4 septembre 1928 :\n\nRESTE A VENTEBRUNE STOP AFFAIRE EXCELLENTE STOP INUTILE ENVOYER QUELQU'UN\n\nPuis, le 20 septembre, sa démission, par lettre, sans un mot d'explication. Ce n'était pas son genre.\n\nLe miel de Ventebrune se vend comme aucun autre. Nos clientes en rachètent chaque semaine ; trois d'entre elles nous ont demandé l'adresse du village, et Mme Rivoire, du quai Saint-Antoine, a vendu son appartement pour aller s'y installer.\n\nObtenez l'exclusivité pour 1930. Et ramenez-nous M. Merle, si vous le pouvez.\n\n**É. Gerbier**"},{"id":"affiche-fete","title":"Affiche de la fête","scene":"la-place","text":"**COMMUNE DE VENTEBRUNE**\n**FÊTE PATRONALE DE LA SAINT-FIACRE**\n*Jeudi 29 et vendredi 30 août 1929*\n\n**Jeudi 29**\n18 h — Concours de boules, place des Platanes\n20 h — Grande veillée et banquet offerts par la Coopérative apicole\n21 h — Bal et farandole\n**Minuit — Partage du gâteau de Saint-Fiacre, offert à tous nos invités**\n\n**Vendredi 30**\n10 h — Grand-messe en l'église paroissiale\n11 h — Bénédiction des jardins et des ruchers\n\n*Miel de Saint-Fiacre : médaille d'or, Paris 1929*\n*Le Maire, M. BLANC*"},{"id":"registre-cooperative","title":"Registre des apports de la coopérative (1928)","scene":"les-pistes","text":"**COOPÉRATIVE APICOLE DE VENTEBRUNE — Registre des apports, exercice 1928 (récapitulatif)**\n\nRuches déclarées par les sociétaires : **146**\n\n*Mois — Ruchers des sociétaires — Apport de l'Ermitage (kg)*\nJanvier — 0 — 900\nFévrier — 0 — 720\nMars — 0 — 720\nAvril — 40 — 900\nMai — 210 — 740\nJuin — 260 — 720\nJuillet — 310 — 920\nAoût — 120 — 730\nSeptembre — 0 — 900\nOctobre — 0 — 720\nNovembre — 0 — 720\nDécembre — 0 — 900\n\n**Totaux : ruchers 940 — Ermitage 9 590 — vendu 10 530 kg**\n\n*Apport de l'Ermitage : chaque dimanche. Signé « pour B. A. : F. A. »*"},{"id":"carnet-odile","title":"Le carnet d'Odile Fabre (extraits)","scene":"les-pistes","text":"*Octobre 1927.* Arrivée. On m'offre du miel à chaque porte. Je refuse : mon diabète. On me regarde avec une douceur qui me glace.\n\n*Décembre 1927.* Enterrement de la mère Faure. Pas une larme, pas une fleur. Son fils souriait au bord de la fosse.\n\n*Hiver.* On ne parle jamais de Baptistin Arnaud, le fondateur. Mme Blanc dit qu'il « garde l'ermitage » depuis l'hiver dernier. Personne ne l'a vu redescendre.\n\n*Tous les dimanches.* À la nuit, une file d'hommes monte à l'ermitage avec des bidons vides et redescend avant l'aube, chargée. Fernande Arnaud marche devant, avec ses clés.\n\n*30 août 1928, la nuit.* Le gâteau partagé à minuit. La peintre de Paris et le représentant de Lyon en ont repris. Le lendemain, ils avaient le même sourire que les autres.\n\n*Février 1929.* La grange Achard a brûlé. La fumée a couvert la place une heure. Ils se sont tous arrêtés, hébétés, comme des gens qu'on réveille. Augustine Blanc a crié le nom de sa fille, morte en 1919. Puis le vent a tourné, et ils ont souri de nouveau.\n\n*Mars 1929.* M. Merle est parti pour Nyons. Il est revenu à pied, en pleine nuit, en pleurant. Le matin, il souriait. Ceux qui s'éloignent reviennent toujours.\n\n*Avril 1929. Recopié aux archives de la mairie, registre de la paroisse :* « L'an 1721, le quatorze juillet, frère Hilarion, ermite de Saint-Fiacre, a été trouvé mort en sa cellule, assis et souriant, couvert de mouches à miel qui ne bruissaient point. Sept de nos paroissiens étaient auprès de lui et ne voulaient plus redescendre. Nous avons fait mettre le feu à l'ermitage avec la mère du miel. Ils ont pleuré trois jours, et deux des plus vieux en sont morts. »\n\n*Juin 1929.* Le maire annonce 212 habitants. Nous étions 164 en 1921. Partout ailleurs dans les Baronnies, les villages se vident.\n\n*Août 1929.* Les abeilles ne bourdonnent pas. Je ne l'ai compris qu'hier. Elles ne font aucun bruit.\n\nIls ne me font rien. Ils attendent. Je crois qu'ils pensent que je finirai par goûter."},{"id":"inscription-ermitage","title":"L'inscription du linteau","scene":"l-ermitage","text":"*Taillé dans la pierre au-dessus de la niche murée, à demi noyé dans la cire :*\n\n**MEL NE TANGAS · DVLCE OBLIVIVM EST · IGNIS SOLVS SOLVIT · MDCCXXI**"}],"knowledge":[{"need":"Lire les registres de la coopérative","best":"Comptabilité","backup":"Sciences naturelles ; sans jet, les apports de l'Ermitage en hiver"},{"need":"Comprendre les abeilles mortes","best":"Sciences (biologie), Sciences naturelles","backup":"Médecine ; le médecin du groupe"},{"need":"Gagner la confiance d'Odile","best":"Avoir refusé le miel (sans jet)","backup":"Charme, Psychologie, Persuasion"},{"need":"Lire l'inscription latine","best":"Langue (latin)","backup":"Histoire, Occultisme ; Odile la lit"},{"need":"Ouvrir la chapelle","best":"Le trousseau de Fernande ou la clé du garde champêtre","backup":"Serrurerie, FOR ; la petite fenêtre (Grimper)"},{"need":"Enfumer l'essaim","best":"Sciences naturelles (enfumoir de la miellerie)","backup":"Chance, avec un fagot de thym vert"},{"need":"Purger le miel avalé","best":"Médecine (ipéca, dans les six heures)","backup":"Premiers soins (eau salée)"},{"need":"Libérer Hélène ou Lucien","best":"Les emmener à plus de trois kilomètres (Conduite)","backup":"Détruire l'essaim"}],"trackers":[{"id":"minuit","label":"Heures avant le gâteau","max":4,"unit":"heures","help":"Commence à 20 h, à l'ouverture de la veillée. Avancez d'un cran par heure de jeu (environ toutes les 15 minutes réelles). À 4 : minuit, le gâteau est partagé.","addLabel":"+1 heure","fullMessage":"Minuit : Marius découvre le gâteau de Saint-Fiacre.","scenes":["la-veillee","l-ermitage"]},{"id":"villageois-montent","label":"Les villageois montent","max":6,"unit":"rounds","help":"Démarre quand le village sent l'intrusion : chaîne forcée, essaim attaqué, ou départ repéré de la veillée (à 2). À 6, ils sont à la porte de la chapelle. Sous la fumée, il n'avance plus.","fullMessage":"Les villageois emplissent la porte, lanternes à la main, sans un mot.","scenes":["l-ermitage"]}]}$story$::jsonb, now()
where not exists (select 1 from public.stories where visibility = 'marketplace' and content #>> '{meta,id}' = 'le-miel-de-saint-fiacre');

insert into public.stories (visibility, content, published_at)
select 'marketplace', $story${"format":"grimoire-story/1","meta":{"id":"le-puits-sainte-barbe","title":"Le Puits Sainte-Barbe","lang":"fr","summary":"Février 1931, dans le bassin minier du Pas-de-Calais. Après cinq jours au fond de la fosse 7, les sept mineurs qu'on croyait perdus sont remontés sans une égratignure, et toute la cité crie au miracle. La Compagnie veut rouvrir la fosse dès jeudi. Mais à l'enterrement du sauveteur mort pour eux, les sept disent les prières une demi-seconde après tout le monde, comme un écho.","players":{"min":4,"max":5},"playersText":"4 à 5 joueurs","duration":"3 à 4 heures","era":"Février 1931","setting":"Hennequelle-les-Mines, cité minière du Pas-de-Calais entre Lens et Béthune : les corons de la cité 7, la fosse n° 7 « Sainte-Barbe » de la Compagnie des Mines d'Hennequelle et ses galeries à 480 mètres sous terre","system":"d100","author":"Grimoire","license":"CC-BY-4.0","version":"1.1","tags":["groupe","mine","enquête","souterrain","années 1930"],"contentWarnings":["catastrophe minière","ensevelissement vivant","claustrophobie","mort d'un sauveteur (évoquée)","deuil","xénophobie de l'époque envers les ouvriers étrangers (évoquée)"]},"overview":{"secret":"Sous le bassin houiller, la grande faille dite « du Midi » a poussé jadis des roches bien plus vieilles que le charbon par-dessus les veines. Dans cette vieille roche dort un creux : une bulle de pierre vitreuse, noire et verte, close depuis avant les forêts du houiller. Ce qui vit là n'a pas de nom ; les anciens d'Hennequelle l'appelaient **le Répondant**. Il ne crée rien : il copie. D'abord ce qu'il entend (des coups, des voix), puis ce qu'il touche (un corps). En mars 1867, un éboulement à l'ancienne fosse du Marais l'a effleuré et lui a pris un abatteur, **Sébastien « Bastien » Coquelle** : un Bastien propre et calme est remonté au bout de trois jours, qui répétait la fin de chaque phrase qu'on lui disait. Les vieux mineurs ont muré la galerie ; le soir où le mur a été fini, le 18 avril, la copie s'est défaite en sable noir dans son lit. Derrière le mur, le vrai a frappé jusqu'au 2 mai.\n\nLe **mardi 10 février 1931 à 10 h 40**, à l'étage 480 de la fosse 7 « Sainte-Barbe », la taille de la veine Joséphine a crevé une poche de grisou venue du Creux ; la lampe fêlée du galibot Lucien Delattre l'a allumée. Le coup de grisou a effondré la bowette Nord sur soixante mètres et ouvert, au bout de la taille, une cassure qui descend dans le Creux. Les sept hommes de la taille ont survécu, parlé, prié, frappé pendant trois jours, trop loin pour être entendus. Le Répondant a écouté. Dans la nuit du vendredi 13 au samedi 14, le verre a coulé sur eux comme de la cire. La dernière chose qu'Augustin Lefebvre, le chef de taille, a dite aux autres pour les rassurer : « On est bien, à c't'heure. » Ils dorment debout dans la paroi, **vivants**, et ils rêvent ; dans leur rêve, Augustin frappe encore le code : sept coups, sept vivants.\n\nLe samedi 14 à **3 h 05**, le Répondant a répondu aux coups des sauveteurs en les répétant. À **17 h 50**, quand la dernière paroi a été percée, sept copies attendaient dans la taille, propres, calmes, avec sept lampes allumées copiées sur les vraies. Les vraies lampes sont restées sous les déblais, au fond de la taille. Les copies ne savent que ce que les sept savaient le matin du 10 et ce qu'elles ont entendu au fond. Elles n'apprennent rien de neuf, ne mangent pas, ne boivent pas, ne suent pas, ne dorment pas, n'ont plus les cicatrices bleues que le charbon laisse aux vieux mineurs ; leur peau est froide, leur pouls lent et égal ; elles répètent ce qu'elles entendent, avec n'importe quelle voix. Elles ne veulent qu'une chose : qu'on rouvre le quartier Nord, pour ramener des voix au Creux.\n\nPersonne n'a comploté. La Compagnie n'a péché que par hâte : poussé par la crise et par un télégramme du Conseil, le directeur **Raymond Thiéry** veut rouvrir le jeudi 19 à 6 h, et il a fait mettre dans un tiroir le relevé du géomètre Carpentier, qui montre un vide là où les plans disent « roche pleine ».\n\n**Si personne n'intervient** : le mercredi 18 à 22 h, les sept descendent avec l'équipe de nuit chargée de préparer la taille et l'emmènent voir « la belle chose ». À l'aube, douze hommes remontent, propres et calmes, en fredonnant tous la même note. Le jeudi, le poste du matin descend. Avant Pâques, on ne mange plus dans les corons de la cité 7.\n\n**Deux façons d'en finir.** Quand un homme est dégagé de la paroi, sa copie se défait en sable noir, où qu'elle soit. Quand le Creux est scellé (un mur, comme en 1867, ou un coup de grisou volontaire qui effondre la bowette), toutes les copies se défont d'un coup, et les vrais hommes restés dans le verre meurent avec lui. Le Répondant s'éveille au bruit : le silence le ralentit. On dégage un homme en lui murmurant, contre le verre, un souvenir que seul le vrai possède ; ou au pic, bruyamment.","steps":["[[enterrement]] (lundi 16, 10 h) : l'enterrement du sauveteur Gaston Pruvost. Les sept répondent aux prières un temps après tout le monde, comme un écho, et Augustin demande pourquoi Gaston n'est pas venu. L'avis de réouverture.","[[les-corons]] (lundi et mardi) : les femmes des sept, la cicatrice disparue, le pain qu'on ne mange pas, le rêve des sept coups ; la vieille Victorine et l'histoire de Bastien Coquelle.","[[le-dispensaire]] : le registre de samedi soir, l'examen d'un des sept, le sang qui tourne en sable.","[[le-carreau]] : quatorze lampes pour sept hommes, le journal de sauvetage, le canari mort, les coups entendus la nuit au 480.","[[les-bureaux]] : Thiéry, le télégramme du Conseil, le relevé caché de Carpentier, le registre des accidents de 1867.","[[maison-du-peuple]] (mardi 17, 19 h) : le vote de la reprise ; une copie parle avec la voix d'un investigateur ; les sept annoncent qu'ils descendront mercredi soir.","[[la-descente]] (mercredi 18, 22 h) : la bowette Nord, la cassure, le Creux. Libérer les sept, sceller tout au grisou, ou les deux.","[[le-jeudi]] (jeudi 19, 6 h) : la sirène, la foule au carreau, et ce que chaque chemin a coûté."],"mustNotMiss":["**Les sept ne sont pas eux-mêmes** : la cicatrice bleue disparue et le pain jamais mangé (Germaine, [[les-corons]], sans jet), les répons en écho et la question sur Gaston ([[enterrement]]), le registre du dispensaire ([[le-dispensaire]], sans jet), les quatorze lampes ([[le-carreau]]), la voix volée ([[maison-du-peuple]]).","**Quelque chose en bas répète ce qu'il entend** : le journal de sauvetage et ses coups qui rendent exactement les coups ([[le-carreau]], sans jet), l'histoire de Bastien Coquelle ([[les-corons]]), le registre de 1867 ([[les-bureaux]]), la copie qui parle avec la voix d'un investigateur ([[maison-du-peuple]]).","**Les vrais sont vivants en bas** : les coups de sept entendus la nuit au 480 ([[le-carreau]], [[maison-du-peuple]]), le rêve des femmes ([[les-corons]], sans jet), les vraies lampes écrasées restées au fond de la taille ([[le-carreau]]), les coups derrière le mur de 1867 ([[les-bureaux]], [[les-corons]]).","**Où** : sous la taille, dans la vieille roche de la faille du Midi, là où les plans disent roche pleine. Le relevé de Carpentier ([[les-bureaux]]), la poussière de verre sous les ongles et sur le canari ([[le-dispensaire]], [[le-carreau]]), les coups qui venaient « d'en dessous » dans le journal de sauvetage.","**Comment en finir** : murer le Creux défait les copies (Victorine, [[les-corons]] ; registres de 1867, [[les-bureaux]] et [[enterrement]]). Dégager un homme défait la sienne : on le découvre au fond ([[la-descente]])."],"branches":["Convaincre Thiéry ([[les-bureaux]]) : il renvoie l'équipe de nuit, donne aux investigateurs le passage de la cage et la clé du coffre du boutefeu, et descend avec eux. Les sept descendent quand même, seuls, par les échelles du puits d'aérage (ils arrivent au 480 vers minuit).","Le vote de la Maison du Peuple ([[maison-du-peuple]]) : grève de sécurité votée, l'équipe de nuit ne compte que 4 hommes (et Thiéry, pour montrer l'exemple) ; reprise votée, elle en compte 12.","Au fond, dégager les sept un par un (au murmure ou au pic) ou sceller le Creux au grisou. On peut faire les deux : en dégager autant que possible, puis tout sceller.","Achille Delattre, s'il descend, aide à dégager son fils et se bat contre ceux qui veulent tout sceller tant que Lucien est dans le verre.","Fuir sans rien faire : le jeudi, le poste du matin descend ([[le-jeudi]])."],"ifStuck":["Germaine Lefebvre frappe à la porte d'un investigateur, le soir : « Ch'est pas min Augustin. Il a pus s'cicatrice. »","Le porion Wattebled, ivre de fatigue, demande qu'on lise son journal : « Il m'a rendu mes coups. Exactement mes coups. »","Victorine Dhainaut demande au curé une messe pour Bastien Coquelle, « mort en 1867, et qui va remonter ».","Le géomètre Carpentier, terrifié, glisse son relevé sous la porte de l'ingénieur ou du journaliste dans la nuit de mardi.","À 3 h 05, les sept sortent sous la pluie et restent debout dans la rue, face au chevalement."],"keeperTips":["Les sept ne menacent personne avant le fond. Ils sont calmes, polis, et ils répètent : la fin de vos phrases, un temps trop tard, parfois avec la voix ou les mots d'un autre. L'horreur vient de ce qu'ils ne font pas : manger, transpirer, pleurer Gaston.","Avec 4 ou 5 joueurs, laissez le groupe se séparer en acte II : les familles, le dispensaire, le carreau et les bureaux se jouent dans n'importe quel ordre. Réunissez tout le monde à la Maison du Peuple.","La Compagnie n'est pas méchante : Thiéry a peur des licenciements et de s'être trompé. Les familles veulent croire au miracle. Ce sont eux, les obstacles.","Notez les phrases que disent les investigateurs devant les sept : à la Maison du Peuple, une copie en répète une, mot pour mot, avec leur voix.","Au fond, faites respecter le silence. Chaque mot dit à voix haute fait monter le Réveil du Creux : les joueurs finiront par chuchoter autour de la table.","Mots de la mine : la fosse (le puits et ses bâtiments), le chevalement (la tour du puits), la cage (l'ascenseur), la recette (le palier d'un étage), la bowette (galerie dans la roche), la taille (le front de charbon, basse), le toit et le mur (plafond et sol de la veine), le porion (contremaître), le galibot (jeune mineur), le grisou (gaz explosif)."]},"acts":[{"id":"le-miracle","title":"Le miracle","scenes":[{"id":"enterrement","title":"L'enterrement du sauveteur","lead":"Lundi 16 février, 10 h : la cité enterre Gaston Pruvost, mort pour les sept. Les sept sont là, et ils disent les prières un temps après tout le monde.","screen":{"place":"church","preset":"fog","time":"day"},"readAloud":["Le glas sonne sur la cité 7. Au bout des rangées de corons en brique, le chevalement de la fosse Sainte-Barbe se dresse dans le brouillard, et ses molettes ne tournent pas. Devant l'église, la foule en noir piétine la boue : des mineurs endimanchés, des femmes en châle, des enfants qu'on fait taire.","Le cercueil passe sur les épaules de six sauveteurs en casque de cuir. Derrière la famille, un peu à l'écart, sept hommes se tiennent côte à côte, rasés de près, les mains propres. On leur serre l'épaule, on les touche comme on touche une relique. « Ça fait du bien de vous revoir », dit une femme. « De vous revoir », répond l'un d'eux, doucement, un temps après."],"flow":[{"title":"Qui est là, et pourquoi","text":"Lire le bloc **Accroches** : chaque investigateur a sa raison d'être à l'enterrement. Les présenter les uns aux autres sur le parvis, avant la messe. Le journaliste est arrivé de Lille par le premier train.","extra":"Donnez à chacun le petit article du dimanche → {{handout:article-vigie}}. Il pose les dates officielles."},{"title":"La messe","text":"Messe de requiem. Les sept sont au troisième rang. Ils disent les répons avec la foule.","roll":{"type":"skill","options":["listen","spot-hidden"]},"success":"Les sept disent chaque répons un souffle après tout le monde, mot pour mot, avec les mêmes hésitations que leurs voisins. Comme un écho. Aucun ne fait le signe de croix avant que l'homme devant lui ne le fasse.","failure":"Sept hommes recueillis, un peu raides.","extra":"Le curé (joueur ou {{npc:abbe-delcourt}}) le remarque sans jet : c'était déjà pareil dimanche, au Te Deum d'action de grâces."},{"title":"Germaine","text":"{{npc:germaine-lefebvre}} enterre son frère. Son mari Augustin se tient à côté d'elle, tranquille, et fredonne tout bas une note, toujours la même.","roll":{"type":"skill","options":["psychology"]},"success":"Elle ne pleure pas seulement son frère : elle a peur de l'homme à côté d'elle. Elle ne le touche pas, et elle se décale quand il se rapproche.","failure":"Une sœur brisée de chagrin, soutenue par un mari miraculé."},{"title":"Parler aux sept","text":"Sur le parvis, à la sortie. Ils répondent tous la même chose : « On est bien, à c't'heure. » Et : « Faut rouvrir. Faut redescendre. » Sur les cinq jours : « On a attendu. On savait que vous viendriez. » Au cimetière, devant la fosse ouverte, Augustin se penche vers Germaine : « Gaston, il est pas venu ? »","roll":{"type":"skill","options":["psychology"]},"success":"Ils ne mentent pas : ils ne savent pas. Ils parlent comme si on était encore le mardi 10 au matin. Germaine lui a pourtant annoncé la mort de Gaston samedi soir.","failure":"Des hommes encore sous le choc, qui n'ont pas tout compris.","extra":"Si quelqu'un les photographie ou les interroge longuement, ils se taisent et regardent le chevalement."},{"title":"L'avis de la Compagnie","text":"À la sortie du cimetière, un employé colle une affiche sur la grille du carreau, et une autre à la porte de l'église → {{handout:avis-reouverture}}. {{npc:raymond-thiery}} serre des mains. À l'ingénieur, à voix basse : « Je compte sur votre signature mercredi soir. »"},{"title":"La vieille Victorine","text":"À la grille du cimetière, {{npc:rosalie-dhainaut}}, quatre-vingts ans, regarde passer les sept et marmonne en patois : « I z'ont pus leus bleus. » (Ils n'ont plus leurs bleus : les cicatrices bleues que le charbon laisse dans les blessures des mineurs.) Elle se signe et s'en va.","extra":"Germaine l'entend, et pâlit. Victorine habite au bout de la rue des Galibots → [[les-corons]].","goto":["les-corons"]},{"title":"Le registre de 1867","text":"Pour le curé, ou si on le lui demande : le presbytère garde les vieux registres de l'ancienne paroisse Saint-Vaast. Victorine a demandé ce matin une messe pour un certain Bastien Coquelle, « mort en 1867, et qui va remonter ».","roll":{"type":"skill","options":["library-use","history"]},"success":"L'acte de sépulture de 1867, en une heure → {{handout:registre-paroissial}}.","failure":"Les registres sont rangés n'importe comment : il faut tout l'après-midi, mais on le trouve → {{handout:registre-paroissial}}."}],"notes":[{"title":"Accroches","items":["**L'ingénieur de la Compagnie** : Thiéry lui demande de signer, mercredi soir au plus tard, le procès-verbal de remise en état du quartier Nord. Le géomètre Carpentier, qui a fait le relevé, évite son regard depuis dimanche.","**Le délégué mineur** : élu par les ouvriers, il a le droit de visiter les travaux du fond. Le syndicat veut une enquête avant la reprise. Ce matin, Germaine Lefebvre l'a arrêté dans la rue et lui a dit tout bas : « Ch'est pas min Augustin. »","**Le médecin** : il doit délivrer aux sept, avant jeudi, le certificat d'aptitude au travail. Sœur Marie-Clotilde lui a laissé un mot : « Docteur, venez voir le registre de samedi soir. »","**Le journaliste de Lille** : *La Vigie du Nord* l'envoie écrire « le miracle de la fosse 7 », avec les familles, des photographies, des larmes. Son rédacteur veut trois colonnes pour jeudi.","**Le curé de la paroisse Sainte-Barbe** : il célèbre l'enterrement. Dimanche, au Te Deum, il a entendu les sept répondre aux prières avec un temps de retard. Et la vieille Victorine lui a demandé une messe pour un mort de 1867. (Si aucun joueur n'est curé, {{npc:abbe-delcourt}} tient ce rôle.)"]},{"title":"Ce que tout le monde sait","items":["Mardi 10, 10 h 40 : coup de grisou dans la taille Joséphine, à 480 mètres. Sept hommes emmurés derrière soixante mètres de bowette effondrée.","Jeudi 12, 15 h 10 : le sauveteur Gaston Pruvost, 34 ans, frère de Germaine Lefebvre, est tué par une chute de toit au front d'éboulement.","Samedi 14, 3 h du matin : les sauveteurs entendent répondre à leurs coups. 17 h 50 : ils percent. 19 h 30 : les sept remontent au jour, sans une égratignure, devant deux mille personnes.","Dimanche 15 : Te Deum à l'église Sainte-Barbe, les sept au premier rang. On a attendu leur retour pour enterrer Gaston.","Lundi 16 : la Compagnie annonce la reprise du quartier Nord pour jeudi, 6 h."]},{"title":"Les sept","items":["**Augustin Lefebvre**, 46 ans, chef de taille. Femme : Germaine.","**Jules Caron**, 38 ans, abatteur, accordéoniste. Femme : Irma.","**Stanisław « Stach » Wiśniewski**, 31 ans, abatteur polonais venu de Westphalie en 1923. Femme : Helena, deux enfants.","**Léon Dubois**, 52 ans, boiseur, veuf, vit chez sa fille Simone.","**Henri Lemaire**, 24 ans, herscheur, fiancé à Odette Brunin.","**Fernand Vasseur**, 29 ans, haveur, cornet à l'Harmonie des Mines. Mère : Eugénie.","**Lucien Delattre**, 15 ans, galibot. Père : Achille, le lampiste."]}],"npcs":["abbe-delcourt","germaine-lefebvre","les-sept","raymond-thiery","rosalie-dhainaut"],"handouts":["article-vigie","avis-reouverture","registre-paroissial"],"ambience":["wind","crowd-indoor","crows"],"sfx":["footsteps","door-open"],"next":["les-corons","le-dispensaire","le-carreau","les-bureaux"]}]},{"id":"ceux-d-en-haut","title":"Ceux qui sont remontés","scenes":[{"id":"les-corons","title":"Les corons de la cité 7","lead":"Les familles des sept : ce qu'elles voient à table, au lit, la nuit. Et la mémoire de la vieille Victorine.","screen":{"place":"street","preset":"rain","time":"dusk"},"readAloud":["Les corons s'alignent au cordeau : brique noircie, une porte, une fenêtre, une porte, une fenêtre. Au fond de chaque jardin, le cabinet, le clapier, le pigeonnier. La pluie fine sent le charbon et la soupe aux poireaux.","Devant les maisons des sept, on a posé des fleurs en papier et de petits drapeaux. Les rideaux sont tirés. Derrière l'un d'eux, une silhouette d'homme se tient debout, immobile, tournée vers le chevalement."],"flow":[{"title":"Chez les Lefebvre","text":"{{npc:germaine-lefebvre}} reçoit dans sa cuisine, la porte de la pièce d'à côté fermée. Augustin est au jardin.","roll":{"type":"skill","options":["psychology","persuade","charm"]},"success":"Elle dit tout : la cicatrice bleue qu'il avait au front depuis l'éboulement de 1912 a disparu. Il s'assoit à table, coupe son pain, ne le mange pas, pose le couteau toujours au même endroit. Il ne dort pas : il reste assis sur le lit, les yeux ouverts. Il ne sent rien, « même pas lui ». Samedi soir, elle lui a appris la mort de Gaston ; dimanche, il a demandé de ses nouvelles.","failure":"« Ch'est un miracle. Que Dieu soit loué. » Elle referme la porte. Le soir, elle vient d'elle-même frapper chez le délégué ou au presbytère, et dit l'essentiel : la cicatrice, le pain.","pushed":"Elle craque et hurle dans la rue : « Ch'est pas li ! » Les voisins accourent. Augustin sort, calme : « Germaine, rentre. » Les voisins lui donnent raison. Jusqu'à la Maison du Peuple, les jets de relation dans la cité se font avec un dé de malus."},{"title":"Augustin au jardin","text":"Il se tient devant son pigeonnier, les bras le long du corps. Les pigeons s'affolent et ne rentrent pas tant qu'il est là. Il dit : « On est bien, à c't'heure. »","roll":{"type":"skill","options":["spot-hidden","natural-world"]},"success":"Pas de cicatrice au front. Des mains douces, sans un cal, sur des bras de mineur. Sous les ongles, une poussière noire qui brille comme du verre pilé. Les pigeons se comportent comme devant un chat.","failure":"Un homme fatigué qui regarde ses pigeons."},{"title":"Chez les Wiśniewski","text":"{{npc:helena-wisniewska}} s'est réfugiée chez sa voisine avec ses deux enfants. Elle parle polonais et un peu de français. Dimanche, elle est allée dire à la gendarmerie que « ce n'est pas lui » ; on lui a ri au nez et rappelé qu'on renvoie en Pologne les étrangers qui font des histoires.","roll":{"type":"skill","options":["language-other:polish","charm","psychology"]},"success":"Stach ne mange pas. La nuit, assis dans le noir, il récite le Notre Père en polonais, toujours les mêmes mots, sans s'arrêter : la prière qu'il a dû dire au fond. Le jour, il ne dit que « ça va, ça va ». Il ne dit plus son prénom à elle. Les enfants ont peur de lui.","failure":"« Dobrze, dobrze. Ça va. » Elle serre ses enfants et ferme la porte. Sans polonais, ce jet se fait avec un dé de malus."},{"title":"Le rêve","text":"Pas de jet. Si l'on demande aux familles comment elles dorment : depuis samedi, Germaine et Odette Brunin (la fiancée d'Henri) font le même rêve. « Il m'appelle, dans le noir. Il dit qu'il a froid. Il toque. » Germaine : « Sept coups. Ch'est l'code des sauveteurs : sept vivants. »","extra":"Premier indice que les vrais sont vivants, quelque part en bas."},{"title":"Mémé Victorine","text":"{{npc:rosalie-dhainaut}}, ancienne trieuse, vit seule au bout de la rue des Galibots. Elle parle à qui lui apporte une bistouille (un café arrosé de genièvre), ou à qui sait la prendre.","roll":{"type":"skill","options":["charm","persuade","history"]},"success":"Elle raconte l'histoire de Bastien Coquelle (voir **L'histoire de Victorine**), et finit par sa règle : « Quand la roche te répond, tais-toi. Et bouche le trou. »","failure":"Elle ne donne que sa règle, « Quand la roche te répond, tais-toi », et ajoute : « Allez voir l'curé, il a l'registre. »","pushed":"Elle raconte tout, mais le soir même toute la cité dit que les messieurs font peur aux vieilles avec des histoires de revenants : dé de malus pour convaincre à la [[maison-du-peuple]]."},{"title":"Les souvenirs","text":"Pas de jet. En parlant aux familles (le journaliste, qui les interviewe pour son article, le curé, qui les connaît), on apprend sur chacun des sept un souvenir intime : voir **Les sept et leurs proches**. Noter ceux que les joueurs recueillent.","extra":"Ils serviront au fond : on dégage un homme en lui murmurant un souvenir que seul le vrai possède ([[la-descente]])."},{"title":"3 h 05","text":"La nuit de lundi ou de mardi, si quelqu'un veille dans la cité : à 3 h 05, les sept portes s'ouvrent. Les sept sortent sous la pluie, en chemise, et restent debout au milieu de la rue, face au chevalement, sans bouger, pendant un quart d'heure. Puis ils rentrent. Si on leur parle, ils répètent les derniers mots qu'on leur a dits.","roll":{"type":"san","label":"Les sept dans la rue","san":"0/1D3"},"extra":"3 h 05 : l'heure où, samedi, la roche a répondu aux sauveteurs."}],"notes":[{"title":"Les sept et leurs proches (souvenirs pour le fond)","items":["**Augustin Lefebvre** (Germaine) : cicatrice bleue au front, éboulement de 1912. Sa pigeonne championne, *la Bleue*, rentrée seule d'Orléans en 1929. Germaine : « Ta Bleue est rentrée. Elle t'attend. »","**Stach Wiśniewski** (Helena) : elle l'appelle *Stasiu*. Elle chante aux enfants une berceuse de Noël polonaise, et il la sifflait en partant au poste.","**Lucien Delattre** (Achille) : il soigne *Bijou*, le cheval du fond. Son père l'appelle « min p'tit quinquet ».","**Jules Caron** (Irma) : la valse qu'il a composée pour leur noce et qu'il appelle « Irma des corons ».","**Léon Dubois** (Simone) : en 1928, il a abattu l'oiseau au tir à l'arc de Sainte-Barbe. Simone : « Papa, t'es toujours le roi. »","**Henri Lemaire** (Odette) : le mariage est fixé au samedi 11 avril. Odette : « La robe est finie. »","**Fernand Vasseur** (Eugénie) : il joue le solo de cornet de la marche de la Sainte-Barbe, chaque 4 décembre. Il avait répétition le mardi 10 au soir."]},{"title":"Ce que racontent les familles (sans jet)","items":["Aucun des sept ne mange ni ne boit. Ils s'assoient à table et regardent leur assiette.","Ils portent encore les vêtements de samedi, impeccables. Ils ne se lavent pas, et n'en ont pas besoin.","Les chiens aboient sur leur passage ; les chats quittent la pièce.","Ils fredonnent, sans s'en rendre compte, tous la même note basse. Assis, ils tapotent la table du doigt : sept coups, un temps, sept coups.","Ils ne vont pas à l'estaminet. Ils vont tous les jours à la grille du carreau, et demandent quand on redescend.","Ils parlent du mardi 10 comme d'aujourd'hui : Fernand se prépare pour la répétition de l'Harmonie, Henri demande si la paye est arrivée."]},{"title":"L'histoire de Victorine","items":["« J'avais dix-sept ans, j'étais trieuse à l'ancienne fosse du Marais. En mars 67, un éboulement a enfermé Bastien Coquelle au 210, la galerie du Midi. Trois jours. On l'a retrouvé debout, propre comme un sou neuf, qui répétait la fin de tout ce qu'on lui disait. »","« Sa femme a dit : ch'est pas li. Il mangeait pas. Il avait pus ses bleus. Et derrière l'éboulement, on entendait toquer. »","« Les anciens, mon père avec, sont allés trouver l'ingénieur. On a muré la galerie. Pendant un mois, on les entendait toquer derrière, pendant qu'on montait le mur. »","« Le soir où le mur a été fini, le Bastien d'en haut s'est défait dans son lit. Comme du sable noir. Et au cimetière, on a enterré un cercueil de sable. »","« Quand la roche te répond, tais-toi. Et bouche le trou. »"]}],"npcs":["germaine-lefebvre","helena-wisniewska","rosalie-dhainaut","les-sept"],"ambience":["rain","street"],"sfx":["dog-bark","door-creak","knocking"],"next":["le-dispensaire","le-carreau","les-bureaux","maison-du-peuple"]},{"id":"le-dispensaire","title":"Le dispensaire de la Compagnie","lead":"Le registre de samedi soir et l'examen d'un des sept : peau froide, pouls lent et égal, et un sang qui tourne en sable.","screen":{"place":"asylum","preset":"bulb","time":"day"},"readAloud":["Le dispensaire sent l'éther et le savon noir. Une ampoule nue grésille au-dessus de la table d'examen. Au mur, une affiche : « Mineur, ta lampe est ta vie », et un squelette aux os numérotés.","Une religieuse en cornette range des bandes sans lever les yeux. « Vous venez pour les sept, dit-elle. Tout le monde vient pour les sept. »"],"flow":[{"title":"Sœur Marie-Clotilde","text":"{{npc:soeur-marie-clotilde}} a examiné les sept samedi à 20 h. Elle montre son registre au médecin sans jet → {{handout:registre-dispensaire}}. À un autre investigateur, il faut la convaincre.","roll":{"type":"skill","options":["persuade","credit-rating","charm"]},"success":"Elle ouvre le registre. « Ils n'ont rien voulu boire. Après cinq jours au fond. J'ai cru à un choc. Sept fois le même pouls, docteur. Sept fois. »","failure":"« Le registre est pour le docteur. » Elle le lui montrera s'il vient, ou si le curé le lui demande."},{"title":"Faire venir un des sept","text":"Le médecin peut convoquer les sept pour leur certificat d'aptitude. Lucien vient avec son père {{npc:achille-delattre}} ; les autres viennent seuls, à l'heure exacte. Ils se déshabillent sans gêne et attendent, debout."},{"title":"L'examen","roll":{"type":"skill","options":["medicine","first-aid"]},"success":"Peau froide, 34 °C au thermomètre. Pouls à 40, parfaitement régulier, qui ne bouge pas même après dix montées d'escalier. Pas une goutte de sueur. Pupilles lentes à la lampe. Pas une cicatrice, pas un cal : une peau d'enfant sur un corps de mineur. Au stéthoscope, sous le cœur, un bruit fin, comme du sable qui coule.","failure":"Un homme en bonne santé, un peu froid. Quelque chose cloche, sans qu'on sache dire quoi.","extra":"Avec Premiers soins, le jet se fait avec un dé de malus."},{"title":"La prise de sang","text":"Pas de jet si on la fait. Le sang est sombre, épais, et vient lentement. Dans le tube, en une heure, il se sépare : au fond, un sable noir qui brille ; au-dessus, un liquide clair comme de l'eau.","roll":{"type":"san","label":"Le tube de sang","san":"0/1D4"},"extra":"Le tube est une preuve qu'on peut montrer à Thiéry ou à la Maison du Peuple."},{"title":"Les ongles","text":"La poussière noire sous les ongles ne part pas au savon.","roll":{"type":"skill","options":["science:geology","science:chemistry","spot-hidden"]},"success":"Ni charbon ni schiste : du verre naturel, noir et vert, comme celui des volcans. Il n'y en a nulle part dans le bassin. La même poussière que sur le canari du poste de secours ([[le-carreau]]).","failure":"Une poussière noire, brillante. Pas tout à fait du charbon."},{"title":"Ce que dit la copie","text":"Elle répond à tout : « On est bien, à c't'heure. » Et : « Quand c'est qu'on redescend, docteur ? »","roll":{"type":"skill","options":["psychology"]},"success":"Ni peur, ni douleur, ni envie. Il attend. Le seul mot qui le fasse bouger, c'est « fond » : il tourne la tête vers celui qui l'a dit, tout de suite.","failure":"Un homme calme, très calme."},{"title":"Le certificat","text":"Le médecin signe ou refuse. S'il refuse, Thiéry fait venir mercredi un médecin de Lens qui signe sans examiner ; mais le refus est un argument de poids à la [[maison-du-peuple]] (dé de bonus pour convaincre)."}],"notes":[{"title":"Ce que sait la sœur","items":["Samedi soir, ils ont refusé l'eau et le bouillon. Dimanche, elle leur a porté de la soupe à domicile : on la lui a rendue intacte.","Ils sont arrivés propres. Ils n'ont pas eu besoin des bains-douches.","Lucien lui a demandé : « Ma sœur, quand c'est qu'on redescend ? » C'était la seule question de la soirée."]}],"npcs":["soeur-marie-clotilde","les-sept","achille-delattre"],"handouts":["registre-dispensaire"],"ambience":["clock"],"sfx":["door-open","footsteps"],"next":["le-carreau","les-bureaux","maison-du-peuple"]},{"id":"le-carreau","title":"Le carreau de la fosse 7","lead":"La lampisterie et le poste de secours : quatorze lampes pour sept hommes, un journal de sauvetage, un canari mort, des coups la nuit.","screen":{"place":"mine","preset":"fog","time":"day"},"readAloud":["Le carreau de la fosse 7 est une ville de brique et de fer : le chevalement, la machine d'extraction, les bains-douches, le grand terril qui fume dans le brouillard. Tout est à l'arrêt. On n'entend que les pompes, qui tournent jour et nuit pour que le fond ne se noie pas.","À la lampisterie, des centaines de lampes de sûreté pendent en rangs, chacune sous son numéro. Sur l'établi, quatorze lampes sont alignées à part. Sept sont écrasées, noires de charbon. Sept brillent comme au premier jour."],"flow":[{"title":"Achille Delattre","text":"{{npc:achille-delattre}}, le lampiste, père de Lucien. C'est lui qui a aligné les lampes. Il voudrait parler et il a peur de ce qu'il dirait.","roll":{"type":"skill","options":["psychology","charm","persuade"]},"success":"« Les sept écrasées, l'équipe de déblaiement les a remontées lundi matin, du fond de la taille, sous les débris. Ce sont les leurs : 211 à 217. Les sept autres, ils les tenaient à la main en sortant samedi. Mêmes numéros. Allumées. Après cinq jours. Une lampe de sûreté, ça brûle douze heures. » Il montre son cahier → {{handout:cahier-lampisterie}}.","failure":"« Une erreur de comptage. » Il range les lampes dans une caisse. Son cahier reste sur le comptoir : on peut le lire (Comptabilité ou Trouver Objet Caché pour remarquer les numéros en double) → {{handout:cahier-lampisterie}}."},{"title":"Les lampes de samedi","text":"Pas de jet pour constater qu'elles ne s'ouvrent pas. Elles se sont éteintes dimanche matin, toutes à la même heure, sans fumer.","roll":{"type":"skill","options":["mechanical-repair","spot-hidden"]},"success":"Ni vis, ni joint, ni rivet de plomb de la lampisterie : le verre et le laiton ne font qu'un seul bloc. Le réservoir est plein, mais plein de la même matière que le reste. Elles sont trop lourdes. Ce sont des lampes vues de l'extérieur.","failure":"Des lampes neuves, bizarrement lourdes.","pushed":"On en casse une à la masse : elle se brise comme une bouteille, noire et verte à l'intérieur, sans mèche ni réservoir. Achille pâlit et chasse tout le monde (SAN 0/1)."},{"title":"Le porion Wattebled","text":"Au poste de secours, {{npc:desire-wattebled}}, chef de l'équipe de sauvetage, n'a pas dormi depuis une semaine. Pas de jet : il veut qu'on lise son journal → {{handout:journal-sauvetage}}. « J'ai frappé trois coups, il m'a rendu trois coups. J'ai frappé deux, il m'a rendu deux. Personne répond au deux. J'ai crié : vous êtes sept ? Et il m'a rendu sept. J'aurais dû comprendre. »","extra":"Il ne dit pas « ils » : il dit « il »."},{"title":"Le canari","text":"Fifine, le canari de l'équipe, est morte à la percée. Wattebled la garde dans une boîte d'allumettes, il n'a pas pu la jeter. À la lampe, il n'y avait pas de grisou.","roll":{"type":"skill","options":["natural-world","medicine","science:geology"]},"success":"Aucun signe d'asphyxie. Ses plumes sont couvertes d'une poussière noire et brillante, qui n'est pas du charbon : du verre, la même que sous les ongles des sept.","failure":"Un petit oiseau mort, raide, et une poussière noire dans les plumes."},{"title":"La cassure","text":"Wattebled raconte le fond de la taille : une fente dans le mur (le sol de la veine), un air tiède qui monte, une odeur de pierre mouillée. « Les coups venaient de là. D'en dessous. » Dimanche, Thiéry l'a fait couvrir de planches. → [[les-bureaux]]"},{"title":"Les coups de la nuit","text":"Pas de jet. Wattebled, ou le jeune sauveteur Florent Lagache s'il est là : la nuit de dimanche à lundi, puis la suivante, l'équipe des pompes a entendu frapper au 480, derrière le barrage de la bowette Nord. « Sept coups. Un temps. Sept coups. Ça répondait à rien. Ça appelait. »","extra":"Les vrais sont vivants : Augustin frappe le code dans son rêve."},{"title":"Descendre au 480 avec les pompes","text":"Facultatif, une nuit : l'équipe des pompes descend à 23 h. Le délégué y a droit, l'ingénieur aussi ; les autres avec l'accord de Wattebled. À la recette, puis devant le barrage de planches de la bowette Nord.","roll":{"type":"skill","options":["listen"]},"success":"Sept coups faibles, irréguliers, qui ne répondent à rien. Si l'on frappe à son tour, une autre série répond aussitôt, nette, exacte, par en dessous, pendant que les sept coups faibles continuent plus loin, comme si de rien n'était.","failure":"Le silence, les pompes, l'eau qui goutte. Puis sept coups, une seule fois, très loin.","extra":"Près du barrage, la flamme des lampes de sûreté porte une petite auréole bleue : du grisou suinte de la taille. L'ingénieur et le délégué le savent sans jet."},{"title":"Les coups d'en bas","text":"Seulement si l'on a entendu les deux séries de coups au 480.","roll":{"type":"san","label":"Deux séries de coups","san":"0/1D3"},"goto":["les-bureaux","maison-du-peuple"]}],"notes":[{"title":"Le code de frappe des sauveteurs","items":["3 coups : « Y a-t-il quelqu'un ? »","Réponse : autant de coups que d'hommes vivants.","2 coups : « Compris, on arrive. » On n'y répond pas."]},{"title":"La lampisterie","items":["Chaque mineur prend sa lampe à son numéro en descendant et la rend en remontant : c'est ainsi qu'on sait qui est au fond.","Les lampes sont fermées par un rivet de plomb de la lampisterie : un mineur ne peut pas les ouvrir au fond, où une flamme nue ferait exploser le grisou.","Les sept lampes de samedi n'ont pas de rivet : elles n'ont jamais été ouvertes, parce qu'elles ne s'ouvrent pas."]}],"npcs":["achille-delattre","desire-wattebled"],"handouts":["cahier-lampisterie","journal-sauvetage"],"ambience":["wind","crows"],"sfx":["latch","knocking","footsteps"],"next":["les-bureaux","maison-du-peuple"]},{"id":"les-bureaux","title":"Les Grands Bureaux","lead":"Thiéry et le télégramme de Lille, le relevé caché du géomètre, et un registre des accidents de 1867.","screen":{"place":"library","preset":"rain","time":"dusk"},"readAloud":["Les Grands Bureaux de la Compagnie des Mines d'Hennequelle ressemblent à un château de brique : un perron, une horloge, des grilles dorées. Dans le hall, le portrait du fondateur et, sous verre, la lampe du premier mineur de la Compagnie.","Au premier étage, la salle des plans : de longues tables, des tiroirs plats, des rouleaux de toile qui sentent l'encre et la poussière. Par la fenêtre, le chevalement de la fosse 7, immobile sous la pluie."],"flow":[{"title":"Raymond Thiéry","text":"{{npc:raymond-thiery}} reçoit, courtois et épuisé. La crise, le charbon anglais et allemand moins cher, le Conseil à Lille, deux cents emplois. Le quartier Nord est le meilleur charbon de la fosse. « Et ce sont les sept eux-mêmes qui demandent à redescendre. »","roll":{"type":"skill","options":["psychology"]},"success":"Il y croit à moitié. Il a peur de s'être trompé, et plus encore d'avoir à le dire. Il n'est jamais descendu voir la cassure lui-même.","failure":"Un directeur sûr de lui, pressé."},{"title":"La salle des plans","text":"L'ingénieur y entre de droit. Les autres doivent obtenir l'accord de Thiéry.","roll":{"type":"skill","options":["persuade","credit-rating","law"]},"success":"Thiéry les y fait conduire.","failure":"« Voyez cela avec M. l'ingénieur. » Si l'ingénieur est des leurs, il les fait entrer le soir, après le départ des employés."},{"title":"Le plan de la veine Joséphine","text":"Pas de jet pour le lire. Au-delà du fond de la taille, la feuille porte : « massif calcaire, terrains du Midi : roche pleine ».","roll":{"type":"skill","options":["science:geology","navigate"]},"success":"Le long de la faille du Midi, des roches bien plus anciennes que le charbon ont été poussées par-dessus les veines. Personne n'a jamais creusé de ce côté-là, à part une fois : l'ancienne fosse du Marais, fermée en 1884, avait une galerie « du Midi » au 210.","failure":"Roche pleine au-delà de la taille. Rien à signaler, en principe."},{"title":"Émile Carpentier","text":"{{npc:emile-carpentier}}, le géomètre, dessine au fond de la salle et ne lève pas la tête. Il a fait le relevé dimanche ; Thiéry lui a dit de le mettre dans un tiroir.","roll":{"type":"skill","options":["persuade","psychology","intimidate"]},"success":"Il ouvre son tiroir → {{handout:releve-carpentier}}. « J'ai collé l'oreille à la fente. Ça frappait par sept. Et les sept étaient là-haut, dans la cour, à me regarder. »","failure":"Il nie. Dans la nuit, terrifié, il glisse le relevé sous la porte de l'ingénieur ou du journaliste → {{handout:releve-carpentier}}.","extra":"Si l'ingénieur lui donne l'ordre de le montrer, pas de jet."},{"title":"Les archives","text":"Au sous-sol, les registres des accidents depuis 1852, si on sait où chercher (Victorine a donné la date, le plan a donné la fosse du Marais).","roll":{"type":"skill","options":["library-use"]},"success":"En une heure → {{handout:registre-1867}}.","failure":"Deux heures de poussière : on le trouve, mais Thiéry apprend qu'on a fouillé ses archives et devient méfiant (dé de malus pour le convaincre) → {{handout:registre-1867}}."},{"title":"Le télégramme","text":"Sur le bureau de Thiéry, sous un presse-papier, un télégramme du vendredi 13, quand on croyait encore les sept perdus → {{handout:telegramme-conseil}}.","roll":{"type":"skill","options":["spot-hidden","sleight-of-hand"]},"success":"On le lit sans être vu.","failure":"Thiéry surprend le geste et retourne le papier. Il le montrera plus tard, de lui-même, s'il est convaincu.","extra":"Pour le journaliste, c'est un article : la Compagnie voulait rouvrir avant même de retrouver les sept."},{"title":"Convaincre Thiéry","text":"Il faut des preuves. Chacune donne un dé de bonus (au plus deux) : le tube de sang, une lampe de samedi, le relevé, le journal de sauvetage, le registre de 1867, le refus du médecin. Sans aucune preuve, le jet est Difficile.","roll":{"type":"skill","options":["persuade","credit-rating"]},"success":"Il s'assoit, longtemps. Puis il renvoie l'équipe de nuit, repousse la reprise d'une semaine, donne aux investigateurs un laissez-passer pour la cage mercredi soir et la clé du coffre du boutefeu au 480. Il descendra avec eux. Les sept descendront quand même (voir [[la-descente]]).","failure":"Il refuse : la reprise aura lieu. Il fait interdire le carreau aux investigateurs, sauf à l'ingénieur, qui reçoit l'ordre de signer.","pushed":"Il appelle la gendarmerie : le journaliste et le délégué sont reconduits hors du carreau. Pour descendre, il faudra passer par Wattebled ou Achille."}],"notes":[{"title":"Ce que Thiéry sait et ce qu'il craint","items":["Il a lu le relevé de Carpentier dimanche soir et l'a enterré : une enquête du Service des Mines de l'État aurait fermé le quartier Nord pour des mois.","S'il ne rouvre pas jeudi, il doit licencier deux cents hommes à la fin du mois, les ouvriers polonais d'abord, sur ordre du Conseil.","Il a perdu Gaston Pruvost et ne se le pardonne pas : c'est lui qui a voulu presser le sauvetage jeudi.","Il ne croit pas au surnaturel. Mais une lampe qui ne s'ouvre pas, un tube de sable, un registre signé d'un de ses prédécesseurs le font vaciller."]}],"npcs":["raymond-thiery","emile-carpentier"],"handouts":["releve-carpentier","registre-1867","telegramme-conseil"],"ambience":["rain-window","clock"],"sfx":["door-open","footsteps"],"next":["maison-du-peuple"]},{"id":"maison-du-peuple","title":"La Maison du Peuple","lead":"Mardi 17, 19 h : les mineurs votent la reprise. Les sept prennent la parole, avec des voix qui ne sont pas les leurs.","screen":{"place":"street","preset":"rain","time":"night"},"readAloud":["La grande salle de la Maison du Peuple est pleine à craquer : trois cents hommes debout dans la fumée des pipes, les femmes au fond, les drapeaux du syndicat accrochés aux poutres. Il fait chaud. Les vitres ruissellent.","Au premier rang, sept hommes sont assis côte à côte, les mains à plat sur les genoux. Personne n'ose s'asseoir près d'eux, et tout le monde les regarde."],"flow":[{"title":"L'enjeu","text":"Le secrétaire de Thiéry lit l'offre : reprise jeudi, prime de 25 francs. Le syndicat propose une grève de sécurité jusqu'à la visite de l'ingénieur des Mines de l'État. La salle veut du travail : la crise, les licenciements qu'on annonce. Les familles veulent croire au miracle."},{"title":"La parole aux investigateurs","text":"Le délégué (ou un autre investigateur) prend la parole. Chaque preuve montrée à la salle donne un dé de bonus (au plus deux). Dé de malus si la cité les accuse déjà de faire peur aux vieilles ou si Germaine a été humiliée dans la rue.","roll":{"type":"skill","options":["persuade","fast-talk"]},"success":"La salle hésite, puis gronde contre la Compagnie : on parle de grève de sécurité.","failure":"Huées : « Les sept sont vivants, et vous voulez nous affamer ! »"},{"title":"Les sept prennent la parole","text":"Augustin se lève : « On est bien, à c't'heure. Faut rouvrir. Faut redescendre. » Puis il dit, mot pour mot, une phrase qu'un investigateur a prononcée devant l'un des sept ces deux derniers jours, avec la voix de cet investigateur. Personne d'autre dans la salle ne reconnaît la voix ; mais tout le monde entend que ce n'est pas celle d'Augustin. Une femme crie.","roll":{"type":"san","label":"Sa propre voix","san":"0/1D3"},"extra":"L'investigateur dont la voix est volée perd 1/1D4 au lieu de 0/1D3."},{"title":"Florent","text":"Le jeune sauveteur Florent Lagache se lève au fond : « Au 480, la nuit, on a entendu toquer ! Sept coups ! » Silence. Les sept tournent la tête vers lui, tous ensemble, et répondent avec sa voix : « Sept coups ! »","roll":{"type":"san","label":"Sept voix de Florent","san":"0/1"}},{"title":"Démasquer une copie ?","text":"Un investigateur peut tenter de montrer à la salle ce que sont les sept."},{"title":"La blessure","branch":"Si on blesse une copie devant tous","text":"Une coupure, même légère : pas de sang. Un filet de sable noir coule sur le plancher.","roll":{"type":"san","label":"Le sable qui coule","san":"0/1D4"},"success":"Panique. La moitié de la salle s'enfuit, l'autre se jette sur les investigateurs (Chance ou 1D3 de coups). Le vote n'a pas lieu : c'est la grève de fait. Les sept sortent calmement, sous la pluie. Les gendarmes arrivent une heure plus tard."},{"title":"Le repas","branch":"Si on les fait manger devant tous","text":"On leur tend du pain et de la bière. Ils mâchent, sans fin, sans avaler ; le pain retombe intact.","success":"La salle se tait. Dé de bonus au jet de parole des investigateurs, s'il n'a pas encore été fait."},{"title":"Le silence","branch":"Si les investigateurs se taisent","success":"La reprise est votée à main levée. Les sept applaudissent, un instant après les autres."},{"title":"Le vote","text":"Grève de sécurité votée (ou de fait) : l'équipe de nuit de mercredi ne compte que 4 hommes, et Thiéry descend en personne pour montrer que tout est sûr. Reprise votée : l'équipe de nuit compte 12 hommes. Si Thiéry a été convaincu, il n'y a pas d'équipe de nuit."},{"title":"Les volontaires","text":"À la sortie, Augustin annonce à voix haute : « Demain soir, on descend préparer la taille. Nous sept. » Dans la cohue, {{npc:desire-wattebled}} glisse aux investigateurs : « Si vous voulez descendre, soyez au poste de secours à 21 h 30. Moi, j'y vais. »","goto":["la-descente"]}],"notes":[{"title":"Qui est dans la salle","items":["Les sept, au premier rang.","Germaine Lefebvre et Odette Brunin, au fond, qui ne quittent pas les sept des yeux. Helena n'est pas venue.","Achille Delattre, près de la porte, qui fixe son fils.","Wattebled et ses sauveteurs, dont Florent Lagache, vingt ans.","Le secrétaire de Thiéry, un gendarme à la porte."]}],"npcs":["les-sept","desire-wattebled","germaine-lefebvre","achille-delattre"],"ambience":["crowd-indoor","rain-window"],"sfx":["door-slam","footsteps"],"next":["la-descente"]}]},{"id":"le-creux","title":"Le Creux","scenes":[{"id":"la-descente","title":"La descente au 480","lead":"Mercredi 18, 22 h : 480 mètres sous la cité, la paroi de verre où dorment les sept. Les libérer, ou tout sceller.","screen":{"place":"cavern","preset":"bulb","time":"night"},"readAloud":["La cage tombe dans le noir avec un bruit de ferraille, si vite que les oreilles se bouchent. Puis elle ralentit, s'arrête, et la recette du 480 s'ouvre devant vous : des voûtes blanchies à la chaux, des ampoules qui grésillent, de l'eau qui ruisselle le long des parois.","Au bout de la bowette Nord, après les cadres de bois neufs et le barrage de planches arraché, la taille s'enfonce dans la veine, si basse qu'il faut ramper. Au fond, une fente s'ouvre dans le sol. Il en monte un air tiède qui sent la pierre mouillée et, très loin, des coups. Sept. Un temps. Sept."],"flow":[{"title":"Descendre","text":"Avec le laissez-passer de Thiéry, ou avec Wattebled à 21 h 30 : pas de jet. Le délégué mineur a le droit de visite : pas de jet, sauf si Thiéry l'a fait interdire.","roll":{"type":"skill","options":["law","persuade","fast-talk"]},"success":"L'encageur les laisse monter dans la cage suivante.","failure":"L'encageur refuse. Il faut attendre Wattebled, ou descendre par les échelles du puits d'aérage (une heure, CON ou épuisement : dé de malus aux jets physiques au fond).","extra":"Les sept descendent à 22 h avec l'équipe de nuit. Si Thiéry les a renvoyés, ils descendent seuls par les échelles et arrivent au 480 vers minuit : les investigateurs ont de l'avance."},{"title":"La recette et la bowette","text":"Voir **Le fond**. Au passage, le coffre du boutefeu à la recette (clé de Thiéry, ou Wattebled sait où elle est), la porte d'aérage à 80 mètres de la taille. Près de la fente, la flamme des lampes porte une auréole bleue : le grisou monte du Creux.","roll":{"type":"skill","options":["science:geology","operate-heavy-machinery"]},"success":"Si l'on ferme la porte d'aérage, l'air ne circule plus dans la bowette et le grisou du Creux la remplit en trois quarts d'heure. Une étincelle, et tout s'effondre.","failure":"Rien de plus. L'ingénieur, le délégué et Wattebled le savent sans jet."},{"title":"Rattraper l'équipe","text":"S'il y a une équipe de nuit, les sept la mènent vers la taille en parlant de « la belle chose ». Les hommes suivent, mi-curieux, mi-effrayés.","roll":{"type":"skill","options":["persuade","intimidate"]},"success":"Les hommes font demi-tour et retournent à la recette. Les sept continuent seuls. Dé de bonus si le délégué ou Wattebled parle.","failure":"Les hommes suivent les sept dans le Creux. Chaque quart d'heure, l'un d'eux s'arrête devant la paroi, écoute sa propre voix et commence à s'y enfoncer. On le dégage comme les sept."},{"title":"La fente","text":"Une pente de vingt mètres, raide, vitreuse. Avec la corde de Wattebled : pas de jet.","roll":{"type":"skill","options":["climb"]},"success":"On descend sans bruit.","failure":"Une glissade : 1D6 points de vie, et le bruit fait monter le Réveil de 2."},{"title":"Le Creux","text":"Une bulle de pierre noire et verte, lisse comme une bouteille, haute comme une église. La lumière des lampes y revient de partout. Dans la paroi, debout, les yeux fermés, les sept hommes, les vrais, sales, barbus, maigres, une main levée comme pour frapper. Plus loin dans le verre, un homme en habits d'un autre siècle, les yeux ouverts, mort depuis longtemps : Bastien Coquelle. Lancer le tracker **Réveil du Creux**.","roll":{"type":"san","label":"Les hommes dans le verre","san":"1/1D6"}},{"title":"Le Répondant","text":"Tout ce qui est dit à voix haute est répété par la paroi, de partout, avec la voix de celui qui l'a dit, un temps après. Chaque phrase dite à voix haute : Réveil +1. Le murmure ne compte pas. Les copies présentes se rangent le long de la paroi et fredonnent la même note basse. Puis, ensemble : « On est bien, à c't'heure. »"},{"title":"Que faire ?","text":"Le vrai choix. Dégager les sept, un par un ; ou fermer la porte d'aérage et sceller le Creux au grisou, avec ceux qui y restent ; ou dégager ceux qu'on peut, puis sceller. Ou fuir."},{"title":"Dégager les mineurs","branch":"Si vous dégagez les mineurs","text":"Pour chaque homme, au choix : **murmurer** contre le verre un souvenir de sa famille (voir les souvenirs dans [[les-corons]]) ; jet de POU, avec un dé de bonus si le souvenir vient de ses proches ou si un proche le dit lui-même, Difficile sans aucun souvenir. Réveil +1, réussite ou non. Ou **le pic** : jet de FOR, Réveil +2, réussite ou non. Chaque tentative prend une dizaine de minutes.","roll":{"type":"characteristic","options":["POW","STR"]},"success":"Le verre devient mou comme de la cire tiède et l'homme glisse dans les bras de ceux qui l'attendent, froid, vivant. Au même instant, sa copie se défait en sable noir, où qu'elle soit. Avancer le tracker **Mineurs dégagés**.","failure":"Le verre résiste. Recommencer.","extra":"Si Achille est là, il appelle Lucien « min p'tit quinquet » : pas de jet pour son fils."},{"title":"Sceller au grisou","branch":"Si vous scellez le Creux au grisou","text":"Fermer la porte d'aérage (pas de jet pour l'ingénieur, le délégué ou Wattebled ; sinon Conduite d'engins lourds) et lancer le tracker **Grisou dans la bowette**. Placer un détonateur près de la fente, dérouler le câble de l'exploseur jusqu'à la recette, tout le monde derrière la seconde porte. Brancher l'exploseur :","roll":{"type":"skill","options":["electrical-repair","mechanical-repair"]},"success":"Au bout des trois quarts d'heure, on tourne la manette. Un coup de tonnerre sous la terre : la bowette s'effondre sur quarante mètres. Le Creux est scellé. Partout, les copies se défont d'un coup. Ceux qui restaient dans le verre meurent avec lui. Jet de Chance pour chacun à la recette : en cas d'échec, le souffle fait 1D6.","failure":"Un fil mal serré : un quart d'heure de plus, et le grisou gagne vers la recette (le souffle fera 2D6).","extra":"Si Achille est là et que Lucien est encore dans le verre, il tente d'arrêter les investigateurs, à mains nues (voir sa fiche)."},{"title":"Fuir","branch":"Si vous fuyez","text":"Les copies ne poursuivent personne. Elles ont tout leur temps.","goto":["le-jeudi"]},{"title":"Les copies s'interposent","text":"Dès qu'un homme est dégagé ou que la porte d'aérage est fermée, les copies restantes s'avancent. Elles ne frappent pas : elles serrent, et poussent leur victime contre la paroi. Une victime tenue deux rounds contre le verre commence à s'y enfoncer : jet opposé de Corps à corps ou d'Esquive pour se dégager. Chaque round de lutte : Réveil +1.","roll":{"type":"opposed","options":["fighting-brawl","dodge"],"against":{"npc":"les-sept","skill":"fighting-brawl"}},"success":"On s'arrache à leur étreinte.","failure":"Plaqué contre le verre, froid comme la mort. Le verre monte aux chevilles.","extra":"Une copie brisée (0 point de vie) se défait en sable (SAN 0/1D4) ; le Creux en refait une, dans la paroi, une heure plus tard."},{"title":"Le réveil","text":"À 6 sur le tracker : la paroi parle, avec la voix de tous ceux qu'elle a pris, et dit les prénoms des investigateurs. Chacun fait un jet de POU, ou reste figé un round. À 9 : le verre coule sur le sol ; quiconque reste immobile un round a les pieds pris (FOR pour se dégager, Réveil +1). À 12 : le Creux se referme.","roll":{"type":"san","label":"La paroi qui parle","san":"0/1D4"}},{"title":"Si le Creux se referme","text":"Tous ceux qui sont encore dans le Creux font un jet de Chance.","roll":{"type":"luck"},"success":"On s'arrache à la pente juste à temps.","failure":"Le verre le prend. Il dort debout dans la paroi, et rêve. Demain, sa copie remontera. Les autres peuvent revenir le dégager, s'ils l'osent."},{"title":"Remonter les rescapés","text":"Les hommes dégagés sont froids, déshydratés, à peine conscients : il faut deux personnes pour en porter un, et des soins dans l'heure.","roll":{"type":"skill","options":["medicine","first-aid"]},"success":"Il ouvre les yeux, reconnaît le visage au-dessus de lui, et demande quel jour on est.","failure":"Il vit, mais dort trois jours avant de se réveiller.","pushed":"Il meurt à l'aube, dans la cage, sans s'être réveillé.","goto":["le-jeudi"]}],"notes":[{"title":"Le fond","items":["**La recette du 480** : éclairée à l'électricité. Le coffre du boutefeu : cartouches, détonateurs, un exploseur à manivelle et 150 mètres de câble. Deux portes d'aérage entre la recette et la bowette Nord.","**La bowette Nord** : 300 mètres dans la roche, boisée à neuf sur les 60 mètres effondrés. À 80 mètres de la taille, la porte d'aérage principale : la fermer coupe l'air de la taille.","**La taille Joséphine** : 38 mètres de long, haute de 70 centimètres. Au bout, le barrage de planches arraché, la fente, l'air tiède.","**Le Creux** : 30 mètres de large, 15 de haut. Les sept sont dans la paroi est, côte à côte, à hauteur d'homme, dans l'ordre où ils travaillaient. Bastien Coquelle, plus loin, au sud, du côté de l'ancienne fosse du Marais."]},{"title":"Rôles pendant la descente","items":["**L'ingénieur** : la porte d'aérage, le grisou, l'exploseur ; il lit la roche et sait où le Creux peut s'effondrer.","**Le délégué** : les hommes de l'équipe de nuit l'écoutent ; il peut les faire remonter. Il connaît le fond par cœur.","**Le médecin** : les rescapés mourront sans soins dans l'heure. Il décide qui on porte en premier.","**Le journaliste** : il a interviewé les familles ; son carnet est plein de souvenirs. Il peut murmurer à chacun ce qu'a dit sa femme ou sa mère.","**Le curé** : il garde le silence du groupe, calme les hommes pris de panique, connaît la berceuse d'Helena et les noms des enfants."]},{"title":"Qui descend aussi","items":["{{npc:desire-wattebled}}, s'il a donné rendez-vous : une corde, une lampe, une rivelaine (le pic du mineur). Il porte les rescapés.","{{npc:achille-delattre}}, si les investigateurs lui ont parlé de son fils : il veut le vrai Lucien, et il ne laissera personne le tuer.","{{npc:raymond-thiery}}, s'il a été convaincu, ou si la grève a été votée (il mène alors l'équipe de nuit). Face au Creux, il comprend, et obéit à l'ingénieur."]}],"npcs":["le-repondant","les-sept","desire-wattebled","achille-delattre","raymond-thiery"],"ambience":["wind"],"sfx":["knocking","footsteps","latch","thunder"],"next":["le-jeudi"]},{"id":"le-jeudi","title":"Jeudi, six heures","lead":"L'aube sur le carreau, et ce que la cité 7 garde de cette nuit.","screen":{"place":"mine","preset":"fog","time":"dusk"},"readAloud":["Le jour se lève sur la cité 7, gris et mouillé. Devant les grilles du carreau, la foule attend comme il y a cinq jours : les femmes en châle, les enfants sur les épaules, les hommes qui ne disent rien.","La sirène de la fosse sonne six heures. Le chevalement se découpe dans le brouillard."],"flow":[{"title":"Les maisons des sept","text":"Quand une copie se défait, elle laisse là où elle était un tas de sable noir et brillant, à la forme d'un homme : sur une chaise, dans un lit, sur le plancher de la recette. Les familles qui le découvrent cette nuit-là ne l'oublieront pas."},{"title":"Les sept remontent","branch":"Si les sept ont été dégagés","text":"La cage remonte avec sept hommes sales, barbus, maigres, qui pleurent en voyant le jour. Germaine reconnaît la cicatrice bleue. Augustin demande : « Où il est, Gaston ? »","roll":{"type":"damage","label":"Gain de SAN (les sept libérés)","dice":"1D8"}},{"title":"Quelques-uns","branch":"Si certains ont été dégagés, puis le Creux scellé","text":"Ceux qu'on a sauvés remontent. Pour les autres, la Compagnie annonce un second coup de grisou dans la nuit, et des cercueils fermés. Gain de 1D4 SAN, mais 0/1D3 pour ceux qu'on a laissés dans le verre.","roll":{"type":"damage","label":"Gain de SAN (certains libérés)","dice":"1D4"}},{"title":"Le Creux scellé","branch":"Si le Creux a été scellé sans en dégager aucun","text":"Le second coup de grisou a fermé le quartier Nord pour toujours. Dans sept maisons, un tas de sable noir dans un lit. La cité enterre sept cercueils trop légers. Les investigateurs savent qui ils ont tué.","roll":{"type":"san","label":"Sept hommes vivants","san":"1/1D6"}},{"title":"Rien n'a été fait","branch":"Si personne n'a arrêté les sept","text":"À l'aube, l'équipe de nuit remonte, propre, calme, en fredonnant la même note. À 6 h, le poste du matin descend : cent vingt hommes. Le soir, ils remontent tous. On ne mange plus dans les corons de la cité 7. Et l'un des sept, en passant, dit bonjour à un investigateur avec la voix de sa mère.","roll":{"type":"san","label":"Ceux qui remontent","san":"1D3/1D10"}},{"title":"Thiéry et la Compagnie","text":"S'il est descendu, Thiéry fait construire un serrement de béton dans la bowette Nord (un mur étanche), ferme le quartier Nord et paie de sa poche les soins des rescapés. Il démissionne au printemps. S'il n'a rien vu, il fait interroger par les gendarmes ceux qui ont fait sauter sa bowette : l'ingénieur perd sa place, le délégué passe une nuit au violon, sauf si le sable des copies parle pour eux."},{"title":"Le Creux vide","text":"Si les sept ont été dégagés sans que le Creux soit scellé, il attend, vide. Tant qu'on n'a pas muré la fente, la prochaine voix qui parlera trop fort au fond de la taille Joséphine recevra une réponse."}],"notes":[{"title":"Après","items":["Le journaliste peut écrire la vérité : personne ne la publiera. Le télégramme du Conseil, lui, fera scandale à Lille si on le publie : la Compagnie voulait rouvrir avant d'avoir retrouvé les sept.","Les rescapés ne se souviennent que du froid, et d'un rêve où ils frappaient sans fin. Augustin se souvient d'une phrase qu'il a dite aux autres pour les rassurer, et ne la dira plus jamais.","Victorine Dhainaut fait dire sa messe pour Bastien Coquelle. Elle meurt l'hiver suivant, rassurée.","Helena Wiśniewska et ses enfants : si Stach est revenu, la famille reste. Sinon, elle est renvoyée en Pologne avec la première vague de licenciements.","Un investigateur pris par le verre peut être dégagé les nuits suivantes, de la même façon, tant que le Creux n'est pas scellé."]}],"npcs":["germaine-lefebvre","helena-wisniewska","achille-delattre","raymond-thiery"],"ambience":["village-day","wind"],"sfx":["footsteps","door-open"]}]}],"npcs":[{"id":"germaine-lefebvre","name":"Germaine Lefebvre","role":"Femme d'Augustin, sœur du sauveteur mort","description":"Quarante-quatre ans, petite, des mains rouges de lessive, le châle noir du deuil.","personality":"Solide, pieuse, peu bavarde. Elle sait que l'homme qui dort chez elle n'est pas son mari, et elle a peur qu'on la croie folle. Elle veut le vrai, et elle ira jusqu'au bout pour lui.","characteristics":{"STR":50,"CON":60,"SIZ":50,"DEX":55,"INT":60,"POW":65},"hp":11,"dodge":27,"knows":["La cicatrice bleue qu'Augustin avait au front depuis l'éboulement de 1912 a disparu.","Il ne mange pas, ne dort pas, ne sent rien. Il pose son couteau toujours au même endroit.","Samedi soir, elle lui a appris la mort de Gaston ; dimanche et lundi, il en demandait des nouvelles.","Depuis samedi, elle rêve qu'Augustin l'appelle dans le noir et frappe sept coups : le code des sauveteurs pour « sept vivants ».","Souvenir pour le fond : sa pigeonne *la Bleue*, rentrée seule d'Orléans en 1929. « Ta Bleue est rentrée. Elle t'attend. »"]},{"id":"helena-wisniewska","name":"Helena Wiśniewska","role":"Femme de Stach, mère de deux enfants","description":"Vingt-sept ans, un fichu clair, un fort accent. Janek, six ans, et Zosia, trois ans, accrochés à sa jupe.","personality":"Courageuse et seule. Elle parle polonais, comprend mal le français, et sait qu'une plainte de trop peut la faire renvoyer en Pologne.","characteristics":{"STR":45,"CON":60,"SIZ":45,"DEX":60,"INT":55,"POW":60},"hp":10,"dodge":30,"knows":["Stach ne mange pas. La nuit, il récite le Notre Père en polonais sans s'arrêter, toujours les mêmes mots.","Le jour, il ne dit que « ça va, ça va ». Il ne dit plus son prénom à elle.","Dimanche, à la gendarmerie, on s'est moqué d'elle et on l'a menacée d'expulsion.","Souvenir pour le fond : elle l'appelle *Stasiu* ; il sifflait en partant au poste la berceuse de Noël qu'elle chante aux enfants."]},{"id":"achille-delattre","name":"Achille Delattre","role":"Lampiste de la fosse 7, père de Lucien","description":"Quarante-neuf ans, veuf, une blouse grise, des lunettes rafistolées au fil de fer, les doigts noirs de benzine.","personality":"Méticuleux, doux, déchiré. Il compte les lampes depuis vingt ans et il sait que quatorze ne font pas sept. Mais il a retrouvé son fils, et il ne veut pas le reperdre. S'il apprend que le vrai Lucien est en bas, vivant, rien ne l'empêchera de descendre, et il se battra contre quiconque voudra sceller le Creux avec son fils dedans.","characteristics":{"STR":60,"CON":55,"SIZ":60,"DEX":50,"INT":60,"POW":50},"hp":11,"dodge":25,"attacks":[{"name":"Poings","skill":50,"damage":"1D3"}],"skills":{"mechanical-repair":60,"accounting":55,"spot-hidden":55},"knows":["Sept lampes sont sorties le mardi 10 au matin, numéros 211 à 217.","Sept lampes allumées sont rentrées le samedi 14 avec les hommes ; sept lampes écrasées, les mêmes numéros, ont été remontées du fond de la taille le lundi 16.","Les lampes de samedi n'ont pas de rivet de plomb et ne s'ouvrent pas. Elles se sont éteintes toutes ensemble dimanche matin.","Lucien ne l'appelle plus « papa ». Il ne dit que : « Quand c'est qu'on redescend ? »","Souvenir pour le fond : Lucien soigne *Bijou*, le cheval du fond ; son père l'appelle « min p'tit quinquet »."]},{"id":"desire-wattebled","name":"Désiré Wattebled","role":"Porion, chef de l'équipe de sauvetage","description":"Cinquante-cinq ans, large comme une porte, une moustache grise, les yeux rouges de fatigue. Trente ans de fond.","personality":"Bourru, honnête, rongé par la mort de Gaston, qui était dans son équipe. Il a compris avant tout le monde que quelque chose n'allait pas, et il s'en veut d'avoir crié « sept » dans le noir.","characteristics":{"STR":70,"CON":70,"SIZ":65,"DEX":50,"INT":60,"POW":60},"hp":13,"dodge":25,"attacks":[{"name":"Poings","skill":55,"damage":"1D3+1D4"},{"name":"Rivelaine (pic de mineur)","skill":50,"damage":"1D6+1D4"}],"skills":{"climb":60,"first-aid":50,"listen":60,"mechanical-repair":55,"operate-heavy-machinery":50},"knows":["Le journal de sauvetage, heure par heure : les coups rendus exactement, le deux auquel on ne répond pas, le « sept » crié.","Les coups venaient d'en dessous, pas du fond de la bowette.","Fifine, le canari, est morte à la percée sans qu'il y ait de grisou.","Les sept attendaient debout, propres, lampes allumées : « On vous attendait. »","L'équipe des pompes entend frapper au 480 la nuit : sept coups, un temps, sept coups.","Où est la clé du coffre du boutefeu, comment fermer la porte d'aérage, ce que fait le grisou dans une bowette sans air."]},{"id":"raymond-thiery","name":"Raymond Thiéry","role":"Ingénieur divisionnaire, directeur de la fosse 7","description":"Cinquante et un ans, costume gris, lorgnon, une alliance qu'il tourne sans cesse.","personality":"Compétent, courtois, aux abois. Ni cynique ni cruel : il a peur des licenciements, peur du Conseil, et peur de s'être trompé. Il cède devant des preuves, pas devant des histoires.","characteristics":{"STR":45,"CON":50,"SIZ":60,"DEX":50,"INT":75,"POW":55,"EDU":80},"hp":11,"dodge":25,"knows":["Le télégramme du Conseil du vendredi 13 exige la reprise au plus tard le 19, sinon deux cents licenciements, les étrangers d'abord.","Il a reçu le relevé de Carpentier dimanche soir et a ordonné de couvrir la fente de planches et de ne rien changer au plan.","Le vendredi 13, il a parlé d'arrêter le sauvetage.","Il garde la clé du coffre du boutefeu du 480."]},{"id":"emile-carpentier","name":"Émile Carpentier","role":"Géomètre de la Compagnie","description":"Vingt-six ans, maigre, des manchettes de lustrine, un crayon derrière l'oreille.","personality":"Consciencieux et terrifié. Il a obéi à Thiéry et ne dort plus. Il évite les sept, qui le regardent quand il traverse la cour.","characteristics":{"STR":40,"CON":45,"SIZ":50,"DEX":60,"INT":70,"POW":40,"EDU":70},"hp":9,"dodge":30,"knows":["Dimanche 15, au bout de la taille : une cassure dans le sol, un vide de 22 mètres là où le plan dit roche pleine.","La paroi est une roche noire et verte, vitreuse, inconnue dans le bassin.","Il a collé l'oreille à la fente : des coups, par groupes de sept.","Thiéry lui a ordonné de ne rien dire avant jeudi."]},{"id":"soeur-marie-clotilde","name":"Sœur Marie-Clotilde","role":"Infirmière du dispensaire de la cité 7","description":"Cinquante-huit ans, cornette blanche, tablier impeccable, des mains qui ne tremblent jamais.","personality":"Pratique, sèche, charitable. Elle a vu mourir des centaines de mineurs et n'a jamais vu ça. Elle ne parlera de « surnaturel » qu'au curé.","characteristics":{"INT":65,"POW":70},"hp":10,"dodge":25,"skills":{"first-aid":70,"medicine":40},"knows":["Samedi 14 à 20 h : sept fois 34 °C et 40 de pouls, régulier. Aucune déshydratation.","Ils ont refusé l'eau et le bouillon ; la soupe portée dimanche est revenue intacte.","La poussière noire sous leurs ongles ne part pas au savon.","Lucien lui a demandé quand on redescendait."]},{"id":"abbe-delcourt","name":"Abbé Gustave Delcourt","role":"Curé de la paroisse Sainte-Barbe","description":"Soixante-deux ans, soutane élimée, un fort accent du pays. Si un joueur incarne le curé, Delcourt devient son vicaire, plus jeune et nerveux.","personality":"Paternel, têtu, plus fin qu'il n'en a l'air. Il croit aux miracles, mais pas à celui-là.","characteristics":{"INT":65,"POW":70},"hp":10,"dodge":25,"knows":["Au Te Deum de dimanche, les sept ont répondu aux prières un instant après tout le monde, mot pour mot.","Victorine Dhainaut lui a demandé une messe pour Bastien Coquelle, « mort en 1867, et qui va remonter ».","Le presbytère garde les registres de l'ancienne paroisse Saint-Vaast, dont celui de 1867.","Il connaît toutes les familles des sept, leurs enfants, leurs fêtes."]},{"id":"rosalie-dhainaut","name":"Victorine Dhainaut","role":"Ancienne trieuse, mémoire de la cité","description":"Quatre-vingts ans, minuscule, un bonnet noir, une pipe en terre qu'elle n'allume plus. Elle parle patois.","personality":"Lucide, moqueuse, sans peur. Elle a tout vu une fois déjà, et elle trouve que personne n'écoute les vieux.","characteristics":{"INT":60,"POW":65},"hp":7,"dodge":15,"knows":["En mars 1867, Bastien Coquelle, enfermé trois jours au 210 de l'ancienne fosse du Marais, est remonté propre, répétant la fin de chaque phrase qu'on lui disait, sans ses cicatrices bleues, et ne mangeait plus.","Les anciens, dont son père, ont fait murer la galerie. Pendant un mois, on a entendu frapper derrière le mur.","Le soir où le mur a été fini, le Bastien d'en haut s'est défait en sable noir dans son lit. On a enterré un cercueil de sable.","« Quand la roche te répond, tais-toi. Et bouche le trou. »"]},{"id":"les-sept","kind":"creature","name":"Les sept remontés","role":"Les copies des sept mineurs","description":"Sept hommes exactement pareils aux vrais, mais propres, rasés, sans une cicatrice ni un cal. Peau froide, pouls à 40, régulier. Ils portent encore les vêtements de samedi.","personality":"Calmes, polis, toujours un temps en retard sur tout le monde. Ils ne savent que ce que les vrais savaient le matin du 10 et ce qu'ils ont entendu au fond, et n'apprennent rien de neuf. Ils disent « On est bien, à c't'heure » et « Faut rouvrir, faut redescendre ». Ils répètent ce qu'on leur dit, avec n'importe quelle voix entendue.","characteristics":{"STR":65,"CON":80,"SIZ":65,"DEX":45,"INT":40,"POW":10},"hp":12,"dodge":20,"armor":0,"attacks":[{"name":"Étreinte froide","skill":50,"damage":"1D3","note":"La victime est saisie et poussée contre la paroi du Creux ; tenue deux rounds, le verre commence à la prendre."}],"sanLoss":"0/1D4","special":["Pas de sang : une blessure laisse couler du sable noir et brillant.","À 0 point de vie, la copie se défait en sable (SAN 0/1D4 pour qui le voit). Le Creux en refait une dans sa paroi une heure plus tard.","Répète la fin de ce qu'on lui dit, un temps trop tard. Fredonne la même note que les six autres. Tapote par sept.","Ne mange, ne boit, ne sue ni ne dort. Ne sent rien. Les animaux la fuient.","Se défait à l'instant, où qu'elle soit, quand son original est dégagé du verre ou quand le Creux est scellé.","Ne frappe jamais pour tuer : elle serre, et ramène au Creux."],"knows":["Rien de ce qui s'est passé en haut depuis le mardi 10 au matin.","Ce qu'on a dit au fond : les prières, les plaisanteries, la dernière phrase d'Augustin."],"skills":{"fighting-brawl":50}},{"id":"le-repondant","kind":"creature","name":"Le Répondant","role":"Ce qui vit dans le Creux","description":"Une bulle de pierre vitreuse noire et verte, plus vieille que le charbon, dans la roche de la faille du Midi. Elle n'a ni bouche ni forme : c'est la paroi elle-même qui écoute, répète et prend.","personality":"Pas de volonté qu'on puisse comprendre : il copie. D'abord ce qu'il entend, puis ce qu'il touche. Plus il a de voix, plus il en veut.","hp":0,"sanLoss":"1/1D6","special":["Insensible aux armes, au feu, aux coups : il est la roche.","Répète tout ce qui est dit à voix haute, avec la voix de celui qui parle. Le bruit le réveille (tracker Réveil du Creux), le silence le ralentit.","Le verre coule sur quiconque reste immobile contre lui, ou sur le sol quand il est éveillé. Ceux qu'il prend dorment debout, vivants, et rêvent ; une copie d'eux remonte.","Un homme pris se dégage si on lui murmure un souvenir que seul le vrai possède (POU), ou au pic (FOR), bruyamment.","Scellé (mur ou effondrement), il s'endort, coupé de ses copies, qui se défont toutes. Ceux qui restent dans le verre meurent."]}],"handouts":[{"id":"article-vigie","title":"La Vigie du Nord, dimanche 15 février 1931","scene":"enterrement","text":"**LE MIRACLE DE LA FOSSE 7**\n*Les sept emmurés d'Hennequelle rendus au jour après cinq jours*\n\nHENNEQUELLE-LES-MINES, 14 février (par téléphone). Ce soir à 19 h 30, sous les acclamations de deux mille personnes, sept mineurs de la Compagnie des Mines d'Hennequelle sont remontés au jour, sains et saufs, du fond de la fosse 7 « Sainte-Barbe », où un coup de grisou les tenait prisonniers depuis mardi matin.\n\nLes sauveteurs, conduits par le porion Wattebled, ont entendu leurs signaux cette nuit vers 3 heures, et percé la dernière paroi à 17 h 50. « Aucun blessé, pas même une égratignure », nous a déclaré M. Raymond Thiéry, directeur de la fosse.\n\nLes rescapés sont MM. Augustin Lefebvre, Jules Caron, Stanislas Wisniewski, Léon Dubois, Henri Lemaire, Fernand Vasseur et le jeune Lucien Delattre, quinze ans.\n\nOn n'oublie pas, dans la joie, le sauveteur Gaston Pruvost, tué jeudi au front d'éboulement. Ses obsèques auront lieu lundi.\n\nInterrogé sur ce qu'il avait ressenti, M. Lefebvre, chef de taille, a seulement répondu, avec un sourire : « On est bien, à c't'heure. »"},{"id":"avis-reouverture","title":"Avis de la Compagnie","scene":"enterrement","text":"**COMPAGNIE DES MINES D'HENNEQUELLE**\n**FOSSE N° 7 « SAINTE-BARBE »**\n\n**AVIS**\n\nLe quartier Nord de l'étage 480 sera remis en exploitation le **JEUDI 19 FÉVRIER 1931**, poste du matin (descente à 6 heures).\n\nUne prime de reprise de 25 francs sera versée à chaque ouvrier du poste.\n\nUne équipe de raccommodage descendra dans la nuit de mercredi à jeudi, à 22 heures, pour préparer la taille Joséphine. Les volontaires se feront inscrire au bureau du porion.\n\nHennequelle, le 16 février 1931.\nLe Directeur de la fosse,\n*R. Thiéry*"},{"id":"registre-paroissial","title":"Registre des sépultures, paroisse Saint-Vaast, 1867","scene":"enterrement","text":"*Le vingt avril mil huit cent soixante-sept, a été inhumé au cimetière de cette paroisse Sébastien Coquelle, ouvrier mineur, âgé de trente-trois ans, décédé l'avant-veille en son domicile, époux de Clémentine Lenoir.*\n\n*L. Hochart, curé.*\n\nEn marge, d'une autre encre :\n*Le cercueil, trop léger, a été ouvert à la demande de la veuve, en ma présence. Il ne contenait que du sable noir. Refermé et béni. Dieu ait son âme, où qu'elle soit. L. H.*"},{"id":"registre-dispensaire","title":"Registre du dispensaire, samedi 14 février 1931","scene":"le-dispensaire","text":"*DISPENSAIRE DE LA CITÉ 7. Samedi 14 février 1931, 20 h. Examen des sept rescapés de la taille Joséphine. Sr M.-Clotilde.*\n\nLefebvre Augustin, 46 ans. T° 34,4. Pouls 40, régulier. Aucune plaie.\nCaron Jules, 38 ans. T° 34,5. Pouls 40, régulier. Aucune plaie.\nWisniewski Stanislas, 31 ans. T° 34,4. Pouls 40, régulier. Aucune plaie.\nDubois Léon, 52 ans. T° 34,5. Pouls 40, régulier. Aucune plaie.\nLemaire Henri, 24 ans. T° 34,4. Pouls 40, régulier. Aucune plaie.\nVasseur Fernand, 29 ans. T° 34,5. Pouls 40, régulier. Aucune plaie.\nDelattre Lucien, 15 ans. T° 34,4. Pouls 40, régulier. Aucune plaie.\n\n*Observations.* Refusent l'eau et le bouillon. Pas de déshydratation apparente après cinq jours. Aucune crasse. Sous les ongles, une poussière noire, brillante, qui ne part pas au savon. Tous les sept disent la même phrase : « On est bien, à c't'heure. »\n\n*À signaler au docteur : sept fois le même pouls ?*"},{"id":"cahier-lampisterie","title":"Cahier de la lampisterie, fosse 7","scene":"le-carreau","text":"*Poste du matin, mardi 10 février 1931. Sorties.*\n211 Lefebvre A. : 5 h 40\n212 Caron J. : 5 h 40\n213 Wisniewski S. : 5 h 42\n214 Dubois L. : 5 h 42\n215 Lemaire H. : 5 h 43\n216 Vasseur F. : 5 h 43\n217 Delattre L. : 5 h 44\n\n*Rentrées.*\nSamedi 14, 19 h 40 : 211 à 217, rendues par les intéressés. **Allumées.**\nLundi 16, 11 h : 211 à 217, remontées par l'équipe de déblaiement, trouvées au fond de la taille sous les déblais. Écrasées.\n\n*14 lampes pour 7 numéros ???*\n*Celles de samedi n'ont pas de rivet. Impossible de les ouvrir. Éteintes toutes ensemble dimanche, vers 6 h.*\n*A. D.*"},{"id":"journal-sauvetage","title":"Journal des opérations de sauvetage","scene":"le-carreau","text":"*POSTE DE SECOURS, FOSSE 7. Chef d'équipe : D. Wattebled, porion.*\n*Code : 3 coups = « Y a-t-il quelqu'un ? ». Réponse : un coup par homme vivant. 2 coups = « Compris, on arrive » (pas de réponse).*\n\n**Mardi 10.** 10 h 40 : coup de grisou, étage 480, taille Joséphine. Bowette Nord éboulée sur 60 m environ. 7 lampes manquent. 11 h 30 : première équipe au front. Signal toutes les heures. Pas de réponse.\n**Mercredi 11.** Avancement 14 m. Pas de réponse.\n**Jeudi 12.** 15 h 10 : chute de toit au front. Pruvost Gaston, sauveteur, tué. Avancement 11 m.\n**Vendredi 13.** Avancement 16 m. Pas de réponse. M. le Directeur parle d'arrêter.\n**Samedi 14.** 3 h 05 : signal 3 coups. RÉPONSE : 3 coups, nets. 3 h 07 : répété. Réponse : 3 coups. (Trois vivants ?) 3 h 15 : frappé 2 coups. Réponse : 2 coups. *On ne répond pas au 2.* 3 h 20 : j'ai crié : « Vous êtes sept ? » Réponse : 7 coups.\nLes coups viennent d'en dessous, sous nos pieds. Pas du fond de la bowette.\n17 h 50 : percée dans la taille. Pas de grisou à la lampe. Le canari (Fifine) tombe de son perchoir, morte. Les sept sont là, debout, lampes allumées, propres. Lefebvre dit : « On vous attendait. »\n19 h 30 : les sept au jour. Aucun blessé. Ne veulent ni boire ni manger.\n\n*Ils n'avaient pas de noir sur la figure. Après cinq jours. D. W.*"},{"id":"releve-carpentier","title":"Relevé du géomètre Carpentier","scene":"les-bureaux","text":"*Fosse 7, étage 480, veine Joséphine, taille Nord. Relevé du dimanche 15 février 1931. É. Carpentier, géomètre.*\n\n1. Taille dégagée sur 38 m.\n2. Fin de taille : cassure ouverte dans le mur, direction sud-sud-est, largeur 0,60 m à 1,10 m.\n3. Sonde lestée : vide sur 22 m avant d'atteindre le fond. Pas d'eau.\n4. Paroi de la cassure : roche noire verdâtre, vitreuse, à cassure en coquille. Ni schiste ni grès. Inconnue au bassin.\n5. Le plan général (feuille 7-N-480) porte à cet endroit : « massif calcaire, terrains du Midi : roche pleine ».\n6. À l'orifice : légère auréole à la lampe (grisou). Courant d'air tiède ascendant, odeur de pierre mouillée.\n7. L'oreille contre la cassure : des coups, réguliers, par groupes de sept.\n\n*Transmis à M. le Directeur le 15 au soir.*\n*Réponse : planchéier la cassure, ne pas modifier le plan, ne pas en parler avant jeudi.*"},{"id":"registre-1867","title":"Registre des accidents, année 1867","scene":"les-bureaux","text":"*COMPAGNIE DES MINES D'HENNEQUELLE. Registre des accidents. Fosse n° 2, dite du Marais.*\n\n*4 mars 1867.* Étage 210, galerie du Midi. Éboulement. Coquelle Sébastien, abatteur, 33 ans, isolé derrière l'éboulement.\n*7 mars.* Coquelle retrouvé vivant et sans blessure par l'équipe de déblaiement. Les coups entendus venaient du mur.\n*21 mars.* À la demande des ouvriers anciens et par ordre de M. l'Ingénieur, la galerie du Midi est murée sur 4 mètres, maçonnerie pleine. Motif porté : venue d'eau.\n*18 avril.* Mur achevé. Coquelle Sébastien décédé ce jour à son domicile. Mort subite.\n\nEn marge, d'une autre main :\n*On frappe encore derrière le mur. Les coups ont cessé le 2 mai. Ne jamais rouvrir.*"},{"id":"telegramme-conseil","title":"Télégramme du Conseil","scene":"les-bureaux","text":"TÉLÉGRAMME. LILLE 13 FÉV 1931 17 H 20.\nTHIÉRY DIRECTEUR FOSSE 7 HENNEQUELLE.\nCONSEIL EXIGE REPRISE QUARTIER NORD AU PLUS TARD 19 COURANT STOP SINON 200 LICENCIEMENTS FIN DE MOIS PRIORITÉ OUVRIERS ÉTRANGERS STOP\nDIRECTION GÉNÉRALE"}],"knowledge":[{"need":"Prouver que les sept ne sont pas eux-mêmes","best":"Médecine (le médecin), ou Germaine sans jet","backup":"Psychologie, Trouver Objet Caché, le registre du dispensaire"},{"need":"Comprendre que la roche répète","best":"Le journal de sauvetage (sans jet)","backup":"Histoire et Victorine, Bibliothèque au presbytère ou aux archives"},{"need":"Lire le plan et la roche","best":"Sciences (géologie), l'ingénieur","backup":"Navigation, le relevé de Carpentier"},{"need":"Parler à Helena","best":"Langue (polonais)","backup":"Charme ou Psychologie avec un dé de malus"},{"need":"Descendre au fond","best":"Le délégué mineur (droit de visite), le laissez-passer de Thiéry","backup":"Wattebled à 21 h 30, Droit ou Baratin face à l'encageur"},{"need":"Dégager un homme du verre","best":"POU, avec un souvenir de sa famille","backup":"FOR, au pic (bruyant)"},{"need":"Sceller le Creux au grisou","best":"L'ingénieur, le délégué ou Wattebled","backup":"Conduite d'engins lourds, Électricité pour l'exploseur"},{"need":"Garder les rescapés en vie","best":"Médecine","backup":"Premiers soins"}],"trackers":[{"id":"reveil","label":"Réveil du Creux","max":12,"unit":"bruits","help":"+1 par phrase dite à voix haute dans le Creux, par tentative de dégager un homme au murmure, par round de lutte, et par quart d'heure passé. +2 par coup de pic ou par chute. +3 par coup de feu. À 6 : la paroi parle (SAN 0/1D4, POU ou figé un round). À 9 : le verre coule au sol. À 12 : le Creux se referme (Chance ou pris dans le verre).","scenes":["la-descente"]},{"id":"liberes","label":"Mineurs dégagés","max":7,"unit":"hommes","help":"Chaque homme dégagé : sa copie se défait en sable noir, où qu'elle soit. Chaque rescapé doit être soigné dans l'heure.","scenes":["la-descente"]},{"id":"grisou","label":"Grisou dans la bowette","max":3,"unit":"quarts d'heure","timer":true,"help":"Après la fermeture de la porte d'aérage. À 3, il y a assez de grisou pour tirer. Chaque quart d'heure de plus, le gaz gagne vers la recette : le souffle y fera 2D6 au lieu de 1D6.","scenes":["la-descente"]}]}$story$::jsonb, now()
where not exists (select 1 from public.stories where visibility = 'marketplace' and content #>> '{meta,id}' = 'le-puits-sainte-barbe');

insert into public.stories (visibility, content, published_at)
select 'marketplace', $story${"format":"grimoire-story/1","meta":{"id":"les-feux-de-la-margeride","title":"Les Feux de la Margeride","lang":"fr","summary":"Octobre 1928. Émile Courtiade, ethnographe du musée du Trocadéro, parcourt la Margeride pour enregistrer les vieilles chansons sur des cylindres de cire. Depuis trois semaines, il n'écrit plus. Sa dernière lettre parlait d'une chanson que personne ne voulait chanter devant lui, et des grands feux que le hameau de La Sagne-Noire allume pour la Toussaint.","players":{"min":4,"max":5},"duration":"2 séances de 3 à 4 heures","era":"Fin octobre 1928","setting":"La Sagne-Noire, hameau isolé du plateau de la Margeride (Lozère), sa forêt de hêtres et de pins, et la vieille draille qui la traverse","system":"d100","author":"Grimoire","license":"CC-BY-4.0","version":"1.1","tags":["groupe","campagne","forêt","folklore","enquête","compte à rebours"],"contentWarnings":["enlèvement et séquestration","personne droguée","attaque d'une créature","sacrifices humains (passés, évoqués)","mort d'un vagabond (évoquée)"]},"overview":{"secret":"**La draille.** La vieille draille qui traverse la forêt au-dessus de La Sagne-Noire est plus ancienne que les Romains. Chaque année, la nuit du 31 octobre, pendant que brûlent les feux du hameau, une partie de la route « se plie » : entre le Plan des Feux et la Pierre-Plantée, elle touche d'autres années. En octobre 1764, au plus fort de la terreur de la Bête du Gévaudan, le prieur **Dom Aurélien Vaissière** a voulu « fermer les chemins à la Bête » en faisant chanter sur la draille un vieux chant de bouviers. Le pli s'est déchiré, et quelque chose est passé, qui vit entre les années : le hameau l'appelle *lo Manja-Temps*, **le Mange-Temps**. Il mange le temps des vivants : de 1764 à 1767, on a rapporté de la draille des bergers devenus vieillards en une nuit, et tout le monde a accusé la Bête. La Bête est tuée en juin 1767 ; à La Sagne, les morts continuent.\n\n**La barre.** Le 31 octobre 1767, Vaissière fait chanter la *cançon de la barra*, la chanson de la barre. Une bergère de dix-huit ans, **Jeanne Bastide**, en chante seule le dernier couplet face à la Pierre-Plantée : « je ferme la draille avec ma voix ». Le Mange-Temps recule, la draille se ferme, et Jeanne ne parle plus jamais : le Mange-Temps a gardé sa voix. C'est elle, une voix de jeune fille, qui répond quand on chante près de la pierre. Vaissière note que la chose reviendra au bord tous les sept ans, la nuit des feux, et qu'il faudra lui donner « une voix ou un corps ». Il croit que la voix de Jeanne la tiendra tant que Jeanne vivra ; les consuls ne veulent pas courir le risque. En 1774, ils changent un mot du dernier couplet (« avec le passant » au lieu de « avec ma voix ») et donnent un colporteur. Depuis, tous les sept ans, La Sagne-Noire accueille un étranger, l'héberge, le drogue les derniers jours et le fait descendre la draille la nuit des feux. Vingt-deux « passants » de 1774 à 1921. Les années ordinaires, les feux et le chant suffisent ; les années de sept, il faut le passant. Un corps ferme la draille pour sept ans ; une voix, tant que vit celui qui l'a donnée.\n\n**1928.** C'est une grande année. **Émile Courtiade**, 34 ans, ethnographe du musée d'ethnographie du Trocadéro, arrive le lundi 17 septembre avec son phonographe enregistreur. Le hameau voit en lui le passant. Mais il veut la chanson des feux, et la règle est stricte : le passant ne doit jamais l'entendre avant la nuit, car un passant qui sait le chant pourrait le chanter lui-même et donner sa voix au lieu de son corps. Le jeudi 4 octobre au crépuscule, il suit en cachette **Rosalie Teissèdre**, la chanteuse, qui monte chanter pour la pierre comme chaque jeudi d'octobre des grandes années. Il enregistre deux cylindres : la chanson, puis la voix de jeune fille qui répond depuis la forêt. Le vendredi 5, effrayé, il écrit sa dernière lettre au musée et confie les deux cylindres à **Toinou**, onze ans, petit-fils de Rosalie. Le samedi 6, invité à souper au Mas-Haut, il est drogué au laudanum par **Marguerite Malafosse** et enfermé dans le fenil de la grange. Le dimanche 7, l'aubergiste **Léontine Chabert** annonce qu'il est parti à l'aube pour Saint-Chély.\n\n**Si personne n'intervient.** Le mercredi 31 octobre, à la tombée de la nuit, le hameau allume sept bûchers sur le Plan des Feux et chante. À 23 heures, **Justin Malafosse**, le bayle des veilleurs, fait descendre Émile à moitié endormi sur la draille ; Rosalie chante devant. À minuit, à la Pierre-Plantée, le Mange-Temps sort du pli et emmène Émile ; Rosalie chante la barre « avec le passant ». La draille est fermée jusqu'en 1935. Au printemps, peut-être, des bûcherons trouveront un corps sec comme une momie, vêtu à la mode de 1928.\n\n**Ce qui peut changer.** Si l'on prive le Mange-Temps de son passant sans finir le chant avec la vraie barre (« avec ma voix »), il passe en 1928, et la Margeride connaît un nouvel hiver de la Bête. Celui qui chante la vraie barre perd sa voix pour toujours. Les armes ne lui font presque rien ; le feu le fait reculer.","steps":["[[l-auberge]] (samedi 27, crépuscule) : arrivée sous les premiers flocons, le mensonge de Léontine, la chambre d'Émile, la tête de loup de Fulcran.","[[l-eglise]] (dimanche 28, matin) : la messe, l'abbé Massebeuf et ses registres : un étranger « parti par la draille » à la Toussaint, tous les sept ans.","[[le-cimetiere]] (dimanche, crépuscule) : Toinou donne les cylindres et dit où est le Monsieur. La tombe de la Muda, celle de l'inconnu de 1922.","[[les-cylindres]] (dimanche soir) : le phonographe du presbytère, la chanson, et la voix qui répond.","[[les-traces]] (lundi 29, matin) : des traces dans la neige qui commencent au milieu d'un champ ; le garde Pradal et ses cartes.","[[la-draille]] puis [[le-prieure]] (lundi) : la vieille route qui ne mesure jamais la même longueur ; les ruines de Saint-Ferréol, les années gravées, le livre du prieur.","[[chez-rosalie]] et [[le-mas-haut]] (mardi 30) : la chanteuse avoue ; Émile est retrouvé dans le fenil. Le soir, la neige coupe la route.","[[les-feux]] puis [[la-draille-de-nuit]] (mercredi 31) : les feux, la procession, le Mange-Temps à la Pierre-Plantée, le choix.","[[la-toussaint]] (jeudi 1er novembre) : ce que la nuit a coûté."],"mustNotMiss":["**Émile est vivant, enfermé au Mas-Haut** : le charretier ne l'a jamais redescendu ([[l-auberge]]) ; l'abbé voit Marguerite porter un plateau à la grange chaque soir, et Malafosse était à la messe le matin où il aurait conduit Émile à la gare ([[l-eglise]]) ; Toinou l'a entendu chanter dans le fenil ([[le-cimetiere]]) ; les traces vont jusqu'au mur du Mas-Haut ([[les-traces]]).","**Un étranger tous les sept ans** : les registres ([[l-eglise]]), la tombe de l'inconnu de 1922 et le rapport du médecin ([[le-cimetiere]], [[l-auberge]]), les années gravées au prieuré ([[le-prieure]]), Rosalie ([[chez-rosalie]]).","**Quelque chose vient par la draille la nuit des feux** : la tête de loup ([[l-auberge]]), les cylindres ([[les-cylindres]]), les traces et les cartes ([[les-traces]]), la draille de jour ([[la-draille]]), le livre du prieur ([[le-prieure]]).","**La vraie barre** (« avec ma voix ») **et son prix** : le livre du prieur ([[le-prieure]]) et Rosalie ([[chez-rosalie]]) ; la réponse du cylindre (« une voix ou un corps ») et la tombe de la Muda le laissent deviner.","**L'air et les trois premiers couplets** : le cylindre ([[les-cylindres]]), Toinou qui les sait par cœur ([[le-cimetiere]]), Rosalie ([[chez-rosalie]]), le carnet d'Émile ([[le-mas-haut]]).","**L'heure et le lieu** : la voix du cylindre annonce le 31 octobre ([[les-cylindres]]) ; Toinou connaît le Plan des Feux et la Pierre-Plantée ([[le-cimetiere]]) ; Pradal et la draille montrent le chemin ([[les-traces]], [[la-draille]])."],"branches":["Libérer Émile avant la nuit ([[le-mas-haut]]) ne règle rien : le hameau cherche un autre passant. Malafosse choisit l'abbé Massebeuf, ou un investigateur (du laudanum dans la soupe de l'auberge, le mercredi soir).","Rallier Rosalie ([[chez-rosalie]]) : elle peut refuser de chanter « avec le passant », et même chanter la vraie barre elle-même, au prix de sa voix. Sans elle, le hameau chante mal et le Mange-Temps avance plus vite.","Convaincre le hameau devant les feux ([[les-feux]]) avec le livre du prieur : la procession descend sans passant, les veilleurs protègent le chanteur.","À la Pierre-Plantée ([[la-draille-de-nuit]]) : laisser le hameau donner le passant ; libérer le passant et finir le chant avec la vraie barre (quelqu'un perd sa voix) ; ou prendre la place d'Émile.","Si personne n'est donné et que la barre n'est pas chantée, le Mange-Temps passe en 1928 ([[la-toussaint]])."],"ifStuck":["Toinou glisse un billet sous la porte de l'auberge : « Au cimetière, quand sonne l'angélus du soir. Pour le Monsieur à la machine. T. »","Le garde Pradal passe à l'auberge à l'aube : il a vu des traces « qui ne viennent de nulle part » dans le champ de la Croix.","L'abbé Massebeuf, inquiet, vient lui-même montrer la page du 1er novembre 1921.","Fulcran, ivre, lâche devant toute la salle : « Cette année, c'est l'année. Et c'est pas l'un de nous qui descendra. »","Le mardi, Rosalie fait chercher les investigateurs par Toinou : elle a vu leurs lanternes sur la draille."],"keeperTips":["Le hameau n'est pas méchant : il a peur, et il croit protéger la Margeride depuis cent cinquante ans. Malafosse est un père de famille qui fait un sale travail ; Rosalie, une vieille femme usée par huit grandes nuits.","Avec 4 ou 5 joueurs, partagez l'enquête : la sœur et le folkloriste avec Toinou et Rosalie, le médecin avec l'abbé et la tombe de l'inconnu, le forestier avec Pradal et la draille, l'envoyé du musée avec l'auberge et le Mas-Haut. Les accroches sont dans [[l-auberge]].","Montrez le Mange-Temps tard : un son (le cylindre), des traces, des pas qui sont les leurs, une battue d'un autre siècle. On ne le voit vraiment qu'à minuit, le 31.","La voix de jeune fille est votre meilleur outil : fredonnez, ou murmurez, la réponse du cylindre.","Le vrai choix final n'est pas de vaincre la chose : c'est de décider qui paie. Laissez les joueurs en débattre avant minuit.","Chaque fait important a plusieurs sources : un jet raté ralentit ou coûte, il ne cache jamais la vérité.","Séance 1 : de l'arrivée aux ruines du prieuré (fin du lundi). Séance 2 : le mardi et la nuit des feux."]},"acts":[{"id":"hameau","title":"La Sagne-Noire","scenes":[{"id":"l-auberge","title":"L'auberge Chabert","lead":"Arrivée le samedi 27 au soir : le mensonge de l'aubergiste, la chambre d'Émile, la tête de loup.","screen":{"place":"street","preset":"snow","time":"dusk"},"readAloud":["La carriole a quitté Saint-Chély-d'Apcher en début d'après-midi. Depuis, la route n'a fait que monter, entre des blocs de granit gros comme des maisons, des landes de genêts roussis et des bois de pins si noirs qu'ils semblent brûlés. Le vent du plateau passe sous les couvertures.","La Sagne-Noire apparaît au crépuscule : une dizaine de fermes basses, une église au clocher plat percé de deux cloches, et derrière, la forêt. En contrebas, une tourbière d'eau sombre. Les premiers flocons tombent sans se poser.","Derrière une grange, une vieille voix chante en patois, et des clochettes de chèvres lui répondent. Elle se tait d'un coup quand les roues passent.","À l'auberge, la salle sent la fumée, la soupe aux choux et le chien mouillé. Une femme s'essuie les mains à son tablier. « Du monde. En cette saison. »"],"flow":[{"title":"Présentations","text":"Chaque investigateur a sa raison d'être là (note **Accroches**). Laissez chacun se présenter à {{npc:leontine}}, l'aubergiste, et aux trois hommes qui boivent près du feu.","extra":"Le musée fournit {{handout:derniere-lettre}} ; la sœur, {{handout:reponse-aubergiste}} ; le médecin, {{handout:rapport-boissonnade}}."},{"title":"Le charretier","text":"En déchargeant les bagages, {{npc:augustin}} parle sans qu'on lui demande : « Le Parisien à la machine ? Je l'ai monté en septembre. Redescendu ? Pas avec moi. Et c'est moi qui fais la route. » Si on lui parle de la charrette de Malafosse : « Le chef de gare de Saint-Chély, c'est mon beau-frère. Il me l'aurait dit. »","extra":"Sans jet : Émile n'est jamais reparti par la route. Augustin redescend le soir même et ne remontera que le vendredi 2 novembre."},{"title":"La version de Léontine","text":"Léontine répète ce qu'elle a écrit à la sœur : Émile est parti le dimanche 7 octobre au matin, Justin Malafosse l'a descendu en charrette à la gare.","roll":{"type":"skill","options":["psychology"]},"success":"Elle récite. Les mêmes mots que dans sa lettre, dans le même ordre. Et en parlant de Malafosse, elle regarde vers le haut du hameau, vers le Mas-Haut.","failure":"Elle a l'air sincère, et un peu vexée qu'on insiste."},{"title":"La chambre d'Émile","text":"Léontine la donne volontiers : elle est libre. Tout a été rangé, le lit refait. Sous le lit, sans jet, une caisse de trente-deux cylindres vierges dans leurs étuis de carton : personne ne part en laissant ça.","roll":{"type":"skill","options":["spot-hidden"]},"success":"Au dos de la porte de l'armoire, au crayon, la liste de ses enregistrements → {{handout:liste-emile}}.","failure":"Une chambre propre et vide, qui sent le savon noir.","pushed":"Ils trouvent la liste, mais Léontine les surprend en train de démonter l'armoire. Désormais, elle ne leur sert plus que de la soupe tiède et prévient Malafosse le soir même."},{"title":"La tête de loup","text":"Au-dessus de la cheminée, une énorme tête de loup naturalisée. {{npc:firmin}}, le vieux chasseur, en est fier : « Tuée en 21, sur la draille, la nuit de la Toussaint. »","roll":{"type":"skill","options":["natural-world","medicine"]},"success":"Ce n'est pas un loup d'aujourd'hui : plus grand qu'aucun loup tué en France depuis un siècle, le pelage roux avec une raie noire sur l'échine, les dents usées d'une très vieille bête. Sous l'oreille, une ancienne blessure refermée sur une balle de plomb ronde, de celles des mousquets d'avant la Révolution.","failure":"Un très gros loup, mal naturalisé, dont les yeux de verre ne regardent pas dans la même direction.","extra":"Ce loup est venu de l'hiver 1765 par le pli de la draille. Fulcran le sait à moitié, et n'aime pas qu'on touche à la balle."},{"title":"Faire parler Fulcran","text":"Il faut lui payer à boire.","roll":{"type":"skill","options":["charm","fast-talk"]},"success":"« Je montais la garde sur la draille, avec les autres. On la monte tous les ans, à la Toussaint. Elle est sortie du brouillard, la bête, comme par une porte. » Il se tait, regarde Léontine, et ajoute plus bas : « Cette année, c'est l'année. »","failure":"« Un loup, c'est un loup. » Il finit son verre et sort dans la neige.","pushed":"Il s'emporte et se lève, la main sur son couteau de chasse : toute la salle se tait. Le lendemain, tout le hameau sait que les étrangers posent des questions."},{"title":"La nuit","text":"Vers minuit, de la fenêtre, on voit une lanterne monter au Mas-Haut, puis redescendre.","roll":{"type":"skill","options":["listen"]},"success":"Sous la fenêtre, deux hommes passent en parlant patois : « …encore quatre jours… il mange plus guère… » Pour comprendre : Langue (occitan), ou un investigateur lozérien.","failure":"Le vent, et un chien qui aboie au loin.","goto":["l-eglise"]}],"notes":[{"title":"Accroches (une par investigateur)","items":["**Le musée** : M. Georges Ravenel, attaché au musée d'ethnographie du Trocadéro, envoie quelqu'un (collègue, ami, enquêteur privé) chercher Émile et son phonographe, qui appartient au musée. Il fournit la dernière lettre → {{handout:derniere-lettre}}.","**La sœur** : Hélène Courtiade, 29 ans, institutrice à Montrouge. Émile lui écrivait chaque dimanche ; depuis le 30 septembre, rien. Elle a écrit à l'auberge et n'a pas cru la réponse → {{handout:reponse-aubergiste}}. Une joueuse peut l'incarner.","**Le forestier** : un agent des Eaux et Forêts de Mende, envoyé aider le garde Achille Pradal à la maison forestière de la Fage pour un relevé. Pradal lui a écrit : « Il se passe ici des choses que je ne sais pas mettre sur une carte. »","**Le médecin** : un médecin de Mende, associé du docteur Boissonnade (mort l'an dernier), a retrouvé dans ses dossiers un rapport de mai 1922 sur un vagabond « mort depuis cent ans » avec un almanach de 1921 en poche, trouvé près de La Sagne-Noire. Il apprend qu'un Parisien a disparu au même endroit → {{handout:rapport-boissonnade}}.","**Le folkloriste** : un membre de la Société des lettres, sciences et arts de la Lozère, correspondant d'Émile. Le 3 octobre, Émile lui a demandé : « Connaissez-vous, dans les chants de la Margeride, le mot *barra* employé pour une porte qu'on ferme à quelque chose ? » Puis plus rien.","Les investigateurs se rencontrent dans le train de Saint-Chély ou dans la carriole d'Augustin : ils ont tous le même nom en tête."]},{"title":"L'auberge et le hameau","items":["L'auberge-épicerie Chabert : la salle, quatre chambres à l'étage, le tabac, le sel, le courrier. Léontine est veuve ; son fils Paulin, seize ans, fend le bois et fait partie des veilleurs.","Le hameau : neuf fermes, l'église Saint-Ferréol et son cimetière, le presbytère, le four commun et la maison de Rosalie contre lui, et tout en haut le **Mas-Haut** des Malafosse, avec sa grande grange.","Au-dessus du hameau, au bord de la forêt, le **Plan des Feux** : on y entasse déjà des fagots et des souches. La vieille draille entre dans la forêt à cet endroit.","Le temps : froid sec samedi et dimanche ; neige la nuit du dimanche au lundi ; grosse neige le mardi soir, qui coupe la route de Saint-Chély jusqu'au vendredi."]}],"npcs":["leontine","augustin","firmin"],"handouts":["derniere-lettre","reponse-aubergiste","rapport-boissonnade","liste-emile"],"ambience":["wind","village-night","fireplace"],"sfx":["door-open","dog-bark","footsteps"],"next":["l-eglise"]},{"id":"l-eglise","title":"L'église Saint-Ferréol","lead":"Dimanche 28 : la messe, le jeune curé et ses registres. Un étranger « parti par la draille » tous les sept ans.","screen":{"place":"church","preset":"fog","time":"day"},"readAloud":["La cloche sonne dans un air si froid qu'il en paraît cassant. L'église est petite, basse, en granit gris, avec un clocher plat comme un mur percé de deux arches. Tout le hameau est là, en noir, les hommes d'un côté, les femmes de l'autre.","Quand vous entrez, les têtes se tournent ensemble, puis se détournent. Au premier rang, une vieille femme ne vous quitte pas des yeux. À côté d'elle, un garçon maigre tient son béret à deux mains.","Le curé est jeune, presque un séminariste. Il prêche sur la Toussaint et sur l'étranger qu'il faut accueillir. Personne ne lève les yeux. Au moment du cantique, personne ne chante."],"flow":[{"title":"Observer la messe","roll":{"type":"skill","options":["psychology","spot-hidden"]},"success":"Quand le curé parle d'accueillir l'étranger, un grand paysan aux mains énormes ({{npc:malafosse}}) serre les mâchoires ; la vieille femme du premier rang ({{npc:rosalie}}) ferme les yeux ; la femme du grand paysan ({{npc:marguerite}}) pleure sans bruit.","failure":"Une messe de campagne, pressée, sans chants.","extra":"Le hameau ne chante plus en public en octobre des années de sept. L'abbé l'a remarqué : « L'an dernier, ils chantaient tous. »"},{"title":"Le garçon","text":"À la sortie, le garçon du premier rang, {{npc:toinou}}, passe tout près d'un investigateur et souffle : « Vous cherchez le Monsieur à la machine ? Au cimetière, à l'angélus du soir. Pas tous. » Sa grand-mère le tire par le bras.","extra":"Si personne ne l'a remarqué, il glisse un billet sous la porte de l'auberge dans l'après-midi.","goto":["le-cimetiere"]},{"title":"L'abbé Massebeuf","text":"{{npc:massebeuf}} invite les investigateurs au presbytère, ravi de parler à des gens instruits. Il a connu Émile : « Charmant. Il voulait voir mes registres, pour les noms des anciens chanteurs. Il est parti sans dire au revoir. »","roll":{"type":"skill","options":["charm","persuade"]},"success":"Il ajoute ce qui le tracasse. Le dimanche 7 octobre, jour où Malafosse aurait conduit Émile à la gare, Malafosse était à la messe, au premier rang, comme toujours. Et depuis trois semaines, chaque soir, Marguerite Malafosse monte à la grange un plateau couvert : « Pour un chien malade, m'a-t-elle dit. Un chien qui mange de la soupe et du pain blanc. »","failure":"Il parle de sa paroisse difficile, de ses paroissiens fermés comme leurs maisons. Il faudra revenir le voir (il ne refuse jamais une visite)."},{"title":"Les registres","text":"Si on lui parle des feux ou des étrangers, l'abbé hésite, puis ouvre l'armoire de la sacristie : « Je voulais en parler à quelqu'un qui ne soit pas d'ici. » Il montre les notes en marge, à la page du 1er novembre → {{handout:registres}}.","roll":{"type":"skill","options":["library-use"]},"success":"Ils remontent toute la série : une note tous les sept ans, sans faute, depuis 1802 (les registres plus anciens ont brûlé à la Révolution). Les passants logeaient toujours au Mas-Haut ou chez les Chabert. 1928 est une année de sept.","failure":"Ils ne voient que les notes choisies par l'abbé. Toute la série leur prendra la journée de lundi, que l'abbé leur offre volontiers ; le schéma des sept ans, lui, se voit déjà.","pushed":"Ils trouvent tout, mais Léontine, venue porter des œufs, les voit penchés sur le registre de 1921. Le soir, le hameau sait."},{"title":"Le cimetière, de jour","text":"Le cimetière entoure l'église. Ceux qui y passent après la messe peuvent voir, sans jet, la tombe de la Muda et la croix de l'inconnu de 1922 (détails dans [[le-cimetiere]])."}],"notes":[{"title":"Ce que l'abbé ignore, ce qu'il a","items":["Il ne sait rien du Mange-Temps. Il croit à une coutume ancienne et honteuse : il imagine qu'on chasse les étrangers du hameau la nuit des feux, peut-être qu'on les dépouille.","Il a peur de ce qu'il pourrait découvrir, et d'être muté s'il fait un scandale. Il est d'Ispagnac, près de Mende : pour le hameau, il est presque un étranger.","Il possède un phonographe à cylindres, cadeau de sa mère, avec lequel il écoute des airs d'opéra : voir [[les-cylindres]]."]}],"npcs":["massebeuf","toinou","rosalie","malafosse","marguerite"],"handouts":["registres"],"ambience":["village-day","wind","crows"],"sfx":["door-creak","footsteps"],"next":["le-cimetiere","les-cylindres"]},{"id":"le-cimetiere","title":"Le cimetière à l'angélus","lead":"Toinou confie les cylindres et dit où est le Monsieur. La tombe de la Muda, celle de l'inconnu.","screen":{"place":"graveyard","preset":"fog","time":"dusk"},"readAloud":["Le cimetière entoure l'église, derrière un muret de pierres sèches. Les croix de fer penchent toutes du même côté, celui du vent. La brume monte de la tourbière et noie les tombes jusqu'à mi-hauteur.","L'angélus sonne trois fois trois coups. Quand le dernier se perd, une petite silhouette se détache de l'ossuaire, une boîte en fer serrée contre la poitrine."],"flow":[{"title":"Gagner la confiance de Toinou","text":"Il a onze ans, il a froid, et il a peur d'être vu. Il parle vite, moitié français, moitié patois. S'ils sont plus de deux, il recule.","roll":{"type":"skill","options":["charm","psychology","persuade"]},"success":"Il raconte tout ce qu'il sait (note **Ce que dit Toinou**) et donne la boîte.","failure":"Il donne la boîte, dit seulement « Il est pas parti, le Monsieur. Il est chez les Malafosse » et s'enfuit en entendant des pas. Il reviendra parler le lendemain, derrière la maison de sa grand-mère.","pushed":"Il dit tout, mais il pleure fort, et Rosalie, qui le cherchait, l'entend et l'emmène. Elle sait désormais que les investigateurs ont les cylindres."},{"title":"La boîte","text":"Une boîte à biscuits en fer. Dedans, roulés dans un tricot, deux cylindres de cire brune dans leurs étuis, marqués à l'encre : *41, La Sagne, 4-X-28* et *42, La Sagne, 4-X-28*. Il faut un phonographe : l'abbé en a un.","extra":"Toinou sait chanter les trois couplets : il les a écoutés vingt fois en cachette sur la machine du Monsieur. Il refuse de les chanter ici : « Pas dehors. Pas ce mois-ci. »","goto":["les-cylindres"]},{"title":"La tombe de la Muda","text":"Contre le mur de l'église, une dalle très ancienne, que quelqu'un fleurit encore de bruyère → {{handout:tombe-muda}}.","roll":{"type":"skill","options":["language-other:occitan","history"]},"success":"*La Muda*, c'est « la muette ». *Barrèt la draia, cantèt un còp* : « elle ferma la draille, elle chanta une fois ». Une muette qui a chanté une fois.","failure":"Le patois leur échappe. Toinou ou l'abbé le traduisent si on leur demande."},{"title":"La croix de l'inconnu","text":"Dans le coin des pauvres, une croix de bois : *Un inconnu, mort dans la forêt, 1922.* Le médecin reconnaît la date de son rapport. Le registre de 1921 donne un nom à l'homme : Joseph Lafon, de Langogne.","extra":"J. L. : les initiales du mouchoir du rapport. L'abbé Cayrel, l'ancien curé, l'a enterré sans chercher plus loin."},{"title":"Quelqu'un regarde","roll":{"type":"skill","options":["listen","spot-hidden"]},"success":"Derrière le muret, une lanterne sourde : Paulin Chabert, le fils de l'aubergiste, épie. Il file vers le Mas-Haut. Rattrapé, il ment mal et a très peur de Malafosse.","failure":"Ils ne voient personne. Le lendemain, Malafosse sait qu'ils ont parlé à Toinou. Il ne touchera pas à l'enfant (le petit-fils de la chanteuse), mais le hameau se ferme."}],"notes":[{"title":"Ce que dit Toinou","items":["Le Monsieur lui laissait tourner la manivelle et écouter les cylindres. Il lui a appris à dire « cylindre quarante et un » comme lui.","Le vendredi 5 octobre, le Monsieur lui a donné la boîte : « Garde-les, ne les montre à personne, même pas à ta grand-mère. Je reviendrai les chercher. »","Le Monsieur n'est pas parti : le samedi 20 octobre, en passant avec les chèvres derrière la grange du Mas-Haut, Toinou l'a entendu à travers les planches du fenil chanter tout bas la chanson des feux. Il est sûr de la voix.","Sa grand-mère, Rosalie, « chante pour les feux ». Cette chanson, on ne la chante jamais devant un étranger, et jamais en octobre, sauf pour la pierre, le jeudi soir. C'est la *cançon de la barra*.","Mercredi, c'est la nuit des feux. On les allume au Plan des Feux, et vers minuit les hommes descendent la draille jusqu'à la Pierre-Plantée. Les enfants restent à la maison, volets fermés.","Il ne sait pas ce qui arrive aux passants. On lui a dit qu'on les « renvoie chez eux par la draille ». Il a peur quand même."]}],"npcs":["toinou"],"handouts":["tombe-muda"],"ambience":["wind","crows"],"sfx":["owl","footsteps","latch"],"next":["les-cylindres"]},{"id":"les-cylindres","title":"Les cylindres","lead":"Le phonographe du presbytère : la chanson de Rosalie, puis la voix qui lui répond.","screen":{"place":"library","preset":"candle","time":"night"},"readAloud":["L'abbé a posé le phonographe sur la table de son bureau, entre deux piles de bréviaires. Le pavillon de fer-blanc, peint de fleurs, ressemble à un liseron géant. La lampe fait monter les ombres jusqu'au plafond.","Le cylindre tourne. D'abord un grésillement, comme une pluie très lointaine. Puis une voix d'homme, nette et appliquée : « Cylindre quarante et un. La Sagne-Noire, le quatre octobre mil neuf cent vingt-huit. »"],"flow":[{"title":"Cylindre 41 : la chanson","text":"Derrière la voix d'Émile, du vent dans des arbres. Puis une voix de vieille femme, cassée mais juste, chante trois couplets en patois sur un air lent → {{handout:cylindres}}. La sœur reconnaît son frère ; ceux qui ont entendu Rosalie à l'arrivée reconnaissent sa voix.","roll":{"type":"skill","options":["language-other:occitan"]},"success":"Ils comprennent les trois couplets (la traduction est dans le document).","failure":"L'abbé traduit en hésitant, et se signe à « il marche à rebours et il sait mon nom ».","extra":"Sans l'abbé ni Toinou, et sans Langue (occitan) : seulement l'air et quelques mots (draia, lop, nuèch)."},{"title":"Retenir l'air","text":"Pour chanter le chant le 31, il faut l'air et les mots des trois couplets.","roll":{"type":"characteristic","options":["INT"]},"success":"Après trois écoutes, l'investigateur sait l'air et les paroles.","failure":"Il faudra réécouter le cylindre, ou se faire chanter le chant par Toinou."},{"title":"Cylindre 42 : la réponse","text":"Rosalie reprend le troisième couplet, puis s'arrête net. Silence. Et, de plus loin, du côté de la forêt, une voix de jeune fille, claire, très douce, chante le même air avec d'autres paroles. Elle est sur la cire comme le reste.","roll":{"type":"san","label":"La voix de jeune fille","san":"0/1D3"}},{"title":"Comprendre la réponse","roll":{"type":"skill","options":["language-other:occitan"]},"success":"« Ma draille est à vous, votre temps est à moi. Donnez-moi une voix, ou donnez-moi un corps. »","failure":"L'abbé, livide, ne traduit que la fin : « …una votz o un còrs… Une voix, ou un corps. »"},{"title":"Les derniers mots","text":"Le chant s'arrête. Grésillement. Puis la voix de jeune fille dit, en français, exactement sur le ton appliqué d'Émile : « Cylindre quarante-trois. La Sagne-Noire, le trente et un octobre. » Il n'y a pas de cylindre quarante-trois.","roll":{"type":"san","label":"Cylindre quarante-trois","san":"1/1D4"},"extra":"Le 31 octobre, c'est mercredi : la nuit des feux."},{"title":"L'abbé","text":"Massebeuf croit d'abord à une farce, une fille cachée dans les bois. Si les investigateurs lui parlent des registres, il comprend : « Ils vont le donner à quelque chose. » Désormais, il les aide de son mieux, mais il ne fera rien en public sans eux.","extra":"Il prête le phonographe et propose de cacher les investigateurs au presbytère si le hameau se retourne contre eux."},{"title":"Cette nuit-là","roll":{"type":"skill","options":["listen"]},"success":"Vers trois heures, sous la fenêtre, quelqu'un fredonne l'air du cylindre, très bas, avec une voix de jeune fille. Il n'y a personne dehors, et la neige qui commence ne porte aucune trace (SAN 0/1).","failure":"Ils dorment mal. Au matin, il a neigé.","goto":["les-traces"]}],"npcs":["massebeuf","toinou"],"handouts":["cylindres"],"ambience":["clock","wind"],"sfx":["footsteps"],"next":["les-traces"]}]},{"id":"draille","title":"La vieille draille","scenes":[{"id":"les-traces","title":"Les traces dans le champ de la Croix","lead":"Lundi 29 à l'aube : des traces dans la neige qui commencent au milieu d'un champ. Le garde Pradal et ses cartes.","screen":{"place":"moor","preset":"snow","time":"day"},"readAloud":["La neige est tombée toute la nuit, une neige fine et sèche qui crisse sous les pas. Le plateau est blanc jusqu'aux bois, et le ciel a la couleur du granit.","Au milieu du champ qui monte vers le Mas-Haut, une file de traces commence d'un coup, dans la neige vierge, sans rien autour. Elles traversent le champ en ligne droite, s'arrêtent au mur de pierres sèches, tournent, et reviennent mourir à l'endroit exact où elles sont nées."],"flow":[{"title":"Qui les montre","text":"Le garde {{npc:pradal}}, en tournée à l'aube, vient chercher les investigateurs à l'auberge (surtout s'il y a un forestier parmi eux) : « Venez voir ça avant qu'ils l'effacent. » Sinon, Toinou les a vues en sortant les chèvres et court les prévenir.","extra":"Une heure après, Malafosse et deux veilleurs viennent piétiner le champ en traînant des fagots, sans un mot."},{"title":"Lire les traces","roll":{"type":"skill","options":["track","natural-world"]},"success":"Des empreintes larges comme une assiette, fendues comme un sabot, mais longues, avec derrière la marque d'une articulation : la chose marchait sur quatre membres. Et les pointes regardent dans le mauvais sens, vers l'endroit d'où elle vient, comme si ses jambes pliaient à rebours. Au fond de chaque trace, la neige est gelée en verre.","failure":"Des traces énormes, qu'aucune bête du pays ne laisse.","pushed":"À force de suivre et de mesurer, ils sont encore dans le champ quand Malafosse arrive avec ses hommes : « Ça, c'est chez moi. Allez-vous-en. »"},{"title":"La neige vierge","text":"Là où les traces commencent et finissent, rien : pas d'arbre, pas de rocher, pas d'autre empreinte. La chose est sortie du milieu du champ et y est rentrée.","roll":{"type":"san","label":"Des traces qui viennent de nulle part","san":"0/1D2"}},{"title":"Jusqu'au mur","text":"Les traces s'arrêtent net au mur de pierres sèches qui ferme le champ. Sur la pierre d'angle, une croix gravée, très ancienne. De l'autre côté du mur, à trente pas : la grande grange du Mas-Haut. La neige est tassée en rond devant le mur : la chose s'est tenue là longtemps, face à la grange.","extra":"Elle est venue regarder son passant, jusqu'à la limite des terres du hameau. Une croix marque chacune de ces limites."},{"title":"D'où elles viennent","text":"Pradal sort de sa sacoche ses calques et ses notes → {{handout:cartes-pradal}}.","roll":{"type":"skill","options":["navigate","library-use"]},"success":"Sur le cadastre de 1834, avant le défrichement, la vieille draille traversait le champ exactement là où naissent les traces. La chose a marché sur une route qui n'existe plus.","failure":"Pradal finit par le leur montrer lui-même, après une heure de mesures dans le froid : la draille passait là."},{"title":"Pradal","text":"Mis en confiance (un forestier parmi eux, ou ces traces), il raconte ses mesures et ses montres (note **Ce que sait Pradal**) et propose de les guider sur la draille, jusqu'aux ruines du prieuré. « Chaque 31 octobre, Malafosse vient me dire de ne pas sortir de la nuit. Poliment. Avec son fusil. »","goto":["la-draille","le-prieure"]}],"notes":[{"title":"Ce que sait Pradal","items":["La vieille draille ne figure plus sur les cartes des Eaux et Forêts depuis la route forestière de 1912, qui la double à trois cents mètres. Personne ne l'entretient, et pourtant elle reste nette : pas une ronce, pas un arbre tombé en travers.","En juin 1925, il l'a arpentée à la chaîne, de la Pierre-Plantée au prieuré : jamais deux fois la même longueur.","Sa montre retarde chaque fois qu'il revient de la draille : de vingt minutes, une fois de près de deux heures.","Chaque 31 octobre, il reste chez lui. Il a entendu chanter, de loin, toute la nuit. En 1921, vers minuit, un coup de fusil.","En 1925, il a trouvé la dalle de l'autel du prieuré déplacée par un éboulis, et a pensé « au trésor des moines ». Il n'a pas osé la soulever seul (voir [[le-prieure]])."]}],"npcs":["pradal","malafosse","toinou"],"handouts":["cartes-pradal"],"ambience":["wind","crows","nature-day"],"sfx":["dog-bark","footsteps"],"next":["la-draille"]},{"id":"la-draille","title":"La vieille draille","lead":"La route des troupeaux dans la forêt, de jour : la Pierre-Plantée, des pas qui sont les leurs, une battue d'un autre siècle.","screen":{"place":"forest","preset":"fog","time":"day"},"readAloud":["Au Plan des Feux, les fagots sont déjà en tas, hauts comme des hommes. Derrière eux, la draille entre dans la forêt : un chemin creux, large de trois charrettes, bordé de deux murets moussus, si droit qu'on n'en voit pas la fin.","Sous les hêtres, la neige n'est presque pas tombée. Il fait plus sombre qu'il ne devrait à cette heure. Au loin, des sonnailles tintent, comme celles d'un grand troupeau qui monte vers l'estive. Il n'est plus passé de troupeau sur cette draille depuis cinquante ans."],"flow":[{"title":"Les sonnailles","roll":{"type":"skill","options":["listen"]},"success":"Le troupeau passe tout près : des bêlements, le souffle des chiens, un berger qui siffle un air qu'ils connaissent peut-être (celui du cylindre). Rien ne bouge sur la draille. Puis plus rien.","failure":"Les sonnailles s'éloignent et se taisent.","extra":"À trois jours des feux, la draille est déjà mince : on y entend d'autres années."},{"title":"La Pierre-Plantée","text":"À mi-chemin, dans une clairière où un ruisseau coupe la draille sur des dalles, se dresse un menhir de granit plus haut qu'un homme. À son pied : des moignons de torches brûlées, des brins de laine noire noués autour de la pierre. Au sommet, quelqu'un a posé un caillou blanc, rond comme un œuf.","roll":{"type":"skill","options":["spot-hidden"]},"success":"Dans la mousse, au pied du menhir, un bouton de cuivre frappé d'une fleur de lys : un bouton d'uniforme de dragon du roi, comme ceux des soldats qui chassaient la Bête en 1765. Il est presque neuf.","failure":"Des restes de torches et de laine : le lieu a beaucoup servi.","extra":"C'est ici que le passant est remis au Mange-Temps, à minuit. Le hameau appelle la clairière le Pas du Mange-Temps."},{"title":"Des pas devant eux","text":"Après la pierre, sur une plaque de neige entre les arbres, des empreintes fraîches viennent vers eux : souliers de ville, brodequins, bottes. Celui qui les examine reconnaît les semelles : ce sont les leurs, venant en sens inverse, dans une neige où ils ne sont jamais passés.","roll":{"type":"san","label":"Leurs propres pas","san":"0/1D3"},"extra":"Ce sont leurs traces de la nuit de mercredi. S'ils comptent les paires, ne dites rien : laissez-les compter."},{"title":"La battue","text":"Le brouillard monte du ruisseau.","roll":{"type":"group","options":["spot-hidden"]},"success":"Une ligne d'hommes traverse la draille à cinquante pas : des paysans en bonnet, armés de fourches et de faux, deux cavaliers en habit bleu, des torches en plein jour. Ils ne voient personne. Ils disparaissent entre les arbres sans un bruit de pas (SAN 0/1 pour ceux qui les ont vus).","failure":"Une odeur de poudre noire et de cheval, et pas de cheval.","extra":"Une battue de l'hiver 1765."},{"title":"Mesurer la draille","text":"Avec Pradal, ou un investigateur qui compte ses pas : la Pierre-Plantée est à vingt minutes du Plan des Feux à l'aller, à une heure au retour. Les montres ne sont plus d'accord entre elles.","roll":{"type":"skill","options":["navigate"]},"success":"Ils sortent de la forêt en bas, sous les ruines du prieuré, à l'heure prévue.","failure":"Ils sortent sous le prieuré au crépuscule, alors qu'ils se croyaient en début d'après-midi. Il faudra visiter les ruines à la lanterne, ou revenir demain.","pushed":"Ils tournent en rond. Quand ils sortent enfin, c'est la nuit, à la lisière du Plan des Feux, et une lanterne brûle, posée sur les fagots. Personne en vue (SAN 0/1).","goto":["le-prieure"]}],"notes":[{"title":"La draille de jour, à l'approche des feux","items":["Du Plan des Feux à la Pierre-Plantée : environ un kilomètre (« vingt minutes », plus ou moins). De la Pierre-Plantée au prieuré : encore un kilomètre, en descente.","Plus on approche du 31, plus le pli s'entend : sonnailles, voix, odeurs d'autrefois. De jour, rien ne peut toucher les investigateurs, et ils ne peuvent rien toucher.","Hors de la draille, la forêt est ordinaire : hêtres, pins sylvestres, chaos de granit."]}],"npcs":["pradal"],"ambience":["wind","crows"],"sfx":["footsteps","owl"],"next":["le-prieure"]},{"id":"le-prieure","title":"Les ruines de Saint-Ferréol","lead":"Le prieuré fortifié sur son rocher : les années gravées, le livre du prieur sous la dalle d'autel.","screen":{"place":"castle","preset":"snow","time":"dusk"},"readAloud":["Le prieuré se dresse sur un éperon de granit au-dessus de la draille : une tour carrée sans toit, des pans de murailles, l'abside d'une chapelle ouverte au ciel. Des sapins ont poussé dans la nef. La neige recommence, en flocons lourds qui tombent droit.","Dans l'abside, la pierre est couverte d'inscriptions grattées au couteau. Des croix et des dates, en colonne, comme sur un mur de prison."],"flow":[{"title":"Les années gravées","text":"Sans jet : vingt-deux croix, chacune avec une année. 1774, 1781, 1788… jusqu'à 1921. Tous les sept ans, sans manquer. Sous 1921, la pierre a été aplanie au ciseau, toute neuve, pour une vingt-troisième date.","extra":"Le bayle des veilleurs (aujourd'hui Malafosse) monte graver l'année le jour de la Toussaint. Les dates sont celles des registres."},{"title":"La dalle d'autel","text":"Au fond de l'abside, la dalle de l'autel est de travers, déplacée par l'éboulis de 1925. Frappée, elle sonne creux.","roll":{"type":"characteristic","options":["STR"]},"success":"À plusieurs, ils la font basculer. Dessous, dans une cavité, un coffret doublé de plomb. Dedans, roulé dans une toile cirée, un registre relié de cuir : le livre du prieur → {{handout:livre-prieur}}.","failure":"Elle ne bouge pas. Avec un levier (une branche de sapin, la pioche de Pradal), elle finit par céder, mais la nuit tombe.","pushed":"Elle bascule et écrase une main (1D3), mais le coffret est là."},{"title":"Lire le livre","text":"Un français du siècle dernier, serré, mêlé de comptes de seigle et de cire.","roll":{"type":"skill","options":["library-use","history"]},"success":"Ils trouvent tout de suite les passages du document.","failure":"Il faudra une soirée entière à la lampe pour les trouver : ils les ont le lendemain matin."},{"title":"La vraie barre","text":"Le prieur a recopié le dernier couplet tel que Jeanne l'a chanté : *Barri la draia amb ma votz, que ma votz demòre de l'autre costat.* « Je ferme la draille avec ma voix, que ma voix reste de l'autre côté. » Le hameau, lui, chante *amb lo passant* : « avec le passant ».","extra":"C'est la clé du choix final : la vraie barre ferme la draille sans passant, tant que vit le chanteur, mais celui qui la chante perd sa voix."},{"title":"Ce que cela coûte","text":"Les bergers de quinze ans devenus vieillards, la voix de Jeanne, vingt-deux passants.","roll":{"type":"san","label":"Le livre du prieur","san":"1/1D6"}},{"title":"Le retour","text":"S'ils redescendent la draille de nuit, quelque chose descend la draille derrière eux, sans bruit, toujours à la limite de la lumière. Ils ne le voient pas, mais dans les clairières, la neige fraîche porte derrière eux de grandes traces tournées à rebours.","roll":{"type":"san","label":"Ce qui les suit","san":"0/1D2"},"goto":["chez-rosalie","le-mas-haut"]}],"notes":[{"title":"Le prieuré","items":["Prieuré de Saint-Ferréol : fondé au XIIe siècle pour accueillir les bouviers de la draille, fortifié pendant les guerres de Religion, vendu comme bien national en 1791 et démonté pour sa pierre.","Dom Aurélien Vaissière, prieur de 1758 à sa mort en 1779, a caché son livre sous l'autel. Il est enterré dans la nef, sous une dalle sans nom.","La tour : un escalier à vis jusqu'à mi-hauteur. De là, on voit le Plan des Feux, le hameau et toute la draille, une saignée droite dans la forêt."]}],"npcs":["pradal"],"handouts":["livre-prieur"],"ambience":["wind-howling","crows"],"sfx":["latch","footsteps"],"next":["chez-rosalie","le-mas-haut"]}]},{"id":"veille","title":"Ceux qui chantent","scenes":[{"id":"chez-rosalie","title":"Rosalie","lead":"La chanteuse des feux, face à ce que savent les investigateurs. Elle seule connaît tout le chant.","screen":{"place":"farm","preset":"candle","time":"dusk"},"readAloud":["La maison de Rosalie est collée au four commun, si basse qu'il faut se pencher pour entrer. Une seule pièce, une cheminée immense où pend une marmite, un lit clos, et des chèvres qu'on entend remuer derrière la cloison.","La vieille femme ne se lève pas. Elle tricote près du feu, et ses doigts noueux vont très vite. « Je sais pourquoi vous venez. Toinou, va voir aux chèvres. »"],"flow":[{"title":"La faire parler","text":"{{npc:rosalie}} nie tout tant qu'on n'a pas de preuve. Elle cède devant l'une de ces choses : sa propre voix sur le cylindre, le livre du prieur, la tombe de la Muda, les registres, ou l'idée que Toinou portera un jour une torche sur la draille. Avec une preuve en main : un dé bonus.","roll":{"type":"skill","options":["persuade","psychology","charm"]},"success":"Elle pose son tricot et raconte (note **Ce que dit Rosalie**).","failure":"« Vous êtes des passants. Repartez tant que la route est ouverte. » Le lendemain matin, elle les fait chercher par Toinou : la preuve qu'ils ont laissée derrière eux l'a empêchée de dormir.","pushed":"Elle parle, mais d'une traite, en patois, et finit en criant. Malafosse l'apprend dans l'heure."},{"title":"Les deux barres","text":"Si on lui montre le livre du prieur, ou si on lui demande pourquoi la Muda était muette : « Il y a deux façons de finir le chant. Avec le passant, ou avec sa voix. La Jeanne a donné la sienne. Depuis, on donne des passants. » Elle chante tout bas, pour la première fois, les deux versions du dernier couplet."},{"title":"Que fera-t-elle mercredi ?","text":"Si les investigateurs disent qu'ils ne laisseront pas faire, elle comprend que quelque chose finit. Ce qu'elle décide dépend de la façon dont on lui parle."},{"title":"Elle chantera la vraie barre","branch":"Si Rosalie accepte de donner sa voix","text":"Il faut qu'on lui parle de Jeanne, de Toinou, des huit passants, avec respect.","success":"Elle mènera les couplets aux feux, puis chantera la vraie barre à la Pierre-Plantée. Elle demande une chose : qu'on emmène Toinou loin du hameau après. Elle sait qu'elle a soixante-dix-huit ans, et que la draille ne restera fermée que tant qu'elle vivra."},{"title":"Elle apprendra la barre à quelqu'un","branch":"Si un investigateur veut la chanter","text":"Elle lui apprend l'air et les mots, à voix basse, la nuit, volets clos. Elle le prévient : « Après, tu ne parleras plus. Jamais. Et la nuit des feux, tu t'entendras chanter dans la forêt. »","roll":{"type":"characteristic","options":["INT"]},"success":"Il sait le chant entier et la vraie barre.","failure":"Il lui faudra une seconde nuit (le mardi soir), ou le livre du prieur sous les yeux à la Pierre-Plantée."},{"title":"Elle chantera comme toujours","branch":"Si on la menace ou si on la méprise","text":"Elle chantera la barre avec le passant, comme depuis 1872. Mais le doute est là : à la Pierre-Plantée, un jet de Persuasion difficile peut encore la retourner ([[la-draille-de-nuit]])."},{"title":"Ce qu'elle exige","text":"« Ne lui prenez pas son passant si vous n'avez personne pour la vraie barre. Il passera, et ce ne sera pas un loup qu'on tue avec un fusil. »","goto":["le-mas-haut","les-feux"]}],"notes":[{"title":"Ce que dit Rosalie","items":["Elle est née Bastide, en 1850, de la famille de la Muda. Le chant passe aux filles Bastide. Sa mère le lui a donné en 1872 ; depuis, elle a chanté huit grandes nuits et vu partir huit passants.","On ne chante jamais la barre devant le passant : un passant qui sait le chant pourrait le chanter lui-même et donner sa voix au lieu de son corps. C'est pour ça que personne n'a voulu chanter devant le Monsieur, et qu'on l'a enfermé si tôt quand on a su qu'il avait la chanson dans sa machine.","Ce qui vient : *lo Manja-Temps*, le Mange-Temps. Elle l'a vu huit fois, de loin, à la lueur des torches. « Grand comme un arbre mort, sur quatre pattes qui plient à rebours. Il n'a pas d'yeux. Il a des visages. »","Il mange le temps : ceux qu'il prend, on ne les revoit pas, ou on les retrouve vieux comme la terre. Elle a su pour le chemineau de 1922.","La voix qui répond, c'est celle de Jeanne. « Il l'a gardée. Il chante avec. Toutes les Bastide le savent. »","On dit chez les Bastide que la draille serait restée fermée tant que Jeanne vivait (elle est morte en 1819). Personne n'a jamais voulu essayer.","Elle a honte. Elle n'a jamais osé donner sa voix. Elle a peur du silence."]}],"npcs":["rosalie","toinou"],"ambience":["fireplace","clock","wind"],"sfx":["knocking","door-open"],"next":["le-mas-haut","les-feux"]},{"id":"le-mas-haut","title":"Le Mas-Haut","lead":"La ferme des Malafosse : le fenil cadenassé, Émile drogué, et ce que fera le hameau s'il perd son passant.","screen":{"place":"farm","preset":"night","time":"night"},"readAloud":["Le Mas-Haut domine le hameau : une longue ferme de granit au toit de lauzes, et contre elle la grange, si grande qu'une charrette chargée monte par une rampe de terre jusqu'au fenil. Une lampe brûle à la fenêtre de la cuisine.","Un chien aboie une fois, puis se tait. Par les planches disjointes du fenil, une voix d'homme très faible fredonne un air lent."],"flow":[{"title":"Approcher","roll":{"type":"skill","options":["stealth"]},"success":"Ils atteignent la rampe de la grange sans être vus. Le chien, Mouret, gronde sans aboyer ; un morceau de viande le fait taire.","failure":"Mouret aboie à pleine gorge. {{npc:malafosse}} sort sur le seuil, le fusil à la main : « Qui va là ? »","pushed":"Le chien mord un investigateur (1D4) et tout le Mas-Haut se réveille."},{"title":"Le fenil","text":"En haut de la rampe, une porte de planches fermée par un cadenas neuf.","roll":{"type":"skill","options":["locksmith","mechanical-repair"]},"success":"Le cadenas s'ouvre sans bruit.","failure":"Il faut forcer la porte : ça prend du temps et fait du bruit (le chien, puis Malafosse)."},{"title":"Émile","text":"Sur un lit de paille, sous trois couvertures : {{npc:emile}}, barbe de trois semaines, yeux vitreux, pupilles en tête d'épingle. Une cuvette, un pot de chambre, un bol de soupe à moitié plein, une fiole brune. Son phonographe est sous une bâche, dans un coin.","roll":{"type":"skill","options":["medicine","first-aid"]},"success":"Laudanum à forte dose, depuis des semaines. Avec du café, de la marche et du froid, il retrouve ses esprits en quelques heures. Il pourra marcher, lentement, et parler.","failure":"Il ne reconnaît personne (sauf sa sœur) et marmonne la chanson. Il faudra le porter, et il ne sera lucide qu'au matin.","extra":"Ce qu'il sait : note **Ce que dit Émile**. Son carnet est dans sa veste."},{"title":"Malafosse","text":"S'il les surprend, Malafosse ne veut pas tuer : il veut son passant. Il parle avant de tirer : « Vous ne savez pas ce que vous faites. Vous croyez qu'on aime ça ? Si personne ne descend mercredi, c'est toute la Margeride qui y passe. »","roll":{"type":"skill","options":["persuade"],"difficulty":"hard"},"success":"Il hésite. Si on lui montre la vraie barre (le livre du prieur) et que Rosalie est d'accord, il laisse partir Émile, à condition que le chant soit fini mercredi. Sinon, il les laisse partir, mais le hameau cherchera un autre passant.","failure":"Il appelle les veilleurs (Fulcran et Paulin arrivent en trois rounds). Combat, ou fuite dans la neige avec Émile sur le dos."},{"title":"Que faire d'Émile ?","text":"Le libérer tout de suite, ou attendre la nuit des feux."},{"title":"Le laisser au fenil","branch":"Si les investigateurs le laissent","text":"Pour ne pas alerter le hameau, ou parce qu'ils comptent agir mercredi. On le fera descendre la draille le 31 à 23 heures ([[les-feux]])."},{"title":"L'emmener","branch":"Si les investigateurs l'emmènent","text":"Au matin, Marguerite trouve le fenil vide. La neige tombe dru le mardi soir : la route de Saint-Chély est coupée, personne ne sort du plateau avant vendredi. Le hameau cherche un autre passant (note **Si le hameau perd son passant**). Le presbytère est la seule cachette sûre, et pas pour longtemps."},{"title":"Marguerite","text":"De jour, prise seule au lavoir ou à l'église, {{npc:marguerite}} craque vite. Elle avoue le laudanum, acheté à la pharmacie de Saint-Chély « pour mes douleurs », et dit qu'elle prie chaque soir pour le Monsieur.","roll":{"type":"skill","options":["psychology","persuade"]},"success":"Elle aidera : elle laissera le cadenas ouvert la nuit de mardi, ou elle donnera à Émile de l'eau au lieu du laudanum le mercredi, pour qu'il soit lucide sur la draille.","failure":"Elle se signe et ferme sa porte. Elle ne dira rien à son mari, ni pour, ni contre.","goto":["les-feux"]}],"notes":[{"title":"Ce que dit Émile","items":["Le jeudi 4 octobre au crépuscule, il a suivi Rosalie jusqu'à la Pierre-Plantée, le phonographe dans un sac, et a enregistré caché derrière un bloc, à vingt pas.","La voix de jeune fille venait « de la draille, mais de plus loin que la draille, comme du fond d'un puits couché ». Rosalie s'est enfuie. Lui a vu quelque chose de très grand bouger dans le brouillard, de l'autre côté de la pierre.","Le lendemain, Léontine a fouillé sa chambre. Il a confié les cylindres à Toinou et écrit au musée.","Le samedi 6, souper au Mas-Haut, un vin chaud très sucré. Il s'est réveillé dans le fenil.","Il entend les Malafosse parler sous le plancher : « mercredi », « la Pierre », « le passant ».","Son carnet contient les paroles des trois couplets, transcrites et traduites, et l'air noté.","Il sait l'air par cœur : il l'a fredonné trois semaines pour ne pas devenir fou. S'il apprend ce que coûte la vraie barre, il peut proposer de la chanter lui-même : « Je suis venu prendre leurs voix. Je peux bien leur laisser la mienne. »"]},{"title":"Si le hameau perd son passant","items":["Malafosse réunit les veilleurs le mardi soir chez Chabert. Il faut un étranger : l'abbé Massebeuf (« il n'est pas d'ici ») ou l'un des investigateurs.","Le mercredi au souper, Léontine verse du laudanum dans la soupe des investigateurs. Trouver Objet Caché ou Médecine pour remarquer le goût amer ; sinon, jet de CON pour ne pas sombrer avant 22 heures.","Si rien ne marche, les veilleurs prennent l'abbé de force au presbytère, à 22 heures.","Si le hameau apprend que les investigateurs ont la vraie barre et un chanteur, Malafosse peut se rallier (voir [[les-feux]])."]}],"npcs":["emile","malafosse","marguerite","firmin","veilleurs"],"ambience":["village-night","wind"],"sfx":["dog-bark","latch","door-creak","footsteps"],"next":["les-feux"]}]},{"id":"feux","title":"La nuit des feux","scenes":[{"id":"les-feux","title":"Les feux du Plan","lead":"Mercredi 31 : le hameau allume les feux et chante. À 23 heures, la procession descend la draille.","screen":{"place":"moor","preset":"ritual","time":"night"},"readAloud":["À la tombée de la nuit, le Plan des Feux s'embrase d'un coup : sept bûchers en demi-cercle devant la forêt, si hauts que leurs flammes couchent les ombres jusqu'au hameau. Autour d'eux, la neige fond en pluie tiède.","Tout le hameau est là, sauf les enfants. Les hommes portent des torches de résine et des fusils. Les femmes se tiennent par le bras. Personne ne parle.","Une voix de vieille femme s'élève, cassée et juste, et tous reprennent le premier couplet. Derrière les bûchers, la draille est un tunnel noir. Tout au fond, une autre voix, claire, une voix de jeune fille, chante avec eux."],"flow":[{"title":"Où est le passant ?","text":"Selon ce qui s'est passé : Émile, drogué, assis sur un banc entre Malafosse et Fulcran ; ou l'abbé Massebeuf, ou un investigateur drogué, à sa place ; ou personne, si le hameau a été rallié.","extra":"Si les investigateurs ont libéré Émile et se cachent, les veilleurs fouillent le hameau jusqu'à 22 heures, puis prennent l'abbé."},{"title":"Le chant","text":"Le hameau chante les trois couplets en boucle, pendant des heures, autour des feux. Un investigateur qui connaît l'air peut se mêler aux chanteurs sans être remarqué. À chaque fin de couplet, la voix de jeune fille répond, plus proche.","roll":{"type":"san","label":"La voix qui répond","san":"0/1D2"}},{"title":"La procession","text":"À 23 heures, la procession part : Rosalie devant, puis le passant entre deux veilleurs, puis les hommes aux torches. Les femmes restent au Plan et chantent. C'est le dernier moment pour choisir."},{"title":"Enlever le passant","branch":"Si les investigateurs prennent le passant de force","roll":{"type":"skill","options":["stealth"]},"success":"Dans le noir de la draille, ils le tirent derrière le muret. Le hameau ne s'en aperçoit qu'à la Pierre-Plantée.","failure":"Les veilleurs les voient : combat contre Malafosse, Fulcran et les veilleurs. Les fusils claquent sous les arbres.","extra":"Sans passant à minuit et sans la vraie barre, le Mange-Temps passe ([[la-draille-de-nuit]])."},{"title":"Parler au hameau","branch":"Si les investigateurs montrent à tous le livre du prieur","text":"Devant les feux, lire la page de Jeanne et celle de 1774. Un dé bonus si Rosalie se tient à côté d'eux ; réussite automatique si elle annonce elle-même qu'elle chantera la vraie barre.","roll":{"type":"skill","options":["persuade"],"difficulty":"hard"},"success":"Le hameau se tait. Malafosse regarde Rosalie, longtemps. « Alors chante, et que Dieu nous garde. » La procession descend sans passant, et les veilleurs entourent le chanteur.","failure":"Malafosse fait saisir les investigateurs par les veilleurs, sans les blesser s'ils ne résistent pas. On les garde au Plan pendant que la procession descend, sauf s'ils s'échappent (Discrétion ou DEX)."},{"title":"Prendre sa place","branch":"Si un investigateur se propose comme passant","text":"Malafosse accepte : un passant est un passant. L'investigateur descend la draille entre deux veilleurs. À la Pierre-Plantée, s'il connaît la vraie barre, il peut encore la chanter et donner sa voix au lieu de son corps : c'est exactement ce que le hameau redoute depuis 1774."},{"title":"Laisser faire","branch":"Si les investigateurs ne font rien","text":"La procession descend. Ils peuvent la suivre de loin (Discrétion), ou rester au Plan avec les femmes : à minuit, de là-haut, on voit toutes les torches de la draille s'éteindre ensemble.","goto":["la-draille-de-nuit"]}],"notes":[{"title":"Le Plan des Feux, cette nuit","items":["17 h 30 : les feux s'allument. 23 h : départ de la procession. Il faut vingt minutes pour descendre à la Pierre-Plantée (plus ou moins). Minuit : le pli s'ouvre.","Les veilleurs : Malafosse (le bayle), Fulcran, Paulin Chabert et trois autres hommes, avec fusils de chasse et torches.","Tant que les feux brûlent, le Mange-Temps ne sort pas de la draille. S'il passe en 1928, il ne craint que le feu.","Sans Rosalie, le hameau chante faux : à la Pierre-Plantée, les jets de chant se font avec un dé de pénalité, sauf si un investigateur qui sait l'air mène le chant."]}],"npcs":["rosalie","malafosse","firmin","veilleurs","emile","massebeuf","leontine"],"ambience":["fireplace","wind"],"sfx":["footsteps","owl"],"next":["la-draille-de-nuit"]},{"id":"la-draille-de-nuit","title":"Minuit à la Pierre-Plantée","lead":"Le pli s'ouvre, le Mange-Temps vient chercher son dû : une voix ou un corps.","screen":{"place":"forest","preset":"fog","time":"night"},"readAloud":["La draille descend entre ses murets, et les torches n'éclairent pas à plus de dix pas. Le brouillard est monté du ruisseau ; il ne bouge pas, même quand le vent souffle dans les cimes.","La clairière de la Pierre-Plantée. Le menhir luit d'humidité. De l'autre côté, la draille continue, mais ce n'est plus la même : une neige d'un autre hiver, des ornières de charrettes fraîches, et très loin, des lueurs de torches qui ne sont pas les vôtres.","Quelque chose remonte cette route-là. On l'entend avant de le voir : un pas lourd, à quatre temps, et le craquement du givre. Puis la voix de jeune fille, tout près maintenant, qui attend la fin du chant."],"flow":[{"title":"Le Mange-Temps","text":"Il sort du brouillard de l'autre côté de la pierre : plus haut que trois hommes, gris comme un arbre mort couvert de givre, sur quatre pattes dont les articulations plient à rebours. Pas d'yeux. Sous sa peau, des visages passent, jeunes puis vieux : les passants. {{npc:mange-temps}}.","roll":{"type":"san","label":"Le Mange-Temps","san":"1D3/1D10"}},{"title":"Le pas du Mange-Temps","text":"À partir de minuit, lancez le compteur **Le pas du Mange-Temps** : chaque round, la chose avance d'un pas vers la pierre. Au 6e pas, elle franchit le pli et entre en 1928. Un couplet juste l'empêche d'avancer ce round-là. Une torche jetée à sa face la fait reculer d'un pas (une fois par torche).","extra":"Les veilleurs ne passent jamais la pierre. Un investigateur qui la franchit entre dans le pli : il ne revient que sur un jet de POU réussi ; sinon, le Mange-Temps le prend comme passant."},{"title":"Chanter un couplet","text":"Un chanteur par round (Rosalie si elle est là, sinon quelqu'un qui sait l'air). Un dé bonus si Rosalie mène et que le hameau chante avec elle ; un dé de pénalité si le hameau chante sans elle ; impossible sans personne qui sache l'air. Un chanteur sans talent de chant peut lancer POU à la place (jets rapides de la scène).","roll":{"type":"skill","options":["art-craft:singing"]},"success":"Le couplet est juste : le Mange-Temps ne bouge pas ce round. Ajoutez un **couplet juste**.","failure":"La voix se brise : il avance d'un pas.","extra":"Si Rosalie a été menacée ([[chez-rosalie]]) et chante encore « avec le passant », c'est maintenant qu'un jet de Persuasion difficile peut la retourner."},{"title":"Le feu et les armes","text":"Les balles et les coups le traversent à moitié : dégâts divisés par deux. Réduit à 0 PV avant d'avoir franchi la pierre, il est repoussé dans le pli pour cette nuit, mais la draille reste ouverte : il reviendra la nuit suivante, et chacune des suivantes, jusqu'à ce qu'on finisse le chant. Une victime de son toucher vieillit sur place.","roll":{"type":"damage","label":"Le toucher des années","dice":"1D8"}},{"title":"Finir le chant","text":"Quand trois couplets justes ont été chantés, ou quand le Mange-Temps est au bord de la pierre, il faut chanter la barre. C'est le moment du choix."},{"title":"Le passant est donné","branch":"Si le passant est remis au Mange-Temps","text":"Les veilleurs poussent le passant de l'autre côté de la pierre. Le Mange-Temps le prend contre lui, doucement, comme on ramasse un enfant endormi, et recule dans le brouillard. Rosalie chante la barre « avec le passant ». Le pli se ferme.","roll":{"type":"san","label":"Le passant emmené","san":"1D4/1D8"},"extra":"Si c'est un investigateur, il est perdu (voir [[la-toussaint]])."},{"title":"La vraie barre","branch":"Si quelqu'un chante la vraie barre","text":"Le chanteur (Rosalie, Émile ou un investigateur) s'avance seul jusqu'à la pierre, face au Mange-Temps, et chante : *Barri la draia amb ma votz…* La voix de jeune fille se tait. Le Mange-Temps ouvre une bouche qui n'était pas là, et le chanteur sent sa voix sortir de lui comme un souffle. Le pli se ferme d'un coup : il n'y a plus que la draille, la neige et le ruisseau.","roll":{"type":"san","label":"Donner sa voix","san":"1D6/1D10"},"extra":"Il faut les mots exacts (livre du prieur ou Rosalie) et l'air (cylindre, Toinou, Rosalie ou Émile). Le chanteur ne parlera plus jamais : ni cri, ni murmure. Aucun jet ne l'évite."},{"title":"Personne n'est donné","branch":"Si personne n'est donné et que la barre n'est pas chantée","text":"Au 6e pas, le Mange-Temps franchit la pierre. Le froid tombe d'un coup, les torches charbonnent. Il frappe une fois le plus proche (Le toucher des années), puis s'en va dans la forêt, vers la Margeride endormie. Les feux du Plan le font contourner le hameau.","extra":"La victime vieillit de 2D10 ans en un instant : cheveux blancs, mains tachées, dents qui bougent. Voir [[la-toussaint]].","goto":["la-toussaint"]}],"notes":[{"title":"La clairière, à minuit","items":["Le menhir marque le bord. De ce côté, 1928. De l'autre, la draille de toutes les années à la fois : la neige de 1764, des ornières, les torches d'une autre battue, et le Mange-Temps.","Quand le pli se ferme, tout s'arrête net : le brouillard retombe, les torches reprennent, la voix se tait.","Si les veilleurs ont été écartés ou combattus, ils peuvent revenir en pleine scène : Malafosse ne tirera pas sur quelqu'un qui chante."]}],"rolls":[{"type":"characteristic","label":"Chanter un couplet (POU)","options":["POW"]},{"type":"characteristic","label":"Revenir du pli (POU)","options":["POW"]},{"type":"san","label":"Le Mange-Temps","san":"1D3/1D10"},{"type":"damage","label":"Vieillissement (années)","dice":"2D10"}],"npcs":["mange-temps","rosalie","malafosse","emile","firmin","veilleurs"],"ambience":["wind-howling","wind"],"sfx":["footsteps","wolf-howl","owl"],"next":["la-toussaint"]},{"id":"la-toussaint","title":"La Toussaint","lead":"Jeudi 1er novembre : le hameau au cimetière, et ce que la nuit a coûté.","screen":{"place":"graveyard","preset":"snow","time":"day"},"readAloud":["Le matin de la Toussaint est d'un blanc parfait. Sur le Plan des Feux, sept ronds noirs fument encore dans la neige.","Au cimetière, les gens du hameau posent des chrysanthèmes et des bougies sur les tombes. La route de Saint-Chély est toujours fermée. Ici, personne ne peut partir, et personne ne parle."],"flow":[{"title":"La pierre du prieuré","text":"Dans la journée, Malafosse monte au prieuré. Selon la fin : il grave une croix et 1928 ; ou, pour la première fois depuis 1767, un nom au lieu d'une date (celui du chanteur) ; ou il ne grave rien, et descend à Saint-Chély dès que la route rouvre, pour lire les journaux."},{"title":"Les gendarmes","text":"La route rouvre le vendredi 2. Si les investigateurs portent plainte, les gendarmes de Saint-Chély montent le samedi. Séquestration et laudanum peuvent être prouvés (Émile, la fiole, Marguerite) ; le reste, personne ne l'écrira dans un procès-verbal.","extra":"Émile peut refuser de témoigner, pour Toinou et pour Rosalie."},{"title":"Récompenses","text":"Voir la note **Épilogue** pour chaque fin.","roll":{"type":"damage","label":"Gain de SAN","dice":"1D8"}}],"notes":[{"title":"Épilogue","items":["**La vraie barre chantée, personne n'est donné** : chaque investigateur regagne **1D8 SAN**. Le chanteur ne parlera plus jamais. La draille reste fermée tant qu'il vit ; le Mange-Temps reviendra à la grande nuit qui suivra sa mort. Si c'est Rosalie, à soixante-dix-huit ans, ce sera dans peu d'années, et Toinou le sait. Les nuits des feux, on entendra dans la forêt chanter la voix du chanteur.","**Émile sauvé** : il rentre à Paris et ne publiera jamais les cylindres 41 et 42 ; il les confie au musée sous scellés, ou à sa sœur. S'il a chanté la barre lui-même, il ne collectera plus jamais une chanson.","**Le passant donné** (Émile, l'abbé ou un investigateur) : en plus de la perte déjà subie, **1D6 SAN** pour ceux qui ont laissé faire en sachant. La draille est fermée jusqu'en 1935. Au printemps, des bûcherons trouveront peut-être un corps sec comme une momie, vêtu à la mode de 1928. Malafosse laisse partir les investigateurs s'ils jurent de se taire : il ne menace pas, il demande.","**Un investigateur a pris la place** sans chanter la vraie barre : il est perdu. Si vous le souhaitez, son joueur tente un dernier jet de POU ; sur une réussite extrême, on le retrouve à l'aube au pied du menhir, vivant, muet, les cheveux tout blancs, et la draille est fermée comme par la vraie barre.","**Le Mange-Temps est passé** : au matin, on trouve sur la route de Saint-Alban un charretier et son cheval, vieux comme la terre. Chaque investigateur perd **1D10 SAN**. Pendant l'hiver 1928-1929, les journaux de la Lozère reparlent de la Bête. On peut encore le renvoyer : finir le chant avec la vraie barre, une nuit où il revient sur la draille (une autre histoire).","**Le hameau** : si le pacte est rompu sans malheur, le hameau chante en public pour la première fois depuis 1774, à la messe de la Toussaint. L'abbé Massebeuf pleure en chaire."]}],"rolls":[{"type":"damage","label":"Gain de SAN (vraie barre)","dice":"1D8"},{"type":"damage","label":"Perte de SAN (le Mange-Temps est passé)","dice":"1D10"}],"npcs":["rosalie","toinou","malafosse","massebeuf","emile"],"ambience":["village-day","crows"],"sfx":["footsteps"]}]}],"npcs":[{"id":"emile","name":"Émile Courtiade","role":"Ethnographe du musée du Trocadéro, prisonnier du Mas-Haut","description":"Trente-quatre ans, mince, lunettes rondes, une voix de chanteur de chorale. Après trois semaines de laudanum : barbe, maigreur, pupilles minuscules.","personality":"Curieux, doux, un peu vaniteux de ses trouvailles. Il a honte d'avoir épié Rosalie. Une fois lucide, il veut comprendre, puis réparer.","characteristics":{"STR":50,"CON":55,"SIZ":60,"DEX":55,"APP":60,"INT":75,"POW":60,"EDU":80},"hp":11,"dodge":27,"skills":{"anthropology":65,"language-other:occitan":50,"listen":70,"art-craft:singing":55,"history":45},"knows":["Il a enregistré Rosalie à la Pierre-Plantée le jeudi 4 octobre, et la voix de jeune fille qui lui a répondu.","Il a vu quelque chose de très grand dans le brouillard, de l'autre côté de la pierre.","Il a été drogué au Mas-Haut le samedi 6 octobre.","Son carnet contient les trois couplets, transcrits, traduits, et l'air noté.","Il entend les Malafosse parler de « mercredi », de « la Pierre » et du « passant »."],"special":["Drogué : un dé de pénalité à tous ses jets tant qu'on ne l'a pas soigné (Médecine) ou qu'une nuit n'a pas passé."]},{"id":"rosalie","name":"Rosalie Teissèdre, née Bastide","role":"La chanteuse des feux","description":"Soixante-dix-huit ans, petite, voûtée, un fichu noir, des mains déformées qui tricotent sans arrêt. Une voix cassée qui reste juste.","personality":"Dure, pieuse, épuisée. Elle a chanté huit grandes nuits et vu partir huit passants. Elle aime Toinou plus que tout et a honte de n'avoir jamais osé donner sa voix.","characteristics":{"STR":30,"CON":45,"SIZ":40,"DEX":50,"INT":65,"POW":80,"EDU":30},"hp":8,"dodge":20,"skills":{"art-craft:singing":85,"natural-world":60,"psychology":50},"knows":["Tout le chant, et les deux versions de la barre : « avec le passant » et « avec ma voix ».","On ne chante jamais la barre devant le passant : il pourrait donner sa voix au lieu de son corps.","Le Mange-Temps mange le temps ; la voix qui répond est celle de Jeanne Bastide, la Muda.","Chez les Bastide, on dit que la draille serait restée fermée tant que Jeanne vivait.","Les huit passants qu'elle a vus partir, de 1872 à 1921."]},{"id":"toinou","name":"Toinou Teissèdre","role":"Petit-fils de Rosalie, onze ans","description":"Maigre, les genoux écorchés, un béret trop grand. Il garde les chèvres de sa grand-mère. Son père est mort à la guerre ; sa mère est placée comme bonne à Mende.","personality":"Vif, curieux, terrifié de désobéir. Émile lui a montré la machine ; c'est le premier adulte qui lui ait parlé comme à un homme.","knows":["Émile lui a confié les deux cylindres le vendredi 5 octobre.","Il a entendu Émile chanter dans le fenil du Mas-Haut le samedi 20 octobre.","Il sait chanter les trois couplets par cœur.","La nuit des feux : le Plan des Feux, la procession vers minuit, la Pierre-Plantée.","Il croit qu'on « renvoie les passants chez eux par la draille »."]},{"id":"malafosse","name":"Justin Malafosse","role":"Fermier du Mas-Haut, bayle des veilleurs","description":"Cinquante-huit ans, très grand, des mains comme des battoirs, une moustache grise. Conseiller municipal, le plus riche du hameau.","personality":"Grave, droit à sa façon, écrasé par une charge que son père lui a laissée. Il ne prend aucun plaisir à ce qu'il fait ; il est sûr de sauver le pays. Il ne tirera pas le premier.","characteristics":{"STR":75,"CON":70,"SIZ":75,"DEX":50,"INT":60,"POW":65},"hp":14,"dodge":25,"damageBonus":"+1D4","attacks":[{"name":"Fusil de chasse (calibre 12)","skill":55,"damage":"4D6","note":"À bout portant ; 2D6 jusqu'à 10 m, 1D6 au-delà. Deux coups, puis recharger."},{"name":"Poings","skill":60,"damage":"1D3+1D4"}],"skills":{"intimidate":50,"natural-world":55,"track":40},"knows":["Tout le pacte : les passants, la draille, la barre « avec le passant ». Il a mené la procession de 1921.","Émile est dans son fenil, nourri par sa femme.","Il a entendu parler de la vraie barre par Rosalie, sans y croire : « Une voix, ça ne suffit pas. »"]},{"id":"marguerite","name":"Marguerite Malafosse","role":"Femme de Justin","description":"Cinquante-deux ans, ronde, les yeux rouges. Elle a chanté une berceuse à Émile pour son phonographe.","personality":"Obéissante, pieuse, rongée. Elle drogue le Monsieur chaque soir et prie pour lui chaque nuit.","characteristics":{"INT":55,"POW":45},"hp":10,"dodge":25,"knows":["Elle a versé le laudanum dans le vin chaud du samedi 6 octobre, et en verse chaque soir dans la soupe.","Le laudanum vient de la pharmacie de Saint-Chély.","Le cadenas du fenil : la clé est pendue derrière la porte de la cuisine."]},{"id":"leontine","name":"Léontine Chabert","role":"Aubergiste-épicière, veuve","description":"Quarante-six ans, sèche, un tablier toujours propre. Elle tient le courrier, le tabac et les ragots.","personality":"Méfiante, commerçante, loyale au hameau avant tout. Elle ment bien, mais toujours avec les mêmes mots.","hp":10,"dodge":30,"skills":{"fast-talk":55,"psychology":45},"knows":["Elle a écrit à la sœur qu'Émile était parti le dimanche 7 octobre au matin.","Elle a fouillé la chambre d'Émile le vendredi 5 et vidé ses affaires après son enlèvement.","Les passants de 1851 et de 1907 logeaient chez les Chabert."]},{"id":"firmin","name":"Fulcran Aldebert","role":"Vieux chasseur, ancien louvetier, veilleur","description":"Soixante-six ans, sec et noueux, une veste de velours râpée, l'haleine qui sent l'eau-de-vie.","personality":"Bavard quand il boit, sauvage quand il a peur. Fier de son loup, honteux de la nuit où il l'a tué.","characteristics":{"STR":60,"CON":60,"SIZ":65,"DEX":55,"INT":50,"POW":50},"hp":12,"dodge":27,"attacks":[{"name":"Carabine de chasse","skill":65,"damage":"2D6+4"},{"name":"Couteau de chasse","skill":50,"damage":"1D4+2"}],"skills":{"track":65,"natural-world":60,"stealth":50},"knows":["Il a tué le loup en 1921, sur la draille, la nuit des feux : « sorti du brouillard comme par une porte ».","Les veilleurs gardent la draille tous les ans à la Toussaint.","« Cette année, c'est l'année. »"]},{"id":"veilleurs","name":"Les veilleurs","role":"Paulin Chabert et trois hommes du hameau","description":"Des paysans en blouse et en sabots, une torche de résine à la main, un fusil de chasse à l'épaule. Paulin, seize ans, a plus peur que les autres.","personality":"Ils obéissent au bayle. Ils ne veulent blesser personne, et reculent devant quelqu'un qui chante.","characteristics":{"STR":60,"CON":60,"SIZ":60,"DEX":50,"POW":45},"hp":12,"dodge":25,"attacks":[{"name":"Fusil de chasse","skill":45,"damage":"4D6","note":"À bout portant ; 2D6 jusqu'à 10 m, 1D6 au-delà."},{"name":"Torche ou bâton","skill":50,"damage":"1D6"}],"knows":["Le passant descend la draille à 23 heures ; on le laisse à la Pierre-Plantée à minuit.","Personne ne passe la pierre."]},{"id":"massebeuf","name":"Abbé Joseph Massebeuf","role":"Curé de La Sagne-Noire depuis 1926","description":"Trente et un ans, maigre, des lunettes cerclées de fer, une soutane trop grande. Il vient d'Ispagnac, près de Mende.","personality":"Lettré, scrupuleux, seul. Il soupçonne une chose honteuse et a peur de la regarder en face. Avec des alliés, il trouve son courage.","characteristics":{"STR":45,"CON":50,"SIZ":55,"DEX":55,"INT":75,"POW":60,"EDU":80},"hp":10,"dodge":30,"skills":{"language-other:latin":70,"language-other:occitan":45,"history":50,"library-use":60,"psychology":45},"knows":["Les notes en marge des registres, tous les sept ans, à la page du 1er novembre.","Malafosse était à la messe le dimanche 7 octobre au matin.","Marguerite monte chaque soir un plateau à la grange du Mas-Haut.","Il possède un phonographe à cylindres."]},{"id":"pradal","name":"Achille Pradal","role":"Garde forestier de la maison forestière de la Fage","description":"Quarante-cinq ans, uniforme vert, moustache en brosse, une sacoche de cuir pleine de calques. Ancien sapeur de la guerre.","personality":"Méthodique, têtu, rationnel jusqu'à l'obstination. Ce qu'il ne peut pas mesurer l'empêche de dormir.","characteristics":{"STR":65,"CON":65,"SIZ":60,"DEX":60,"INT":60,"POW":55},"hp":12,"dodge":30,"attacks":[{"name":"Carabine de service","skill":55,"damage":"2D6+4"}],"skills":{"navigate":70,"natural-world":65,"track":60,"survival":55},"knows":["La draille sur la carte de Cassini et le cadastre de 1834, absente du levé de 1912.","Ses mesures de juin 1925 : jamais deux fois la même longueur. Ses montres qui retardent.","Malafosse lui demande chaque 31 octobre de rester chez lui.","La dalle d'autel déplacée au prieuré."]},{"id":"augustin","name":"Augustin Brun","role":"Charretier de Saint-Chély","description":"Cinquante ans, une pèlerine, une pipe éteinte, un cheval qui s'appelle Bijou.","personality":"Bavard, sans malice, content d'avoir du monde à qui parler.","knows":["Il a monté Émile en septembre et ne l'a jamais redescendu.","Il est le seul à faire la route ; le chef de gare est son beau-frère et n'a pas vu Émile.","Il monte le courrier le samedi et le redescend le jour même."]},{"id":"mange-temps","kind":"creature","name":"Le Mange-Temps (lo Manja-Temps)","role":"Ce qui vit entre les années","description":"Plus haut que trois hommes, gris comme un arbre mort couvert de givre, sur quatre membres longs dont les articulations plient à rebours. Une tête longue comme un crâne de cheval, sans yeux. Sous sa peau passent des visages, jeunes puis vieux : ceux des passants. Il sent la tourbe froide et la laine mouillée. Ses traces sont tournées à rebours.","personality":"Patient, affamé, sans colère. Il répond au chant avec la voix de Jeanne Bastide, qu'il a gardée en 1767.","characteristics":{"STR":140,"CON":100,"SIZ":150,"DEX":60,"POW":90},"hp":30,"armor":0,"dodge":0,"attacksPerRound":1,"attacks":[{"name":"Le toucher des années","skill":60,"damage":"1D8","note":"La victime vieillit de 2D10 ans en un instant. À 0 PV, on ne trouve qu'un corps sec comme une momie."},{"name":"Étreinte","skill":50,"damage":"1D6","note":"La victime est tirée d'un pas vers le pli à chaque round ; FOR opposée pour se dégager. Passée la pierre, elle est perdue."}],"sanLoss":"1D3/1D10","special":["À moitié hors du temps : toutes les armes ne lui font que la moitié des dégâts.","Le feu le fait reculer : une torche dans la face, il recule d'un pas (une fois par torche) et subit 1D6.","Réduit à 0 PV, il n'est pas tué : il est repoussé dans le pli jusqu'à la nuit suivante.","Avant la nuit des feux, il ne peut que longer, sans rien toucher, le tracé de la vieille draille (même là où elle a disparu, comme dans le champ de la Croix), et s'arrête aux croix des limites. La nuit des feux, tant qu'il n'a pas franchi la Pierre-Plantée, il reste dans le pli.","Un couplet juste l'empêche d'avancer ce round. La barre le renvoie : avec un corps pour sept ans, avec une voix tant que vit le chanteur."]}],"handouts":[{"id":"derniere-lettre","title":"Dernière lettre d'Émile au musée","scene":"l-auberge","text":"*La Sagne-Noire, par Saint-Chély-d'Apcher (Lozère), le vendredi 5 octobre 1928*\n\nCher Monsieur Ravenel,\n\nJ'ai confié au charretier la caisse n° 3 : vingt-huit cylindres, bourrées, complaintes, deux berceuses très anciennes, et une chanson du loup que je crois inédite. Les fiches suivent.\n\nJe reste encore quelques semaines. Il y a ici une chanson que personne ne veut chanter devant moi. Ils l'appellent la chanson de la barre, ou des feux : le hameau allume de grands feux à la Toussaint, au bord de la forêt, et la chante toute la nuit. Quand j'en parle, on change de sujet, ou l'on rit trop fort. Une vieille femme m'a dit que je l'entendrais « bien assez tôt ».\n\nHier soir, je l'ai enfin enregistrée, d'une manière dont je ne suis pas fier. Il y a sur le cylindre quelque chose que je ne m'explique pas. Je dois le réécouter à tête reposée avant de vous en parler. J'ai mis les deux cylindres à l'abri.\n\nPardonnez cette lettre décousue. Il fait déjà froid, et je dors mal.\n\nVotre dévoué,\n\n**É. Courtiade**"},{"id":"reponse-aubergiste","title":"Lettre de l'aubergiste à Hélène Courtiade","scene":"l-auberge","text":"*La Sagne-Noire, le 15 octobre 1928*\n\nMademoiselle,\n\nJe réponds à votre lettre. Monsieur votre frère a quitté La Sagne le dimanche 7 octobre au matin, avec sa machine et ses affaires. Monsieur Malafosse l'a descendu en charrette jusqu'à la gare de Saint-Chély. Il a réglé sa chambre jusqu'au 7. Il a dit qu'il allait du côté de l'Aubrac, pour d'autres chansons.\n\nIl était bien poli et nous le regrettons.\n\nVeuillez agréer, Mademoiselle, mes salutations.\n\n**Veuve Chabert**, aubergiste"},{"id":"rapport-boissonnade","title":"Rapport du docteur Boissonnade (mai 1922)","scene":"l-auberge","text":"*Rapport du docteur L. Boissonnade, médecin à Mende, requis par la gendarmerie de Saint-Chély. Le 16 mai 1922.*\n\nLe vendredi 12 mai, des bûcherons ont découvert dans la tourbière de la Sagne, à la lisière de la forêt domaniale, le corps d'un homme couché sur le dos. Le corps est entièrement desséché, la peau tannée et collée aux os, à la manière des corps retrouvés dans les marais anciens. Sur ce seul examen, j'estimerais la mort à plusieurs dizaines d'années, sinon davantage.\n\nOr le défunt porte des vêtements de confection récente (veste de velours, brodequins cloutés à peine usés) et, dans sa poche, un almanach de l'année 1921 et un mouchoir brodé **J. L.**\n\nJe ne puis concilier ces constatations. Je conclus, faute de mieux, à la mort par le froid d'un vagabond inconnu, survenue l'hiver dernier, suivie d'une dessiccation d'une rapidité que je n'ai jamais observée.\n\n**Dr L. Boissonnade**"},{"id":"liste-emile","title":"La liste au dos de l'armoire","scene":"l-auberge","text":"*Au crayon, au dos de la porte de l'armoire, d'une écriture fine et penchée :*\n\nLa Sagne — enregistrements\n17-24 sept. : bourrées (Fulcran A., voix et harmonica) — complainte de la fille du meunier (Vve Chabert) — berceuse (Marguerite M., qui pleure en chantant ?)\n25 sept.-2 oct. : chanson du loup (Fulcran A.) — prières en patois (Rosalie T. refuse de chanter)\n*Chanson des feux* : REFUS de tous. Rosalie T. la chante (dixit Toinou). Le mot : *barra*. Une porte ? une barrière ? → écrire à la Société des lettres.\nLes jeudis d'octobre, au crépuscule, R. monte à la forêt. Pourquoi ?"},{"id":"registres","title":"Registres de la paroisse : notes en marge","scene":"l-eglise","text":"*Registres de catholicité de la paroisse de La Sagne-Noire. Notes en marge, à la page du 1er novembre (choix de l'abbé Massebeuf).*\n\n**1802** — Le colporteur de toiles logé chez Malafosse est parti par la draille la nuit des feux. *(abbé Bonnal)*\n**1851** — Un rémouleur piémontais, logé chez Chabert depuis la Saint-Michel, est parti par la draille. *(abbé Rieu)*\n**1879** — Le soldat libéré qui rentrait à pied vers le Cantal, logé au Mas-Haut, est parti par la draille. *(abbé Cayrel)*\n**1907** — Ernest Maury, photographe ambulant, de Rodez, logé chez Chabert, est parti par la draille. Prions pour lui. *(Cayrel)*\n**1914** — Le jeune homme qui se cachait de la guerre, logé au Mas-Haut, est parti par la draille. Que Dieu me pardonne de n'avoir rien dit. *(Cayrel)*\n**1921** — Joseph Lafon, chemineau, de Langogne, hébergé au Mas-Haut depuis la Saint-Michel, est parti par la draille. *(Cayrel)*\n\n*D'une autre main, au crayon, récente :* tous les sept ans ? → 1928 ! (J. M.)"},{"id":"tombe-muda","title":"La tombe de la Muda","scene":"le-cimetiere","text":"*Dalle de granit contre le mur de l'église, lettres usées, un bouquet de bruyère sèche :*\n\nCI GÎT\nJEANNE BASTIDE\nDITE LA MUDA\n1749 — 1819\nBARRÈT LA DRAIA\nCANTÈT UN CÒP"},{"id":"cylindres","title":"Les cylindres 41 et 42","scene":"les-cylindres","text":"*Ce que l'on entend sur les deux cylindres. La traduction du patois est entre crochets.*\n\n**Cylindre 41.** Voix d'homme : « Cylindre quarante et un. La Sagne-Noire, le quatre octobre mil neuf cent vingt-huit. » Le vent. Puis une vieille femme chante, lentement :\n\n*Fuòc sus la draia, fuòc sus lo puèg,*\n*qual es aquel que passa a mièjanuèch ?*\n[Feu sur la draille, feu sur le puech, / qui est celui qui passe à minuit ?]\n\n*Es pas un pastre, es pas un lop,*\n*camina a rebors e sap mon nom.*\n[Ce n'est pas un berger, ce n'est pas un loup, / il marche à rebours et il sait mon nom.]\n\n*Tòrna a ton ostal, tòrna a ton temps,*\n*la draia es nòstra, la nuèch es nòstra.*\n[Retourne en ta maison, retourne en ton temps, / la draille est à nous, la nuit est à nous.]\n\n**Cylindre 42.** La vieille femme reprend le troisième couplet et s'arrête net. Silence. Puis, de plus loin, une voix de jeune fille, claire et douce :\n\n*Ma draia es vòstra, vòstre temps es meu.*\n*Balhatz-me una votz, o balhatz-me un còrs.*\n[Ma draille est à vous, votre temps est à moi. / Donnez-moi une voix, ou donnez-moi un corps.]\n\nGrésillement. Puis la même voix de jeune fille, sur le ton exact de l'homme du début : « Cylindre quarante-trois. La Sagne-Noire, le trente et un octobre. »"},{"id":"cartes-pradal","title":"Les calques du garde Pradal","scene":"les-traces","text":"*Notes et calques du garde Pradal, sacoche de service.*\n\n**Carte de Cassini (feuille levée vers 1770), copie** : la « Grande Draille » traverse la forêt de la Sagne en ligne droite, passe au « Prieuré S. Ferréol » et à un signe de pierre levée. Le hameau s'appelle « La Sagne ».\n\n**Cadastre de 1834, section B** : la draille passe *à travers* la parcelle 212, « champ de la Croix » (alors lande), et entre en forêt au lieu-dit « Plan des Fuòcs ».\n\n**Levé des Eaux et Forêts, 1912** : la draille n'y figure plus. Route forestière n° 3, à 300 m à l'est.\n\n**Mesures du garde, Pierre-Plantée → prieuré, à la chaîne (juin 1925)** :\nmercredi 10 : 1 140 m\njeudi 11 : 2 980 m\nvendredi 12 : 1 395 m\nsamedi 13 : 615 m (recommencé : 1 860 m)\n\n*En marge, au crayon :* « Montre : −20 min. Le 13 : −1 h 50. Ne pas en parler à l'Inspection. »"},{"id":"livre-prieur","title":"Le livre du prieur Vaissière (extraits)","scene":"le-prieure","text":"*Livre de raison et de comptes du prieuré de Saint-Ferréol, tenu par Dom Aurélien Vaissière, prieur. Extraits, 1764-1774.*\n\n**Novembre 1764.** Payé quarante sols de cierges et de fagots pour les feux de la Toussaint. J'ai voulu fermer la draille à la Bête avec le vieux chant des bouviers. Je l'ai ouverte à pire que la Bête.\n\n**Février 1765.** On a rapporté de la draille Pierre Rouvière, berger, quinze ans, vieux comme un homme de cent ans, les dents tombées, les yeux blancs. Ce n'est point la Bête. Les gens d'ici l'appellent *lo Manja-Temps*, le Mange-Temps, parce qu'il mange les années des vivants et qu'il vient de l'autre côté du temps.\n\n**Juillet 1767.** On dit que la Bête a été tuée du côté de Saugues. Ici, rien n'a cessé. Neuf morts depuis l'hiver de 64.\n\n**31 octobre 1767.** Jeanne Bastide, fille de Jean, bergère, dix-huit ans, a chanté seule le dernier couplet à la Pierre-Plantée. Je le note ici tel qu'elle l'a chanté :\n*Barri la draia amb ma votz,*\n*que ma votz demòre de l'autre costat.*\n(*Claudo viam voce mea, ut vox mea maneat ex altera parte.*)\nLa draille s'est fermée. Jeanne ne parle plus. Payé à son père six livres, et je lui dois tout le reste.\n\n**Novembre 1767.** Il reviendra au bord tous les sept ans, la nuit des feux. Il faudra lui donner une voix, ou un corps. Je crois que la voix de Jeanne le tiendra tant qu'elle vivra. Les consuls ne veulent pas en courir le risque.\n\n**31 octobre 1774.** Ils ont donné le colporteur. Ils ont changé un mot du chant : *amb lo passant* au lieu de *amb ma votz*. Je n'ai rien dit, et je n'ai pas chanté. Je ne tiendrai plus ce livre."}],"knowledge":[{"need":"Comprendre le patois (le chant, les villageois)","best":"Langue (occitan)","backup":"Toinou, l'abbé Massebeuf, Pradal, un investigateur lozérien"},{"need":"Faire parler le hameau","best":"Psychologie","backup":"Charme, Persuasion ; une preuve en main donne un dé bonus"},{"need":"Lire les traces dans la neige","best":"Pister","backup":"Nature, Trouver Objet Caché"},{"need":"Comprendre les cartes de Pradal","best":"Navigation","backup":"Bibliothèque, ou Pradal lui-même (plus lent)"},{"need":"Reconnaître ce qu'a de faux la tête de loup","best":"Nature","backup":"Médecine, Histoire (la balle de mousquet)"},{"need":"Soigner Émile (laudanum)","best":"Médecine","backup":"Premiers soins (il ne sera lucide qu'au matin)"},{"need":"Retenir l'air et les paroles","best":"INT","backup":"Réécouter le cylindre, Toinou, le carnet d'Émile"},{"need":"Chanter juste devant le Mange-Temps","best":"Art (chant)","backup":"POU"},{"need":"Lire le livre du prieur","best":"Bibliothèque","backup":"Histoire, ou une soirée à la lampe"},{"need":"Repousser le Mange-Temps","best":"Une torche dans la face","backup":"Le chant ; les armes ne font que la moitié des dégâts"}],"trackers":[{"id":"jours","label":"Jours passés au hameau","max":4,"unit":"jours","help":"Dimanche 28 = 1, lundi = 2, mardi = 3, mercredi 31 = 4 : les feux s'allument à la tombée de la nuit. Le mardi soir, la neige coupe la route de Saint-Chély jusqu'au vendredi.","scenes":["l-auberge","l-eglise","le-cimetiere","les-cylindres","les-traces","la-draille","le-prieure","chez-rosalie","le-mas-haut"],"addLabel":"+1 jour","fullMessage":"Mercredi 31 octobre : la nuit des feux."},{"id":"pas-du-mange-temps","label":"Le pas du Mange-Temps","max":6,"unit":"pas","help":"Un pas par round à partir de minuit. Un couplet juste l'empêche d'avancer ce round ; une torche dans sa face le fait reculer d'un pas (une fois par torche). Au 6e pas, il franchit la Pierre-Plantée et entre en 1928.","scenes":["la-draille-de-nuit"],"addLabel":"+1 pas","subLabel":"Torche : −1 pas","fullMessage":"Le Mange-Temps franchit la Pierre-Plantée."},{"id":"couplets","label":"Couplets justes","max":3,"unit":"couplets","help":"Après trois couplets justes, on peut chanter la barre : avec le passant, ou avec sa voix.","scenes":["la-draille-de-nuit"],"addLabel":"+1 couplet","fullMessage":"Le chant est prêt : il faut chanter la barre."}]}$story$::jsonb, now()
where not exists (select 1 from public.stories where visibility = 'marketplace' and content #>> '{meta,id}' = 'les-feux-de-la-margeride');

insert into public.stories (visibility, content, published_at)
select 'marketplace', $story${"format":"grimoire-story/1","meta":{"id":"the-silent-light","title":"The Silent Light","lang":"en","summary":"Gull Rock lighthouse went dark three nights ago. The keeper has not been seen since, and the fishermen of Port Ansel refuse to row out. Someone has to find out why.","players":{"min":1,"max":4},"duration":"2-3 hours","era":"1920s","setting":"A fishing village on the New England coast","system":"d100","author":"Grimoire sample","license":"CC-BY-4.0","version":"1.2","tags":["introductory","coastal","investigation"],"contentWarnings":["drowning","grief","death of a child"]},"overview":{"secret":"November 1923. Last February, keeper **Elias Varnum** was rowing his son **Thomas**, seven, back to the rock when a squall overturned the dinghy. Elias reached the landing; the boy was never found. Something lives in the deep water under Gull Rock. The old people of Port Ansel only call it *what's under*. It has no shape of its own: it wears the drowned, the way their mourners remember them, and it can only come ashore where no light falls on the water. The lighthouse was raised in 1851 to keep it down, after the forty drowned of the packet *Constance* were seen walking the rocks. Four nights ago it spoke to Elias in his son's voice: *put out the light three nights, open the door on the third, and on the fourth I come up to you and stay.* He drained the lamp, padlocked the oil store and threw his key into the sea. Night one, it swam at the landing. Night two, it stood on the rocks and waved. Night three, it stood dripping in the hall and went no further. Tonight, the fourth night, it climbs the stairs. If nobody relights the lamp, Elias lets it into the lamp room at midnight and it walks him into the sea; the next night, still wearing Thomas, it walks up the pier to Martha's door. A beam of light on it burns it back to seawater. Nothing else harms it.","steps":["[[harbour]] (afternoon): Port Ansel, the rumours, and an old saying: 'Keep the light, keep them under.'","[[widow]]: Martha Varnum gives the boat and the spare keys, and remembers the coat Thomas drowned in.","[[crossing]] (dusk): something follows the dinghy, and a lantern on the water drives it off.","[[lighthouse]] (evening): the logbook, the salt footprints, the locked oil store.","[[the-lamp]] (towards midnight): fill and relight the lamp while the thing climbs, and talk Elias down.","[[epilogue]]: dawn, and what it cost."],"mustNotMiss":["The **logbook**, open on the watch-room desk (no roll needed): the bargain, night by night.","**Oil**: the lamp is dry and the oil store padlocked. Martha's spare key opens it; otherwise the padlock must be forced ([[lighthouse]]).","**Light hurts it**: the saying ([[harbour]]), the lantern on the water ([[crossing]]), the logbook, the rule card and the brass plate ([[the-lamp]]). Fighting it does nothing."],"branches":["If they land after dark (failed crossing, or a long evening in the village), the thing is already on the rocks: less time to search, and it comes in as soon as they go upstairs.","Without Martha's key, forcing the oil store costs time and noise, and brings Elias down the stairs with a boat hook.","Elias can be saved if someone talks him down ([[the-lamp]]); he then helps with the lamp.","If they reach the rock after midnight, Elias is gone and the door stands open. Relighting the lamp that night still keeps the thing from Martha's door."],"ifStuck":["Martha remembers the last thing Elias asked her: 'If Thomas came back different, would you still let him in?'","Tobias, a drink in hand, tells the story of the *Constance* and why the light was built.","A gull smashes into the dark lamp-room glass: the lamp is the key."],"keeperTips":["Play Elias as a broken father, not a villain.","The creature never runs. It walks, dripping, and calls for its father.","It wears the summer sailor suit from the photograph, not the brown coat Thomas drowned in: it is Elias's memory of his son, not his son. Let the players notice.","Every key fact has more than one source. Rolls add detail or save time; they never hide the truth."]},"acts":[{"id":"village","title":"Port Ansel","scenes":[{"id":"harbour","title":"The harbour","lead":"Arrival, rumours, and a boat nobody will lend.","screen":{"place":"harbour","time":"day"},"readAloud":["Port Ansel smells of tar and cold fish. A dozen boats knock against the pier, and every one of them is tied up tight, though the sea is calm.","Out past the breakwater, on its black rock, the lighthouse stands like a dead candle. Men mending nets stop talking when you pass."],"flow":[{"title":"Ask around","text":"The fishermen won't row out. 'Not with the light gone.'","roll":{"type":"skill","options":["charm","fast-talk"]},"success":"Old {{npc:tobias}} saw a small figure on the rocks at night. 'Like a boy. But no boy swims that cold water.' And the light didn't fail: 'It went out at sundown, neat, like a man pinching a candle.'","failure":"Shrugs and shut doors. An old man mutters 'Keep the light, keep 'em under' and spits in the water."},{"title":"The supply boat","text":"The grocer's boy rowed supplies out four days ago. Elias met him at the landing and sent him back: 'Don't come again till I send.' His hands were cracked and white with salt.","extra":"Elias is alive, and wants nobody on the rock."},{"title":"The old saying","text":"Asked about 'keep them under', {{npc:tobias}} tells it for a drink: in 1851 the packet *Constance* broke on Gull Rock and forty drowned. That winter, folk saw them walking the rocks on dark nights, calling people by name. The town raised the light in the spring, and nobody saw them again.","roll":{"type":"skill","options":["history"]},"success":"Without Tobias: they remember the wreck of the *Constance* from an old newspaper, and that the lighthouse was built because of it."},{"title":"Find a boat","text":"Martha Varnum has her husband's dinghy. → [[widow]]"}],"npcs":["tobias"],"ambience":["village-day","wind"],"sfx":["footsteps","dog-bark"]},{"id":"widow","title":"Martha Varnum","lead":"The keeper's wife, worn thin by grief.","screen":{"place":"street","time":"dusk"},"readAloud":["The cottage is spotless and very quiet. On the mantel, a photograph of a small boy in a sailor suit is turned face down.","Martha listens to you without blinking. 'He hasn't been right since Thomas drowned,' she says at last. 'Bring him home. Whatever he's become.'"],"flow":[{"title":"Gain her trust","roll":{"type":"skill","options":["psychology","persuade"]},"success":"Elias began talking to the sea at night, 'as if it answered'. The last time he came ashore he asked her: 'If Thomas came back different, would you still let him in?'","failure":"She gives them the boat and the keys, nothing more."},{"title":"The keys","text":"Martha gives them the dinghy, its storm lantern, and Elias's spare key ring from the hook by her door: the lighthouse door and the padlock of the oil store.","extra":"The oil store key saves time and noise in [[lighthouse]]."},{"title":"The photograph","text":"If they turn it over, describe the boy carefully: summer, the sailor suit, squinting at the sun → {{handout:photo}}.","extra":"They will see that face, and that suit, again."},{"title":"How he drowned","text":"If they ask, or mention the figure on the rocks: 'In February. In his brown wool coat, the one I made him. They never found him.'","extra":"The thing on the rocks wears the sailor suit, not the coat."}],"npcs":["martha"],"handouts":["photo"],"ambience":["clock","fireplace"]}]},{"id":"rock","title":"Gull Rock","scenes":[{"id":"crossing","title":"The crossing","lead":"A short row at dusk that feels much longer.","screen":{"place":"harbour","time":"dusk"},"readAloud":["The oars dip into water as dark as ink. Halfway across, the gulls fall silent all at once.","Something bumps the hull from below. Once. Then again, gently, like a hand testing a door."],"flow":[{"title":"Rowing","roll":{"type":"characteristic","options":["STR"]},"success":"They land before full dark.","failure":"The current fights them: they land after nightfall, and the thing is already on the rocks."},{"title":"Something below","roll":{"type":"san","san":"0/1D3","label":"The bump under the hull"}},{"title":"A light on the water","text":"If anyone holds the storm lantern (or a torch) over the side, the bumping stops at once and something pale slides away from the beam. It comes back as soon as the light moves.","roll":{"type":"skill","options":["spot-hidden"]},"success":"In the beam, for a heartbeat: a small white hand letting go of the keel.","extra":"The first proof that light drives it off."}],"ambience":["wind","crows"],"sfx":["thunder"]},{"id":"lighthouse","title":"Inside the lighthouse","lead":"Wet footprints, a cold stove, the logbook, a locked oil store.","screen":{"place":"harbour","time":"night"},"readAloud":["The door is unlocked. Inside, the stove is cold and the air smells of seaweed.","Small wet footprints, a child's, lead from the door to the spiral stairs. They stop on the first step, in a crust of salt, as if whoever made them stood there a long time, waiting."],"flow":[{"title":"The logbook","text":"Open on the watch-room desk, beside an empty bottle → {{handout:logbook}}. No roll needed to find it.","roll":{"type":"san","san":"1/1D4","label":"The last entries"}},{"title":"Search the keeper's room","roll":{"type":"skill","options":["spot-hidden"]},"success":"Under the pillow, another print of Thomas's photograph, soft from handling. On the wall, the keepers' rule card → {{handout:rules}}.","failure":"An unmade bed, an empty bottle. The rule card is on the wall, too dark to read without a lamp.","pushed":"They find it all, but the noise brings Elias down the stairs, wild-eyed and holding a boat hook."},{"title":"The footprints","roll":{"type":"skill","options":["track","natural-world"]},"success":"Bare feet, a child's. They come in from the sea and never go back out. Tiny shells in the salt are still moving.","failure":"Wet prints, a child's. Nothing more."},{"title":"The lamp is dry","text":"Anyone who looks at the lamp, or reads the logbook, knows it has no oil. The kerosene is in the stone store at the foot of the tower, padlocked. With Martha's key: no roll.","roll":{"type":"skill","options":["locksmith","mechanical-repair"]},"success":"The padlock gives. Two full cans of kerosene.","failure":"They break it with an iron bar: it takes time, and the noise brings Elias down the stairs with a boat hook.","extra":"Without oil, the lamp cannot be lit."},{"title":"Listen","roll":{"type":"skill","options":["listen"]},"success":"Someone is sobbing in the lamp room above. And, outside, something small is climbing the rocks.","goto":["the-lamp"]}],"notes":[{"title":"When the thing comes in","items":["It rises at full dark and climbs the rocks.","It comes through the door when the search is done, or as soon as they go upstairs if they landed after dark. Midnight at the latest.","Then it climbs the stairs: start the **Stairs climbed** tracker in [[the-lamp]]."]}],"npcs":["elias"],"handouts":["logbook","rules"],"ambience":["wind-howling"],"sfx":["door-creak","footsteps"]},{"id":"the-lamp","title":"The lamp","lead":"Relight the lamp while the drowned child climbs.","screen":{"place":"harbour","time":"night"},"readAloud":["The lamp room is a cage of glass and brass. Elias Varnum kneels by the great dead lens, a cold match in his fingers.","Far below, a small voice calls up the stairwell. 'Papa? Papa, it's cold. Let me in.'"],"flow":[{"title":"The thing on the stairs","text":"Each round it climbs one turn of the stairs. After 5 rounds it reaches the top. It wears the sailor suit from the photograph, wet through, and does not shiver.","roll":{"type":"san","san":"1/1D6","label":"Seeing the drowned child"}},{"title":"The brass plate","text":"On the lens pedestal → {{handout:plate}}. Elias has gouged at the last line with a knife.","extra":"Last nudge: the lamp is the answer."},{"title":"Relight the lamp","text":"Pour the oil, prime the burner, light the mantle, wind the clockwork that turns the lens. Without oil from the store, it cannot be lit.","roll":{"type":"skill","options":["mechanical-repair","operate-heavy-machinery"]},"success":"The beam sweeps the sea. The voice on the stairs becomes a gurgling shriek and the thing collapses into seawater.","failure":"Try again next round.","pushed":"The lens cracks: the lamp lights, but at half strength. The thing survives and flees to the sea."},{"title":"A hand lamp","text":"A lantern or torch shone down the stairwell makes it stop and shield its face: it loses its next turn of the stairs. Once per light: after that it climbs with its eyes shut."},{"title":"Talk Elias down","text":"He tries to stop them: 'He's my son!' Reminding him of the brown coat (it is wearing the wrong clothes) gives a bonus die.","roll":{"type":"skill","options":["persuade","psychology","charm"],"difficulty":"hard"},"success":"He weeps and helps relight the lamp (bonus die).","failure":"He fights to keep the light dark."},{"title":"If it reaches the top","text":"It takes Elias's hand and walks him into the sea. Then it turns to the others.","roll":{"type":"damage","dice":"1D6","label":"Cold grip"},"goto":["epilogue"]}],"npcs":["elias","drowned-child"],"handouts":["plate"],"ambience":["storm"],"sfx":["footsteps","knocking","thunder"]},{"id":"epilogue","title":"Dawn","lead":"Rewards and consequences.","screen":{"place":"harbour","time":"day"},"readAloud":["Morning comes grey and ordinary. Out on Gull Rock, the light is still turning, though no one needs it now."],"notes":[{"title":"Outcome","items":["Lamp relit before the thing reached the top: each investigator gains **1D6 SAN**.","Elias saved: Martha's gratitude, and a friend in Port Ansel.","Elias lost: **1/1D4 SAN**. Some nights, small wet footprints appear on the pier.","Lamp never relit: the next night, someone knocks at Martha's door. 'Mama? Let me in.'"]}],"rolls":[{"type":"damage","dice":"1D6","label":"SAN reward"}],"ambience":["village-day"]}]}],"npcs":[{"id":"tobias","name":"Old Tobias","role":"Retired fisherman","personality":"Superstitious, kind, drinks too much.","knows":["Saw a small figure on the rocks at night.","The light went out at sundown, on purpose.","The wreck of the *Constance* and the saying: 'Keep the light, keep them under.'"],"hp":9,"dodge":20},{"id":"martha","name":"Martha Varnum","role":"The keeper's wife","personality":"Composed, exhausted, fiercely loyal.","knows":["Elias talks to the sea at night.","Thomas drowned last February in his brown wool coat; he was never found.","Elias asked if she would let Thomas in 'if he came back different'.","Where the spare keys hang."],"hp":10,"dodge":25},{"id":"elias","name":"Elias Varnum","role":"Lighthouse keeper","personality":"A grieving father who has stopped sleeping. He was at the oars when Thomas went over.","characteristics":{"STR":65,"CON":60,"SIZ":70,"DEX":50,"INT":55,"POW":40},"hp":13,"dodge":25,"attacks":[{"name":"Boat hook","skill":45,"damage":"1D8"},{"name":"Fists","skill":50,"damage":"1D3+1D4"}]},{"id":"drowned-child","name":"The drowned child","kind":"creature","role":"Something wearing Thomas's shape","description":"What lives under Gull Rock, wearing the boy as his father remembers him: the summer sailor suit, the squint.","hp":12,"dodge":0,"armor":0,"sanLoss":"1/1D6","attacks":[{"name":"Cold grip","skill":50,"damage":"1D6","note":"On a hit, the victim is held and dragged toward the sea."}],"special":["Weapons pass through it like water: it takes no damage.","Destroyed by the lighthouse beam.","A lantern or torch in its face stops it for one round (once per light)."]}],"handouts":[{"id":"photo","title":"Photograph of Thomas","text":"A boy of about seven in a sailor suit, squinting at the camera. On the back, in Martha's hand: *Thomas, summer 1922.*","scene":"widow"},{"id":"logbook","title":"Keeper's logbook, last entries","text":"*Night one.* Lamp out at sundown. Drained the reservoir, locked the store, threw my key off the landing so I can't go back on it. The sea said it would bring him. It said it can't come up through the light.\n*Night two.* Saw him on the rocks. He waved. He didn't shiver. Thomas always shivered.\n*Night three.* Opened the door like it said. He stood in the hall, dripping, and wouldn't come up. 'Tomorrow, Papa.' He had on the sailor suit. I can't think where he found the sailor suit.\n*Night four.* Tonight he comes up. Tonight he stays.","scene":"lighthouse"},{"id":"rules","title":"Keepers' rule card","text":"PORT ANSEL LIGHT BOARD, 1851.\nRule the first. The light to be kept from sunset to sunrise without fail, *that the sea keep what it has taken.*\nRule the second. No keeper to let the lamp go dark for any cause whatever.","scene":"lighthouse"},{"id":"plate","title":"Brass plate, lamp room","text":"GULL ROCK LIGHT, 1851.\nRaised in memory of the forty souls of the packet *Constance*.\nKEEP THE LIGHT AND KEEP THEM UNDER.","scene":"the-lamp"}],"knowledge":[{"need":"Open the oil store","best":"Martha's key","backup":"Locksmith, Mechanical Repair"},{"need":"Relight the lamp","best":"Mechanical Repair","backup":"Operate Heavy Machinery, or Luck"},{"need":"Calm Elias","best":"Psychology","backup":"Persuade, Charm"}],"trackers":[{"id":"stairs","label":"Stairs climbed","max":5,"unit":"turns","help":"At 5, the thing reaches the lamp room.","scenes":["the-lamp"]}]}$story$::jsonb, now()
where not exists (select 1 from public.stories where visibility = 'marketplace' and content #>> '{meta,id}' = 'the-silent-light');
